ClinicalChunks.register("data/orders-014.js",[{"id":"orders-8c9a76d491666c137e49","key":"v1-c9ccc21dfe2a3058|orders-8c9a76d491666c137e49","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化疗通用医嘱与预处理","category":"化疗","raw":{"name":"化疗通用医嘱与预处理","category":"化疗","summary":"化疗通用医嘱包括化疗前预处理（止吐、抗过敏、水化）、化疗药物输注医嘱、化疗后支持治疗与监测，是保证化疗安全实施的标准流程。不同方案的预处理与监测重点不同（如顺铂需水化、紫杉醇需抗过敏、大剂量MTX需亚叶酸钙解救）。","symptoms":["化疗输注中：胸闷、心悸、皮疹、瘙痒、呼吸困难（过敏反应）；穿刺部位疼痛、肿胀（外渗）","化疗后24小时内：恶心、呕吐、乏力、食欲减退、发热","化疗后3～7天：口腔黏膜炎、腹泻或便秘、骨髓抑制（乏力、发热、出血倾向）","化疗后7～14天：白细胞与血小板降至最低（骨髓抑制低谷期），感染与出血风险最高","迟发性反应：手足综合征、周围神经毒性、脱发、肝肾功能异常"],"diagnosis":["化疗前：血常规、肝肾功能、心电图（达标方可化疗）","输注中：观察过敏反应、外渗、输液速度与生命体征（前15分钟每5分钟观察一次）","化疗后：每2～3天查血常规（骨髓抑制期每日或隔日）、肝肾功能每周期复查","疗效评估：每2～3周期复查影像（RECIST标准）与肿瘤标志物","不良反应分级：按CTCAE 5.0标准分级（1～4级），据分级决定处理与剂量调整"],"infusion":["⚠️ 按方案与不良反应选择，切勿全部同时使用！","方案1（水化，顺铂/大剂量MTX/环磷酰胺）：","用法：0.9%氯化钠 1000～2000ml 静滴（化疗前6～12小时开始，化疗后继续24小时）；必要时呋塞米 20mg 静推或甘露醇 125ml 静滴利尿〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","方案2（止吐，高致吐方案）：","用法：昂丹司琼 8mg 静推（化疗前30分钟）+ 地塞米松 10～20mg 静推 + 阿瑞匹坦 125mg 口服（d1）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案3（亚叶酸钙解救，大剂量MTX后）：","用法：亚叶酸钙 15mg/m² 静推 q6h（MTX后24小时开始），按MTX血药浓度调整至<0.1μmol/L","方案4（过敏反应抢救，紫杉醇/利妥昔单抗输注时）：","用法：立即停止输注；肾上腺素 0.3～0.5mg 肌注（大腿外侧）；地塞米松 10mg 静推；苯海拉明 20mg 肌注；0.9%氯化钠 快速补液；必要时吸氧与升压药〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","📌 化疗药物输注前必须双人核对；发疱性药物经中心静脉输注；输注前15分钟密切观察过敏反应。"],"oral_medication":["⚠️ 化疗后支持用药，按需选择，同类只选一种：","药物1（止吐）：","用法：昂丹司琼 8mg bid 或 阿瑞匹坦 80mg qd（d2～d3）；甲氧氯普胺 10mg tid（餐前）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物2（升白）：","用法：利可君 20mg tid 或 地榆升白片 4片 tid（轻中度）；rhG-CSF 皮下注射（中重度，遵医嘱）","药物3（口腔黏膜炎）：","用法：复方氯己定含漱液 含漱 tid；康复新液 含漱 tid；必要时利多卡因含漱（疼痛剧烈）","药物4（止泻/通便）：","用法：蒙脱石散 3g tid（腹泻）；乳果糖 15ml bid（便秘，避免用力排便）〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物5（抗感染预防，中性粒细胞缺乏者）：","用法：复方磺胺甲噁唑 2片 bid（预防肺孢子菌，每周3天）或 氟康唑 100mg qd（遵医嘱）","📌 所有支持用药须在医师指导下使用；出现发热（体温≥38.3℃或≥38℃持续1小时）立即就诊。"],"treatment":["预处理：止吐（5-HT3拮抗剂+地塞米松+NK-1拮抗剂）、抗过敏（紫杉醇/利妥昔单抗）、水化（顺铂/MTX）","输注管理：中心静脉或PICC输注发疱性药物；输注前后冲管；输注速度按方案（紫杉醇需3小时）","化疗后支持：止吐、升白、口腔护理、营养支持、水化与利尿（顺铂后24～48小时）","不良反应处理：按CTCAE分级处理——1～2级对症治疗，3～4级暂停化疗并积极处理，下周期减量","剂量调整：出现3～4级骨髓抑制、肝肾功能损害、严重黏膜炎等，下周期减量20%～25%或延迟","疗效评估：每2～3周期复查影像与肿瘤标志物，评估继续原方案或更换方案","中心静脉通路管理：PICC/CVC/输液港每周维护、冲管与封管（生理盐水10～20ml脉冲式冲管+肝素盐水封管）"],"management":["化疗前核对：患者身份、体表面积、药物名称与剂量、给药途径与顺序、过敏史，双人核对","输注观察：前15分钟每5分钟测生命体征并观察反应，之后每30分钟巡视一次","外渗预防与观察：输注中询问穿刺部位疼痛、观察有无肿胀、回血是否通畅；发现外渗立即停止并处理","化疗后随访：告知骨髓抑制低谷期（7～14天）注意事项，嘱每周复查血常规，出现发热立即就诊","记录与评估：记录化疗日期、剂量、不良反应分级与处理措施（供下周期剂量决策）","生活指导：口腔护理（软毛牙刷、含漱）、饮食卫生、避免去人群密集场所、注意休息"],"notes":["化疗药物外渗可致组织坏死（尤其蒽环类、长春碱类），必须经中心静脉输注并密切观察","中性粒细胞缺乏伴发热（FN）是化疗急症，需在1小时内经验性使用广谱抗生素","骨髓抑制低谷期一般为化疗后7～14天，此期间避免感染、避免剧烈活动与外伤","顺铂化疗后需充分水化24～48小时并监测电解质（低镁、低钾），防止肾损害","大剂量甲氨蝶呤必须按血药浓度进行亚叶酸钙解救并碱化尿液，否则可致严重黏膜炎与肾衰"],"emergency":["输注中出现呼吸困难、喉头水肿、血压下降（严重过敏反应）→ 立即停输、肌注肾上腺素、抗过敏抗休克","穿刺部位疼痛、肿胀、发红（药物外渗）→ 立即停止输注、回抽、按药物特性拮抗处理（如蒽环类用右雷佐生、长春碱类用透明质酸酶）","化疗后发热≥38.3℃伴中性粒细胞<0.5×10⁹/L（粒细胞缺乏伴发热）→ 1小时内经验性广谱抗生素，留取血培养"],"pinyin":"hltyyzycl","icd10":"Z51.1","physical_exam":["生命体征：体温（每4小时，警惕FN）、脉搏、呼吸、血压、血氧","输注部位：穿刺点有无红肿、疼痛、渗漏，回血与输液是否通畅，中心静脉置管位置","一般情况：精神状态、面色、营养状态、有无脱水","皮肤黏膜：有无皮疹、瘙痒（过敏）、口腔黏膜有无溃疡与真菌感染","心肺：心音与心率（蒽环类心脏毒性）、呼吸音（过敏反应、肺部感染）","腹部：肠鸣音、有无腹胀腹痛腹泻（化疗相关性腹泻/便秘）","四肢与神经：手足麻木、感觉异常（周围神经毒性）、手足皮肤改变（手足综合征）"],"lab_tests":["血常规+中性粒细胞绝对值：化疗后每2～3天复查，低谷期（7～14天）每日或隔日","肝肾功能+电解质（含镁、钾、钙）：每周期前及化疗后复查，顺铂方案需密切监测","尿常规+尿量：顺铂等肾毒性药物监测（尿量>100ml/h）","甲氨蝶呤血药浓度：大剂量MTX方案必须监测（决定亚叶酸钙解救）","心电图+心脏超声（LVEF）：蒽环类、曲妥珠单抗等方案定期复查","肿瘤标志物+增强CT/MRI：每2～3周期评估疗效（RECIST标准）","血培养（发热者）+降钙素原：粒细胞缺乏伴发热时立即留取"],"nursing":["输注护理：严格无菌操作，双人核对药物；发疱性药物经中心静脉输注，输注前后用生理盐水冲管","过敏观察：输注前15分钟床旁守候，观察皮疹、胸闷、呼吸困难，备好抢救药（肾上腺素、地塞米松）","外渗观察与处理：每15～30分钟观察穿刺部位，发现疼痛肿胀立即停止输注并保留针头回抽","骨髓抑制期护理：监测体温（≥38℃立即报告）、口腔护理（每日含漱）、保护性隔离、避免外伤与用力","止吐护理：化疗前30分钟给予止吐药，指导少量多餐、避免油腻，观察呕吐量与脱水征象","健康宣教：告知低谷期注意事项、按时复查血常规、出现发热/出血倾向立即就诊"],"diet":["少量多餐（每日5～6餐），清淡易消化，避免油腻、辛辣与过甜食物","高蛋白（鱼、瘦肉、蛋、奶、豆制品）、高维生素（新鲜蔬果）促进恢复","化疗前1～2小时避免进食；呕吐后及时补充水分与电解质（口服补液盐）","白细胞低时：食物充分加热、避免生食（刺身、沙拉、未消毒乳制品）、水果削皮","多饮水（每日2000ml以上，顺铂方案需更多），促进药物代谢产物排泄"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1335},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"632770ef6b272a7af6dfd0b35f08b41381b4db3d9681a58abc4956dc4da92680","pinyin":"hualiaotongyongyizhuyuyuchuli","initials":"hltyyzyycl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","化疗输注中：胸闷、心悸、皮疹、瘙痒、呼吸困难（过敏反应）；穿刺部位疼痛、肿胀（外渗）\\n化疗后24小时内：恶心、呕吐、乏力、食欲减退、发热\\n化疗后3～7天：口腔黏膜炎、腹泻或便秘、骨髓抑制（乏力、发热、出血倾向）\\n化疗后7～14天：白细胞与血小板降至最低（骨髓抑制低谷期），感染与出血风险最高\\n迟发性反应：手足综合征、周围神经毒性、脱发、肝肾功能异常",60],["摘要","化疗通用医嘱包括化疗前预处理（止吐、抗过敏、水化）、化疗药物输注医嘱、化疗后支持治疗与监测，是保证化疗安全实施的标准流程。不同方案的预处理与监测重点不同（如顺铂需水化、紫杉醇需抗过敏、大剂量MTX需亚叶酸钙解救）。",30],["疾病编码","Z51.1",30],["原首字母","hltyyzycl",60]]},{"id":"orders-f20951cee216918db6d3","key":"v1-c9ccc21dfe2a3058|orders-f20951cee216918db6d3","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化疗所致恶心呕吐（CINV）防治","category":"化疗","raw":{"name":"化疗所致恶心呕吐（CINV）防治","category":"化疗","summary":"化疗所致恶心呕吐（CINV）是最常见且最影响生活质量的化疗不良反应，按发生时间分为急性（化疗后24小时内）、延迟性（24～120小时）、预期性（化疗前）与爆发性（预防后仍出现）。防治原则是按致吐风险分级预防性用药（三联或四联方案）。","symptoms":["急性呕吐：化疗后数分钟至24小时内出现，多与5-HT3相关","延迟性呕吐：化疗后24～120小时（顺铂、环磷酰胺、蒽环类常见），多与NK-1/P物质相关","预期性呕吐：化疗前即出现（与既往化疗的 conditioning 有关），以抗焦虑与行为治疗为主","伴随症状：食欲减退、乏力、脱水、电解质紊乱（低钾低钠）、体重下降","严重者：频繁呕吐致食管黏膜撕裂（Mallory-Weiss）、误吸、肾功能损害"],"diagnosis":["评估致吐风险分级：高致吐（顺铂、环磷酰胺≥1500mg/m²、蒽环类+环磷酰胺）、中致吐、低致吐、轻微致吐","评估呕吐类型与分级（CTCAE）：1级（24小时内1～2次）、2级（3～5次）、3级（≥6次或需补液）、4级（危及生命）","电解质+肾功能：频繁呕吐者评估脱水与电解质紊乱","评估其他原因：脑转移、肠梗阻、高钙血症、胃肠炎、药物（阿片类）所致呕吐","评估既往CINV史与患者焦虑程度（预期性呕吐风险）"],"infusion":["⚠️ 按致吐风险选择方案，切勿全部同时使用！","方案1（高致吐方案，四联预防：NK-1+5-HT3+地塞米松+奥氮平）：","用法：阿瑞匹坦 125mg 口服 d1 + 80mg qd d2～d3；昂丹司琼 8mg 静推 化疗前30分钟；地塞米松 10～20mg 静推 d1（d2～d4 8mg qd）；奥氮平 5mg 口服 qn d1～d4〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案2（中致吐方案，三联预防）：","用法：昂丹司琼 8mg 静推 化疗前30分钟 + 地塞米松 10mg 静推 d1～d3〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案3（爆发性呕吐解救，每6小时可用一次，最多3次/日）：","用法：甲氧氯普胺 10mg 静推 q6h（必要时）+ 地塞米松 10mg 静推 q12h；或昂丹司琼 8mg 静推（如预防未用同类）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","方案4（补液纠正脱水）：","用法：0.9%氯化钠/葡萄糖 500～1000ml 静滴；补钾（见尿补钾）、维生素B6 200mg 静滴","📌 预防用药是关键——CINV应以“化疗前预防”为主，不能等呕吐后再给药；爆发性呕吐处理需换用不同机制药物。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（延迟性呕吐，口服）：","用法：阿瑞匹坦 80mg qd（d2～d3）或 奥氮平 5mg qn（d1～d4，注意嗜睡）","药物2（辅助止吐）：","用法：甲氧氯普胺 10mg tid（餐前30分钟）或 多潘立酮 10mg tid（餐前）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物3（5-HT3口服）：","用法：昂丹司琼 8mg bid 或 格拉司琼 2mg qd（含服/口服）〔调 ★ 肝功能不全减量；QT延长风险〕","药物4（中药/辅助）：","用法：生姜含服或姜茶（辅助减轻恶心）；维生素B6 10mg tid","📌 阿瑞匹坦与地塞米松合用时地塞米松需减量约50%（药物相互作用）；奥氮平慎用于老年与认知障碍患者。"],"treatment":["按致吐风险分级预防：高致吐方案用四联（NK-1+5-HT3+地塞米松+奥氮平），中致吐用三联，低致吐用单药","预防给药时机：化疗前30～60分钟给予，延迟性呕吐需持续用药至化疗后3～4天","爆发性呕吐：换用不同作用机制药物（如已用5-HT3则加NK-1或甲氧氯普胺），避免同类重复","预期性呕吐：抗焦虑药（劳拉西泮 0.5～1mg 化疗前夜与当日）、心理疏导、行为放松训练","补液与电解质：频繁呕吐者静脉补液、纠正低钾低钠、必要时补镁","非药物措施：清淡饮食、少量多餐、避免强烈气味、音乐放松、针灸/穴位按压（内关穴）","下周期调整：如预防失败，下一周期升级方案（加用NK-1或奥氮平）"],"management":["评估与记录：化疗前后每日评估恶心呕吐次数、性质与持续时间，按CTCAE分级记录","用药依从性：向患者强调按医嘱服用止吐药（尤其延迟性呕吐需连续用药3～4天）","饮食护理：化疗前2小时避免进食，少量多餐，清淡温凉食物，避免油腻甜食与强烈气味","补液与出入量：记录24小时出入量，频繁呕吐者监测电解质与尿量","心理支持：解释CINV可有效预防，减轻预期性呕吐；播放音乐、放松训练","观察并发症：呕吐物带血（食管撕裂）、误吸（老年/意识障碍者）、脱水与意识改变"],"notes":["CINV防治以『预防为主』——等出现呕吐再用药效果明显差于预防用药","延迟性呕吐（24小时后）常被忽视，顺铂、环磷酰胺、蒽环类方案必须持续预防至化疗后3～4天","阿瑞匹坦为CYP3A4抑制剂，与地塞米松、部分化疗药（伊立替康、长春碱类）有相互作用，需调整剂量","奥氮平可有效控制突破性呕吐但引起嗜睡，老年患者需谨慎","5-HT3拮抗剂可致便秘与QT间期延长，心脏病患者需监测心电图"],"emergency":["频繁呕吐伴脱水、低血压、少尿（3级以上CINV）→ 静脉补液纠正脱水与电解质紊乱","呕吐物呈咖啡色或鲜血（食管黏膜撕裂出血）→ 急诊内镜评估与止血","呕吐伴意识障碍、误吸（老年患者）→ 立即清理气道、防误吸性肺炎"],"pinyin":"hlscxetcinv","icd10":"R11","physical_exam":["生命体征：血压（脱水致低血压）、心率（增快）、体温","一般情况：脱水征（皮肤弹性差、口唇干燥、眼窝凹陷）、精神萎靡、体重变化","腹部：上腹压痛、腹胀、肠鸣音（活跃或减弱）、有无振水音（幽门梗阻）","神经系统：意识状态、有无颅内压增高征象（脑转移所致呕吐）","皮肤黏膜：口腔黏膜干燥程度、皮肤弹性、有无巩膜黄染","评估呕吐物性质：有无咖啡色/鲜红色（出血）、有无粪臭味（肠梗阻）","心理状态：焦虑程度、对化疗的恐惧（预期性呕吐）"],"lab_tests":["电解质（钾、钠、氯、镁、钙）：频繁呕吐者每1～2天复查，警惕低钾低钠低镁","肾功能+尿素氮：评估脱水所致肾前性氮质血症","血气分析：严重呕吐可致代谢性碱中毒（低氯低钾）","血常规：评估基础骨髓抑制情况（发热鉴别）","血糖：糖尿病患者的血糖波动（激素预处理可致高血糖）","必要时头颅CT/MRI：呕吐伴头痛、意识改变时排除脑转移/颅内压增高","腹部平片/CT：疑肠梗阻时（呕吐伴腹胀、停止排气排便）"],"nursing":["恶心呕吐评估：每次呕吐后记录时间、量、性状并报告，按CTCAE分级记录","止吐给药：严格按医嘱于化疗前30～60分钟给予止吐药，观察疗效与不良反应（便秘、头痛、嗜睡）","饮食护理：少量多餐、清淡温凉，避免油腻与强烈气味；呕吐后协助漱口、清洁环境","补液护理：遵医嘱补液并记录出入量，观察尿量与皮肤弹性改善情况","环境与心理护理：保持病室通风、无异味，播放轻音乐，指导放松与深呼吸，减轻焦虑","安全护理：呕吐时头偏一侧防误吸，呕吐后协助半卧位休息"],"diet":["化疗前2小时避免进食；少量多餐（每日5～6餐）","选择清淡、温凉、易消化食物（米粥、面条、苏打饼干、蒸蛋羹）","避免油腻、辛辣、过甜与气味浓烈食物（油炸、奶油、大蒜）","呕吐后漱口，30分钟后少量饮水或口服补液盐，逐步恢复进食","适量生姜、柠檬水可辅助减轻恶心；保证足够水分摄入"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1336},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8f24ce05a96c8d4bf8b7dde650428c6ecd5d69269bb6eab21a90812b5e7f1244","pinyin":"hualiaosuozhiexinoutu（CINV）fangzhi","initials":"hlszexot（fz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性呕吐：化疗后数分钟至24小时内出现，多与5-HT3相关\\n延迟性呕吐：化疗后24～120小时（顺铂、环磷酰胺、蒽环类常见），多与NK-1/P物质相关\\n预期性呕吐：化疗前即出现（与既往化疗的 conditioning 有关），以抗焦虑与行为治疗为主\\n伴随症状：食欲减退、乏力、脱水、电解质紊乱（低钾低钠）、体重下降\\n严重者：频繁呕吐致食管黏膜撕裂（Mallory-Weiss）、误吸、肾功能损害",60],["摘要","化疗所致恶心呕吐（CINV）是最常见且最影响生活质量的化疗不良反应，按发生时间分为急性（化疗后24小时内）、延迟性（24～120小时）、预期性（化疗前）与爆发性（预防后仍出现）。防治原则是按致吐风险分级预防性用药（三联或四联方案）。",30],["疾病编码","R11",30],["原首字母","hlscxetcinv",60]]},{"id":"orders-21800aafb2117e20aa45","key":"v1-c9ccc21dfe2a3058|orders-21800aafb2117e20aa45","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化疗后骨髓抑制与粒细胞缺乏伴发热","category":"化疗","raw":{"name":"化疗后骨髓抑制与粒细胞缺乏伴发热","category":"化疗","summary":"骨髓抑制是化疗最常见剂量限制性毒性，表现为白细胞/中性粒细胞、血小板、血红蛋白下降，白细胞低谷一般在化疗后7～14天。中性粒细胞缺乏伴发热（FN，中性粒细胞<0.5×10⁹/L且体温≥38.3℃或≥38℃持续1小时）是肿瘤急症，需在1小时内经验性广谱抗生素治疗。","symptoms":["乏力、倦怠、活动后心悸气短（贫血）","发热（FN：单次≥38.3℃或≥38℃持续1小时），可伴寒战","皮肤黏膜出血：牙龈出血、鼻出血、皮下瘀斑、血尿、黑便（血小板减少）","口腔溃疡、咽痛、咳嗽、腹泻、肛周疼痛（感染灶常不典型，因炎症反应被抑制）","严重者出现脓毒症休克、意识改变、呼吸衰竭"],"diagnosis":["血常规（含中性粒细胞绝对值ANC）：化疗后每2～3天复查，低谷期每日或隔日；ANC<0.5×10⁹/L为粒细胞缺乏","血培养（需氧+厌氧）×2套+尿培养+痰培养：发热时立即留取（抗生素使用前）","CRP+PCT：评估感染程度与细菌感染可能","胸片/胸部CT：发热伴呼吸道症状者（肺部感染常见但影像可延迟出现）","肝肾功能+电解质：评估感染与药物影响","骨髓穿刺+活检（必要时）：骨髓抑制持续不恢复者，评估骨髓储备与肿瘤浸润","口腔、肛周、置管部位检查：寻找感染灶（粒细胞缺乏时局部炎症体征轻）"],"infusion":["⚠️ 抢救用药，FN需在1小时内经验性使用广谱抗生素！","","方案1（FN经验性抗感染，单药，抗铜绿假单胞菌）：","  用法：哌拉西林他唑巴坦 4.5g（NS 100ml 或 5%GS 100ml）静滴 q6～8h 或 头孢吡肟 2g 静滴 q8h 或 美罗培南 1g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案2（重症/血流动力学不稳/疑耐药）：","  用法：美罗培南 1g（NS 100ml）静滴 q8h + 万古霉素 1g 静滴 q12h（或利奈唑胺 0.6g q12h）± 阿米卡星〔调 ★★ 按 CrCl 调量并监测谷浓度10-20mg/L；耳肾毒性〕","","方案3（升白治疗）：","  用法：rhG-CSF 5μg/kg 皮下注射 qd（或聚乙二醇化rhG-CSF 6mg 单次）至ANC>2.0×10⁹/L","","方案4（支持治疗）：","  用法：0.9%氯化钠/葡萄糖 静滴补液；血小板<10×10⁹/L或有出血时输注血小板；Hb<70g/L输注红细胞；必要时丙种球蛋白","","📌 FN患者应在抗生素前留取血培养，1小时内给药；升白针需在化疗后24～48小时之后使用（过早使用影响骨髓恢复）。"],"oral_medication":["⚠️ FN患者口服用药为辅，需遵医嘱：","药物1（口服升白，轻中度骨髓抑制）：","用法：利可君 20mg tid 或 地榆升白片 4片 tid（疗程2～4周）","药物2（预防感染）：","用法：复方磺胺甲噁唑 2片 bid（每周3天，预防肺孢子菌）；氟康唑 100mg qd（真菌预防，遵医嘱）","药物3（口腔护理）：","用法：复方氯己定含漱液 含漱 tid；康复新液 10ml 含漱/口服 tid","药物4（止血辅助，血小板减少）：","用法：氨甲环酸片 0.5g tid（出血时，遵医嘱）；维生素C 0.2g tid〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","📌 中性粒细胞缺乏期避免服用可能掩盖感染的退热药（如自行服对乙酰氨基酚），发热必须立即就医。"],"treatment":["FN处理：立即留取血培养（双套）+经验性广谱抗生素（1小时内），覆盖铜绿假单胞菌","升白治疗：rhG-CSF（G-CSF）皮下注射至ANC恢复；高危患者下一周期预防性使用","抗生素调整：48～72小时评估疗效，明确病原体后降阶梯治疗；持续发热>4～7天加抗真菌（棘白菌素类/唑类）","血制品支持：血小板<10×10⁹/L或有出血倾向时输注血小板；Hb<70g/L或症状明显时输注红细胞","隔离防护：保护性隔离（单间/层流床）、限制探视、严格手卫生、避免鲜花与生食","下周期剂量调整：发生FN者，下一周期化疗减量20%～25%或延迟，并预防性使用G-CSF","寻找并处理感染灶：口腔、肛周、中心静脉置管、肺部、腹腔（粒细胞缺乏时体征可轻微）"],"management":["体温监测：化疗后低谷期每日测体温2～4次，出现发热（≥38℃）立即报告并处理","严密观察感染征象：咽痛、咳嗽、腹泻、肛周疼痛、置管部位红肿（局部炎症反应可被抑制）","血常规监测：化疗后第7～14天为重点监测期，隔日复查直至恢复","保护性隔离：住单间或层流床，限制探视，进入病房戴口罩、严格手卫生","口腔与肛周护理：软毛牙刷、每日含漱、便后坐浴清洁，避免测肛温与灌肠","心理护理与宣教：向患者说明低谷期风险，出现发热立即告知医护人员，不可自行用退热药"],"notes":["FN是肿瘤急症，1小时内经验性抗感染可显著降低病死率，不可等待血培养结果","粒细胞缺乏时感染局部炎症反应常缺失（无脓、无红肿），必须主动寻找感染灶","G-CSF应在化疗结束后24～48小时开始使用，与化疗同时使用会加重骨髓抑制","血小板<20×10⁹/L时避免肌注、灌肠、测肛温等有创操作，防止出血","反复FN或骨髓抑制延迟恢复者，需评估骨髓储备，考虑减量或更换方案"],"emergency":["体温≥38.3℃或≥38℃持续1小时伴ANC<0.5×10⁹/L（FN）→ 立即血培养+1小时内广谱抗生素","血压下降、意识改变、乳酸升高（脓毒症休克）→ 立即抢救、补液、升压药、转ICU","血小板<10×10⁹/L伴活动性出血（牙龈、鼻、消化道、颅内）→ 立即输注血小板并止血处理"],"pinyin":"hlhgsyyljlfbfr","icd10":"D70","physical_exam":["生命体征：体温（每4小时）、脉搏、呼吸、血压、血氧（脓毒症筛查）","一般情况：精神萎靡、面色苍白（贫血）、皮肤湿冷、脱水征","皮肤黏膜：出血点、瘀斑、牙龈出血、口腔黏膜溃疡与真菌感染（鹅口疮）","口腔与咽部：溃疡、红肿、扁桃体（粒细胞缺乏时可不明显）、有无吞咽疼痛","肛周：红肿、压痛、肛裂、脓肿（避免直肠指检与测肛温）","中心静脉置管部位：红肿、渗出、压痛（导管相关感染）","心肺：呼吸音（肺部感染）、心率心律（贫血、感染致心率增快）"],"lab_tests":["血常规+中性粒细胞绝对值（ANC）：低谷期每日或隔日复查，直至ANC>2.0×10⁹/L","血培养（需氧+厌氧，双套，外周+中心静脉）+尿培养+痰培养：发热时立即留取（抗生素前）","CRP+降钙素原（PCT）：评估感染程度与治疗反应","肝肾功能+电解质+乳酸：评估器官功能与灌注（脓毒症）","胸部CT：发热伴呼吸道症状者（胸片对粒细胞缺乏者敏感性低）","G试验/GM试验：疑真菌感染时","骨髓穿刺+活检（骨髓抑制延迟恢复者）：评估骨髓造血功能与有无肿瘤浸润"],"nursing":["发热护理：低谷期每4小时测体温，发热立即报告并配合留取培养、按时给予抗生素（1小时内）","保护性隔离：住单间/层流床、限制探视、戴口罩、严格手卫生，病室每日通风消毒","口腔护理：软毛牙刷、每餐后含漱（复方氯己定/康复新液），观察口腔黏膜与有无真菌感染","肛周与皮肤护理：便后温水清洗坐浴，保持干燥；避免测肛温、灌肠与肌注（血小板低时）","出血观察：皮肤瘀斑、牙龈鼻出血、尿便颜色、注射点渗血，异常立即报告","饮食护理：食物充分加热、水果削皮、避免生冷与不洁食物，保证高蛋白高热量摄入"],"diet":["高蛋白、高热量、高维生素饮食促进骨髓恢复（鱼、瘦肉、蛋、奶、动物肝脏）","食物必须充分加热煮熟；禁生食（刺身、沙拉、溏心蛋）、禁未消毒乳制品与生水","水果选择可削皮者（苹果、香蕉、橙子），避免草莓、葡萄等不易清洗的水果","贫血者增加含铁食物（动物肝脏、红肉、菠菜）并遵医嘱补充铁剂/叶酸","血小板低者避免坚硬、粗糙、带刺食物（防口腔与消化道出血），食物宜软烂"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1337},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"fdcde4f236d044cbca8e39b7f801d57665bdfc4e4d60604d6a463783854c61d9","pinyin":"hualiaohougusuiyizhiyulixibaoquefabanfare","initials":"hlhgsyzylxbqfbfr","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、倦怠、活动后心悸气短（贫血）\\n发热（FN：单次≥38.3℃或≥38℃持续1小时），可伴寒战\\n皮肤黏膜出血：牙龈出血、鼻出血、皮下瘀斑、血尿、黑便（血小板减少）\\n口腔溃疡、咽痛、咳嗽、腹泻、肛周疼痛（感染灶常不典型，因炎症反应被抑制）\\n严重者出现脓毒症休克、意识改变、呼吸衰竭",60],["摘要","骨髓抑制是化疗最常见剂量限制性毒性，表现为白细胞/中性粒细胞、血小板、血红蛋白下降，白细胞低谷一般在化疗后7～14天。中性粒细胞缺乏伴发热（FN，中性粒细胞<0.5×10⁹/L且体温≥38.3℃或≥38℃持续1小时）是肿瘤急症，需在1小时内经验性广谱抗生素治疗。",30],["疾病编码","D70",30],["原首字母","hlhgsyyljlfbfr",60]]},{"id":"orders-7ba41f3e864e57eb3a58","key":"v1-c9ccc21dfe2a3058|orders-7ba41f3e864e57eb3a58","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化疗药物外渗处理","category":"化疗","raw":{"name":"化疗药物外渗处理","category":"化疗","summary":"化疗药物外渗指发疱性或刺激性药物漏出血管进入周围组织，可致局部剧痛、组织坏死、溃疡与功能障碍。蒽环类（多柔比星、表柔比星）、长春碱类（长春新碱、长春瑞滨）外渗后果最严重，需立即停止输注并现场按药物特性处理。","symptoms":["输注部位疼痛、烧灼感、刺痛（最早出现的症状）","局部肿胀、发红、皮肤紧绷，输液速度变慢或回血不畅","数小时至数天后出现水疱、皮肤变色（苍白/紫红/发黑）、硬结","后期：组织坏死、溃疡形成、经久不愈，可累及肌腱与神经致功能障碍","全身反应：发热、白细胞升高（继发感染）"],"diagnosis":["立即评估：外渗药物种类、浓度、量、外渗范围与时间（决定处理方式）","局部体征：红肿范围（厘米）、皮温、颜色、疼痛评分、有无水疱与坏死","外渗分级（CTCAE）：1级（皮肤红斑、无痛）、2级（红斑伴疼痛、肿胀）、3级（水疱、溃疡、坏死，需手术）、4级（危及肢体功能）","必要时超声：评估皮下组织受累范围与积液","血常规+CRP：继发感染时（后期）","记录并拍照：外渗部位、范围与演变过程（医疗文书与随访依据）"],"infusion":["⚠️ 外渗处理用药按药物特性选择，切勿全部同时使用！","方案1（蒽环类外渗解毒，右雷佐生）：","用法：右雷佐生 1000mg/m²（最大2000mg）+ 0.9%氯化钠 500ml 静滴（外渗后6小时内，越快越好，第1天），第2、3天各500mg/m²","方案2（长春碱类外渗，透明质酸酶）：","用法：透明质酸酶 150～900IU + 0.9%氯化钠 1～3ml 局部皮下注射（沿外渗边缘多点注射）","方案3（局部封闭与抗炎）：","用法：地塞米松 5mg + 利多卡因 2ml 局部环形封闭（非蒽环类可用；蒽环类避免局部激素）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案4（补液/抗感染，继发感染或坏死）：","用法：0.9%氯化钠 静滴；头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 CrCl<30 减量；青霉素过敏禁用〕","📌 处理原则：立即停止输注（不拔针，先回抽3～5ml药液）、按药物选用拮抗剂、局部冷敷或热敷（蒽环类冷敷、长春碱类热敷）、抬高患肢、密切观察。"],"oral_medication":["⚠️ 外渗后辅助用药（按医嘱）：","药物1（镇痛）：","用法：塞来昔布 200mg bid 或 洛索洛芬钠 60mg tid（餐后）；剧痛者曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（抗感染，水疱破溃/溃疡）：","用法：头孢氨苄 0.5g qid 或 阿莫西林克拉维酸 0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物3（局部用药）：","用法：喜辽妥（多磺酸粘多糖乳膏）外用 bid（后期）；莫匹罗星软膏 外用（有感染时）","📌 禁自行热敷/冷敷（须按药物类型由医护决定）；禁按摩、禁挤压外渗部位。"],"treatment":["立即停止输注，保留针头并回抽3～5ml血液/药液（减少局部药量），再拔针","局部处理：蒽环类→冷敷（15～20分钟/次，q4h，共24～48小时）+ 右雷佐生；长春碱类→热敷（促进药物扩散）+ 透明质酸酶局部注射","解毒剂局部封闭：非蒽环类可用地塞米松+利多卡因环形封闭（蒽环类区域避免局部糖皮质激素）","抬高患肢（48小时内）促进回流，避免局部受压与按摩","观察与随访：外渗后24～72小时为坏死进展期，每日评估、拍照记录；水疱处理与大疱抽液需无菌操作","外科处理：出现溃疡、坏死、经久不愈者行清创术，必要时皮瓣移植；功能障碍者康复治疗","抗感染与止痛：预防继发感染，充分镇痛","上报与记录：按不良事件上报，详细记录外渗药物、处理过程与随访结果"],"management":["立即报告主管医师与护士长，启动外渗处理流程，保留药物安瓿与输液器（必要时送检）","局部评估与记录：每2～4小时观察红肿范围、颜色、疼痛与皮温变化并记录、拍照","换药护理：水疱保持完整（防感染），破溃后无菌换药，按医嘱使用敷料","疼痛管理：评估疼痛评分，遵医嘱镇痛，避免局部受压","心理护理：外渗可致组织坏死与长期换药，患者焦虑明显，需解释处理方案与预后","随访：出院后每周随访至愈合（外渗损伤可能延迟数周出现），记录愈合情况","预防再发：该侧肢体避免再次穿刺；后续化疗改用PICC/输液港（发疱性药物必须中心静脉）"],"notes":["发疱性化疗药物（蒽环类、长春碱类）必须经PICC/CVC/输液港输注，禁止外周小静脉推注","外渗处理≤6小时是关键窗口，越早处理组织坏死范围越小","右雷佐生是蒽环类外渗的特效解毒剂，需在6小时内使用","蒽环类外渗禁局部冷敷与激素（部分指南建议右雷佐生+冷敷）；长春碱类需热敷","外渗损伤可延迟出现，需随访数周至数月，不可因初期症状轻而忽视"],"emergency":["外渗后局部剧痛、迅速肿胀伴水疱（3级以上）→ 立即按药物特性解毒处理并请外科会诊","外渗部位皮肤发黑、坏死、溃疡经久不愈 → 整形/骨科会诊，评估手术清创","继发感染伴发热、红肿扩展 → 抗感染并评估坏死性筋膜炎风险"],"pinyin":"hlxywscsl","icd10":"T80.8","physical_exam":["局部外渗区：范围（以厘米记录，画线标记）、红肿、皮温、颜色（苍白/紫红/发黑）、有无水疱","疼痛评估：疼痛评分（NRS 0～10）、性质（灼痛/刺痛）、对镇痛药的反应","末梢循环：远端动脉搏动、毛细血管充盈时间、手指/足趾温度与感觉","神经功能：感觉异常、肌力（外渗累及神经与肌腱时）","肢体肿胀：与对侧对比周径，抬高患肢后肿胀变化","全身评估：体温、有无淋巴结肿大与发热（继发感染）","输液通路检查：中心静脉置管位置、回血与通畅度（判断有无其他外渗风险）"],"lab_tests":["血常规+CRP：外渗后1周开始评估有无继发感染（水疱破溃、溃疡）","凝血功能：拟手术清创者术前评估","肝肾功能+电解质：评估全身状态与用药安全","局部超声：评估皮下组织受累范围、有无积液与脓肿","细菌培养（破溃分泌物）：指导抗感染用药","必要时MRI：评估深部组织（肌腱、神经、骨）受累范围"],"nursing":["立即处理：停止输注、保留针头回抽药液、报告医师，按医嘱局部冷敷/热敷与解毒剂处理","观察记录：每2～4小时观察并记录外渗范围（画线标记）、颜色、疼痛与皮温，拍照留存","患肢护理：抬高患肢、避免受压与按摩、避免在该侧肢体测血压与穿刺","疼痛与换药护理：评估疼痛并镇痛，水疱保持完整，破溃后无菌换药，观察感染征象","心理护理：解释处理方案与可能病程，减轻焦虑与恐惧；随访期间保持联系","预防措施：后续化疗应用中心静脉通路，输注中每15～30分钟巡视穿刺部位"],"diet":["高蛋白、高维生素饮食促进组织修复（鱼、瘦肉、蛋、奶、新鲜蔬果）","充足饮水（每日2000ml以上），促进化疗药物代谢产物排泄","避免辛辣刺激与酒类（加重局部炎症与血管扩张）","保证足够热量摄入，必要时口服营养补充剂（创面愈合需较多营养）","控制血糖（糖尿病患者），高血糖会延缓创面愈合"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1338},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"16389ff08bfe09a66b190957dc308d653346d57e30d4706974f61b32ce8ac65f","pinyin":"hualiaoyaowuwaishenchuli","initials":"hlywwscl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","输注部位疼痛、烧灼感、刺痛（最早出现的症状）\\n局部肿胀、发红、皮肤紧绷，输液速度变慢或回血不畅\\n数小时至数天后出现水疱、皮肤变色（苍白/紫红/发黑）、硬结\\n后期：组织坏死、溃疡形成、经久不愈，可累及肌腱与神经致功能障碍\\n全身反应：发热、白细胞升高（继发感染）",60],["摘要","化疗药物外渗指发疱性或刺激性药物漏出血管进入周围组织，可致局部剧痛、组织坏死、溃疡与功能障碍。蒽环类（多柔比星、表柔比星）、长春碱类（长春新碱、长春瑞滨）外渗后果最严重，需立即停止输注并现场按药物特性处理。",30],["疾病编码","T80.8",30],["原首字母","hlxywscsl",60]]},{"id":"orders-29d0aebd96fe4ce464f5","key":"v1-c9ccc21dfe2a3058|orders-29d0aebd96fe4ce464f5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"常用化疗方案速查","category":"化疗","raw":{"name":"常用化疗方案速查","category":"化疗","summary":"常用化疗方案速查汇总常见实体瘤与血液肿瘤的经典化疗方案（药物组成、给药周期、主要毒性），供临床参考。具体方案与剂量须结合指南、患者体表面积、脏器功能与既往治疗调整，实际用药以主管医师医嘱为准。","symptoms":["本条目为方案速查，非症状描述——可结合方案对应的不良反应（骨髓抑制、恶心呕吐、神经毒性、心脏毒性、肾毒性）进行查阅","常见共性反应：乏力、食欲减退、脱发、骨髓抑制、口腔黏膜炎","方案特异反应：顺铂（肾毒性、耳毒性、呕吐）、奥沙利铂（遇冷加重周围神经毒性）、紫杉醇（过敏、神经毒性）、蒽环类（心脏毒性）、伊立替康（延迟性腹泻）、氟尿嘧啶（手足综合征、腹泻）","免疫治疗：免疫相关不良反应（皮疹、结肠炎、肝炎、甲状腺功能异常、肺炎）"],"diagnosis":["用药前：病理确诊+分期+TNM、体能状态（ECOG）、脏器功能评估（血常规、肝肾功能、心电图、LVEF）","方案选择依据：瘤种与分期、指南推荐（CSCO/NCCN）、既往治疗与疗效、基因检测（靶向/免疫相关标志物：EGFR、ALK、ROS1、MSI/dMMR、PD-L1、HER2、BRCA）","剂量计算：体表面积（BSA，Mosteller公式）或按体重（AUC，卡铂按Calvert公式）","疗效评估：每2～3周期复查影像（RECIST 1.1）与肿瘤标志物","毒性评估：按CTCAE 5.0分级，决定是否减量、延迟或停药"],"infusion":["⚠️ 以下为常见方案示例，具体剂量与用法必须按指南与患者情况由主诊医师确定！","","方案1（非小细胞肺癌，含铂双药）：","  用法：培美曲塞 500mg/m²（NS 250-500ml；禁用含塑化剂容器；按说明书预处理）静滴 d1（非鳞癌）+ 顺铂 75mg/m² 静滴 d1（需水化止吐），q21d；或 紫杉醇 175mg/m² + 卡铂 AUC 5～6，q21d","","方案2（胃癌/食管癌）：","  用法：奥沙利铂 130mg/m² 静滴 d1 + 卡培他滨 1000mg/m² 口服 bid d1～14，q21d（XELOX）；或 SOX（替吉奥+奥沙利铂）","","方案3（结直肠癌）：","  用法：mFOLFOX6（奥沙利铂85mg/m² + 亚叶酸钙400mg/m² + 5-FU 400mg/m² 静推 + 5-FU 2400mg/m² 持续泵入46h），q14d；或 FOLFIRI（伊立替康180mg/m²）","","方案4（乳腺癌）：","  用法：AC-T（多柔比星60mg/m² + 环磷酰胺600mg/m² q21d×4 → 多西他赛100mg/m² q21d×4）；或 TAC 方案","","方案5（弥漫大B细胞淋巴瘤，R-CHOP）：","  用法：利妥昔单抗 375mg/m² + 环磷酰胺750mg/m² + 多柔比星50mg/m² + 长春新碱1.4mg/m²（max 2mg）d1 + 泼尼松100mg qd d1～5，q21d〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","","📌 以上均为示例，剂量须按指南版本与患者情况调整；发疱性药物（蒽环类、长春碱类）必须经中心静脉输注。"],"oral_medication":["⚠️ 常用口服化疗药与支持用药（按医嘱）：","药物1（口服氟尿嘧啶类）：","用法：卡培他滨 1000～1250mg/m² bid（早晚餐后30分钟，d1～14，q21d）；替吉奥 40～60mg bid（按BSA，d1～14，q21d）","药物2（口服靶向药）：","用法：吉非替尼 250mg qd 或 厄洛替尼 150mg qd 或 奥希替尼 80mg qd（EGFR突变NSCLC，空腹或随餐固定时间）","药物3（止吐/支持）：","用法：昂丹司琼 8mg bid；甲氧氯普胺 10mg tid；利可君 20mg tid〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物4（手足综合征防治）：","用法：维生素B6 100mg tid（卡培他滨/索拉非尼）；尿素软膏 外用 bid","📌 口服化疗药需按时按量服用，漏服不可自行加倍；卡培他滨与食物同服可减轻胃肠反应。"],"treatment":["方案执行：严格按方案的时间、顺序与速度给药（如FOLFOX中奥沙利铂 85mg/m² 静滴2h 需先于5-FU，5-FU 400mg/m² 静推+2400mg/m² 持续泵入46小时）","预处理：按方案给予止吐（昂丹司琼 8mg 静推）、抗过敏（紫杉醇前地塞米松 20mg 口服）、水化（顺铂前生理盐水 1000ml 静滴）、亚叶酸钙解救（大剂量MTX后 15mg/m² 静滴 q6h）","剂量调整：出现3～4级毒性时下周期减量20%～25%；肝功能异常时蒽环类、紫杉类、长春碱类减量","疗效评估与方案转换：每2～3周期评估，进展则更换二线方案或进入临床试验","维持治疗：一线治疗获益后（如非鳞NSCLC）可用培美曲塞 500mg/m² 静滴 q3w 或靶向药维持","靶向与免疫联合：按基因检测结果选择（EGFR/ALK/ROS1/HER2/PD-L1/MSI），免疫治疗需筛查自身免疫病与感染","支持治疗：止吐、升白、营养支持、心理支持贯穿全程"],"management":["建立化疗方案记录表：方案名称、药物剂量、给药日期、周期数、不良反应（便于随访与调整）","输注顺序与时间管理：部分方案对顺序敏感（如FOLFOX/FOLFIRI），须严格按方案执行并使用输液泵","监测计划：每周期前血常规+肝肾功能，方案相关特殊监测（心电图/LVEF、听力、神经毒性评估）","患者宣教：方案预期疗程、常见不良反应与应对、何时需立即就医（发热、出血、严重腹泻）","多学科协作：肿瘤内科、外科、放疗科、病理科、影像科共同制定与调整方案","临床试验与患者意愿：告知可选方案与临床试验机会，尊重患者选择"],"notes":["本条目为速查工具，实际化疗方案必须依据最新指南与患者个体情况（病理、分期、基因、体能、脏器功能）确定","卡铂剂量按Calvert公式（AUC×[GFR+25]）计算，不用体表面积；顺铂需按肌酐清除率调整","伊立替康可致急性胆碱能综合征（输注中腹痛腹泻，用阿托品）与延迟性腹泻（48小时后，用洛哌丁胺）","奥沙利铂周围神经毒性遇冷加重，化疗后3～5天避免冷饮、冷水洗手","含蒽环类方案需计算累积剂量并监测LVEF；曲妥珠单抗与蒽环类联用增加心脏毒性"],"emergency":["输注中过敏反应（紫杉醇、利妥昔单抗、铂类）→ 立即停止输注并按过敏反应抢救","化疗后发热伴中性粒细胞缺乏（FN）→ 1小时内经验性抗生素","伊立替康急性胆碱能综合征（输注中腹痛、大汗、腹泻）→ 阿托品 0.25～0.5mg 皮下注射","严重腹泻（≥7次/日）或血性腹泻 → 立即停用化疗药、补液、奥曲肽/洛哌丁胺，评估中性粒细胞"],"pinyin":"cyhlfaSC","icd10":"Z51.1","physical_exam":["生命体征与体能状态：体温、血压、体重、ECOG评分（每周期化疗前记录）","浅表淋巴结与肿瘤灶：评估可测量病灶变化（疗效评价）","心肺：心界、心率心律（蒽环类心脏毒性）、呼吸音（肺部病灶、免疫性肺炎）","腹部：肝脾大小、腹块、腹水（疗效与肝转移评估）","神经系：四肢感觉（紫杉类、奥沙利铂、长春碱类神经毒性）、腱反射、肌力","皮肤黏膜：手足皮肤改变（手足综合征）、皮疹（靶向/免疫治疗）、口腔黏膜炎","静脉通路：PICC/输液港/中心静脉置管位置与维护情况"],"lab_tests":["血常规（含ANC）：每周期前必查，低谷期每2～3天复查","肝功能（ALT/AST/胆红素）+肾功能（肌酐/肌酐清除率）：每周期前复查，决定剂量调整","心电图+心脏超声（LVEF）：蒽环类、曲妥珠单抗、氟尿嘧啶类方案定期复查","肿瘤标志物（按瘤种）+增强CT/MRI：基线及每2～3周期评估疗效","基因检测（组织/血液）：EGFR、ALK、ROS1、HER2、MSI/dMMR、PD-L1、BRCA、RAS/BRAF等","电解质（含镁、钾、钙）+尿常规：顺铂、大剂量MTX方案密切监测","听力检查（顺铂方案）：基线及必要时复查（耳毒性）"],"nursing":["方案核对：双人核对方案名称、药物、剂量（按BSA或AUC计算）、给药顺序与时间","输注管理：使用输液泵控制速度（5-FU持续泵入46小时需专用泵与管路），按时巡视并记录","通路维护：PICC/CVC/输液港每周维护，冲管封管规范，发疱性药物经中心静脉输注","毒性观察：按方案特点重点观察（伊立替康腹泻、奥沙利铂冷敏感、紫杉醇过敏、蒽环类心律）","宣教与随访：告知家庭护理要点（腹泻用药、手足护理、体温监测）与复诊时间","心理支持：长期治疗易疲劳抑郁，鼓励表达并提供支持资源"],"diet":["高蛋白、高热量、易消化饮食，少量多餐（每日5～6餐）","化疗当日清淡饮食，避免油腻、辛辣与强烈气味食物","伊立替康/氟尿嘧啶方案：避免生冷、高纤维与乳制品（减轻腹泻）","奥沙利铂方案：化疗后3～5天禁冷饮、冷食（防喉部与肢体冷敏感加重）","卡培他滨/索拉非尼方案：补充维生素B6，避免长时间热水浸泡与摩擦手足（防手足综合征加重）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1339},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"cf3bebc76e41914e46c875967ce90dbe70e76c693ee086e21e70f2a1278b6671","pinyin":"changyonghualiaofangansucha","initials":"cyhlfasc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","本条目为方案速查，非症状描述——可结合方案对应的不良反应（骨髓抑制、恶心呕吐、神经毒性、心脏毒性、肾毒性）进行查阅\\n常见共性反应：乏力、食欲减退、脱发、骨髓抑制、口腔黏膜炎\\n方案特异反应：顺铂（肾毒性、耳毒性、呕吐）、奥沙利铂（遇冷加重周围神经毒性）、紫杉醇（过敏、神经毒性）、蒽环类（心脏毒性）、伊立替康（延迟性腹泻）、氟尿嘧啶（手足综合征、腹泻）\\n免疫治疗：免疫相关不良反应（皮疹、结肠炎、肝炎、甲状腺功能异常、肺炎）",60],["摘要","常用化疗方案速查汇总常见实体瘤与血液肿瘤的经典化疗方案（药物组成、给药周期、主要毒性），供临床参考。具体方案与剂量须结合指南、患者体表面积、脏器功能与既往治疗调整，实际用药以主管医师医嘱为准。",30],["疾病编码","Z51.1",30],["原首字母","cyhlfaSC",60]]},{"id":"orders-a4493061bb29b4700a55","key":"v1-c9ccc21dfe2a3058|orders-a4493061bb29b4700a55","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肿瘤溶解综合征防治","category":"化疗","raw":{"name":"肿瘤溶解综合征防治","category":"化疗","summary":"肿瘤溶解综合征（TLS）是大量肿瘤细胞快速破坏、细胞内物质（钾、磷、核酸）释放入血引起的代谢紊乱，表现为高钾、高磷、高尿酸、低钙及急性肾损伤，多见于高负荷、高增殖的血液肿瘤（淋巴瘤、白血病）化疗后12～72小时。防治核心是水化、别嘌醇/拉布立酶、监测电解质。","symptoms":["恶心、呕吐、乏力、食欲减退（早期非特异）","少尿、水肿（急性肾损伤），尿色深或呈茶色（尿酸结晶）","心律失常、心悸（高钾血症）、手足抽搐、抽搐（低钙血症）","肌肉痉挛、感觉异常（低钙）、意识改变、嗜睡","严重者出现急性肾衰竭、心律失常致猝死"],"diagnosis":["血钾：>6.0mmol/L为高危；高钾是最危险的表现（可致心脏骤停）","血磷：>1.45mmol/L（儿童>1.94mmol/L）为异常，高磷加重低钙与肾损害","血尿酸：>476μmol/L为高危；尿酸结晶沉积致急性肾损伤","血钙：低钙（<1.75mmol/L）伴症状","肾功能（肌酐、尿素氮）+尿量：评估急性肾损伤（AKI）","LDH：>2倍正常上限提示高肿瘤负荷、TLS风险高","心电图：高钾致T波高尖、QRS增宽、PR延长（危急）","Cairo-Bishop标准：符合≥2项实验室异常即可诊断TLS"],"infusion":["⚠️ TLS防治用药，须尽早使用！","方案1（水化，核心措施）：","用法：0.9%氯化钠 2～3L/m²/日 静滴（化疗前24～48小时开始，化疗后持续48～72小时），维持尿量>80～100ml/h；必要时呋塞米 20～40mg 静推（尿量不足时，避免用于高尿酸未控者）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","方案2（降尿酸，拉布立酶，高危首选）：","用法：拉布立酶 0.2mg/kg 静滴 qd（化疗前，疗程3～7天）；G6PD缺乏者禁用","方案3（纠正高钾，紧急）：","用法：10%葡萄糖酸钙 10ml 缓慢静推（心脏保护，低钙有症状时慎用）；胰岛素 10U + 50%葡萄糖 50ml 静滴；呋塞米 20～40mg 静推；必要时血液透析〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","方案4（碱化尿液，慎用）：","用法：5%碳酸氢钠 125ml 静滴（尿pH目标7.0～7.5，仅在无高磷时可考虑；高磷时碱化加重磷酸钙沉积）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","📌 拉布立酶优于别嘌醇（起效快、不需碱化尿液）；水化是防治基础，尿量目标>100ml/h。"],"oral_medication":["⚠️ TLS预防口服用药（按医嘱）：","药物1（抑制尿酸生成）：","用法：别嘌醇 100mg tid（或300mg qd，肾功能不全减量至50～100mg/日）；注意皮疹与过敏","药物2（降钾树脂，轻中度高钾）：","用法：聚苯乙烯磺酸钙散 15g tid（口服或灌肠）","药物3（纠正低钙，有症状时）：","用法：碳酸钙D3 600mg tid（无症状低钙不必积极补钙，避免加重钙磷沉积）","药物4（补液/碱化，轻症）：","用法：枸橼酸钾钠颗粒 1袋 tid（碱化尿液，遵医嘱）","📌 别嘌醇与拉布立酶不可同时使用（别嘌醇影响拉布立酶代谢）；别嘌醇过敏者可致重症药疹（HLA-B*5801阳性者禁用）。"],"treatment":["高危识别与预防：高肿瘤负荷（LDH>2倍、巨大肿块、白细胞>25×10⁹/L）者化疗前即开始水化与降尿酸治疗","水化：化疗前24～48小时开始，静脉补液2～3L/m²/日，维持尿量>100ml/h，化疗后持续48～72小时","降尿酸：高危用拉布立酶；低危用别嘌醇（化疗前2～3天开始）","电解质管理：高钾（降钾治疗+必要时透析）、高磷（限磷饮食+磷酸盐结合剂+水化）、低钙（仅症状性补钙）","急性肾损伤处理：水化、避免肾毒性药物、必要时血液透析（指征：血钾>6.5mmol/L、少尿/无尿、严重酸中毒、容量负荷过重）","监测频率：高危者化疗后每4～6小时查电解质与肾功能（至少前72小时）","化疗方案调整：极高危患者可先减量化疗（gradual debulking）或改用低强度方案，避免一次大量肿瘤细胞破坏"],"management":["液体管理与出入量：准确记录24小时出入量，尿量目标>100ml/h（必要时留置尿管监测）","电解质监测：高危者每4～6小时复查血钾、磷、钙、尿酸、肌酐，异常立即报告","心电监护：高钾血症者持续心电监护，警惕心律失常（T波高尖、QRS增宽）","尿液观察：观察尿色、尿量（茶色尿提示尿酸结晶），必要时碱化尿液","饮食管理：低钾低磷低嘌呤饮食（避免香蕉、橙子、坚果、动物内脏、浓肉汤）","用药护理：拉布立酶输注前后冲管（不可与含别嘌醇溶液混用）；别嘌醇观察皮疹","体重与水肿监测：每日测体重与腹围，警惕容量负荷过重（尤其少尿者）"],"notes":["TLS多发生于化疗后12～72小时，高负荷血液肿瘤（Burkitt淋巴瘤、ALL、AML高白细胞）风险最高","水化是防治基础，未充分水化时使用拉布立酶/别嘌醇效果有限","高磷时慎用碱化尿液（加重磷酸钙沉积与肾损害），拉布立酶优于别嘌醇的地方在于不需碱化","无症状低钙不需积极补钙（可加重钙磷沉积），仅在出现症状性低钙（抽搐、手足搐搦）时补充","出现少尿/无尿、血钾>6.5mmol/L、严重酸中毒时需紧急血液透析"],"emergency":["血钾>6.5mmol/L或心电图出现QRS增宽、无脉性心律 → 立即降钾+心脏保护，急诊透析","少尿/无尿伴肌酐快速上升（急性肾损伤）→ 急诊评估并血液透析","抽搐、意识改变（重度低钙或高钾）→ 立即处理电解质紊乱并监护"],"pinyin":"zlrjzhz","icd10":"E88.3","physical_exam":["生命体征：心率、心律（高钾致心律失常）、血压、呼吸、体温","一般情况：意识状态、水肿程度、尿量（少尿提示肾损伤）","心肺：心律不齐、心音、肺部湿啰音（容量负荷过重）","神经系统：手足搐搦（低钙）、Chvostek征与Trousseau征、肌肉痉挛、感觉异常、抽搐","皮肤黏膜：脱水或水肿、尿色观察（茶色尿提示尿酸结晶）","肿瘤评估：肿块大小、肝脾大小、浅表淋巴结（肿瘤负荷评估）","出入量与体重：每日体重变化、24小时尿量（<0.5ml/kg/h提示少尿）"],"lab_tests":["血钾（每4～6小时）：TLS最危险指标，>6.0mmol/L需紧急处理","血磷+血钙（每4～6小时）：高磷致低钙与肾损害，监测钙磷乘积","血尿酸（每6～12小时）：评估降尿酸治疗疗效（目标<476μmol/L）","肾功能+尿量（每6～12小时）：评估急性肾损伤（肌酐、尿量）","乳酸脱氢酶（LDH）：>2倍正常上限提示高肿瘤负荷与高危TLS","血气分析+电解质（含镁）：评估酸碱失衡与电解质紊乱","心电图（持续监护）：高钾血症的早期识别（T波高尖、QRS增宽）"],"nursing":["严密监测：高危患者化疗后72小时内每4～6小时监测生命体征、尿量与电解质，异常立即报告","水化护理：按医嘱保证输液速度与量，记录出入量，观察有无水肿与肺水肿（老年/心功能不全者）","心电监护：高钾患者持续监护，观察心律失常，床旁备急救药（葡萄糖酸钙、胰岛素+葡萄糖）","尿液观察与记录：观察尿色、尿量，茶色尿立即报告；必要时遵医嘱碱化尿液","用药护理：拉布立酶输注前后用生理盐水冲管；别嘌醇观察皮疹（重症药疹风险）","饮食指导：低钾低磷低嘌呤饮食，避免高钾高磷高嘌呤食物；准确记录进食情况"],"diet":["低钾饮食：避免香蕉、橙子、橘子、土豆、菠菜、蘑菇、低钠盐（含钾）","低磷饮食：避免坚果、动物内脏、蛋黄、全谷物、碳酸饮料、加工肉制品","低嘌呤饮食：避免动物内脏、浓肉汤、海鲜、啤酒","充足水分摄入（在不违背水化医嘱前提下），促进尿酸排泄","高热量易消化饮食，必要时肠内营养；避免高蛋白过量（增加尿酸与磷负荷）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1340},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e20d93c8a3a81750e151816e8f9d2dbe6f749720f18b64f922d8660d56147354","pinyin":"zhongliurongjiezonghezhengfangzhi","initials":"zlrjzhzfz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","恶心、呕吐、乏力、食欲减退（早期非特异）\\n少尿、水肿（急性肾损伤），尿色深或呈茶色（尿酸结晶）\\n心律失常、心悸（高钾血症）、手足抽搐、抽搐（低钙血症）\\n肌肉痉挛、感觉异常（低钙）、意识改变、嗜睡\\n严重者出现急性肾衰竭、心律失常致猝死",60],["摘要","肿瘤溶解综合征（TLS）是大量肿瘤细胞快速破坏、细胞内物质（钾、磷、核酸）释放入血引起的代谢紊乱，表现为高钾、高磷、高尿酸、低钙及急性肾损伤，多见于高负荷、高增殖的血液肿瘤（淋巴瘤、白血病）化疗后12～72小时。防治核心是水化、别嘌醇/拉布立酶、监测电解质。",30],["疾病编码","E88.3",30],["原首字母","zlrjzhz",60]]},{"id":"orders-a284ba5d3111ad4ba09b","key":"v1-c9ccc21dfe2a3058|orders-a284ba5d3111ad4ba09b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"铂类药物毒性管理","category":"化疗","raw":{"name":"铂类药物毒性管理","category":"化疗","summary":"铂类药物（顺铂、卡铂、奥沙利铂、奈达铂）是常用化疗药，毒性各有侧重：顺铂以肾毒性、耳毒性、高致吐性、电解质紊乱（低镁低钾）为主；卡铂以骨髓抑制为主；奥沙利铂以遇冷加重的周围神经毒性为主。管理重点是水化、止吐、电解质监测与神经毒性评估。","symptoms":["顺铂：恶心呕吐（高致吐）、耳鸣与听力下降、肾功能损害（肌酐升高）、低镁低钾致乏力与手足麻木","卡铂：骨髓抑制（血小板减少最突出）、贫血、乏力","奥沙利铂：遇冷加重的四肢麻木、咽喉部冷敏感（吞咽冷食时喉部紧缩感）、感觉异常","共性：乏力、食欲减退、外周神经病变（累积剂量相关）","过敏反应（铂类均可，多见于多周期治疗后）：皮疹、瘙痒、呼吸困难"],"diagnosis":["肾功能（肌酐、尿素氮、肌酐清除率）：每周期前必查，顺铂按肌酐清除率调整剂量","电解质（镁、钾、钙、钠）：顺铂方案每周期监测，低镁常见且需补充","血常规：卡铂骨髓抑制明显，化疗后每2～3天复查","听力检查（纯音测听）：顺铂方案基线及累积剂量高时复查","神经毒性评估：奥沙利铂累积剂量>540mg/m² 时周围神经毒性明显，按Levi专用分级评估","尿常规+尿量：评估肾小管损伤（尿β2微球蛋白、NAG酶必要时）","过敏反应评估：多周期铂类治疗后出现皮疹、胸闷者警惕过敏"],"infusion":["⚠️ 按药物选择方案，切勿全部同时使用！","方案1（顺铂水化利尿，必做）：","用法：化疗前6～12小时 0.9%氯化钠 1000ml 静滴；化疗中 0.9%氯化钠 1000ml + 氯化钾 1.5g 静滴；化疗后 0.9%氯化钠 1000～1500ml 静滴（必要时加呋塞米 20mg 静推或甘露醇 125ml），维持尿量>100ml/h〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","方案2（止吐，顺铂高致吐四联）：","用法：阿瑞匹坦 125mg d1 + 80mg d2～d3；昂丹司琼 8mg 静推；地塞米松 10～20mg 静推；奥氮平 5mg qn〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案3（补镁补钾，顺铂后）：","用法：25%硫酸镁 10ml + 10%氯化钾 10～15ml + 0.9%氯化钠 500ml 静滴 qd（按血镁血钾调整）","方案4（过敏反应抢救）：","用法：立即停输；肾上腺素 0.3～0.5mg 肌注；地塞米松 10mg 静推；苯海拉明 20mg 肌注；补液与吸氧〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","📌 顺铂必须充分水化并监测电解质；奥沙利铂输注后3～5天避免冷饮冷食与接触冷水。"],"oral_medication":["⚠️ 对症支持用药（按医嘱）：","药物1（补镁补钾口服）：","用法：门冬氨酸钾镁片 2片 tid 或 枸橼酸钾颗粒 1袋 tid + 氧化镁 0.5g tid","药物2（神经毒性，营养神经）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid；必要时加巴喷丁 0.1～0.3g tid（疼痛性神经病变）","药物3（止吐序贯）：","用法：阿瑞匹坦 80mg qd（d2～d3）；昂丹司琼 8mg bid；甲氧氯普胺 10mg tid〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物4（升白/升血小板，卡铂方案）：","用法：rhG-CSF 皮下注射（遵医嘱）；重组人血小板生成素或白介素-11（血小板低时）","📌 补镁补钾需按血电解质结果调整，避免盲目补充；神经毒性明显时可考虑减量或更换铂类。"],"treatment":["顺铂：充分水化（化疗前中后共2000～3000ml生理盐水）+ 利尿，监测尿量与电解质，必要时补镁补钾","顺铂肾毒性预防：避免与其他肾毒性药物（氨基糖苷类、NSAIDs）同用；按肌酐清除率减量","卡铂：按Calvert公式（AUC×[GFR+25]）给药，减轻骨髓抑制；发生3～4级骨髓抑制时减量","奥沙利铂：避免冷刺激（输注后3～5天禁冷饮冷水），神经毒性≥2级时减量或停用，必要时用钙镁合剂（争议）","过敏反应处理：多周期后出现过敏者，可减慢输注速度、加强预处理，必要时更换铂类（如顺铂不耐受换卡铂/奈达铂）","听力损害：出现耳鸣或听力下降时评估听力，明显损害时停用顺铂","剂量调整：肾功能恶化、神经毒性≥2级、严重骨髓抑制时减量20%～25%或更换方案"],"management":["水化执行与记录：严格按医嘱输液速度与总量，记录24小时出入量与尿量（目标>100ml/h）","电解质监测：顺铂方案每周期前后监测镁、钾、钙、钠，低镁者遵医嘱补充","听力与耳鸣观察：询问耳鸣、听力下降，出现异常报告并安排听力检查","神经毒性评估：每周期评估四肢麻木范围与程度、有无冷敏感、精细动作（扣纽扣、写字）影响","冷刺激预防宣教：奥沙利铂后3～5天不饮冷饮、不用冷水洗手洗脸、注意保暖","过敏观察：输注前15分钟床旁守护，多周期患者（尤其第6周期后）警惕过敏反应","肾功能保护：避免同期使用肾毒性药物，保证充分水化与尿量"],"notes":["顺铂的剂量限制性毒性是肾毒性与神经/耳毒性，水化与电解质管理是安全使用的关键","顺铂所致低镁血症常见且易被忽视，可致乏力、手足麻木与心律失常，需定期监测并补充","奥沙利铂周围神经毒性与累积剂量相关，出现持续（非冷刺激相关）感觉异常时应及时评估减量","卡铂骨髓抑制（尤其血小板）明显，需按AUC给药并监测血常规","铂类过敏多发生于多周期治疗后，再次使用需加强预处理并备抢救药品"],"emergency":["输注中皮疹、胸闷、呼吸困难、血压下降（过敏反应）→ 立即停止输注并按过敏反应抢救","严重低镁低钾致心律失常、肌无力 → 立即静脉补充镁钾并心电监护","奥沙利铂致喉部冷敏感出现呼吸困难（吞咽冷饮后）→ 保暖、吸氧，多数可自行缓解","少尿/无尿伴肌酐快速升高（顺铂肾毒性）→ 补液、利尿、停用肾毒性药物，必要时透析"],"pinyin":"blxywdxgl","icd10":"T45.1","physical_exam":["生命体征：血压、心率、呼吸、体温（过敏、容量状态）","一般情况：乏力程度、脱水或水肿（水化过度）、体重变化","神经系统：四肢感觉（麻木、痛觉过敏）、腱反射、肌力、冷敏感、精细动作","耳部：耳鸣、听力下降（顺铂耳毒性，必要时听力检查）","肾功能相关：尿量、眼睑与下肢水肿、皮肤弹性","心肺：心律（低镁低钾致心律失常）、呼吸音","输注部位：有无外渗与静脉炎（铂类刺激性强）"],"lab_tests":["肾功能（肌酐、尿素氮、肌酐清除率）：每周期前必查，顺铂方案加密监测","电解质（镁、钾、钙、钠）：顺铂方案每周期前后监测，低镁需重点补充","血常规（含血小板）：卡铂方案每2～3天复查（血小板减少突出），低谷期加密","尿常规+尿量+尿β2微球蛋白：评估肾小管损伤","听力检查（纯音测听）：顺铂累积剂量高时复查","心电图：低镁低钾致心律失常风险评估","肝功能+白蛋白：评估营养与药物代谢"],"nursing":["水化护理：按医嘱保证输液速度与总量，准确记录出入量与尿量，观察水肿与肺水肿征象","电解质观察：询问乏力、心悸、手足麻木（低镁低钾），异常立即报告","神经毒性观察：每周期评估四肢麻木、冷敏感与精细动作，做好安全防护（防烫伤、跌倒）","冷刺激宣教：奥沙利铂化疗后3～5天禁冷饮冷食、避免接触冷水与金属物品","过敏抢救准备：床旁备肾上腺素、地塞米松、吸氧装置，输注前15分钟密切观察","静脉炎与外渗观察：铂类刺激性强，观察穿刺部位红肿疼痛，发疱风险药物经中心静脉输注"],"diet":["高热量、高蛋白、易消化饮食，少量多餐","顺铂方案：多饮水与含钾食物（在血钾允许范围内），避免高镁补充剂滥用","低镁者适当增加坚果、深绿色蔬菜、全谷物（同时遵医嘱补镁）","奥沙利铂化疗后3～5天：食物与饮水均需温热，禁冷饮、冰淇淋、冷水果","避免辛辣刺激与酒类；恶心呕吐明显时以清淡流质为主"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1341},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c1961a0f8984201614eccb5226e039e575f0ca7448371c0122c3427954535a77","pinyin":"boleiyaowuduxingguanli","initials":"blywdxgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","顺铂：恶心呕吐（高致吐）、耳鸣与听力下降、肾功能损害（肌酐升高）、低镁低钾致乏力与手足麻木\\n卡铂：骨髓抑制（血小板减少最突出）、贫血、乏力\\n奥沙利铂：遇冷加重的四肢麻木、咽喉部冷敏感（吞咽冷食时喉部紧缩感）、感觉异常\\n共性：乏力、食欲减退、外周神经病变（累积剂量相关）\\n过敏反应（铂类均可，多见于多周期治疗后）：皮疹、瘙痒、呼吸困难",60],["摘要","铂类药物（顺铂、卡铂、奥沙利铂、奈达铂）是常用化疗药，毒性各有侧重：顺铂以肾毒性、耳毒性、高致吐性、电解质紊乱（低镁低钾）为主；卡铂以骨髓抑制为主；奥沙利铂以遇冷加重的周围神经毒性为主。管理重点是水化、止吐、电解质监测与神经毒性评估。",30],["疾病编码","T45.1",30],["原首字母","blxywdxgl",60]]},{"id":"orders-7e758d261efefc1f01eb","key":"v1-c9ccc21dfe2a3058|orders-7e758d261efefc1f01eb","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"蒽环类药物心脏毒性监测","category":"化疗","raw":{"name":"蒽环类药物心脏毒性监测","category":"化疗","summary":"蒽环类药物（多柔比星、表柔比星、吡柔比星、阿霉素脂质体）是乳腺癌、淋巴瘤、白血病等常用化疗药，心脏毒性是其主要剂量限制性毒性，分为急性（输注中/后即刻）、早期慢性（1年内）与迟发性（1年后）。监测核心是累积剂量限制与LVEF动态评估。","symptoms":["急性：输注中或后出现心悸、胸闷、心律失常（多为暂时性）","早期慢性：活动后气促、乏力、下肢水肿、夜间阵发性呼吸困难（心功能不全）","迟发性：数年后出现扩张型心肌病、心力衰竭（预后差）","心电图改变：ST-T改变、QT间期延长、房性或室性早搏、传导阻滞","无症状LVEF下降：最常见早期表现（须依靠心脏超声发现）"],"diagnosis":["心脏超声（LVEF）：化疗前基线、每2～4周期或累积剂量达阈值时复查（LVEF下降>10%且<50%需警惕）","肌钙蛋白（cTnI/cTnT）+脑钠肽（BNP/NT-proBNP）：化疗后监测，升高提示心肌损伤","心电图：每周期前复查（QT间期、ST-T改变、心律失常）","累积剂量计算：多柔比星≤550mg/m²、表柔比星≤900mg/m²、吡柔比星≤950mg/m²（有心脏病/放疗史者应更低）","心脏MRI（必要时）：评估心肌纤维化与水肿","心脏危险因素评估：年龄>65岁、既往心脏病、高血压、糖尿病、纵隔放疗、合用曲妥珠单抗/环磷酰胺"],"infusion":["⚠️ 心脏保护与支持用药，按医嘱选择！","","方案1（心脏保护剂，右雷佐生）：","  用法：右雷佐生 500～1000mg/m² 静滴（多柔比星前30分钟，剂量比为右雷佐生:多柔比星=10:1），可降低心脏毒性","","方案2（蒽环类输注方式调整）：","  用法：多柔比星改为持续静脉输注（24～96小时）可降低心脏毒性（须由医师决定）；或使用脂质体多柔比星","","方案3（心衰治疗，出现心功能不全时）：","  用法：呋塞米 20～40mg 静推（利尿）；硝酸酯类（NS 50ml；泵入，按体重配）静滴（减轻前负荷）；必要时多巴酚丁胺/米力农（专科指导下）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","方案4（心肌营养支持）：","  用法：磷酸肌酸钠 1g + 0.9%氯化钠 100ml 静滴 qd；左卡尼汀 2g 静滴 qd（遵医嘱）","","📌 蒽环类输注期间监测心律与生命体征；出现胸闷、心悸立即减慢输注并评估。"],"oral_medication":["⚠️ 心脏相关口服用药（按医嘱）：","药物1（心衰标准治疗，出现心功能不全时）：","用法：沙库巴曲缬沙坦 50mg bid 起 或 依那普利 5mg bid；美托洛尔缓释片 23.75mg qd；螺内酯 20mg qd〔调 ★ 严重心动过缓/二度以上AVB禁用；哮喘慎用；★ 不可骤停〕","药物2（心肌营养）：","用法：辅酶Q10 20mg tid；曲美他嗪 20mg tid（餐时）；维生素C 0.2g tid","药物3（对症）：","用法：呋塞米 20mg qd（水肿，注意补钾）；氯化钾缓释片 1g bid（与利尿剂同用）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","📌 心衰用药需心内科协作调整；出现气促、水肿加重立即就诊（勿自行加量利尿剂）。"],"treatment":["严格限制累积剂量：多柔比星≤550mg/m²（有危险因素者≤400mg/m²）、表柔比星≤900mg/m²","心脏保护：高危患者使用右雷佐生或改用脂质体蒽环类；改变给药方式（持续输注）降低峰浓度","LVEF监测：基线、每2～4周期、累积剂量达阈值（多柔比星300mg/m²）时复查","心功能不全处理：LVEF下降>10%且<50%时暂停蒽环类，请心内科会诊并按心衰指南治疗（ACEI/ARB/β受体阻滞剂/利尿剂）","危险因素控制：控制血压、血糖、血脂；避免合用其他心脏毒性药物（曲妥珠单抗、环磷酰胺需评估）","替代方案：心脏高危者改用非蒽环类方案（如脂质体多柔比星、紫杉类、铂类）","长期随访：化疗结束后定期复查LVEF与心功能（迟发性心脏毒性可于数年后出现）"],"management":["化疗前评估：心脏超声LVEF基线、心电图、肌钙蛋白与BNP，评估心脏危险因素并记录","输注监测：输注期间与输注后观察心率、心律、血压与症状（胸闷、心悸、气促）","累积剂量台账：记录每周期蒽环类剂量并累计，接近阈值时提醒主管医师","症状观察：每日询问气促、乏力、下肢水肿、夜间憋醒等心衰早期症状","体重与出入量：每日测体重，观察水肿与尿量，警惕液体负荷过重","患者宣教：告知心脏毒性风险与随访计划，化疗后出现气促水肿及时就诊","多学科协作：与心内科共同管理高危患者与出现心功能不全者"],"notes":["蒽环类心脏毒性呈剂量累积性且可能不可逆，累积剂量限制是最有效的预防措施","LVEF下降常先于症状出现，无症状者也必须定期复查心脏超声","合用曲妥珠单抗、环磷酰胺、纵隔放疗会显著增加心脏毒性，需密切监测","右雷佐生可降低心脏毒性，但可能影响抗肿瘤疗效（需权衡，多用于高危患者）","迟发性心脏毒性可在化疗后数年至十余年出现，长期随访不可忽视"],"emergency":["输注中出现严重心律失常（室速、室颤）或急性心衰 → 立即停止输注、心电监护、抗心律失常与抗心衰抢救","急性肺水肿（端坐呼吸、咳粉红色泡沫痰）→ 立即吸氧、利尿、扩血管，请心内科急会诊","血压下降伴心功能不全（心源性休克）→ 立即抢救并转ICU"],"pinyin":"ehlywzdxdjc","icd10":"I42.7","physical_exam":["生命体征：血压、心率、心律、呼吸频率与形态（心衰评估）","一般情况：活动耐量（NYHA分级）、乏力、体重变化","心脏：心界扩大、心率增快、心律不齐、心音低钝、奔马律、杂音","肺部：双肺底湿啰音（肺淤血）、呼吸音","颈静脉：颈静脉怒张（右心衰）","下肢与骶部：凹陷性水肿、腹水征象","皮肤黏膜：发绀、末梢循环（心输出量下降）"],"lab_tests":["心脏超声（LVEF）：基线必查，每2～4周期复查（LVEF下降>10%且<50%需暂停并评估）","肌钙蛋白（cTnI/cTnT）+BNP/NT-proBNP：化疗后监测心肌损伤与心衰","心电图（每周期前）：QT间期、ST-T改变、心律失常","肝功能+肾功能+电解质：蒽环类经肝代谢，肝功能异常需减量；低钾低镁增加心律失常风险","血常规：与其他骨髓抑制药物联合时","心肌酶谱（CK-MB）：必要时评估急性心肌损伤","心脏MRI（必要时）：评估心肌纤维化（晚期）"],"nursing":["输注监测：输注中每15～30分钟观察心率、心律与症状，出现胸闷心悸立即减慢停止输注并报告","心脏症状观察：每日询问活动后气促、夜间憋醒、下肢水肿，记录体重与尿量","用药护理：右雷佐生需在多柔比星前30分钟给予（严格按时间），观察输注反应","心衰护理：出现心衰者半卧位、吸氧、限制液体与钠盐，遵医嘱利尿并记录出入量","宣教与随访：解释心脏毒性可能迟发，强调按期复查心脏超声的重要性，出现气促水肿立即就诊","活动指导：心功能下降者限制剧烈活动，按心功能分级指导活动量"],"diet":["低盐饮食（每日钠盐<5g，心衰者<2～3g），减轻水钠潴留","限制液体入量（心功能不全者按医嘱，一般<1500ml/日）","高蛋白、高维生素、易消化饮食，少量多餐（减轻心脏负荷）","补充含钾食物（橙子、香蕉、土豆）但需按血钾与肾功能调整","避免浓茶咖啡与酒类（刺激心脏），控制体重（肥胖加重心脏负担）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1342},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"dc539e7fc0f6633d4d6de751752a086dc04fd8fd5d4a5f719c3fdff5efe364f4","pinyin":"enhuanleiyaowuxinzangduxingjiance","initials":"ehlywxzdxjc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性：输注中或后出现心悸、胸闷、心律失常（多为暂时性）\\n早期慢性：活动后气促、乏力、下肢水肿、夜间阵发性呼吸困难（心功能不全）\\n迟发性：数年后出现扩张型心肌病、心力衰竭（预后差）\\n心电图改变：ST-T改变、QT间期延长、房性或室性早搏、传导阻滞\\n无症状LVEF下降：最常见早期表现（须依靠心脏超声发现）",60],["摘要","蒽环类药物（多柔比星、表柔比星、吡柔比星、阿霉素脂质体）是乳腺癌、淋巴瘤、白血病等常用化疗药，心脏毒性是其主要剂量限制性毒性，分为急性（输注中/后即刻）、早期慢性（1年内）与迟发性（1年后）。监测核心是累积剂量限制与LVEF动态评估。",30],["疾病编码","I42.7",30],["原首字母","ehlywzdxdjc",60]]},{"id":"orders-0528a8a43aea8877b464","key":"v1-c9ccc21dfe2a3058|orders-0528a8a43aea8877b464","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"紫杉类药物过敏与神经毒性管理","category":"化疗","raw":{"name":"紫杉类药物过敏与神经毒性管理","category":"化疗","summary":"紫杉类药物（紫杉醇、多西他赛、白蛋白结合型紫杉醇、紫杉醇脂质体）广泛用于乳腺癌、肺癌、卵巢癌、胃癌等。主要毒性为过敏反应（紫杉醇需严格预处理）、周围神经毒性（剂量累积性）、骨髓抑制与体液潴留（多西他赛）。","symptoms":["过敏反应：输注数分钟内出现皮疹、面红、胸闷、呼吸困难、支气管痉挛、血压下降（紫杉醇多见）","周围神经毒性：手足麻木、刺痛、感觉减退（袜套手套样分布）、精细动作受限、腱反射减弱","骨髓抑制：中性粒细胞减少（低谷约7～14天）、贫血、血小板减少","体液潴留（多西他赛）：下肢水肿、体重增加、胸腔积液、腹水（与累积剂量相关）","其他：脱发（几乎全部）、肌肉关节痛、腹泻、黏膜炎"],"diagnosis":["过敏风险评估：既往紫杉类过敏史、其他药物过敏史；紫杉醇必须规范预处理","神经毒性评估：每周期询问与检查四肢感觉、腱反射、精细动作（扣纽扣、写字），按CTCAE分级","血常规：每周期前及化疗后每2～3天复查（骨髓抑制）","肝功能：紫杉类经肝代谢，胆红素升高需减量（多西他赛尤其）","体液潴留评估（多西他赛）：体重、下肢水肿、有无胸腹水；累积剂量>400mg/m²时明显","肌电图/神经传导速度（必要时）：评估神经损伤程度"],"infusion":["⚠️ 预处理与抢救用药，须严格执行！","方案1（紫杉醇标准预处理，化疗前12小时与6小时）：","用法：地塞米松 20mg 口服（化疗前12小时与6小时各一次）；化疗前30～60分钟：苯海拉明 20mg 肌注 + 西咪替丁 300mg 静推（或雷尼替丁 50mg 静推）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案2（多西他赛预处理，化疗前1天开始）：","用法：地塞米松 8mg 口服 bid ×3天（化疗前1天、当天、后1天）——可减轻过敏反应与体液潴留〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案3（过敏反应抢救）：","用法：立即停止输注；肾上腺素 0.3～0.5mg 肌注（大腿外侧，必要时5～15分钟重复）；地塞米松 10mg 静推；苯海拉明 20mg 肌注；0.9%氯化钠 快速补液；面罩吸氧；必要时气管插管与升压药〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案4（神经毒性支持）：","用法：甲钴胺 0.5mg + 0.9%氯化钠 100ml 静滴 qd；硫辛酸 0.6g 静滴 qd（遵医嘱）","📌 紫杉醇输注前15分钟必须床旁密切观察，输注速度按方案（一般3小时，白蛋白结合型30分钟）；出现过敏征象立即停药。"],"oral_medication":["⚠️ 对症支持用药（按医嘱）：","药物1（神经毒性，口服）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid；加巴喷丁 0.1g tid 起（疼痛性神经病变，逐渐加量）或 普瑞巴林 75mg bid","药物2（肌肉关节痛，紫杉醇常见）：","用法：塞来昔布 200mg bid 或 布洛芬 0.3g bid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物3（激素预处理口服）：","用法：地塞米松 20mg（紫杉醇，化疗前12小时与6小时）或 8mg bid×3天（多西他赛）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","药物4（升白）：","用法：利可君 20mg tid；rhG-CSF 皮下注射（遵医嘱）","📌 预处理激素不可漏服（漏服显著增加过敏风险）；糖尿病者需监测血糖（激素升高血糖）。"],"treatment":["严格预处理：紫杉醇需地塞米松 20mg 口服（输注前12h及6h）+ 苯海拉明 50mg 肌注 + 西咪替丁 300mg 静推三联预处理，缺一不可","输注管理：紫杉醇 135-175mg/m² 静滴3h，输注前15分钟密切观察，输注速度按方案；出现过敏先停药并抢救，轻度反应经处理后可减慢速度继续（须医师决定）","神经毒性管理：≥2级神经毒性时减量20%，≥3级或影响功能时停用；可换用白蛋白结合型紫杉醇 260mg/m² 静滴30min q3w 或改用其他药物","骨髓抑制处理：按血常规结果使用G-CSF（5μg/kg 皮下注射 qd），3～4级骨髓抑制下周期减量","体液潴留（多西他赛）处理：规范使用地塞米松 8mg 口服 bid×3天预防；出现水肿/胸腹水时利尿与减量","剂量调整：胆红素升高（多西他赛）、神经毒性、骨髓抑制时减量或延迟","替代方案：过敏或不能耐受者可改用白蛋白结合型紫杉醇 260mg/m² 静滴 q3w（过敏率低）或其他类别药物"],"management":["预处理核对：化疗前核对激素与抗组胺药是否按时给予（尤其多西他赛化疗前1天开始）","输注观察：输注前15分钟每5分钟观察生命体征与过敏征象，之后每30分钟巡视","抢救准备：床旁备肾上腺素、地塞米松、苯海拉明、氧气与吸引装置，随时可用","神经毒性评估与随访：每周期记录麻木范围、程度与对生活的影响（扣纽扣、走路、书写）","安全防护：感觉减退者防烫伤（热水袋、热水）、防跌倒（尤其下肢麻木者）","体重与水肿监测（多西他赛）：每次化疗前测体重并对比，出现水肿与气促及时报告","患者宣教：告知紫杉醇过敏反应的表现与及时呼叫、神经毒性可恢复（多数停药后数周至数月缓解）"],"notes":["紫杉醇预处理不规范是严重过敏反应的主要原因，必须严格按时给予地塞米松+抗组胺药+H2受体拮抗剂","过敏反应多发生于输注最初10分钟内，此期间必须床旁守护并备好抢救药","周围神经毒性与累积剂量相关，出现持续感觉异常应及时减量，避免不可逆损伤","多西他赛体液潴留与累积剂量相关，规范使用地塞米松可显著降低发生率","神经毒性导致的感觉减退会掩盖烫伤与外伤，需加强安全教育与防护"],"emergency":["输注中出现皮疹、胸闷、呼吸困难、血压下降（过敏反应）→ 立即停输、肌注肾上腺素、抗过敏抗休克抢救","喉头水肿、支气管痉挛致窒息 → 吸氧、肾上腺素、必要时气管插管","严重神经毒性致无法行走或精细动作丧失 → 暂停化疗并评估，调整方案","中性粒细胞缺乏伴发热（FN）→ 1小时内经验性抗生素"],"pinyin":"zslxwgmyszdxgl","icd10":"T45.1","physical_exam":["生命体征：血压、心率、呼吸、血氧（过敏反应评估）","皮肤黏膜：皮疹、荨麻疹、面部潮红、口唇肿胀（过敏）、脱发","呼吸系统：呼吸音、喘鸣音、呼吸频率（支气管痉挛）","神经系统：四肢远端感觉（触觉、痛觉、振动觉）、麻木范围、腱反射、肌力、精细动作","双足与手：皮肤完整性（麻木者自查烫伤/外伤）、足背动脉搏动","水肿与体重：下肢凹陷性水肿、体重变化（多西他赛体液潴留）","口腔黏膜：黏膜炎、溃疡（与骨髓抑制相关）"],"lab_tests":["血常规（含ANC、血小板）：每周期前及化疗后每2～3天复查","肝功能（ALT/AST/胆红素/ALP）：紫杉类经肝代谢，胆红素升高需减量（多西他赛尤其）","肾功能+电解质：评估基础状态与用药安全","肌电图+神经传导速度（必要时）：评估周围神经损伤程度","血糖（糖尿病者）：激素预处理的血糖影响","心电图：紫杉类可致心律失常（少见），基础评估","体重与水肿相关检查（胸腹水超声，必要时）：多西他赛体液潴留评估"],"nursing":["输注护理：确认预处理已完成；输注前15分钟床旁守护，观察皮疹、胸闷、血压变化","抢救配合：床旁备肾上腺素、地塞米松、苯海拉明、氧气，出现过敏立即配合抢救","神经毒性护理：每周期评估四肢麻木与精细动作，指导防烫伤、防跌倒，必要时协助行走","疼痛护理：紫杉醇所致肌肉关节痛常见，遵医嘱镇痛并观察疗效","水肿与体重观察：多西他赛方案每次化疗前测体重，观察下肢水肿与气促并报告","宣教：告知过敏反应早期表现（皮疹、胸闷）应立刻呼叫；神经毒性多可在停药后恢复"],"diet":["清淡易消化饮食，少量多餐；避免过敏风险高的食物（如既往过敏食物）","高蛋白、高维生素饮食促进恢复；骨髓抑制期食物需充分加热","糖尿病者注意激素预处理致血糖升高，控制碳水摄入并监测血糖","神经毒性者避免烫食（温度感觉减退易烫伤口腔），食物宜温凉适中","多饮水（每日1500～2000ml），促进药物代谢产物排泄"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1343},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"50d6c6f7dce05e1e99223023775f327978653ca7fd7fd057c5aac40cc7316c87","pinyin":"zishanleiyaowuguominyushenjingduxingguanli","initials":"zslywgmysjdxgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","过敏反应：输注数分钟内出现皮疹、面红、胸闷、呼吸困难、支气管痉挛、血压下降（紫杉醇多见）\\n周围神经毒性：手足麻木、刺痛、感觉减退（袜套手套样分布）、精细动作受限、腱反射减弱\\n骨髓抑制：中性粒细胞减少（低谷约7～14天）、贫血、血小板减少\\n体液潴留（多西他赛）：下肢水肿、体重增加、胸腔积液、腹水（与累积剂量相关）\\n其他：脱发（几乎全部）、肌肉关节痛、腹泻、黏膜炎",60],["摘要","紫杉类药物（紫杉醇、多西他赛、白蛋白结合型紫杉醇、紫杉醇脂质体）广泛用于乳腺癌、肺癌、卵巢癌、胃癌等。主要毒性为过敏反应（紫杉醇需严格预处理）、周围神经毒性（剂量累积性）、骨髓抑制与体液潴留（多西他赛）。",30],["疾病编码","T45.1",30],["原首字母","zslxwgmyszdxgl",60]]},{"id":"orders-0c3254e79f74c7e19cbe","key":"v1-c9ccc21dfe2a3058|orders-0c3254e79f74c7e19cbe","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"靶向与免疫治疗常见不良反应","category":"化疗","raw":{"name":"靶向与免疫治疗常见不良反应","category":"化疗","summary":"靶向治疗（抗EGFR、抗HER2、抗血管生成、小分子TKI等）与免疫检查点抑制剂（PD-1/PD-L1/CTLA-4抑制剂）不良反应机制与化疗不同：靶向药多有皮疹、腹泻、高血压、蛋白尿、手足综合征、间质性肺炎；免疫治疗则可致免疫相关不良反应（irAE），累及皮肤、结肠、肝、肺、甲状腺、垂体等，重者可致命。","symptoms":["靶向治疗：痤疮样皮疹（EGFR抑制剂）、腹泻、甲沟炎、口腔黏膜炎、高血压与蛋白尿（抗血管生成）、手足综合征、乏力","间质性肺炎：干咳、活动后气促、血氧下降（EGFR-TKI、ALK抑制剂、免疫治疗均可致，属严重不良反应）","免疫相关皮肤毒性：皮疹、瘙痒、白癜风样脱色、大疱性皮炎","免疫相关结肠炎：腹泻（可为血性）、腹痛、黏液便，重者腹泻>7次/日","免疫相关肝炎：乏力、食欲减退、转氨酶升高、黄疸","免疫相关内分泌毒性：甲状腺功能减退（乏力、畏寒、水肿）、垂体炎（头痛、乏力、低血压）、1型糖尿病（多饮多尿）","免疫相关肺炎：干咳、气促、发热，影像见磨玻璃影","免疫相关心肌炎（少见但致命）：胸闷、心悸、气促、心律失常"],"diagnosis":["用药前基线：血常规、肝肾功能、甲状腺功能（TSH/FT3/FT4）、血糖、心电图、胸部CT（免疫治疗前必查）","治疗中监测：每2～4周复查肝肾功能、甲状腺功能、血糖；每6～12周复查胸部CT","irAE分级（CTCAE）：1级（无症状/轻微）、2级（中度症状，影响日常活动）、3级（严重，需住院/激素治疗）、4级（危及生命）","免疫相关结肠炎：腹泻次数、便血、腹膜炎体征；必要时肠镜+活检","免疫相关肺炎：胸部高分辨CT（磨玻璃影、机化性肺炎）、血氧、必要时支气管镜肺泡灌洗","心肌炎筛查：肌钙蛋白、BNP、心电图、心脏超声（出现胸闷心悸时紧急检查）","靶向药相关：EGFR-TKI皮疹分级、血压监测（抗血管生成药每日测血压）、尿蛋白定量"],"infusion":["⚠️ 按不良反应类型与分级选择，切勿全部同时使用！","","方案1（免疫相关不良反应，2级及以上，糖皮质激素为首选）：","  用法：甲泼尼龙 1～2mg/kg/日（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴（或等效泼尼松口服）；3～4级：甲泼尼龙 1g/日 静滴×3～5天（冲击治疗）后逐渐减量（减量过程需≥4～6周）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（免疫相关结肠炎，激素无效时）：","  用法：英夫利西单抗 5mg/kg 静滴（单次，2周后可重复）","","方案3（过敏反应，单抗类输注反应）：","  用法：立即停输；肾上腺素 0.3～0.5mg 肌注；地塞米松 10mg 静推；苯海拉明 20mg 肌注；补液吸氧〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案4（靶向药相关皮肤毒性/支持）：","  用法：0.9%氯化钠 静滴（补液）；葡萄糖酸钙+维生素C 静滴（辅助）；抗生素（继发感染时）","","📌 免疫治疗相关不良反应处理核心是『早识别、早停免疫药物、及时足量激素』；激素减量需缓慢（≥4周），过快减量可致复发。"],"oral_medication":["⚠️ 按不良反应类型选择，同类只选一种：","药物1（免疫相关不良反应口服激素，轻症或减量期）：","用法：泼尼松 0.5～1mg/kg/日（晨起顿服，逐渐减量，不可骤停）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物2（皮疹/皮肤毒性）：","用法：多西环素 0.1g bid（EGFR-TKI痤疮样皮疹）；氢化可的松乳膏 外用 bid；米诺环素 0.1g bid（二选一）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","药物3（免疫相关甲状腺功能减退）：","用法：左甲状腺素钠 25～50μg qd 起（晨起空腹，按TSH调整）","药物4（腹泻，免疫相关结肠炎1级）：","用法：洛哌丁胺 2mg tid（症状控制后减量）；蒙脱石散 3g tid；益生菌〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物5（靶向药相关腹泻/手足综合征）：","用法：洛哌丁胺（腹泻）；维生素B6 100mg tid + 尿素软膏外用（手足综合征）","📌 免疫相关不良反应≥2级应暂停免疫治疗并口服/静脉激素；1级可在密切监测下继续治疗。"],"treatment":["免疫相关不良反应（irAE）总原则：1级密切监测可继续治疗；2级暂停免疫药物并口服激素（泼尼松0.5～1mg/kg/日）；3级停用免疫药物并静脉激素（甲泼尼龙1～2mg/kg/日）；4级永久停用并大剂量激素冲击±其他免疫抑制","免疫相关结肠炎：激素+必要时英夫利西单抗；警惕肠穿孔（剧烈腹痛、腹膜炎体征需急诊）","免疫相关肺炎：停免疫药+激素；3～4级需住院、吸氧、必要时机械通气；激素减量需≥6周","免疫相关肝炎：停免疫药+激素；严重者加用吗替麦考酚酯（不用英夫利西单抗，可能致肝毒性）","免疫相关内分泌毒性：甲状腺功能减退予左甲状腺素替代（多数需长期）；垂体炎予激素替代；1型糖尿病予胰岛素治疗","免疫相关心肌炎：立即停免疫药、大剂量激素冲击、心内科协作（必要时加用抗胸腺细胞球蛋白/英夫利西单抗），病死率高","靶向药不良反应处理：皮疹（保湿+抗生素软膏+多西环素，重者减量或短期激素）、腹泻（洛哌丁胺，重者停用）、高血压（ACEI/ARB降压）、蛋白尿（减量或停用）、间质性肺炎（立即停药+激素）","多学科协作：皮疹/皮肤科、结肠炎/消化科、肝炎/肝病科、肺炎/呼吸科、内分泌毒性/内分泌科、心肌炎/心内科"],"management":["基线评估与记录：免疫治疗前完成血常规、肝肾功能、甲功、血糖、心电图、胸部CT，作为对比基线","定期监测：每2～4周复查肝肾功能、甲功、血糖；每6～12周胸部CT；出现症状随时检查","症状日记：指导患者记录皮疹、腹泻次数、大便性状、咳嗽气促、乏力与体重变化，复诊时提供","激素使用护理：遵医嘱足量起始、缓慢减量（≥4～6周），观察激素不良反应（高血糖、高血压、感染、骨质疏松、失眠）","感染筛查：激素治疗前筛查结核、乙肝、丙肝、HIV（激素可致潜伏感染再激活）","患者宣教：强调任何新发症状（腹泻、皮疹、气促、乏力、多饮多尿）都必须及时报告，不可自行停药或用止泻药掩盖","多学科随访：出现3级以上irAE时联合相关专科会诊处理"],"notes":["免疫治疗不良反应可在治疗期间或停药后数周至数月出现（迟发性），随访期仍需警惕","免疫相关心肌炎、肺炎、中毒性表皮坏死松解症虽少见但可致命，出现相应症状须紧急处理","激素减量过快是irAE复发的主要原因，减量过程一般不少于4～6周","免疫治疗相关结肠炎禁用洛哌丁胺长期止泻（可致中毒性巨结肠），2级以上须激素治疗","EGFR-TKI皮疹与疗效有一定相关性，但严重皮疹需积极处理并可能减量","抗血管生成药物（贝伐珠单抗等）可致出血、血栓与胃肠穿孔，围手术期需停药（一般术前4～6周）"],"emergency":["呼吸困难、血氧下降伴双肺磨玻璃影（免疫相关肺炎3～4级）→ 立即停药、大剂量激素、吸氧，必要时机械通气","胸闷心悸、肌钙蛋白升高、心律失常（免疫相关心肌炎）→ 立即停药、激素冲击、心内科急会诊","剧烈腹痛、腹膜刺激征、血性腹泻（免疫相关结肠炎致穿孔）→ 急诊评估手术","血压急剧升高伴头痛视力模糊（抗血管生成药致高血压危象）→ 立即降压处理","严重皮疹伴发热、黏膜糜烂（Stevens-Johnson综合征/中毒性表皮坏死松解症）→ 立即停药、皮肤科急会诊、支持治疗"],"pinyin":"bxymyzlycjbzdy","icd10":"Y43.3","physical_exam":["生命体征：体温（感染/免疫性发热）、血压（抗血管生成药致高血压）、呼吸与血氧（肺炎）","皮肤黏膜：皮疹范围与分级（体表面积）、瘙痒、甲沟炎、黏膜糜烂（口腔、眼、生殖器）、色素脱色","呼吸系统：呼吸频率、双肺呼吸音、湿啰音、喘鸣（肺炎/间质性肺炎）","消化系统：腹部压痛、肠鸣音（结肠炎可亢进）、有无腹膜炎体征、肛周情况","内分泌：甲状腺肿大与质地、体重变化、皮肤干燥与水肿（甲减）、有无脱水与多尿（糖尿病）","心脏：心率、心律、心音、颈静脉（心肌炎、心衰）","神经系统：意识、肌力、感觉（免疫相关神经毒性、垂体炎致头痛）","眼部：结膜炎、眼睑水肿、视力变化（免疫相关眼毒性）"],"lab_tests":["肝功能（ALT/AST/胆红素）+肾功能：每2～4周复查（免疫相关肝炎、靶向药肝毒性）","甲状腺功能（TSH、FT3、FT4）+皮质醇+ACTH：免疫治疗前基线及每4～6周复查（内分泌毒性）","血糖+糖化血红蛋白+尿酮：免疫治疗相关1型糖尿病筛查（出现多饮多尿时急查）","血常规+CRP+PCT：感染与免疫性炎症鉴别，骨髓抑制评估","肌钙蛋白+BNP+心电图+心脏超声：胸闷心悸时紧急评估（心肌炎）","胸部高分辨CT：免疫治疗前基线，出现咳嗽气促时紧急复查（肺炎）","尿蛋白定量/尿常规：抗血管生成药物相关肾毒性监测（每周期）","病原学检查（痰培养、G试验、GM试验、结核筛查）：免疫治疗前与疑感染时，排除感染后诊断irAE"],"nursing":["症状监测与记录：每日评估皮疹部位与面积、腹泻次数与性状、咳嗽气促、乏力、体重，异常立即报告","激素治疗护理：遵医嘱按时给药并观察不良反应（血糖升高、血压升高、失眠、情绪改变、感染征象）","皮肤护理：温水清洁、避免搔抓与刺激性护肤品，按医嘱外用药物，观察有无继发感染","腹泻护理：记录次数与性状，遵医嘱用药（2级以上禁用洛哌丁胺自行止泻），注意肛周皮肤保护与补液","呼吸道护理：出现干咳气促者监测血氧、限制活动、必要时吸氧，配合胸部CT检查","宣教与随访：告知免疫不良反应可能迟发，出院后出现任何新症状须立即联系医疗团队，不可自行停药"],"diet":["高蛋白、高热量、易消化饮食，少量多餐；骨髓抑制期食物需充分加热","腹泻者：低渣低脂饮食，避免生冷、油腻、乳制品与高纤维食物，补充水分与电解质","皮疹/黏膜炎者：避免辛辣、过烫、酸性食物，进食软烂食物并加强口腔护理","激素治疗期间：低盐低糖饮食，控制碳水摄入（防血糖升高），注意补钾补钙","免疫治疗期间避免服用免疫增强类保健品（如大剂量维生素、灵芝孢子粉等），可能干扰疗效（须先咨询医师）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1344},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"60a7710fc053b8ec8359744c0be461a71309ef8d987f5893409080a68ea38bce","pinyin":"baxiangyumianyizhiliaochangjianbuliangfanying","initials":"bxymyzlcjblfy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","靶向治疗：痤疮样皮疹（EGFR抑制剂）、腹泻、甲沟炎、口腔黏膜炎、高血压与蛋白尿（抗血管生成）、手足综合征、乏力\\n间质性肺炎：干咳、活动后气促、血氧下降（EGFR-TKI、ALK抑制剂、免疫治疗均可致，属严重不良反应）\\n免疫相关皮肤毒性：皮疹、瘙痒、白癜风样脱色、大疱性皮炎\\n免疫相关结肠炎：腹泻（可为血性）、腹痛、黏液便，重者腹泻>7次/日\\n免疫相关肝炎：乏力、食欲减退、转氨酶升高、黄疸\\n免疫相关内分泌毒性：甲状腺功能减退（乏力、畏寒、水肿）、垂体炎（头痛、乏力、低血压）、1型糖尿病（多饮多尿）\\n免疫相关肺炎：干咳、气促、发热，影像见磨玻璃影\\n免疫相关心肌炎（少见但致命）：胸闷、心悸、气促、心律失常",60],["摘要","靶向治疗（抗EGFR、抗HER2、抗血管生成、小分子TKI等）与免疫检查点抑制剂（PD-1/PD-L1/CTLA-4抑制剂）不良反应机制与化疗不同：靶向药多有皮疹、腹泻、高血压、蛋白尿、手足综合征、间质性肺炎；免疫治疗则可致免疫相关不良反应（irAE），累及皮肤、结肠、肝、肺、甲状腺、垂体等，重者可致命。",30],["疾病编码","Y43.3",30],["原首字母","bxymyzlycjbzdy",60]]},{"id":"orders-7e3fec6d73c93f62ce53","key":"v1-c9ccc21dfe2a3058|orders-7e3fec6d73c93f62ce53","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"自发性气胸（外科处理与胸腔闭式引流）","category":"胸外科","raw":{"name":"自发性气胸（外科处理与胸腔闭式引流）","category":"胸外科","summary":"自发性气胸是肺组织及脏层胸膜自发破裂，气体进入胸膜腔致肺萎陷。原发性多见于瘦高体型青年男性（肺大疱破裂），继发性多见于慢阻肺、肺结核、肺癌等。张力性气胸可迅速危及生命，需紧急减压。","symptoms":["突发患侧胸痛（针刺样或刀割样），随后出现呼吸困难","呼吸困难程度与气胸量及基础肺功能相关，重者不能平卧、发绀","刺激性干咳，少量咯血","患侧胸廓饱满、呼吸动度减弱、叩诊鼓音、呼吸音减弱或消失","张力性气胸：极度呼吸困难、发绀、烦躁、血压下降、气管健侧移位、颈静脉怒张"],"diagnosis":["胸部X线（立位）：首选，可见气胸线、肺压缩、纵隔移位；少量气胸需呼气相摄片","胸部CT：明确气胸量、肺大疱位置、有无胸腔积液与纵隔气肿（拟手术者必查）","血气分析：评估缺氧与二氧化碳潴留","床旁超声：快速判断气胸（肺滑动征消失）、可引导穿刺","诊断性胸腔穿刺：抽出气体确诊（张力性气胸在紧急减压时进行）","心电图：排除急性心肌梗死（胸痛鉴别）"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","","方案1（抗感染，胸膜腔穿刺/引流后）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 头孢呋辛酯口服序贯〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（镇痛）：","  用法：对乙酰氨基酚 0.5g（NS 100ml 或 5%GS 100ml）静滴/口服 必要时 或 曲马多 100mg 静滴 必要时〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","方案3（补液支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；气胸禁剧烈咳嗽者必要时镇咳","","📌 张力性气胸急救以穿刺减压为第一要务，用药为辅助。"],"oral_medication":["⚠️ 按病情选择药物，同类只选一种：","药物1（镇咳）：","用法：复方甲氧那明 2粒 tid 或 可待因 15mg 必要时（剧烈干咳影响肺复张时）","药物2（通便，防用力）：","用法：乳果糖 15ml bid（避免用力排便致复发）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（镇痛）：","用法：布洛芬 0.3g bid 或 塞来昔布 200mg qd〔调 ★ eGFR<30 禁用；心血管血栓风险〕","📌 避免使用抑制呼吸的强效镇静药；继发性气胸需同时治疗基础肺病。"],"treatment":["少量气胸（肺压缩<20%）且无症状：卧床休息、吸氧、观察，复查胸片","胸腔穿刺抽气：肺压缩20%～50%者，锁骨中线第2肋间穿刺抽气","胸腔闭式引流：肺压缩>50%、张力性气胸、呼吸困难明显或抽气后复发者（锁骨中线第2肋间或腋中线第4～5肋间置管）","张力性气胸急救：立即于患侧锁骨中线第2肋间粗针穿刺减压，随后置管引流","手术治疗：反复发作（≥2次）、持续漏气>3～5天、双侧气胸、血气胸、肺大疱明显者行胸腔镜下肺大疱切除+胸膜固定","基础病治疗：慢阻肺、肺结核、肺癌等的规范治疗；戒烟"],"management":["卧床休息，取半卧位，给予吸氧（2～4L/min）","监测呼吸、血氧、心率与血压，观察呼吸困难与发绀变化","胸腔闭式引流护理：观察水封瓶气泡（漏气）、引流量与性状，防止管路脱出与逆流","避免剧烈咳嗽、用力排便、屏气与剧烈活动（防止复发）","复查胸片：置管后及拔管前确认肺复张，拔管后24小时复查","复发预防宣教：戒烟、避免剧烈运动与乘坐飞机（未愈合前）、及时治疗呼吸道感染"],"notes":["张力性气胸是急症，必须立即穿刺减压，不能等待影像学检查","瘦高体型青年男性反复气胸应警惕肺大疱，建议胸腔镜手术根治","继发性气胸（慢阻肺、肺结核等）病情更重，病死率高，需积极处理基础病","拔管后仍有气胸复发可能，需随访胸片"],"emergency":["极度呼吸困难、发绀、烦躁、血压下降、气管移位（张力性气胸）→ 立即穿刺减压+闭式引流","胸痛伴咯血、血红蛋白下降（血气胸）→ 急诊评估，必要时手术","双侧气胸或呼吸衰竭 → 立即转ICU并双侧减压"],"pinyin":"zfxqx","icd10":"J93.0","physical_exam":["生命体征：呼吸频率与形态、血氧、心率、血压（张力性气胸可致休克）","一般情况：神志、发绀程度、是否可平卧、有无烦躁","颈部：气管位置（有无向健侧移位）、颈静脉充盈情况（张力性气胸可怒张）","胸部视诊：患侧胸廓饱满、呼吸动度减弱、肋间隙增宽","胸部触诊：语颤减弱或消失、皮下气肿（握雪感）","胸部叩诊与听诊：患侧鼓音、呼吸音减弱或消失","心脏：心音遥远（大量气胸）、心率增快"],"lab_tests":["血气分析：评估低氧血症与二氧化碳潴留（继发性气胸常异常）","血常规+CRP：评估感染与有无血胸","胸部X线（立位正侧位）：诊断与随访肺复张情况","胸部CT：明确肺大疱、胸腔积液、纵隔气肿及基础肺病，为手术提供依据","凝血功能+血型+交叉配血：拟手术者术前准备","心电图：胸痛鉴别（排除心肌梗死）、张力性气胸致心律失常评估","肺功能（病情稳定后）：评估基础肺功能与手术耐受"],"nursing":["急性期护理：绝对卧床、半卧位，吸氧，密切监测呼吸与血氧，发现呼吸困难加重立即报告","闭式引流护理：水封瓶低于胸壁引流口60～100cm，保持密闭与通畅，观察气泡与引流量，搬动时夹闭管路","疼痛护理：评估疼痛程度，遵医嘱镇痛，指导深呼吸与有效咳嗽（促进肺复张）","活动指导：避免剧烈咳嗽、屏气、用力排便及剧烈运动，戒烟","复发观察：出院后如再次突发胸痛、呼吸困难，立即就诊"],"diet":["高蛋白、高维生素、易消化饮食，促进胸膜愈合","多饮水，多食蔬菜水果，保持大便通畅（避免用力排便）","避免产气食物（豆类、碳酸饮料）以免腹胀影响呼吸","戒烟酒，避免辛辣刺激食物","继发性气胸者按基础病饮食管理（如限盐、控糖）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1345},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"dc685bb97138a80a32475771a3368046979efc1d2eab4d068584698f8d8cb95c","pinyin":"zifaxingqixiong（waikechuliyuxiongqiangbishiyinliu）","initials":"zfxqx（wkclyxqbsyl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发患侧胸痛（针刺样或刀割样），随后出现呼吸困难\\n呼吸困难程度与气胸量及基础肺功能相关，重者不能平卧、发绀\\n刺激性干咳，少量咯血\\n患侧胸廓饱满、呼吸动度减弱、叩诊鼓音、呼吸音减弱或消失\\n张力性气胸：极度呼吸困难、发绀、烦躁、血压下降、气管健侧移位、颈静脉怒张",60],["摘要","自发性气胸是肺组织及脏层胸膜自发破裂，气体进入胸膜腔致肺萎陷。原发性多见于瘦高体型青年男性（肺大疱破裂），继发性多见于慢阻肺、肺结核、肺癌等。张力性气胸可迅速危及生命，需紧急减压。",30],["疾病编码","J93.0",30],["原首字母","zfxqx",60]]},{"id":"orders-f332dba2107668bea6e4","key":"v1-c9ccc21dfe2a3058|orders-f332dba2107668bea6e4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肛周脓肿（切开引流与围手术期管理）","category":"肛肠外科","raw":{"name":"肛周脓肿（切开引流与围手术期管理）","category":"肛肠外科","summary":"肛周脓肿是肛腺感染经肛管括约肌间隙扩散形成的化脓性感染，多见于肛管直肠周围间隙（皮下、坐骨直肠窝、骨盆直肠间隙）。主要治疗为切开引流，延误可形成肛瘘或导致全身感染。","symptoms":["肛门周围持续性跳痛或胀痛，坐卧不安，排便时加重","局部红肿、硬结、压痛，可有波动感（脓肿形成）","发热、乏力、食欲减退（深部脓肿全身症状更明显）","骨盆直肠间隙脓肿可仅有高热、里急后重、排尿困难而无明显局部红肿","脓肿破溃后疼痛缓解，可见脓液流出"],"diagnosis":["体格检查：肛门周围红肿、硬结、压痛、波动感（最关键）","直肠指检：可触及压痛性包块、波动感，判断脓肿位置与范围","血常规+CRP：白细胞与CRP升高","肛周超声/腔内超声：明确脓肿部位、范围与是否多房","盆腔MRI/CT：深部脓肿（骨盆直肠间隙、直肠后间隙）评估范围","脓液细菌培养及药敏：指导抗生素选择"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","方案1（抗感染，覆盖肠道菌群）：","用法：头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h 或 头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 CrCl<30 减量；青霉素过敏禁用〕","方案2（重症/糖尿病）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案3（镇痛/支持）：","用法：0.9%氯化钠 静滴；对乙酰氨基酚 0.5g 静滴 必要时〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 抗感染不能替代切开引流；糖尿病患者须同时控制血糖。"],"oral_medication":["⚠️ 术后与恢复期遵医嘱，同类只选一种：","药物1（抗感染序贯）：","用法：阿莫西林克拉维酸 0.625g tid 或 头孢呋辛酯 0.25g bid + 甲硝唑 0.4g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（通便，避免便秘）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（止痛，外用）：","用法：复方角菜酸酯栓 1枚 纳肛 bid 或 利多卡因凝胶 外用","📌 保持排便通畅、温水坐浴是术后恢复关键，避免用力排便。"],"treatment":["切开引流：主要治疗，脓肿形成即应切开（波动感处或压痛最明显处），充分敞开引流、清除脓液与坏死组织","深部脓肿：需在麻醉下充分探查，放置引流管，必要时挂线引流","抗感染：术前术后抗感染，覆盖肠道菌群","温水坐浴与换药：术后每日温水坐浴（1:5000高锰酸钾），保持引流通畅，每日换药","合并糖尿病：严格控制血糖（影响愈合、易复发）","肛瘘处理：约50%患者后期形成肛瘘，需二期手术（肛瘘切开/挂线术）"],"management":["观察局部红肿范围、疼痛、分泌物与体温变化","换药护理：保持引流口通畅，由内向外清洁，避免引流口过早闭合（易致复发）","坐浴指导：术后每日温水坐浴2～3次，每次15～20分钟（水温40℃左右）","排便管理：保持大便通畅，避免便秘与腹泻（必要时用缓泻剂），便后清洁","饮食管理：忌辛辣、酒类，多饮水、多纤维食物","随访：术后1～2周复查，评估愈合与有无肛瘘形成"],"notes":["肛周脓肿一经确诊应尽早切开引流，抗生素不能替代手术","脓肿自行破溃或引流不充分易形成肛瘘或复发","深部脓肿（骨盆直肠间隙）局部症状不明显，可仅表现为高热，须警惕","糖尿病患者易发生、易复发、愈合慢，围手术期必须控制血糖"],"emergency":["高热寒战伴肛周红肿迅速扩展、皮肤发黑（坏死性筋膜炎）→ 急诊广泛清创","会阴部广泛肿胀伴排尿困难、气性坏疽征象 → 急诊抢救手术","脓毒症休克表现 → 立即抢救并急诊引流"],"pinyin":"gznz","icd10":"K61.0","physical_exam":["生命体征：体温、脉搏、血压（评估感染程度）","一般情况：精神状态、有无中毒症状、营养状态","肛周视诊：红肿范围、皮肤颜色（有无发黑）、破溃口、分泌物","肛周触诊：压痛部位与范围、硬结、波动感、皮温升高","直肠指检：压痛性包块、波动感、括约肌张力、有无内口","会阴与阴囊：有无肿胀蔓延（坏死性筋膜炎征象）","腹部：有无下腹痛与压痛（深部脓肿/盆腔受累）"],"lab_tests":["血常规+CRP+PCT：评估感染程度，术后动态复查","脓液细菌培养+药敏：切开时留取，指导抗生素选择（多为肠道菌群）","血糖+糖化血红蛋白：糖尿病筛查（影响愈合与复发）","肛周超声/腔内超声：明确脓肿部位、范围与是否多房","盆腔MRI（深部脓肿）：评估范围、有无瘘管及与括约肌关系","凝血功能+肝肾功能：术前评估与用药安全"],"nursing":["疼痛护理：评估疼痛程度，遵医嘱镇痛；协助侧卧位减轻肛门受压","换药护理：每日换药，保持引流口通畅，由内向外换药，观察引流液色质量","坐浴护理：每日温水/高锰酸钾坐浴2～3次，水温40℃左右，时间15～20分钟","排便护理：指导避免用力排便，便后清洁并坐浴，必要时遵医嘱用缓泻剂","饮食与宣教：忌辛辣酒类，多饮水多纤维，保持大便通畅，按时复查"],"diet":["多饮水（每日2000ml以上），多食高纤维蔬菜水果与粗粮","高蛋白饮食（鱼、瘦肉、蛋、豆制品）促进创面愈合","严格忌辛辣刺激食物与酒类（刺激肛门直肠充血）","避免坚硬粗糙与产气食物，减少排便刺激","糖尿病患者按糖尿病饮食严格控糖"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1346},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0316f0fed86bcdd3688e9386180ae26d60d5dca121ed3045376a24d94fc52812","pinyin":"gangzhounongzhong（qiekaiyinliuyuweishoushuqiguanli）","initials":"gznz（qkylywssqgl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肛门周围持续性跳痛或胀痛，坐卧不安，排便时加重\\n局部红肿、硬结、压痛，可有波动感（脓肿形成）\\n发热、乏力、食欲减退（深部脓肿全身症状更明显）\\n骨盆直肠间隙脓肿可仅有高热、里急后重、排尿困难而无明显局部红肿\\n脓肿破溃后疼痛缓解，可见脓液流出",60],["摘要","肛周脓肿是肛腺感染经肛管括约肌间隙扩散形成的化脓性感染，多见于肛管直肠周围间隙（皮下、坐骨直肠窝、骨盆直肠间隙）。主要治疗为切开引流，延误可形成肛瘘或导致全身感染。",30],["疾病编码","K61.0",30],["原首字母","gznz",60]]},{"id":"orders-5ef8856eb3c0cc18d711","key":"v1-c9ccc21dfe2a3058|orders-5ef8856eb3c0cc18d711","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性阑尾炎（外科手术与围手术期处理）","category":"胃肠外科","raw":{"name":"急性阑尾炎（外科手术与围手术期处理）","category":"胃肠外科","summary":"急性阑尾炎是最常见的外科急腹症，多因阑尾管腔梗阻（粪石、淋巴滤泡增生、异物、肿瘤）继发细菌感染所致。按病理分为急性单纯性、化脓性、坏疽穿孔性及阑尾周围脓肿。典型表现为转移性右下腹痛伴麦氏点压痛、反跳痛，一经确诊原则上应尽早手术（腹腔镜阑尾切除术为首选）。","symptoms":["转移性右下腹痛：起初为脐周或上腹隐痛/胀痛（内脏痛），数小时后（6～8小时）转移并固定于右下腹（躯体痛），呈持续性","胃肠道症状：恶心、呕吐（多在腹痛后出现）、食欲减退、便秘或腹泻；盆位阑尾可有里急后重、排尿不适","发热：多为低热（37.5～38.5℃）；高热提示化脓、坏疽或穿孔","右下腹固定压痛（麦氏点，脐与右髂前上棘连线中外1/3处），伴反跳痛与肌紧张提示腹膜炎","特殊类型：小儿病情进展快、易穿孔；老年人症状轻而病理重、易延误；孕妇压痛点偏上外、易流产早产"],"diagnosis":["症状+体征为核心：转移性右下腹痛 + 右下腹固定压痛（诊断符合率可达90%）","血常规：白细胞计数及中性粒细胞比例升高（老年、早期可正常）","CRP+PCT：CRP>正常提示炎症重，PCT升高提示化脓/穿孔可能","腹部超声：可见阑尾增粗（直径>6mm）、壁增厚、周围积液、粪石，可鉴别妇科及泌尿系疾病","腹部CT（平扫/增强）：诊断准确性最高，评估有无穿孔、脓肿、阑尾周围炎（不典型、老年、肥胖者首选）","尿常规+Hcg（育龄女性）：排除泌尿系结石、宫外孕","Alvarado评分：≥7分高度提示急性阑尾炎（症状、体征、实验室综合评分）"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","","方案1（术前/保守抗感染，覆盖肠道G-杆菌+厌氧菌）：","  用法：头孢呋辛 1.5g 静滴 q8h（或头孢曲松 2g 静滴 qd）+ 甲硝唑 0.5g 静滴 q8h〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（化脓/穿孔/腹膜炎，重症）：","  用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 头孢哌酮舒巴坦 3g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案3（补液与电解质，术前禁食者）：","  用法：平衡盐溶液 500～1000ml 静滴；呕吐明显者补钾（见尿补钾）","","方案4（镇痛，诊断明确后）：","  用法：间苯三酚 40mg（NS 100ml）静滴/静推 或 氟比洛芬酯 50mg 静滴","","📌 诊断未明确前慎用强效镇痛药与解痉药（可掩盖病情）；术前0.5～1小时给予预防性抗菌药物。"],"oral_medication":["⚠️ 术后或保守治疗序贯用药，同类只选一种：","药物1（抗感染序贯）：","用法：头孢呋辛酯 0.25g bid + 甲硝唑 0.4g tid 或 阿莫西林克拉维酸 0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（通便，防术后便秘）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时 或 塞来昔布 200mg qd〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（肠道菌群调节，术后腹泻者）：","用法：双歧杆菌三联活菌 2粒 bid","📌 保守治疗的急性阑尾炎复发率约30%～40%，建议症状控制后3个月内择期手术（'interval appendectomy'）。"],"treatment":["腹腔镜阑尾切除术：首选术式——创伤小、恢复快、切口感染率低、可探查腹腔（尤其肥胖、老年、诊断不明确者）","开腹阑尾切除术：适用于腹腔镜禁忌（广泛腹腔粘连、严重心肺功能不全等）或术中大出血等","围手术期抗菌药物：术前0.5～1小时预防性给药，术后按病情（单纯性24小时，穿孔/腹膜炎3～7天）","保守治疗指征：单纯性阑尾炎早期、发病>72小时已形成炎性包块、有手术禁忌或拒绝手术者——禁食、补液、抗感染、观察","阑尾周围脓肿：先行抗感染+补液，必要时超声/CT引导下穿刺引流，3～6个月后择期阑尾切除","术后并发症处理：切口感染（换药引流）、腹腔脓肿（引流+抗感染）、肠梗阻（禁食减压）、出血（止血/输血）","穿孔性阑尾炎：术中彻底冲洗腹腔、放置引流管，术后加强抗感染与营养支持"],"management":["术前：禁食禁水、建立静脉通路、完善检查（血常规、凝血、心电图、腹部超声/CT），备皮，做好手术准备","体位：术前取半卧位（局限炎症、减轻疼痛）；术后麻醉清醒后取半卧位，利于渗液引流","病情观察：每1～2小时观察腹痛部位与性质、腹膜刺激征范围、体温、生命体征（警惕穿孔与腹膜炎）","术后观察：切口渗血渗液、引流液量与性状、肠鸣音恢复、排气排便时间","活动与康复：术后6小时床上活动，术后第1天下床活动（促进肠功能恢复、防血栓）","饮食过渡：术后肠鸣音恢复/排气后从流质开始，逐步过渡半流质、软食，避免牛奶豆浆等产气食物","出院指导：2周内避免剧烈运动与重体力劳动，切口保持清洁干燥，出现腹痛、发热及时就诊"],"notes":["『转移性右下腹痛+麦氏点固定压痛』是诊断核心，但小儿、老年、孕妇及后位阑尾表现不典型，需借助影像学","老年患者腹痛轻、白细胞可不升高，但病理常已坏疽穿孔，须放宽手术指征","妊娠期阑尾炎一经确诊应尽早手术，围手术期加用黄体酮保胎、产科协同管理","阑尾周围脓肿不宜急诊手术（易致肠瘘），以抗感染+引流为主，择期再手术","保守治疗成功者需告知复发风险与择期手术建议"],"emergency":["腹痛突然加重、范围扩大伴全腹压痛反跳痛、板状腹（穿孔致弥漫性腹膜炎）→ 急诊手术","高热寒战、心率增快、血压下降（脓毒症）→ 立即抢救并急诊手术","右下腹包块迅速增大伴剧痛（脓肿破裂）→ 急诊处理/引流"],"pinyin":"jxlcwy","icd10":"K35.8","physical_exam":["生命体征：体温、脉搏、呼吸、血压（高热与心率增快提示化脓/穿孔）","一般情况：痛苦面容、体位（屈髋侧卧减轻疼痛）、有无脱水","腹部视诊：呼吸运动受限（右下腹）、有无膨隆、手术瘢痕","麦氏点压痛：脐与右髂前上棘连线中外1/3处固定压痛（最重要体征）","反跳痛与肌紧张：提示腹膜受累（化脓/穿孔）","结肠充气试验（Rovsing征）：按压左下腹引起右下腹痛为阳性","腰大肌试验（Psoas征）：后位阑尾阳性；闭孔内肌试验（Obturator征）：盆位阑尾阳性","直肠指检：直肠右前方触痛提示盆位阑尾或盆腔积液"],"lab_tests":["血常规+CRP+PCT：入院急查，白细胞与中性粒细胞升高支持诊断，PCT升高提示化脓/穿孔","尿常规：排除泌尿系结石与感染（阑尾靠近输尿管可有少量红细胞）","血Hcg（育龄女性）：必须排除异位妊娠（宫外孕）","腹部超声：评估阑尾直径、壁厚、粪石、周围积液，同时鉴别妇科疾病","腹部CT（平扫/增强）：不典型病例、老年或肥胖患者首选，明确有无穿孔与脓肿","凝血功能+肝肾功能+心电图：术前常规评估","血型+交叉配血：拟手术者备血"],"nursing":["术前护理：禁食禁水、禁用镇痛药（诊断未明前）、禁用灌肠与泻药（防穿孔）、观察腹痛变化并记录","术后体位：麻醉清醒、血压平稳后取半卧位，减轻切口张力并利于引流","切口与引流观察：观察切口渗血渗液、引流液色质量，保持引流通畅，警惕腹腔脓肿","活动与饮食：鼓励早期下床活动（术后第1天），肠功能恢复后按流质→半流质→软食过渡","并发症观察：发热、腹痛加重、腹胀、停止排气排便（腹腔脓肿、肠梗阻、切口感染）","健康宣教：切口保持清洁干燥、2周内避免剧烈运动、按时复诊"],"diet":["术前：严格禁食禁水6～8小时","术后：肠鸣音恢复或排气后开始少量温开水，逐步过渡流质（米汤、藕粉）→半流质→软食","恢复期：高蛋白（鱼、瘦肉、蛋）、高维生素、易消化饮食促进切口愈合","避免产气食物（牛奶、豆浆、红薯、碳酸饮料）与辛辣刺激、油腻食物","多食蔬菜水果与粗纤维食物，保持大便通畅（防便秘增加腹压）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1347},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4d11d7a0fbf9e58a5cde48166dd073145ff2c5e5beb6a4c6fb5f86a883d4fbd0","pinyin":"jixinglanweiyan（waikeshoushuyuweishoushuqichuli）","initials":"jxlwy（wkssywssqcl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","转移性右下腹痛：起初为脐周或上腹隐痛/胀痛（内脏痛），数小时后（6～8小时）转移并固定于右下腹（躯体痛），呈持续性\\n胃肠道症状：恶心、呕吐（多在腹痛后出现）、食欲减退、便秘或腹泻；盆位阑尾可有里急后重、排尿不适\\n发热：多为低热（37.5～38.5℃）；高热提示化脓、坏疽或穿孔\\n右下腹固定压痛（麦氏点，脐与右髂前上棘连线中外1/3处），伴反跳痛与肌紧张提示腹膜炎\\n特殊类型：小儿病情进展快、易穿孔；老年人症状轻而病理重、易延误；孕妇压痛点偏上外、易流产早产",60],["摘要","急性阑尾炎是最常见的外科急腹症，多因阑尾管腔梗阻（粪石、淋巴滤泡增生、异物、肿瘤）继发细菌感染所致。按病理分为急性单纯性、化脓性、坏疽穿孔性及阑尾周围脓肿。典型表现为转移性右下腹痛伴麦氏点压痛、反跳痛，一经确诊原则上应尽早手术（腹腔镜阑尾切除术为首选）。",30],["疾病编码","K35.8",30],["原首字母","jxlcwy",60]]},{"id":"orders-02235a267fa881c1f854","key":"v1-c9ccc21dfe2a3058|orders-02235a267fa881c1f854","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肝外伤（肝破裂）","category":"肝胆外科","raw":{"name":"肝外伤（肝破裂）","category":"肝胆外科","summary":"肝外伤多由腹部钝性外伤（撞击、坠落、车祸）或穿透伤所致，是腹部外伤中病死率较高的损伤。按AAST分级Ⅰ～Ⅵ级，主要表现为腹腔内出血与失血性休克，可合并胆道损伤致胆汁性腹膜炎。治疗以血流动力学状态为核心：稳定者保守或介入治疗，不稳定者急诊手术。","symptoms":["右上腹或全腹疼痛，可向右肩背部放射（膈肌刺激）","面色苍白、脉搏细速、血压下降、四肢湿冷（失血性休克）","腹部压痛、反跳痛、肌紧张（腹腔内出血/胆汁性腹膜炎）","腹胀、移动性浊音阳性（腹腔积血），腹围进行性增大","合并肋骨骨折、气胸、颅脑或四肢损伤（多发伤）"],"diagnosis":["血流动力学评估：血压、心率、尿量、意识（首要，决定处理策略）","FAST床旁超声：快速判断腹腔积液（首选筛查，可重复）","腹部增强CT（血流动力学稳定者）：明确肝损伤分级、活动性出血（造影剂外溢）、合并伤","诊断性腹腔穿刺/灌洗：抽出不凝血提示腹腔内出血","血常规+血型+交叉配血+凝血功能：动态监测血红蛋白与备血","肝功能+淀粉酶：评估肝损伤程度与有无胆道/胰腺损伤","腹部立位平片：合并空腔脏器损伤时可见膈下游离气体"],"infusion":["⚠️ 抢救用药，须在监护下按病情选择！","","方案1（抗休克液体复苏，控制性复苏原则）：","  用法：平衡盐溶液/0.9%氯化钠 快速补液（晶体为主）；红细胞悬液、新鲜冰冻血浆、血小板按1:1:1输注；目标Hb 70～90g/L、收缩压80～90mmHg（活动性出血未控制时避免过度升压）","","方案2（止血辅助）：","  用法：氨甲环酸 1g（NS 100ml 或 5%GS 100ml）静滴（伤后3小时内，8小时内可用）；维生素K1 10mg 静滴；必要时凝血酶原复合物〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（抑酸与支持）：","  用法：艾司奥美拉唑 40mg 静推 q12h；还原型谷胱甘肽 1.2g（NS 100ml 或 5%GS 100ml）静滴 qd（保肝）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案4（抗感染）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（或头孢曲松 2g qd）〔调 CrCl<30 减量；青霉素过敏禁用〕","","📌 抗休克与手术准备同步进行；控制性复苏避免过量晶体液（加重出血与凝血障碍）。"],"oral_medication":["⚠️ 急性期禁食禁水、不宜口服给药；恢复期遵医嘱：","药物1（保肝）：","用法：多烯磷脂酰胆碱 456mg tid 或 还原型谷胱甘肽片 0.4g tid","药物2（通便，防用力）：","用法：乳果糖 15ml bid〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时（避免长期大剂量）；塞来昔布 200mg qd（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 保守治疗期间需绝对卧床，避免用力排便、剧烈咳嗽与搬动（防迟发性破裂出血）。"],"treatment":["血流动力学不稳定者：立即抗休克+急诊剖腹探查（肝周填塞、缝扎止血、肝部分切除或肝动脉结扎）","血流动力学稳定者：分级处理——Ⅰ～Ⅲ级多可非手术治疗（卧床、监测、输血、必要时介入栓塞）","介入治疗：肝动脉造影栓塞（TAE）适用于活动性出血且血流动力学稳定的病例","腹腔镜探查：适用于诊断不明确、血流动力学稳定者，可同时处理出血与腹腔积血","胆道损伤处理：胆漏者行胆道引流（T管）或胆肠吻合；严重肝损伤注意胆道重建","损伤控制外科：严重多发伤伴凝血障碍、酸中毒、低体温者先行简化止血+填塞，待稳定后二次手术","并发症处理：迟发性破裂出血、肝脓肿、胆漏、胆道出血（胆道出血三联征：黄疸、腹痛、消化道出血）"],"management":["绝对卧床休息（非手术治疗者至少卧床1～2周），避免用力、搬动与剧烈咳嗽","严密监测：血压、心率、尿量、腹围每1～2小时（休克期更频）；动态复查血红蛋白","腹腔引流观察：记录引流液量、颜色与性状（鲜红增多提示再出血，胆汁样提示胆漏）","输血输液管理：按医嘱输注血制品，观察输血反应","疼痛与呼吸管理：充分镇痛，鼓励深呼吸与咳痰（防肺不张），但避免剧烈活动","复查影像：非手术治疗者伤后48～72小时复查CT，评估损伤进展或血肿变化","出院指导：1～3个月内避免剧烈运动与重体力劳动，出现腹痛加剧立即就诊"],"notes":["肝外伤处理的核心是『血流动力学状态』而非CT分级——不稳定者必须立即手术，不能因等待检查延误","非手术治疗期间可发生迟发性破裂出血（伤后数天至数周），需继续卧床与随访","肝外伤合并胆道损伤可致胆漏、胆汁性腹膜炎与胆道出血，需及时识别处理","大量输血注意纠正低体温、酸中毒与凝血障碍（致死性三联征）","合并肋骨骨折、气胸者需同时处理（胸部损伤可加重缺氧与呼吸衰竭）"],"emergency":["血压持续下降、腹围迅速增大、血红蛋白进行性下降（活动性出血）→ 立即急诊手术","非手术治疗期间突发剧烈腹痛伴休克（迟发性破裂）→ 立即抢救并手术","呕血/黑便伴黄疸、右上腹绞痛（胆道出血）→ 急诊内镜/介入或手术止血"],"pinyin":"gwsglpl","icd10":"S36.1","physical_exam":["生命体征：血压、心率、呼吸、血氧、意识（休克评估，每15～30分钟）","一般情况：面色苍白、皮肤湿冷、颈静脉塌陷、尿量减少","腹部视诊：腹围（画线标记并测量）、皮肤瘀斑与轮胎印（撞击部位）、开放性伤口","腹部触诊：压痛部位与范围、反跳痛、肌紧张、肝区压痛（肝浊音界）","腹部叩诊：移动性浊音（腹腔积血）、肝浊音界扩大（肝包膜下血肿）","合并伤评估：肋骨骨折、气胸/血胸、骨盆骨折、颅脑损伤、脊柱损伤","直肠指检：盆腔积液或合并直肠损伤（指套染血）"],"lab_tests":["血常规+血型+交叉配血：急查并动态监测血红蛋白（每1～2小时，休克期）","凝血功能+D-二聚体+纤维蛋白原：评估创伤性凝血病与DIC，指导血制品输注","肝功能（ALT/AST/胆红素）+淀粉酶：评估肝损伤与有无胰胆损伤","血气分析+乳酸：评估组织灌注与休克程度","FAST床旁超声+腹部增强CT：明确肝损伤分级、活动性出血与腹腔积血量","肾功能+电解质：评估器官功能与复苏效果","尿常规+尿量：监测尿量（目标≥0.5ml/kg/h）"],"nursing":["休克护理：平卧、保温、建立两条以上静脉通路，遵医嘱快速补液输血，每15～30分钟监测生命体征与尿量","绝对卧床：非手术治疗者严禁下床、用力与搬动，翻身时保持躯干平直","病情观察：腹痛、腹围、引流液性状、皮肤黏膜出血与意识变化，异常立即报告","引流管护理：妥善固定，记录引流量与性状，保持通畅，防止牵拉脱出","术前准备：拟手术者迅速禁食、备皮、备血、留置胃管与尿管，做好急诊手术准备","呼吸护理：鼓励深呼吸与有效咳嗽（防肺部感染），避免剧烈活动"],"diet":["急性期严格禁食禁水（可能急诊手术或需观察）","非手术治疗稳定后：从流质开始逐步过渡到低脂、易消化软食","高蛋白、高维生素饮食促进肝组织修复（鱼、瘦肉、蛋、奶、新鲜蔬果）","低脂饮食减轻肝脏负担，避免油腻、油炸与酒类","恢复期多饮水、多食纤维食物，保持大便通畅（避免用力排便诱发再出血）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1348},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c3ca40b4d327742ef7ef15d71b000660d91cb9c550e5134456a8dc5045f46efc","pinyin":"ganwaishang（ganpolie）","initials":"gws（gpl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","右上腹或全腹疼痛，可向右肩背部放射（膈肌刺激）\\n面色苍白、脉搏细速、血压下降、四肢湿冷（失血性休克）\\n腹部压痛、反跳痛、肌紧张（腹腔内出血/胆汁性腹膜炎）\\n腹胀、移动性浊音阳性（腹腔积血），腹围进行性增大\\n合并肋骨骨折、气胸、颅脑或四肢损伤（多发伤）",60],["摘要","肝外伤多由腹部钝性外伤（撞击、坠落、车祸）或穿透伤所致，是腹部外伤中病死率较高的损伤。按AAST分级Ⅰ～Ⅵ级，主要表现为腹腔内出血与失血性休克，可合并胆道损伤致胆汁性腹膜炎。治疗以血流动力学状态为核心：稳定者保守或介入治疗，不稳定者急诊手术。",30],["疾病编码","S36.1",30],["原首字母","gwsglpl",60]]},{"id":"orders-22465d4e5278772504e4","key":"v1-c9ccc21dfe2a3058|orders-22465d4e5278772504e4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"胰腺假性囊肿","category":"肝胆外科","raw":{"name":"胰腺假性囊肿","category":"肝胆外科","summary":"胰腺假性囊肿是急性胰腺炎或胰腺外伤后，胰液外渗被纤维组织包裹形成的囊性积液，囊壁无上皮细胞（故称假性）。多在急性胰腺炎后4周以上形成，表现为上腹包块、腹胀、腹痛；直径>6cm、持续6周以上不消退或出现并发症（感染、出血、破裂、压迫）者需干预（内镜/经皮引流或手术）。","symptoms":["上腹或左上腹包块，可活动度差，伴上腹胀满、隐痛或钝痛","进食后腹胀加重、食欲减退、消瘦","压迫症状：压迫胃十二指肠致恶心呕吐（胃排空障碍）、压迫胆管致黄疸、压迫门静脉致脾大或腹水","继发感染：发热、腹痛加剧、包块压痛（囊内感染/脓肿）","并发症：囊肿破裂（急腹症）、囊内出血（腹痛加重、血红蛋白下降）、胰源性腹水"],"diagnosis":["腹部超声：首选筛查，显示上腹囊性无回声区、囊壁厚度、与胰腺关系","腹部增强CT：明确囊肿大小、部位、数目、与胰管和周围脏器关系（决定治疗方式）","MRCP/磁共振：评估囊肿与胰管是否相通（是否适合内镜引流的关键）","血淀粉酶/脂肪酶+肝功能：评估胰腺炎活动与胆道受压","血常规+CRP+PCT：疑感染时（囊内感染需引流）","内镜超声（EUS）：评估囊壁成熟度（是否适合内镜引流）、可行细针穿刺送检（鉴别囊性肿瘤）","囊肿穿刺液分析（必要时）：淀粉酶（极高提示与胰管相通）、CEA/细胞学（排除囊性肿瘤）"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","方案1（抑制胰液分泌）：","用法：生长抑素 3mg/12h 持续泵入 或 奥曲肽 25～50μg/h 泵入（疗程1～2周）；艾司奥美拉唑 40mg 静推 q12h〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","方案2（抗感染，囊内感染时）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 美罗培南 1g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案3（营养支持）：","用法：全肠外营养（葡萄糖+氨基酸+脂肪乳+电解质）；或鼻空肠管肠内营养（避免刺激胰腺分泌）","方案4（支持/镇痛）：","用法：0.9%氯化钠 静滴；布桂嗪 100mg 肌注 必要时；白蛋白 10g 静滴（低蛋白）","📌 囊肿未感染时不需要抗生素；肠内营养须经鼻空肠管（避免经胃喂养刺激胰腺）。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（胰酶补充，胰腺外分泌功能不全）：","用法：胰酶肠溶胶囊 1～2粒 随餐 tid","药物2（抑酸）：","用法：艾司奥美拉唑 20mg qd（餐前）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物3（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时 或 塞来昔布 200mg qd（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 恢复期严格低脂饮食、禁酒；囊肿消退前避免剧烈运动与腹部外伤（防破裂）。"],"treatment":["随访观察：囊肿<6cm、无症状、无并发症者可先观察（每2～3个月复查超声/CT），部分可自行吸收（多见于<4cm者）","内镜引流（首选）：囊肿与胃/十二指肠壁紧贴且囊壁成熟（>4～6周）者行EUS引导下囊肿胃/十二指肠吻合或支架置入","经皮穿刺置管引流：适用于囊肿较大、与胰管相通或不适合内镜者（注意胰瘘风险），可反复冲洗","外科手术：内镜/经皮引流失败、囊肿多发或合并胰管狭窄/断裂者行囊肿空肠Roux-en-Y吻合或胰部分切除","感染性囊肿：引流+抗感染，必要时手术清除坏死组织","并发症处理：破裂（急诊手术）、出血（介入栓塞或手术）、压迫致梗阻（引流解除）","病因处理：胆源性胰腺炎处理结石；高脂血症性控制血脂；戒酒"],"management":["观察囊肿大小与症状：定期复查超声/CT，记录包块大小、腹胀与疼痛变化","饮食管理：低脂饮食，少量多餐；急性期禁食、肠外营养","引流管护理：妥善固定、保持通畅、记录引流液量与淀粉酶（高淀粉酶提示胰瘘），观察引流口周围皮肤","感染监测：体温、腹痛、白细胞与PCT；囊内感染时需及时引流","营养评估：每月测体重与白蛋白，营养不良者加强肠内/肠外营养","随访计划：内镜/经皮引流后每1～3个月复查，确认囊肿消退与有无复发","宣教：避免饮酒、暴饮暴食与腹部外伤；出现腹痛加剧、发热及时就诊"],"notes":["胰腺假性囊肿需与胰腺囊性肿瘤（黏液性/浆液性囊腺瘤、IPMN）鉴别，囊液CEA与细胞学有助鉴别","囊肿壁成熟一般需4～6周，过早引流易致胰瘘与复发","囊肿与胰管相通是选择内镜引流的重要依据（MRCP/EUS评估）","感染性假性囊肿病死率较高，需及时引流并抗感染","合并胰管断裂者常需手术（内镜引流效果差）"],"emergency":["突发剧烈腹痛伴腹膜刺激征（囊肿破裂）→ 急诊手术","腹痛加剧伴血红蛋白下降（囊内出血）→ 急诊评估，介入栓塞或手术","高热寒战伴上腹剧痛、感染指标升高（囊肿感染/脓肿）→ 急诊引流+抗感染"],"pinyin":"yxjxsz","icd10":"K86.3","physical_exam":["生命体征：体温（感染）、脉搏、血压、体重变化","一般情况：营养状态、消瘦、有无黄疸","腹部视诊：上腹膨隆（包块）、手术瘢痕、腹壁静脉曲张","腹部触诊：上腹/左上腹包块（大小、质地、活动度、有无压痛与波动感）、肝脾大小","腹部叩诊：包块叩诊浊音、移动性浊音（胰源性腹水）","腹部听诊：肠鸣音（胃排空障碍时减弱）","皮肤：黄疸、皮下瘀斑（Grey-Turner征）"],"lab_tests":["血淀粉酶+脂肪酶：评估胰腺炎活动性与囊肿性质（囊液淀粉酶极高提示与胰管相通）","血常规+CRP+PCT：感染评估（囊内感染时升高）","肝功能+胆红素：评估胆道是否受压（梗阻性黄疸）","白蛋白+前白蛋白+体重：营养状态评估（指导营养支持）","腹部增强CT+MRCP：明确囊肿大小、部位、与胰管关系（决定治疗方案）","内镜超声（EUS）±细针穿刺：评估囊壁成熟度与囊液分析（鉴别囊性肿瘤）","血糖+糖化血红蛋白：胰腺内分泌功能评估（胰腺炎后糖尿病常见）"],"nursing":["病情观察：观察腹痛、腹胀、包块大小与体温变化，警惕囊肿感染、破裂与出血","饮食护理：低脂饮食、少量多餐；引流期间遵医嘱禁食或肠内营养（鼻空肠管）","引流管护理：妥善固定、防止脱出，记录引流液量与性状，观察引流口周围皮肤有无糜烂（胰液腐蚀），必要时涂氧化锌软膏","营养与体重监测：每周测体重，记录进食量，配合营养师制定方案","活动指导：避免剧烈运动、腹部撞击与用力排便（防囊肿破裂）","宣教随访：禁酒、低脂饮食、按时复查，出现剧烈腹痛或发热立即就诊"],"diet":["严格低脂饮食：禁油炸、肥肉、动物内脏、浓肉汤，脂肪摄入控制在每日30～50g以内","少量多餐（每日5～6餐），减轻胰腺与胃肠负担","适量优质蛋白（鱼、瘦肉、蛋清、豆制品）与充足碳水提供热量","禁酒（酒精是胰腺炎复发与囊肿形成的重要诱因）","恢复期补充胰酶制剂（随餐服用），必要时补充脂溶性维生素"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1349},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ebbe1b17e2b65379ef00121bc0737a4ec085ec8682941ab7f776e5f5a760e86d","pinyin":"yixianjiaxingnangzhong","initials":"yxjxnz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","上腹或左上腹包块，可活动度差，伴上腹胀满、隐痛或钝痛\\n进食后腹胀加重、食欲减退、消瘦\\n压迫症状：压迫胃十二指肠致恶心呕吐（胃排空障碍）、压迫胆管致黄疸、压迫门静脉致脾大或腹水\\n继发感染：发热、腹痛加剧、包块压痛（囊内感染/脓肿）\\n并发症：囊肿破裂（急腹症）、囊内出血（腹痛加重、血红蛋白下降）、胰源性腹水",60],["摘要","胰腺假性囊肿是急性胰腺炎或胰腺外伤后，胰液外渗被纤维组织包裹形成的囊性积液，囊壁无上皮细胞（故称假性）。多在急性胰腺炎后4周以上形成，表现为上腹包块、腹胀、腹痛；直径>6cm、持续6周以上不消退或出现并发症（感染、出血、破裂、压迫）者需干预（内镜/经皮引流或手术）。",30],["疾病编码","K86.3",30],["原首字母","yxjxsz",60]]},{"id":"orders-de19081a6d98453a2942","key":"v1-c9ccc21dfe2a3058|orders-de19081a6d98453a2942","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"胆道术后胆漏","category":"肝胆外科","raw":{"name":"胆道术后胆漏","category":"肝胆外科","summary":"胆漏是胆道手术（胆囊切除、胆总管探查、肝切除、胆肠吻合）后胆汁从胆道系统漏出至腹腔或引流管，发生率约0.5%～2%，多因胆囊管残端处理不当、迷走胆管损伤、胆总管损伤或吻合口漏所致。表现为腹痛、发热、引流液呈胆汁样，需充分引流+抗感染，必要时内镜或手术处理。","symptoms":["术后腹痛（右上腹或全腹）、腹胀，可伴腹膜刺激征（胆汁性腹膜炎）","发热（多为低热至中度热），白细胞升高","腹腔引流管引出胆汁样液体（金黄色、黄绿色），量可多可少","无引流管者出现腹腔积液、腹胀与肠麻痹","严重者出现黄疸（胆道梗阻或损伤）、胆汁性腹膜炎致脓毒症"],"diagnosis":["引流液检查：胆红素浓度显著高于血清（>血清3倍）可确诊胆漏；测淀粉酶排除胰漏","腹部超声/CT：评估腹腔积液部位与量（可引导穿刺引流）","MRCP/肝胆核素扫描（HIDA）：明确胆漏部位与胆道是否通畅","ERCP/胆道造影（经T管或ENBD）：诊断胆漏部位及胆管损伤程度，同时可行治疗（支架/鼻胆管引流）","血常规+CRP+PCT+肝功能（胆红素）：评估感染与胆道梗阻","T管造影（术后2周）：评估胆道通畅性与有无残余结石、胆漏"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","方案1（抗感染，覆盖肠道菌群）：","用法：头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h；或哌拉西林他唑巴坦 4.5g 静滴 q8h（重症）〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案2（抑酸抑酶，减少胆胰分泌）：","用法：艾司奥美拉唑 40mg 静推 q12h；生长抑素 3mg/12h 泵入 或 奥曲肽 25～50μg/h（必要时）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","方案3（保肝与营养支持）：","用法：还原型谷胱甘肽 1.2g 静滴 qd + 腺苷蛋氨酸 1g 静滴 qd；全肠外营养（禁食者）；白蛋白 10g 静滴（低蛋白）","方案4（补液与电解质）：","用法：平衡盐溶液/0.9%氯化钠 静滴（按引流量与尿量补足）；纠正低钾低钠","📌 胆漏治疗核心是『充分引流+保持胆道通畅』；抗生素不能替代引流。"],"oral_medication":["⚠️ 恢复期遵医嘱，同类只选一种：","药物1（利胆）：","用法：熊去氧胆酸 250mg tid 或 腺苷蛋氨酸肠溶片 500mg bid","药物2（保肝）：","用法：多烯磷脂酰胆碱 456mg tid","药物3（抗感染序贯）：","用法：头孢克肟 0.1g bid + 甲硝唑 0.4g tid 或 阿莫西林克拉维酸 0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","📌 引流期间避免剧烈活动与用力（防引流管脱出）；T管需妥善固定并按医嘱拔管。"],"treatment":["充分引流：经皮穿刺置管/原引流管保持通畅，多数小胆漏经充分引流可自愈（1～2周）","内镜治疗（首选干预手段）：ERCP+EST+鼻胆管（ENBD）或胆道支架置入，降低胆道压力促进漏口愈合","抗生素：覆盖肠道菌群，按培养调整，合并胆汁性腹膜炎时加强","营养支持：禁食、全肠外营养；肠功能允许时经鼻空肠管肠内营养；补充白蛋白","手术指征：腹腔引流不畅、胆汁性腹膜炎、胆管横断或损伤、内镜治疗失败——行胆管修补、T管引流或胆肠吻合","胆道通畅维护：T管/ENBD妥善固定，避免牵拉、受压与脱出","随访：引流减少、症状缓解后逐步退管；复查MRCP/超声评估胆道情况"],"management":["引流观察与记录：每日记录引流量、颜色（金黄色/黄绿/浑浊）与性状，突然增多或减少均需报告","引流管护理：妥善固定（标记刻度）、防止牵拉脱出、保持通畅，必要时低压冲洗","腹痛与腹部体征监测：观察腹膜刺激征范围变化（胆汁性腹膜炎加重需紧急处理）","体温与感染指标：每4小时测体温，动态复查血常规、CRP、PCT与肝功能","营养与出入量：记录24小时出入量，按引流量补充液体与电解质，监测白蛋白","皮肤护理：引流口周围胆汁刺激易致皮肤糜烂，及时清洁并涂氧化锌软膏保护","拔管管理：引流量<20～50ml/日、症状缓解、复查影像无积液后逐步拔管（由主管医师决定）"],"notes":["胆漏诊断关键：引流液胆红素>血清3倍；同时注意与胰漏、淋巴漏鉴别","多数小胆漏经充分引流+保持胆道通畅可自愈，避免过早再次手术（局部水肿粘连，手术困难）","胆囊切除术后迷走胆管（Luschka管）漏较常见，多可自愈；胆总管损伤漏需积极处理","ERCP+ENBD/支架是胆漏的非手术治疗首选，可避免再次手术","胆汁性腹膜炎可致严重脓毒症，引流不畅者必须及时手术"],"emergency":["腹痛加剧伴全腹腹膜刺激征、血压下降（胆汁性腹膜炎/脓毒症）→ 急诊手术探查","引流管引出大量鲜血（胆道出血/血管损伤）→ 急诊介入或手术止血","高热寒战伴黄疸加重（胆道梗阻合并感染）→ 紧急胆道引流"],"pinyin":"ddshdl","icd10":"K83.8","physical_exam":["生命体征：体温、脉搏、血压（感染与休克评估）","一般情况：精神、营养状态、有无黄疸与脱水","腹部视诊：切口愈合情况（有无渗液、红肿）、腹胀、手术瘢痕","腹部触诊：压痛部位与范围、反跳痛、肌紧张（胆汁性腹膜炎）、肝区叩击痛","腹部叩诊：移动性浊音（腹腔积液）、肝浊音界","引流管：位置、引流量与性状（胆汁样）、周围皮肤情况","腹部听诊：肠鸣音（肠麻痹时减弱或消失）"],"lab_tests":["引流液胆红素+淀粉酶：与血清对比（胆红素>血清3倍提示胆漏；淀粉酶高提示胰漏）","肝功能+胆红素+ALP/GGT：评估胆道梗阻与损伤程度，动态观察","血常规+CRP+PCT：感染程度评估，每2～3天复查","血培养+引流液培养及药敏：发热或感染加重时留取","腹部超声/CT：评估腹腔积液部位与量（可引导穿刺引流）","MRCP/ERCP：明确胆漏部位与胆道损伤程度，同时可行治疗","电解质+白蛋白+肾功能：评估营养状态与液体丢失"],"nursing":["引流护理：妥善固定并标记刻度，记录引流量与性状，保持通畅，防止牵拉脱出与逆行感染","皮肤护理：胆汁刺激可致引流口周围皮肤糜烂，及时清洁并涂氧化锌软膏或造口护肤粉","腹痛与体温观察：每4小时测体温，观察腹痛与腹膜刺激征变化，异常立即报告","出入量与营养：记录24小时出入量，按引流量补液，遵医嘱给予肠外/肠内营养并观察耐受","体位与活动：半卧位利于引流，避免剧烈活动与用力（防引流管脱出）","拔管宣教：告知拔管需循序渐进（先退管后拔除），避免自行拔管"],"diet":["急性期禁食禁水，行胃肠减压与肠外营养","引流减少、肠功能恢复后：低脂流质→低脂半流质→低脂软食逐步过渡","低脂饮食（每日脂肪<40g），减少胆汁分泌与胆道负担","高蛋白、高维生素饮食促进组织修复（鱼、瘦肉、蛋清、新鲜蔬果）","禁酒、忌辛辣刺激与油炸食物；少量多餐，避免暴饮暴食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1350},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5984d7b7389abebfba1c3181522090d6953e204a63458d9d5834cf72ef19eb1b","pinyin":"dandaoshuhoudanlou","initials":"ddshdl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术后腹痛（右上腹或全腹）、腹胀，可伴腹膜刺激征（胆汁性腹膜炎）\\n发热（多为低热至中度热），白细胞升高\\n腹腔引流管引出胆汁样液体（金黄色、黄绿色），量可多可少\\n无引流管者出现腹腔积液、腹胀与肠麻痹\\n严重者出现黄疸（胆道梗阻或损伤）、胆汁性腹膜炎致脓毒症",60],["摘要","胆漏是胆道手术（胆囊切除、胆总管探查、肝切除、胆肠吻合）后胆汁从胆道系统漏出至腹腔或引流管，发生率约0.5%～2%，多因胆囊管残端处理不当、迷走胆管损伤、胆总管损伤或吻合口漏所致。表现为腹痛、发热、引流液呈胆汁样，需充分引流+抗感染，必要时内镜或手术处理。",30],["疾病编码","K83.8",30],["原首字母","ddshdl",60]]},{"id":"orders-29d9701eb09411487a7c","key":"v1-c9ccc21dfe2a3058|orders-29d9701eb09411487a7c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"脾功能亢进与脾切除术","category":"肝胆外科","raw":{"name":"脾功能亢进与脾切除术","category":"肝胆外科","summary":"脾功能亢进（脾亢）是各种原因（肝硬化门静脉高压、血液病、感染、免疫性疾病）致脾大伴外周血细胞一系或多系减少，脾切除后血象可改善。脾切除指征包括脾亢致严重血细胞减少、门静脉高压致食管胃底静脉破裂出血（断流术）、脾外伤、脾肿瘤与某些血液病。","symptoms":["贫血（乏力、面色苍白、活动后心悸气短）、感染易感性增加（白细胞减少）、出血倾向（血小板减少）","左上腹胀痛或坠胀感、餐后饱胀（脾大压迫胃）","肝硬化门静脉高压者伴腹水、食管胃底静脉曲张（可致呕血黑便）、黄疸","血液病者伴原发病表现（如淋巴瘤发热、遗传性球形红细胞增多症黄疸）","脾梗死或脾周围炎时左上腹剧痛并向左肩放射"],"diagnosis":["血常规+网织红细胞：三系减少（白细胞<4×10⁹/L、血小板<100×10⁹/L、血红蛋白降低）","腹部超声/CT：脾大小（脾长径>12cm或厚径>4cm为脾大）、门静脉内径、有无血栓、腹水","骨髓穿刺+活检：评估骨髓造血功能（鉴别骨髓衰竭与外周破坏）","肝功能+白蛋白+胆红素+凝血：评估肝储备（Child-Pugh分级）","胃镜：门静脉高压者评估食管胃底静脉曲张","病因学检查：肝炎病毒标志物、自身免疫抗体、Coombs试验、红细胞脆性试验、HBV-DNA等","血细胞破坏部位评估（放射性核素）：脾脏是否为破坏主要部位（必要时）"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术前/术后补充凝血）：","  用法：维生素K1 10mg（NS 100ml 或 5%GS 100ml）静滴 qd（肝功能差者）；血小板<30×10⁹/L 或有出血时输注血小板；新鲜冰冻血浆按需","","方案3（保肝/支持，肝硬化患者）：","  用法：还原型谷胱甘肽 1.2g 静滴 qd + 腺苷蛋氨酸 1g 静滴 qd；白蛋白 10g 静滴（低蛋白）；必要时补充凝血酶原复合物","","方案4（降门脉压，门静脉高压者）：","  用法：生长抑素 3mg/12h 泵入 或 奥曲肽 25～50μg/h 泵入（按医嘱，用于出血期）〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","","📌 脾切除术后血小板可显著升高（术后1～2周达高峰），需监测并必要时抗血小板治疗（防血栓）。"],"oral_medication":["⚠️ 术后与长期用药，按医嘱选择：","药物1（抗血小板，血小板显著升高时）：","用法：阿司匹林肠溶片 100mg qd 或 氯吡格雷 75mg qd（血小板>500～1000×10⁹/L时，遵医嘱）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","药物2（预防感染，脾切除后）：","用法：青霉素V钾 0.5g bid（长期预防，尤其术后前2年，遵医嘱）","药物3（保肝）：","用法：多烯磷脂酰胆碱 456mg tid 或 水飞蓟宾 70mg tid","药物4（降门脉压，预防再出血）：","用法：普萘洛尔 10mg bid 起（调整至静息心率下降25%或55～60次/分）","📌 脾切除后需接种肺炎链球菌、脑膜炎奈瑟菌与流感嗜血杆菌疫苗（术前2周或术后恢复期）。"],"treatment":["脾切除术指征：脾亢致严重血细胞减少（尤其血小板<30×10⁹/L或有出血）、门静脉高压致反复食管胃底静脉破裂出血（贲门周围血管离断+脾切除）、脾外伤、脾脓肿/肿瘤、遗传性球形红细胞增多症等血液病","术式选择：开腹脾切除（巨脾、门静脉高压）或腹腔镜脾切除（中等大小脾、血液病）","术前准备：评估肝功能与凝血、补充维生素K₁ 10mg 肌注 qd、血小板低于30×10⁹/L者术前输注血小板 1个治疗量、备血、疫苗接种（肺炎球菌+流感+脑膜炎球菌疫苗）","术中注意：处理脾蒂血管、防止脾破裂（避免脾组织种植致副脾残留、复发）","术后处理：监测血小板与血象变化、血小板>500×10⁹/L时抗凝/抗血小板（阿司匹林 100mg qd 口服）、预防感染","门静脉高压者：术后继续降门脉压治疗（普萘洛尔 10-20mg 口服 bid-tid，心率不低于55次/分）与胃镜随访，预防再出血","血液病者：术后评估疗效与原发病治疗（如需要化疗、免疫抑制）"],"management":["术后监测：血压、心率、引流液（腹腔引流>200ml/h鲜红提示活动性出血需处理）、血小板与血象","血小板管理：术后每日查血常规，血小板>500×10⁹/L时遵医嘱抗血小板治疗（警惕门静脉/脾静脉血栓）","感染预防：术后早期监测体温与切口，脾切除后远期有爆发性感染（OPSI）风险，需疫苗接种与预防性抗生素","疼痛与体位：观察左上腹疼痛与腹胀，协助半卧位与早期活动","引流管护理：保持通畅、记录引流量与性状（胰尾损伤可致胰漏，引流液淀粉酶高）","营养支持：术后遵医嘱从流质过渡，肝硬化者控制蛋白与钠盐","随访：术后1、3、6个月复查血常规、肝功能与超声；血液病者随访原发病"],"notes":["脾切除术后血小板升高是常见现象（多在1～2周达高峰），显著升高需抗血小板治疗并警惕血栓","脾切除后终生有爆发性感染（OPSI）风险（尤其儿童与免疫抑制者），必须接种疫苗并告知发热需及时就诊","门静脉高压患者脾切除+断流术可降低出血风险，但仍需胃镜随访与药物预防","血小板过低者术前输注血小板，术中精细止血（避免术后腹腔出血）","术后左上腹持续剧痛伴发热需警惕脾窝积液/膈下脓肿与胰尾损伤"],"emergency":["术后引流大量鲜红血液、血压下降（腹腔活动性出血）→ 急诊探查止血","术后高热伴左上腹剧痛、感染指标升高（脾窝脓肿/膈下脓肿）→ 引流+抗感染","脾切除后突发高热寒战、休克（OPSI）→ 立即抗感染与抢救","脾切除后腹痛腹胀迅速加重伴血小板显著升高（门静脉血栓）→ 急诊影像评估并抗凝"],"pinyin":"pgnkypqcs","icd10":"D73.1","physical_exam":["生命体征：体温、脉搏、血压（感染与出血评估）","一般情况：贫血貌、皮肤黏膜出血点、营养状态","皮肤黏膜：黄疸、蜘蛛痣、肝掌、瘀斑（肝功能与凝血状态）","腹部视诊：左上腹膨隆（脾大）、腹壁静脉曲张、腹围","腹部触诊：脾下缘位置与质地（大小分级）、肝大小与质地、有无压痛","腹部叩诊：脾区叩击痛、移动性浊音（腹水）","腹部听诊：脾区摩擦音（脾梗死/脾周围炎）、肠鸣音"],"lab_tests":["血常规（三系）+网织红细胞：评估脾亢程度，术后每日复查直至稳定（重点血小板）","肝功能+白蛋白+胆红素+凝血酶原时间：评估肝储备（Child-Pugh）与术前风险","骨髓穿刺+活检：鉴别骨髓造血功能与外周破坏（血液病者必查）","腹部超声/增强CT：脾大小、门静脉内径与血栓、腹水、副脾","胃镜：门静脉高压者评估食管胃底静脉曲张程度与出血风险","病因检查：肝炎病毒标志物+HBV-DNA、自身抗体、Coombs试验、红细胞脆性试验","血型+交叉配血+电解质+肾功能：术前准备与评估"],"nursing":["术前护理：评估出血倾向（牙龈、皮肤瘀斑）、遵医嘱补充维生素K与血小板，做好疫苗接种宣教","术后观察：密切监测血压、心率、引流液性状与量（腹腔出血是主要早期并发症）","血小板监测：术后每日查血常规，血小板>500×10⁹/L时按医嘱抗血小板并观察血栓征象（下肢肿痛、腹痛）","感染预防：监测体温、切口情况；宣教脾切除后感染风险（发热需及时就医）与疫苗接种重要性","体位与活动：麻醉清醒后取半卧位，鼓励早期床上活动与深呼吸，预防肺部感染与血栓","引流与营养：保持腹腔引流管通畅，术后按医嘱从流质过渡到高蛋白饮食（肝硬化者限钠限蛋白）"],"diet":["脾亢伴肝硬化者：限制钠盐（<2g/日）、适量优质蛋白，避免肝性脑病时过量蛋白","非肝硬化者：高蛋白、高维生素、易消化饮食，促进术后恢复","贫血者增加含铁食物（动物肝脏、瘦肉、菠菜）与维生素C促进铁吸收","血小板低者避免粗糙、坚硬、带刺食物（防口腔与消化道出血）","戒酒、忌辛辣刺激；少量多餐，避免饱胀（巨脾压迫胃）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1351},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"41eeee517403362136971452a37b7a66070ea983430048701f954225033ebaa8","pinyin":"pigongnengkangjinyupiqiechushu","initials":"pgnkjypqcs","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","贫血（乏力、面色苍白、活动后心悸气短）、感染易感性增加（白细胞减少）、出血倾向（血小板减少）\\n左上腹胀痛或坠胀感、餐后饱胀（脾大压迫胃）\\n肝硬化门静脉高压者伴腹水、食管胃底静脉曲张（可致呕血黑便）、黄疸\\n血液病者伴原发病表现（如淋巴瘤发热、遗传性球形红细胞增多症黄疸）\\n脾梗死或脾周围炎时左上腹剧痛并向左肩放射",60],["摘要","脾功能亢进（脾亢）是各种原因（肝硬化门静脉高压、血液病、感染、免疫性疾病）致脾大伴外周血细胞一系或多系减少，脾切除后血象可改善。脾切除指征包括脾亢致严重血细胞减少、门静脉高压致食管胃底静脉破裂出血（断流术）、脾外伤、脾肿瘤与某些血液病。",30],["疾病编码","D73.1",30],["原首字母","pgnkypqcs",60]]},{"id":"orders-b5c91caa53b88e8a4e3e","key":"v1-c9ccc21dfe2a3058|orders-b5c91caa53b88e8a4e3e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"胃癌围手术期管理","category":"胃肠外科","raw":{"name":"胃癌围手术期管理","category":"胃肠外科","summary":"胃癌围手术期管理涵盖术前评估与准备（营养、分期、合并症）、手术方式（远端/全胃切除+D2淋巴结清扫，腹腔镜或开腹）、术后并发症防治（吻合口瘘、出血、胃瘫、倾倒综合征）与营养支持，是保证手术安全与远期疗效的关键。","symptoms":["术前：上腹疼痛、饱胀、纳差、消瘦、贫血、呕血或黑便、吞咽困难（贲门癌）","术后早期：发热、腹痛、引流液异常（吻合口瘘）、引流管大量血性液（出血）、腹胀呕吐（胃瘫）","术后远期：倾倒综合征（餐后心悸、出汗、腹泻）、贫血（维生素B12与铁吸收障碍）、反流性食管炎（全胃切除后）","体重下降、营养不良（全胃切除后常见）","复发表现：腹痛、腹块、腹水、锁骨上淋巴结肿大"],"diagnosis":["术前：胃镜+活检（病理确诊）、增强CT（分期/可切除性）、超声内镜（浸润深度T分期）、腹腔镜探查（腹膜转移评估）","术前实验室：血常规（贫血）、白蛋白与前白蛋白（营养）、肿瘤标志物（CEA、CA19-9、CA72-4）","术后监测：血常规、CRP、PCT、白蛋白、引流量与淀粉酶（吻合口瘘评估）","上消化道造影/胃镜：疑吻合口瘘或狭窄时","营养评估：NRS2002评分、体重与白蛋白动态（决定营养支持方式）","术后分期与随访：病理分期（TNM）、每3～6个月复查CT与肿瘤标志物"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g 静滴（或头孢曲松 2g）+ 甲硝唑 0.5g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术后抗感染，按病情）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（单纯术后24～48小时）；吻合口瘘者用哌拉西林他唑巴坦 4.5g q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案3（营养支持，术后早期）：","  用法：全肠外营养（葡萄糖+复方氨基酸+中长链脂肪乳+电解质+维生素+微量元素）经中心静脉输注；白蛋白 10g 静滴（低蛋白者）","","方案4（抑酸与止血）：","  用法：艾司奥美拉唑 40mg 静推 q12h；氨甲环酸 0.5g（NS 100ml 或 5%GS 100ml）静滴（必要时）；维生素K1 10mg 静滴〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","📌 术后应尽早（24～48小时）开始肠内营养（鼻空肠管或空肠造瘘），有利于吻合口愈合与肠功能恢复。"],"oral_medication":["⚠️ 术后与恢复期用药，按医嘱选择：","药物1（抑酸）：","用法：艾司奥美拉唑 20mg qd（晨起餐前）或 雷贝拉唑 10mg qd〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物2（胃动力药，术后胃瘫）：","用法：甲氧氯普胺 10mg tid（餐前30分钟）或 莫沙必利 5mg tid（餐前）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物3（胰酶与消化酶，全胃切除后）：","用法：胰酶肠溶胶囊 1～2粒 随餐；复方消化酶 2粒 tid","药物4（补充维生素与铁，术后贫血）：","用法：维生素B12 500μg 肌注 每月1次（全胃切除后终身）；琥珀酸亚铁 0.1g bid + 维生素C 0.2g tid〔调 ★ 铁负荷过多禁用；★ 与四环素/喹诺酮/左甲状腺素间隔2小时〕","📌 全胃切除者需终身肌注维生素B12；术后贫血需定期监测血常规与铁代谢。"],"treatment":["术前准备：完善分期、营养支持（营养不良者术前7～10天肠内营养）、纠正贫血与低蛋白、控制合并症","手术方式：早期胃癌可行内镜黏膜下剥离（ESD）或腹腔镜局部/远端胃切除；进展期行根治性胃切除（远端/全胃）+D2淋巴结清扫","消化道重建：Billroth Ⅰ/Ⅱ式、Roux-en-Y吻合（全胃切除常用），注意防反流","术后早期管理：早期肠内营养、镇痛、早期下床活动（促进肠功能恢复、减少并发症）","并发症处理：吻合口瘘（引流+抗感染+营养支持）、出血（内镜/手术止血）、胃瘫（禁食减压+促动力药+营养支持）、倾倒综合征（少量多餐、低碳水、餐后平卧）","术后辅助治疗：根据病理分期行辅助化疗（SOX/XELOX等）或放化疗，HER2阳性者加曲妥珠单抗","随访：术后2年内每3～6个月复查（CT、肿瘤标志物、胃镜）"],"management":["术前管理：营养评估与支持（NRS2002≥3分者营养干预）、贫血纠正、戒烟、呼吸训练与床上排便训练","术后监测：生命体征、引流液性状与量（吻合口瘘/出血）、腹部体征、肠鸣音恢复与排气时间","引流管与胃管护理：保持通畅，记录引流量与性状（浑浊/肠内容物提示瘘），胃管减压至肠功能恢复","营养管理：术后24～48小时开始肠内营养（鼻空肠管，从糖盐水→短肽→整蛋白逐渐过渡），监测耐受性（腹胀、腹泻）","早期活动：术后第1天床上活动，逐步下床，促进肠功能恢复与预防深静脉血栓","并发症观察：发热、腹痛、心率增快、引流液异常（吻合口瘘）；呕吐大量胃内容物（胃瘫）","出院指导：少量多餐（每日5～6餐）、细嚼慢咽、低糖高蛋白、餐后平卧30分钟（防倾倒综合征）、定期复查"],"notes":["胃癌术后最常见的严重并发症是吻合口瘘（多发生于术后5～7天）与出血，需密切观察引流液与腹部体征","术后胃瘫表现为大量呕吐、腹胀、肠鸣音弱，需禁食减压+促动力药+营养支持，多数在数周内恢复","全胃切除后需终身补充维生素B12（每月肌注）并监测铁与钙代谢","倾倒综合征预防：少量多餐、低碳水化合物、避免高渗食物、餐后平卧30分钟，多数可通过饮食调整控制","营养状态直接影响预后，术后应常规营养随访与干预"],"emergency":["术后引流液呈浑浊/肠内容物样伴发热腹痛（吻合口瘘）→ 禁食减压+引流+抗感染，必要时手术","引流大量鲜红血液或呕血黑便伴血压下降（术后出血）→ 急诊内镜/手术止血","突发剧烈腹痛伴腹膜刺激征（吻合口裂开/穿孔）→ 急诊手术探查","大量呕吐、脱水与电解质紊乱（重度胃瘫）→ 禁食减压+补液纠正电解质"],"pinyin":"wywssqgl","icd10":"C16.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压（感染、出血与营养状态）","一般情况：营养状态、体重、贫血貌、有无锁骨上淋巴结肿大","腹部视诊：切口愈合情况（红肿渗液）、腹胀、手术瘢痕、肠型","腹部触诊：压痛部位与范围、反跳痛（吻合口瘘）、有无腹块","腹部叩诊与听诊：移动性浊音、肠鸣音（减弱提示肠麻痹/胃瘫）","引流管与胃管：位置、引流量与性状、胃液颜色","直肠指检与盆腔（必要时）：盆腔种植转移评估"],"lab_tests":["术前：血常规（贫血）、白蛋白/前白蛋白（营养）、肝肾功能、凝血功能、肿瘤标志物（CEA/CA19-9/CA72-4）、心电图与肺功能","术前分期：增强CT（胸腹盆）、超声内镜（T分期）、必要时PET-CT与腹腔镜探查","术后监测：血常规、CRP、PCT（吻合口瘘）、白蛋白与前白蛋白（营养）每2～3天","引流液检查：淀粉酶、胆红素、细菌培养（鉴别吻合口瘘与胰漏）","上消化道造影/胃镜：疑吻合口瘘、狭窄或出血时","营养相关：铁代谢、维生素B12、叶酸（术后贫血评估）","随访：每3～6个月肿瘤标志物+腹部CT（术后2年内）"],"nursing":["术前护理：营养支持（口服营养补充/肠内营养）、呼吸训练与有效咳嗽、床上排便训练、戒烟","术后体位与活动：麻醉清醒后取半卧位，鼓励早期床上活动与下床（术后第1天），预防肺部感染与血栓","引流与胃管护理：妥善固定、记录引流量与性状，胃管减压期间做好口腔护理","营养护理：早期肠内营养（鼻空肠管），注意温度、速度与浓度，观察腹胀腹泻等耐受不良征象","并发症观察：发热、腹痛、心率增快、引流液浑浊（吻合口瘘）；呕吐大量胃内容物（胃瘫）","饮食宣教：少量多餐（每日5～6餐）、细嚼慢咽、避免过甜与高渗食物、餐后平卧30分钟"],"diet":["术后早期：禁食+肠外/肠内营养；肠功能恢复后从清流质（米汤、藕粉）开始","过渡期：流质→低渣半流质→软食，少量多餐（每日5～6餐），每餐50～100ml起始逐渐加量","恢复期：高蛋白（鱼、瘦肉、蛋、豆制品）、低碳水化合物、适量脂肪、细软易消化","防倾倒综合征：避免高糖、高渗食物（甜点、含糖饮料、浓汤），餐后平卧30分钟，进餐时少喝汤水","全胃切除者：少量多餐、充分咀嚼、补充维生素B12与铁剂，定期监测营养指标"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1352},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e7594249f7818c2c99ffb52b2a6512aad599032b6279049473b9fd510d33dfed","pinyin":"weiaiweishoushuqiguanli","initials":"wawssqgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术前：上腹疼痛、饱胀、纳差、消瘦、贫血、呕血或黑便、吞咽困难（贲门癌）\\n术后早期：发热、腹痛、引流液异常（吻合口瘘）、引流管大量血性液（出血）、腹胀呕吐（胃瘫）\\n术后远期：倾倒综合征（餐后心悸、出汗、腹泻）、贫血（维生素B12与铁吸收障碍）、反流性食管炎（全胃切除后）\\n体重下降、营养不良（全胃切除后常见）\\n复发表现：腹痛、腹块、腹水、锁骨上淋巴结肿大",60],["摘要","胃癌围手术期管理涵盖术前评估与准备（营养、分期、合并症）、手术方式（远端/全胃切除+D2淋巴结清扫，腹腔镜或开腹）、术后并发症防治（吻合口瘘、出血、胃瘫、倾倒综合征）与营养支持，是保证手术安全与远期疗效的关键。",30],["疾病编码","C16.9",30],["原首字母","wywssqgl",60]]},{"id":"orders-08f4af0e5986b9840cd6","key":"v1-c9ccc21dfe2a3058|orders-08f4af0e5986b9840cd6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"结直肠癌围手术期管理","category":"胃肠外科","raw":{"name":"结直肠癌围手术期管理","category":"胃肠外科","summary":"结直肠癌围手术期管理包括术前肠道准备与分期评估、根治性切除（右半/左半/乙状结肠切除、直肠前切除或腹会阴联合切除）+淋巴结清扫、术后并发症防治（吻合口瘘、出血、肠梗阻）与造口管理，以及术后辅助治疗与随访。","symptoms":["术前：排便习惯改变（腹泻便秘交替）、便血或黏液血便、腹痛腹胀、贫血消瘦、肠梗阻表现（直肠癌可有里急后重、便条变细）","术后早期：发热、腹痛、引流液浑浊（吻合口瘘）、引流量增多或血性（出血）、腹胀无排气（肠梗阻/肠麻痹）","低位直肠癌术后：排便次数增多、里急后重、控便功能下降（前切除综合征）","造口相关：造口水肿、周围皮肤损伤、排泄物量异常","远期：吻合口狭窄、性功能与排尿功能障碍（盆腔手术神经损伤）"],"diagnosis":["术前：结肠镜+活检（病理确诊）、增强CT（胸腹盆分期）、直肠MRI（直肠癌局部分期）、肿瘤标志物（CEA）","术前评估：血常规、肝肾功能、凝血、营养状态、心电图与肺功能；必要时PET-CT","术后监测：血常规、CRP、PCT、引流液性状（吻合口瘘）、白蛋白","消化道造影/CT（含造影剂）：疑吻合口瘘时","病理分期：TNM分期（决定辅助治疗方案）","基因检测（必要时）：RAS/BRAF、MSI/dMMR（指导靶向与免疫治疗）"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染+肠道准备）：","  用法：头孢呋辛 1.5g 静滴 + 甲硝唑 0.5g 静滴（切皮前0.5～1小时）；术前1天口服肠道准备（聚乙二醇电解质散）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术后抗感染）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（24～48小时）；吻合口瘘者哌拉西林他唑巴坦 4.5g q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案3（营养支持）：","  用法：全肠外营养（术后早期禁食者）；尽早过渡到肠内营养（短肽制剂）；白蛋白 10g 静滴（低蛋白）","","方案4（抑酸与支持）：","  用法：艾司奥美拉唑 40mg 静推 q12h；维生素C 2g（NS 100ml 或 5%GS 100ml）静滴 qd；必要时输血（Hb<70g/L）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","📌 直肠癌低位吻合者术后需保持引流通畅；吻合口瘘高危者术中可预防性造口（保护性回肠造口）。"],"oral_medication":["⚠️ 术后与恢复期用药，按医嘱选择：","药物1（通便/调节排便）：","用法：乳果糖 15ml bid（便秘）或 蒙脱石散 3g tid（腹泻）；洛哌丁胺 2mg tid（前切除综合征腹泻）〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物2（肠道菌群调节）：","用法：双歧杆菌三联活菌 2粒 bid 或 地衣芽孢杆菌 0.5g tid","药物3（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时；塞来昔布 200mg qd（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（营养补充）：","用法：口服营养补充剂（ONS）1～2份/日；维生素B12（回肠切除者）","📌 造口患者避免自行服用泻药与产气药；排便频次增多者需防脱水与电解质紊乱。"],"treatment":["术前准备：机械性肠道准备（择期手术）+口服抗生素（遵医嘱）、营养支持、纠正贫血、控制合并症","手术方式：右半/左半/乙状结肠癌根治切除+D3淋巴结清扫（腹腔镜优先）；直肠癌行直肠前切除（Dixon）或腹会阴联合切除（Miles）+全直肠系膜切除（TME）","吻合口保护：低位直肠吻合者可行保护性回肠造口；确保吻合口血供与无张力","术后管理：早期活动、早期肠内营养、镇痛、引流管管理","并发症处理：吻合口瘘（引流+抗感染+营养，必要时手术）、出血（内镜/手术）、肠梗阻（禁食减压）、泌尿与性功能障碍（康复治疗）","术后辅助治疗：Ⅲ期与高危Ⅱ期行辅助化疗（XELOX/FOLFOX，3～6个月）；直肠癌高危者行放化疗","随访：术后2年内每3～6个月复查CEA与CT，术后1年内结肠镜（吻合口与异时病灶）"],"management":["术前管理：肠道准备（聚乙二醇清肠）、营养评估与支持、贫血纠正、造口定位（拟造口者术前由造口治疗师定位）","术后监测：生命体征、腹痛与腹部体征、引流液性状与量（吻合口瘘多发生于术后5～7天）、肠鸣音与排气时间","引流管护理：盆腔引流管保持通畅，记录量与性状（浑浊、粪样提示瘘），避免负压过大","早期活动与营养：术后第1天下床活动，术后24～48小时开始肠内营养（短肽制剂）","造口护理：观察造口颜色（红润为正常）、水肿与排泄物，指导造口产品更换与皮肤保护","排便功能管理：前切除综合征者记录排便频次与性状，遵医嘱用药与盆底肌训练","出院指导：饮食过渡（低渣→普食）、造口自我护理、定期复查、辅助治疗安排"],"notes":["吻合口瘘是结直肠术后最严重并发症（发生率3%～10%），多发生于术后5～7天，需密切观察","低位直肠癌保肛术后前切除综合征常见（排便频次增多、急迫感），多数在1～2年内改善","术后早期肠内营养可促进吻合口愈合与肠功能恢复，不必等到排气（ERAS理念）","造口患者需注意饮食调整（避免产气与堵塞食物）并保持水分与电解质平衡","术后辅助化疗应在术后8周内开始（延迟会影响疗效）"],"emergency":["术后发热、腹痛伴引流液浑浊/粪样（吻合口瘘）→ 禁食减压+引流+抗感染，必要时手术","引流大量鲜血或便血伴血压下降（吻合口出血）→ 急诊内镜/手术止血并输血","腹胀、停止排气排便伴呕吐（术后肠梗阻）→ 禁食减压+补液，必要时手术","造口发黑、剧痛（造口缺血坏死）→ 急诊评估处理"],"pinyin":"jzczwssqgl","icd10":"C18.9","physical_exam":["生命体征：体温、脉搏、血压（感染与出血）","一般情况：营养状态、贫血貌、体重变化","腹部视诊：切口、造口（位置、颜色、水肿）、腹胀、肠型","腹部触诊：压痛与反跳痛（吻合口瘘）、腹块、肝区（肝转移）","腹部叩诊与听诊：移动性浊音、肠鸣音（减弱提示肠麻痹）","直肠指检：吻合口情况（狭窄、复发）、指套染血（术前评估）","引流管：位置、引流量与性状"],"lab_tests":["术前：血常规、肝肾功能、凝血、CEA、结肠镜+活检、增强CT（胸腹盆）、直肠MRI（直肠癌）","术后：血常规、CRP、PCT（吻合口瘘）、白蛋白与前白蛋白（营养）每2～3天","引流液检查：胆红素、淀粉酶、细菌培养（鉴别吻合口瘘）","病理与分子检测：TNM分期、MSI/dMMR、RAS/BRAF（指导辅助治疗）","随访：CEA每3～6个月、胸腹盆CT每6～12个月、结肠镜术后1年内","营养相关：铁代谢、维生素B12（回肠切除或造口者）"],"nursing":["术前护理：肠道准备（饮食控制+清肠药）、造口定位与宣教（拟造口者）、呼吸训练","术后体位与活动：半卧位、鼓励早期下床活动（术后第1天）促进肠功能恢复","引流与切口护理：记录引流量与性状，观察切口有无红肿渗液；造口者按造口护理常规执行","营养护理：早期肠内营养（短肽制剂），观察腹胀腹泻；饮食从低渣流质逐步过渡","并发症观察：发热、腹痛、引流液浑浊（吻合口瘘）、便血（出血）、腹胀无排气（梗阻）","造口宣教：教会更换造口袋、皮肤保护、饮食调整与异常识别（发黑、剧痛、高排量）"],"diet":["术前：低渣饮食2～3天，术前1天流质+清肠药，术前6～8小时禁食禁水","术后：肠功能恢复后从清流质（米汤、藕粉）开始，逐步低渣半流质→软食","恢复期：高蛋白、高热量、易消化，少量多餐；避免产气（豆类、牛奶、碳酸饮料）与高纤维粗糙食物早期","造口患者：低渣饮食为主，充分咀嚼，避免易堵塞食物（玉米、蘑菇、坚果），注意补充水分与电解质","长期：增加膳食纤维（非造口者）、控制红肉与加工肉摄入、戒烟限酒、保持理想体重"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1353},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ce334c83a7e274a15b5406ed90a8a17829fdc075a1ed125851bb723c5632a6d0","pinyin":"jiezhichangaiweishoushuqiguanli","initials":"jzcawssqgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术前：排便习惯改变（腹泻便秘交替）、便血或黏液血便、腹痛腹胀、贫血消瘦、肠梗阻表现（直肠癌可有里急后重、便条变细）\\n术后早期：发热、腹痛、引流液浑浊（吻合口瘘）、引流量增多或血性（出血）、腹胀无排气（肠梗阻/肠麻痹）\\n低位直肠癌术后：排便次数增多、里急后重、控便功能下降（前切除综合征）\\n造口相关：造口水肿、周围皮肤损伤、排泄物量异常\\n远期：吻合口狭窄、性功能与排尿功能障碍（盆腔手术神经损伤）",60],["摘要","结直肠癌围手术期管理包括术前肠道准备与分期评估、根治性切除（右半/左半/乙状结肠切除、直肠前切除或腹会阴联合切除）+淋巴结清扫、术后并发症防治（吻合口瘘、出血、肠梗阻）与造口管理，以及术后辅助治疗与随访。",30],["疾病编码","C18.9",30],["原首字母","jzczwssqgl",60]]},{"id":"orders-8c8895e07518874b7d14","key":"v1-c9ccc21dfe2a3058|orders-8c8895e07518874b7d14","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"术后胃瘫（胃排空障碍）","category":"胃肠外科","raw":{"name":"术后胃瘫（胃排空障碍）","category":"胃肠外科","summary":"术后胃瘫是胃手术后（胃大部切除、胰十二指肠切除、食管胃吻合）出现的胃排空延迟，无机械性梗阻证据，表现为大量胃潴留、呕吐、腹胀。多发生于术后3～10天，属功能性并发症，以保守治疗为主（禁食减压、促动力药、营养支持），多数在数周内恢复。","symptoms":["术后（多在进食后）出现上腹胀满、恶心、大量呕吐（含宿食、无胆汁）","呕吐后腹胀暂时缓解，食欲差、不能耐受进食","胃管引流量持续>500ml/日，夹管或拔管后症状加重","肠鸣音减弱，但无腹痛加剧与腹膜刺激征（与机械性梗阻鉴别）","病程长者可出现脱水、低钾低氯性碱中毒、营养不良与体重下降"],"diagnosis":["胃管引流量测定：每日>500～800ml且持续多日，夹管试验阳性（夹管后腹胀呕吐）","上消化道造影（泛影葡胺/碘水）：胃无蠕动或蠕动弱、排空延迟，但造影剂可通过吻合口（排除机械性梗阻）","胃镜：排除吻合口狭窄、水肿等机械性因素（可见吻合口通畅但胃蠕动差）","腹部CT：排除腹腔感染、脓肿、吻合口瘘与机械性梗阻","电解质+血气分析：低钾低氯性碱中毒（长期呕吐所致）","血糖+甲状腺功能：排除糖尿病胃轻瘫与甲减等全身因素"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","方案1（促动力药）：","用法：甲氧氯普胺 10mg 静推 q6～8h（或肌注）；红霉素 250mg + 0.9%氯化钠 100ml 静滴 q8h（胃动素受体激动剂，短期使用）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","方案2（营养支持）：","用法：全肠外营养（葡萄糖+氨基酸+脂肪乳+电解质）；条件允许时经鼻空肠管（越过吻合口）肠内营养","方案3（补液纠正电解质）：","用法：0.9%氯化钠 1000ml + 10%氯化钾 20～30ml 静滴（纠正低钾低氯性碱中毒，按血钾与血气调整）；必要时补镁","方案4（抑酸与激素，必要时）：","用法：艾司奥美拉唑 40mg 静推 q12h；地塞米松 5mg 静推 qd（减轻吻合口水肿，短期，遵医嘱）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","📌 胃瘫治疗关键：充分胃肠减压+营养支持+促动力药；避免过早经口进食加重症状。"],"oral_medication":["⚠️ 恢复期用药，同类只选一种：","药物1（促动力）：","用法：莫沙必利 5mg tid（餐前30分钟）或 多潘立酮 10mg tid（餐前）；甲氧氯普胺 10mg tid（餐前，短期）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物2（消化酶辅助）：","用法：复方消化酶 2粒 tid 或 胰酶肠溶胶囊 1～2粒 随餐","药物3（通便，防便秘）：","用法：乳果糖 15ml bid〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 促动力药需在餐前30分钟服用；甲氧氯普胺长期使用可致锥体外系反应（不宜超过3个月）。"],"treatment":["胃肠减压：持续或间断减压，减轻胃潴留与吻合口张力（禁食水）","营养支持：全肠外营养为主；条件允许经鼻空肠管行肠内营养（营养液越过吻合口，不刺激胃）","促动力药物：甲氧氯普胺、莫沙必利、红霉素（短期），可联合使用","纠正水电解质紊乱：低钾低氯性碱中毒需补充氯化钠与氯化钾","糖皮质激素（争议）：短期小剂量地塞米松减轻吻合口水肿（遵医嘱）","胃镜/造影评估：排除机械性梗阻；必要时内镜下扩张吻合口狭窄","饮食过渡：引流量<200ml/日、夹管试验阴性后从少量温开水→清流质→流质逐步过渡（每次50ml起始）","难治性胃瘫：病程>4周者考虑幽门成形、胃电刺激或再次手术（极少数）"],"management":["胃管管理：妥善固定、记录引流量与性状（宿食、无胆汁），保持通畅；夹管试验由医师决定","严格禁食：避免过早进食加重胃潴留（进食后呕吐会加重电解质紊乱）","出入量与电解质：准确记录24小时出入量，监测血钾、钠、氯与血气，遵医嘱补液","营养支持护理：肠外营养规范输注（经中心静脉，注意血糖与肝功能）；鼻空肠管营养注意温度、速度与耐受","促动力药给药：按时（餐前30分钟）给药并观察疗效与不良反应（锥体外系反应）","心理护理：胃瘫恢复慢（数周至数月），患者焦虑明显，需耐心解释与鼓励","活动与康复：鼓励下床活动（促进胃肠蠕动），腹部按摩与温水足浴辅助"],"notes":["术后胃瘫为功能性障碍，须先排除机械性梗阻（吻合口狭窄、内疝、粘连）与腹腔感染、吻合口瘘","胃管引流量大且持续是重要指标；夹管试验是判断恢复的实用方法","营养支持是治疗基础，长期禁食可致严重营养不良与吻合口愈合不良","恢复期需循序渐进进食，过早大量进食易致症状反复","糖尿病、甲状腺功能减退、电解质紊乱可加重胃瘫，需同时纠正"],"emergency":["呕吐大量胃内容物致脱水、低钾低氯性碱中毒与意识改变 → 立即补液纠正电解质与酸碱失衡","突发剧烈腹痛伴腹膜刺激征（吻合口瘘/机械性梗阻）→ 急诊评估与手术","胃管引出大量鲜血（术后出血）→ 急诊内镜/手术止血"],"pinyin":"shwt","icd10":"K31.8","physical_exam":["生命体征：血压（脱水致低血压）、心率、体温、体重","一般情况：脱水征、营养状态、精神萎靡、体重下降幅度","腹部视诊：上腹膨隆（胃潴留）、手术瘢痕、可见胃型","腹部触诊：上腹轻压痛（一般无反跳痛）、有无包块","腹部叩诊：胃区振水音（胃潴留典型体征）、移动性浊音","腹部听诊：肠鸣音减弱（但非消失）、有无气过水声（机械性梗阻）","胃管：引流量与性状（宿食、无胆汁提示胃排空障碍）"],"lab_tests":["电解质（钾、钠、氯、镁）+血气分析：长期呕吐致低钾低氯性碱中毒，需每2～3天复查","血常规+CRP+PCT：排除感染与吻合口瘘","白蛋白+前白蛋白+体重：营养状态评估（指导营养支持）","上消化道造影（碘水/泛影葡胺）：判断排空延迟与排除机械性梗阻","胃镜：排除吻合口狭窄、水肿与机械性因素","腹部CT：排除腹腔脓肿、吻合口瘘与内疝","血糖+糖化血红蛋白+甲状腺功能：排除糖尿病胃轻瘫与甲减"],"nursing":["胃管护理：妥善固定、保持通畅，记录引流量与性状（每班记录），口腔护理每日2～3次","出入量管理：准确记录24小时出入量，观察尿量与脱水征，遵医嘱补液并监测电解质","营养护理：肠外营养规范输注与观察；鼻空肠管营养注意温度（38～40℃）、速度（由慢到快）与浓度","促动力药护理：餐前30分钟给药，观察疗效与不良反应（震颤、嗜睡等锥体外系反应）","心理护理：解释胃瘫恢复需要时间（常需数周），鼓励配合治疗，减轻焦虑","康复护理：鼓励下床活动、腹部按摩，夹管试验期间观察腹胀与呕吐情况"],"diet":["严格禁食水期间：静脉营养支持，做好口腔护理与心理安慰","恢复期（引流量<200ml/日、夹管阴性）：从少量温开水（20～30ml）开始，逐步清流质","过渡期：清流质→流质→低脂半流质，每次50～100ml，少量多餐（每日6～8餐）","避免高脂、高纤维与产气食物（延缓胃排空），食物温热细软","进食后保持半卧位30～60分钟，观察有无腹胀呕吐，症状反复则退回前一阶段"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1354},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9f22e1545581518a85fdabb8baa7059f1aa439268e5df96baca39393625e4383","pinyin":"shuhouweitan（weipaikongzhangai）","initials":"shwt（wpkza）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术后（多在进食后）出现上腹胀满、恶心、大量呕吐（含宿食、无胆汁）\\n呕吐后腹胀暂时缓解，食欲差、不能耐受进食\\n胃管引流量持续>500ml/日，夹管或拔管后症状加重\\n肠鸣音减弱，但无腹痛加剧与腹膜刺激征（与机械性梗阻鉴别）\\n病程长者可出现脱水、低钾低氯性碱中毒、营养不良与体重下降",60],["摘要","术后胃瘫是胃手术后（胃大部切除、胰十二指肠切除、食管胃吻合）出现的胃排空延迟，无机械性梗阻证据，表现为大量胃潴留、呕吐、腹胀。多发生于术后3～10天，属功能性并发症，以保守治疗为主（禁食减压、促动力药、营养支持），多数在数周内恢复。",30],["疾病编码","K31.8",30],["原首字母","shwt",60]]},{"id":"orders-30fd38fcd7cf33bc316d","key":"v1-c9ccc21dfe2a3058|orders-30fd38fcd7cf33bc316d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"上消化道大出血（外科处理）","category":"胃肠外科","raw":{"name":"上消化道大出血（外科处理）","category":"胃肠外科","summary":"上消化道大出血指屈氏韧带以上消化道（食管、胃、十二指肠、胰胆）大量出血，表现为呕血与/或黑便，可致失血性休克。常见病因：胃十二指肠溃疡、食管胃底静脉曲张破裂、胃癌、急性胃黏膜病变、贲门黏膜撕裂（Mallory-Weiss）。外科处理针对内科与内镜治疗失败、持续或反复大出血者。","symptoms":["呕血（鲜红或咖啡渣样）、黑便（柏油样）或暗红色血便（出血量大、肠蠕动快）","头晕、心悸、乏力、出汗、口渴（失血表现），重者晕厥","面色苍白、脉搏细速、血压下降、四肢湿冷（失血性休克）","上腹疼痛或不适（溃疡病）、肝病体征（肝硬化门静脉高压）","出血后可有氮质血症（肠内血液吸收）、发热（低热）"],"diagnosis":["血流动力学与出血量评估：血压、心率、尿量、意识；血红蛋白与红细胞压积（早期可正常）","急诊胃镜（24小时内）：诊断与治疗首选，明确出血部位与病因，可行内镜下止血","血常规+血型+交叉配血+凝血功能：动态监测与备血","肝功能+白蛋白+胆红素+血氨：评估肝硬化与肝储备","腹部超声/CT：评估肝硬化、门静脉内径、有无肿瘤","肠系膜血管造影：内镜未明确且持续出血时（可同时栓塞止血）","尿素氮+肌酐：肠内血液吸收致BUN升高（BUN/Cr比值>30提示上消化道出血）"],"infusion":["⚠️ 抢救用药，须在监护下按病情选择！","","方案1（抑酸，溃疡/糜烂出血首选）：","  用法：艾司奥美拉唑 80mg 静推（负荷）后 8mg/h 持续泵入 72小时；或 40mg 静推 q12h〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案2（降门脉压，静脉曲张出血）：","  用法：生长抑素 250μg 静推后 3mg/12h 泵入；或奥曲肽 0.1mg 静推后 25～50μg/h 泵入（疗程3～5天）〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","","方案3（液体复苏与输血）：","  用法：平衡盐溶液/0.9%氯化钠 快速补液；输注红细胞悬液（目标Hb 70～90g/L）、新鲜冰冻血浆、血小板；肝硬化者避免过量输液（防门脉压升高再出血）","","方案4（止血药物与预防性抗感染）：","  用法：氨甲环酸 1g（NS 100ml 或 5%GS 100ml）静滴（必要时）；维生素K1 10mg 静滴（肝硬化/凝血差者）；头孢曲松 1～2g 静滴 qd（肝硬化出血常规预防感染）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","📌 抢救与内镜准备同步进行；避免使用吗啡、NSAIDs等加重出血药物。"],"oral_medication":["⚠️ 止血后序贯用药，按医嘱选择：","药物1（抑酸序贯）：","用法：艾司奥美拉唑 20mg qd 或 雷贝拉唑 10mg qd（疗程4～8周）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物2（降门脉压预防再出血）：","用法：普萘洛尔 10mg bid 起（调整至静息心率55～60次/分）或 卡维地洛 6.25mg bid","药物3（胃黏膜保护与抗幽门螺杆菌）：","用法：铝碳酸镁 1.0g tid；根除Hp：阿莫西林1.0g bid + 克拉霉素0.5g bid + 艾司奥美拉唑20mg bid + 铋剂（疗程14天）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物4（乳果糖，肝硬化防肝性脑病）：","用法：乳果糖 15～30ml bid～tid（调整至每日2～3次软便）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 溃疡出血者需根除幽门螺杆菌（Hp）以防复发；肝硬化者需长期降门脉压治疗与胃镜随访。"],"treatment":["补充血容量抗休克：建立两条以上静脉通路，快速补液输血，维持Hb 70～90g/L（肝硬化者不宜过高）","抑酸治疗：静脉大剂量PPI（溃疡/糜烂出血），维持胃内pH>6促进血凝块稳定","内镜下止血：首选——注射止血（肾上腺素）、电凝、钛夹、套扎（静脉曲张），可重复内镜","门静脉高压出血：生长抑素/奥曲肽+内镜套扎；失败者行三腔二囊管压迫、TIPS或手术断流/分流","外科手术指征：内科与内镜治疗失败持续出血、溃疡穿孔或梗阻、大血管破裂（Dieulafoy病）、胃癌出血","介入治疗：胃左动脉/胃十二指肠动脉栓塞（内镜失败且不宜手术者）","病因治疗：根除Hp、停用NSAIDs/抗凝药（评估后）、护肝与抗病毒（肝硬化）","术后管理：监测再出血（引流、呕血黑便）、继续抑酸、营养支持"],"management":["休克期监测：每15～30分钟测血压、心率、尿量，记录呕血与黑便量与性状","体位与气道：平卧头偏一侧防误吸，呕血时禁食（活动性出血期）","双通道补液：粗针或中心静脉通路，按医嘱输血输液，观察有无输血反应","内镜准备：出血后24小时内完成急诊胃镜，术前禁食、必要时洗胃（冰盐水或去甲肾上腺素盐水）","三腔二囊管护理（如使用）：妥善牵引固定、标记刻度、定时放气（每12～24小时），观察有无窒息与黏膜损伤","活动性出血停止后：逐步从温凉流质开始进食，避免粗糙硬食与刺激性食物","再出血观察：监测生命体征、呕血黑便、肠鸣音与血红蛋白变化；肝硬化者预防肝性脑病（乳果糖、通便）"],"notes":["上消化道大出血的处理原则：先稳定生命体征，再明确病因并止血（内镜为首选）","肝硬化患者出血后易并发感染、肝性脑病与肝肾综合征，需预防性抗感染与护肝","溃疡出血止血后必须根除幽门螺杆菌并停用NSAIDs，否则复发率高","输血目标Hb 70～90g/L（过低影响组织灌注，过高增加门脉压与再出血风险）","外科手术是二线选择（内镜/介入失败），术前应尽量明确出血部位"],"emergency":["大量呕血、血压下降、心率>120次/分（失血性休克）→ 立即双通道补液输血、急诊内镜","内镜止血失败持续出血或反复出血 → 急诊介入栓塞或手术","肝硬化出血后出现意识改变、扑翼样震颤（肝性脑病）→ 乳果糖、降血氨、限制蛋白","呕血致窒息、误吸 → 立即清理气道、侧卧、吸氧"],"pinyin":"sxhddcxywkwcl","icd10":"K92.2","physical_exam":["生命体征：血压、心率、呼吸、意识（休克与出血量评估）","一般情况：面色苍白、皮肤湿冷、口渴、尿量减少、体位（平卧不愿活动）","皮肤黏膜：黄疸、蜘蛛痣、肝掌（肝硬化）、贫血貌、出血点","腹部视诊：腹壁静脉曲张、腹部膨隆（腹水）、手术瘢痕","腹部触诊：上腹压痛（溃疡）、肝脾大小与质地、有无腹块（肿瘤）","腹部叩诊与听诊：移动性浊音、肝浊音界、肠鸣音（活跃提示继续出血）","直肠指检：黑便或暗红色血便（出血量评估）"],"lab_tests":["血常规+红细胞压积（动态每1～2小时）：评估出血速度与程度（早期可正常）","血型+交叉配血+凝血功能+血小板：备血与凝血状态评估","肝功能+白蛋白+胆红素+血氨：肝硬化与肝储备评估（决定治疗策略）","尿素氮+肌酐：BUN升高（BUN/Cr>30）提示上消化道出血","电解质+血气分析+乳酸：评估休克与酸碱失衡","急诊胃镜（24小时内）：明确出血部位与病因，同时内镜下止血","肝炎病毒标志物+HBV-DNA：肝硬化病因与抗病毒治疗依据"],"nursing":["休克护理：绝对卧床、平卧头偏一侧，快速建立静脉通路，每15～30分钟监测生命体征与尿量","出血观察与记录：记录呕血与黑便的次数、量、颜色（鲜红提示活动性出血），观察肠鸣音与血红蛋白","气道护理：呕血时头偏一侧防误吸，及时清理口腔，必要时吸氧","三腔二囊管护理（如使用）：牵引固定、标记刻度、定时放气，观察鼻腔黏膜与有无胸痛呼吸困难","饮食护理：活动性出血期禁食；停止出血后从温凉流质（米汤）开始，忌粗糙、坚硬、过热食物","心理护理：出血场面易致恐惧，安抚患者并解释治疗，减少紧张（紧张可加重出血）"],"diet":["活动性出血期严格禁食禁水（必要时胃肠减压）","出血停止24～48小时后：温凉流质（米汤、藕粉、温牛奶），少量多餐","过渡期：流质→半流质→软食，避免粗糙、坚硬、带刺与过热食物","溃疡患者：规律进食、少量多餐，避免辛辣、浓茶、咖啡与酒类","肝硬化患者：限盐（<2g/日）、适量优质蛋白（肝性脑病期遵医嘱），保持大便通畅"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1355},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e9e5e858257103e233a53d73a200a489c8ea06ad17ef9a6fe71707407eb27bdd","pinyin":"shangxiaohuadaodachuxue（waikechuli）","initials":"sxhddcx（wkcl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","呕血（鲜红或咖啡渣样）、黑便（柏油样）或暗红色血便（出血量大、肠蠕动快）\\n头晕、心悸、乏力、出汗、口渴（失血表现），重者晕厥\\n面色苍白、脉搏细速、血压下降、四肢湿冷（失血性休克）\\n上腹疼痛或不适（溃疡病）、肝病体征（肝硬化门静脉高压）\\n出血后可有氮质血症（肠内血液吸收）、发热（低热）",60],["摘要","上消化道大出血指屈氏韧带以上消化道（食管、胃、十二指肠、胰胆）大量出血，表现为呕血与/或黑便，可致失血性休克。常见病因：胃十二指肠溃疡、食管胃底静脉曲张破裂、胃癌、急性胃黏膜病变、贲门黏膜撕裂（Mallory-Weiss）。外科处理针对内科与内镜治疗失败、持续或反复大出血者。",30],["疾病编码","K92.2",30],["原首字母","sxhddcxywkwcl",60]]},{"id":"orders-13945092f13f9d4c7fcd","key":"v1-c9ccc21dfe2a3058|orders-13945092f13f9d4c7fcd","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"甲状腺癌术后管理与随访","category":"甲状腺乳腺外科","raw":{"name":"甲状腺癌术后管理与随访","category":"甲状腺乳腺外科","summary":"甲状腺癌（以乳头状癌最常见）术后管理包括TSH抑制治疗、并发症监测（低钙、声嘶、出血）、复发风险评估与随访，以及高危患者的碘-131治疗。总体预后良好（乳头状癌10年生存率>90%），规范随访是长期获益的关键。","symptoms":["术后早期：颈部肿胀、呼吸不畅（出血）、声音嘶哑、饮水呛咳、口周与手足麻木（低钙）","TSH抑制过度：心悸、手抖、多汗、失眠、体重下降、骨质疏松（长期）","TSH抑制不足：乏力、畏寒、水肿、体重增加（甲减）","复发/转移表现：颈部新发结节、颈侧区淋巴结肿大、骨痛（骨转移）、咳嗽（肺转移）","碘-131治疗后：唾液腺肿胀、口干、味觉改变、骨髓抑制（少见）"],"diagnosis":["术后病理：肿瘤类型、大小、多灶性、腺外侵犯、淋巴结转移数、脉管侵犯（决定危险分层与后续治疗）","甲状腺功能（TSH、FT3、FT4）：术后4～6周评估并调整左甲状腺素剂量，TSH目标按危险分层（高危<0.1、中危0.1～0.5、低危0.5～2.0mU/L）","甲状腺球蛋白（Tg）+抗Tg抗体（TgAb）：全切术后监测复发（Tg应极低或测不出）","颈部超声：术后6～12个月复查，评估甲状腺床与颈部淋巴结（每6～12个月，高危者更频）","血钙+甲状旁腺激素（PTH）：术后监测低钙（尤其全切+中央区清扫者）","碘-131全身显像+刺激性Tg：高危患者碘治疗前评估","喉镜：声嘶者评估声带运动"],"infusion":["⚠️ 按术后情况选择方案，切勿全部同时使用！","","方案1（术后低钙，静脉补钙）：","  用法：10%葡萄糖酸钙 10～20ml + 5%葡萄糖 20ml 缓慢静推（>10分钟）；继以 10%葡萄糖酸钙 30～60ml + 0.9%氯化钠 500ml 静滴维持（监测血钙与心电图）","","方案2（术后出血应急）：","  用法：氨甲环酸 0.5g（NS 100ml 或 5%GS 100ml）静滴；维生素K1 10mg 静滴；必要时输血〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（碘-131治疗前准备，重组TSH）：","  用法：重组人TSH（rhTSH）0.9mg 肌注 ×2天（碘治疗前）——避免停用左甲状腺素导致的甲减","","方案4（补液支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；维生素C 2g 静滴 qd","","📌 葡萄糖酸钙静推必须缓慢并监测心电图；碘-131治疗需在核医学专科进行并遵守辐射防护。"],"oral_medication":["⚠️ 长期用药，按医嘱选择：","药物1（TSH抑制/替代治疗，核心用药）：","用法：左甲状腺素钠 起始1.6μg/kg/日（晨起空腹30～60分钟），按TSH调整；高危患者TSH目标<0.1mU/L","药物2（补钙与维生素D，低钙者）：","用法：碳酸钙D3 600mg bid～tid + 骨化三醇 0.25～0.5μg qd；血钙恢复后可逐渐减停","药物3（骨质疏松预防，长期TSH抑制者）：","用法：碳酸钙D3 600mg qd + 维生素D 400～800IU/日；必要时双膦酸盐（遵医嘱）","药物4（甲状腺片不推荐）：避免使用甲状腺片（成分不稳定）","📌 左甲状腺素需终身服用（全切者），不可自行停药；与钙剂、铁剂、豆制品间隔4小时以上。"],"treatment":["术后TSH抑制治疗：按危险分层设定TSH目标，左甲状腺素剂量按体重与TSH动态调整（每4～6周复查调整）","低钙处理：术后监测血钙，症状性低钙予静脉补钙+口服钙剂与骨化三醇，多数暂时性（数周恢复）","喉返神经损伤：神经营养药（甲钴胺）+观察，多可恢复；双侧损伤致呼吸困难需气管切开","碘-131治疗：高危患者（肿瘤大、腺外侵犯、淋巴结转移多）术后行碘-131清甲/清灶，治疗前低碘饮食2～4周、停用左甲状腺素或用rhTSH","复发/转移处理：颈部淋巴结复发者手术清扫±碘治疗；远处转移者碘治疗+靶向药（乐伐替尼/索拉非尼）","随访计划：术后1个月评估TSH与血钙；6～12个月颈部超声+Tg/TgAb；之后每6～12个月复查（低危者可放宽）","骨质疏松与心脏监测：长期TSH抑制者监测骨密度、心电图（房颤风险）"],"management":["用药管理：左甲状腺素固定时间（晨起空腹）服用，与餐、钙剂、铁剂间隔；漏服不补加倍，按原剂量继续","随访执行：建立随访计划表（TSH、Tg/TgAb、颈部超声），提醒患者按时复查","低钙观察与宣教：告知口周麻木、手足抽搐症状，出现时立即就诊；指导钙剂与维生素D正确服用","嗓音随访：记录声嘶与呛咳改善情况，持续声嘶者安排喉镜","碘-131治疗护理：治疗前低碘饮食宣教（避免海带、紫菜、加碘盐、海鱼），治疗期辐射防护（单独居住、避免与孕妇儿童密切接触、体液处理）","心理支持：甲状腺癌预后良好但患者焦虑常见，需解释预后与随访意义","生活指导：规律作息、避免颈部剧烈活动与压迫、保持适度运动"],"notes":["甲状腺癌术后TSH抑制治疗需长期坚持：抑制过度增加房颤与骨质疏松风险，不足则增加复发风险，需按危险分层次个体化","Tg与TgAb是复发监测的核心指标（全切+碘治疗后Tg应测不出）；TgAb阳性会干扰Tg测定","术后低钙多为暂时性（数周内恢复），永久性甲状旁腺功能减退需终身补钙与维生素D","碘-131治疗前后需严格低碘饮食与停用左甲状腺素（或用rhTSH），否则影响疗效","复发多发生在术后5～10年内，随访不可中断；低危患者可适当放宽复查频次"],"emergency":["术后颈部迅速肿胀、呼吸困难（出血致气道压迫）→ 立即床旁拆线清除血肿，必要时气管插管/切开","手足抽搐、喉痉挛（重度低钙）→ 立即缓慢静推葡萄糖酸钙并心电监护","碘-131治疗后严重骨髓抑制（白细胞、血小板显著下降）→ 血液科会诊处理"],"pinyin":"jzxashglsf","icd10":"C73","physical_exam":["生命体征：体温、脉搏、血压、体重（评估甲功状态）","颈部：切口愈合、颈部有无新发结节与肿胀、甲状腺床情况","颈部淋巴结：颈侧区（Ⅱ～Ⅵ区）淋巴结大小、质地、活动度（复发监测）","嗓音与吞咽：声音嘶哑、饮水呛咳（喉返/喉上神经功能）","低钙体征：Chvostek征、Trousseau征、口周感觉","甲功相关：心率与心律（房颤）、手抖、皮肤温湿度、体重变化","骨骼：骨密度随访（长期抑制治疗者）、骨痛（骨转移）"],"lab_tests":["甲状腺功能（TSH、FT3、FT4）：术后4～6周首次评估，调整剂量后每4～6周复查至稳定，稳定后每6～12个月","甲状腺球蛋白（Tg）+抗Tg抗体（TgAb）：每6～12个月（全切术后复发监测核心指标）","血钙+磷+PTH：术后1～2天及低钙者每日复查至稳定","颈部超声：术后6～12个月首次，之后每6～12个月（高危者每3～6个月）","碘-131全身显像+刺激性Tg：高危患者碘治疗前后评估","骨密度（DEXA）+心电图：长期TSH抑制治疗者定期监测","肝肾功能+血常规：碘-131治疗前与靶向治疗期间监测"],"nursing":["术后观察：术后6～12小时重点观察颈部肿胀、呼吸、声音与引流，床旁备气管切开包","低钙观察：询问口周麻木与手足麻刺感，观察Chvostek征，异常立即报告并备钙剂","用药宣教：左甲状腺素晨起空腹服用（与钙剂、铁剂间隔4小时），强调终身服药与不可自行停药","随访管理：建立复查提醒（TSH、Tg、超声），解释各项检查的意义，提高依从性","碘-131护理：治疗前低碘饮食宣教（禁海带、紫菜、海鱼、加碘盐），治疗后辐射防护与体液处理指导","心理护理：缓解对复发的焦虑，介绍良好预后数据，鼓励规律生活与适度运动"],"diet":["术后早期：温凉流质逐渐过渡到普食，避免过热引起切口渗血","低钙者：增加含钙食物（牛奶、豆制品、虾皮、深绿色蔬菜）并按医嘱补钙与维生素D","碘-131治疗前2～4周：严格低碘饮食（禁海带、紫菜、海鱼、海虾、加碘盐、含碘保健品与药物）","长期：均衡饮食，适量优质蛋白与蔬果，避免长期大量高碘食物（海带等）","避免吸烟与过量饮酒；TSH抑制治疗期间注意补充钙与维生素D预防骨质疏松"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1356},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"76d0dd90bf8831b922c142b5ad92efbf6794dfa8a803b036480ec3ae4add5714","pinyin":"jiazhuangxianaishuhouguanliyusuifang","initials":"jzxashglysf","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术后早期：颈部肿胀、呼吸不畅（出血）、声音嘶哑、饮水呛咳、口周与手足麻木（低钙）\\nTSH抑制过度：心悸、手抖、多汗、失眠、体重下降、骨质疏松（长期）\\nTSH抑制不足：乏力、畏寒、水肿、体重增加（甲减）\\n复发/转移表现：颈部新发结节、颈侧区淋巴结肿大、骨痛（骨转移）、咳嗽（肺转移）\\n碘-131治疗后：唾液腺肿胀、口干、味觉改变、骨髓抑制（少见）",60],["摘要","甲状腺癌（以乳头状癌最常见）术后管理包括TSH抑制治疗、并发症监测（低钙、声嘶、出血）、复发风险评估与随访，以及高危患者的碘-131治疗。总体预后良好（乳头状癌10年生存率>90%），规范随访是长期获益的关键。",30],["疾病编码","C73",30],["原首字母","jzxashglsf",60]]},{"id":"orders-5eae5e7a74afcb4ddaf4","key":"v1-c9ccc21dfe2a3058|orders-5eae5e7a74afcb4ddaf4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"乳腺癌术后管理与康复","category":"甲状腺乳腺外科","raw":{"name":"乳腺癌术后管理与康复","category":"甲状腺乳腺外科","summary":"乳腺癌术后管理包括引流管与切口护理、患侧上肢功能康复与淋巴水肿预防、辅助治疗（化疗/放疗/内分泌/靶向）衔接与随访。规范康复可显著改善上肢功能与生活质量，降低淋巴水肿发生率。","symptoms":["术后早期：切口疼痛、引流液量多或血清样液、皮瓣坏死（切口边缘发黑）","患侧上肢淋巴水肿：上肢肿胀、沉重感、活动受限、皮肤紧绷（多发生于腋窝淋巴结清扫后）","患侧上肢功能障碍：肩关节活动受限、抬臂困难、肩周疼痛","辅助治疗相关：化疗致恶心脱发、内分泌治疗致潮热关节痛、放疗致皮肤反应","复发/转移表现：胸壁结节、腋窝或锁骨上淋巴结肿大、骨痛、咳嗽"],"diagnosis":["术后病理：肿瘤大小、淋巴结转移数、组织学分级、ER/PR/HER2状态、Ki-67（决定辅助治疗方案）","引流液量与性状监测：术后引流量（一般<30～50ml/日可拔管），浑浊或乳糜样需处理","切口与皮瓣评估：皮瓣颜色、有无坏死、积液与感染","上肢周径测量：双侧对比（髌骨上/下10cm），评估淋巴水肿程度（每3～6个月）","辅助治疗监测：血常规、肝肾功能、心脏超声（蒽环类/曲妥珠单抗）、骨密度（内分泌治疗）","随访影像与标志物：乳腺超声/钼靶（对侧与局部复发）、CA15-3/CEA、骨扫描（骨痛时）"],"infusion":["⚠️ 按术后与辅助治疗需要选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术后支持与镇痛）：","  用法：0.9%氯化钠/葡萄糖 静滴；氟比洛芬酯 50mg 静滴 q12h 或 曲马多 100mg 静滴 必要时","","方案3（化疗/靶向治疗，按方案执行）：","  用法：AC-T、TAC、TC等方案（按体表面积计算）；HER2阳性者曲妥珠单抗 首剂8mg/kg→6mg/kg q21d（首次输注90分钟，监测心脏毒性）","","方案4（淋巴水肿急性加重，抗感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h（丹毒/蜂窝织炎时，按药敏调整）〔调 CrCl<30 减量；青霉素过敏禁用〕","","📌 患侧上肢禁止测血压、抽血、输液与置管（预防淋巴水肿与感染）；曲妥珠单抗需每3个月监测LVEF。"],"oral_medication":["⚠️ 术后与辅助治疗用药，按医嘱选择：","药物1（镇痛）：","用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（内分泌治疗，激素受体阳性）：","用法：他莫昔芬 20mg qd（绝经前，疗程5～10年）或 来曲唑 2.5mg qd／阿那曲唑 1mg qd（绝经后）","药物3（内分泌治疗不良反应）：","用法：碳酸钙D3 600mg qd + 维生素D（防骨质疏松）；帕罗西汀 20mg qd 或 加巴喷丁 0.3g tid（潮热）","药物4（通便/对症）：","用法：乳果糖 15ml bid；甲钴胺 0.5mg tid（化疗致周围神经毒性）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 内分泌治疗需坚持5～10年，不可自行停药；服药期间每年复查骨密度与妇科超声（他莫昔芬）。"],"treatment":["术后切口与引流管理：保持负压引流通畅，一般术后5～7天引流量<30ml/日拔管；皮瓣坏死需清创","患侧上肢康复：循序渐进原则——术后1～2天手指与腕关节活动，3～5天肘关节，1周后肩关节渐进活动（避免过早大幅抬臂）","淋巴水肿预防：避免患侧上肢测血压、抽血、输液、负重与外伤；出现肿胀及早干预（弹力袖套、手法淋巴引流、气压治疗）","辅助化疗：按分子分型与危险度选择方案（蒽环/紫杉类），HER2阳性者加曲妥珠单抗±帕妥珠单抗","放疗：保乳术后常规放疗；改良根治术后高危者胸壁与区域淋巴结放疗（注意放射性皮炎与心肺保护）","内分泌治疗：激素受体阳性者行5～10年内分泌治疗（绝经前他莫昔芬±卵巢功能抑制，绝经后芳香化酶抑制剂）","随访：术后2年内每3～4个月，3～5年每6个月，5年后每年（乳腺超声/钼靶、肿瘤标志物、骨密度）","心理与形体康复：乳房重建或义乳咨询、心理支持、性健康指导"],"management":["引流管护理：妥善固定、保持负压与通畅，记录引流量与性状（>50ml/日暂缓拔管），观察有无皮下积液","切口观察：每班观察皮瓣颜色、温度与切口渗液，皮瓣坏死（发黑）需报告并清创","患肢护理与宣教：严禁患侧上肢测血压、抽血、输液、提重物（>5kg）与戴紧袖口；避免蚊虫叮咬与皮肤破损，出现红肿热痛立即就诊","功能锻炼指导：制定个体化康复计划（术后1天手指→1周肩关节渐进抬举），每日记录肩关节活动度","淋巴水肿监测：每3～6个月测双侧上肢周径（固定位置），出现肿胀（差值>2cm）及早干预","辅助治疗衔接：化疗后血象恢复再放疗，放疗后皮肤反应护理（避免摩擦、暴晒、使用温和清洁剂）","随访与宣教：强调按时复查与终身内分泌治疗的重要性，指导自我乳房检查与异常识别"],"notes":["患侧上肢终生禁止测血压、抽血、输液与置管（淋巴水肿与感染风险），需反复向患者强调并记录在病历","肩关节功能锻炼应循序渐进，过早大幅活动可致皮下积液与皮瓣愈合不良","淋巴水肿一旦发生难以治愈，重在预防与早期干预（弹力袖套+手法引流+气压治疗）","HER2阳性者曲妥珠单抗需每3个月监测LVEF（心脏毒性，与蒽环类联用时更高）","内分泌治疗需坚持5～10年（长期依从性差是复发重要原因），并监测骨质疏松与子宫内膜增厚"],"emergency":["患侧上肢突发红肿热痛伴发热（丹毒/蜂窝织炎）→ 立即抗感染治疗（淋巴水肿患者易感染且进展快）","术后引流管大量鲜红血液伴血压下降（活动性出血）→ 急诊处理并输血","化疗期间发热伴中性粒细胞缺乏（FN）→ 1小时内经验性抗生素","胸壁或骨转移致剧烈疼痛、病理性骨折 → 急诊评估与镇痛、放疗/手术处理"],"pinyin":"rxashglkf","icd10":"C50","physical_exam":["生命体征：体温、脉搏、血压、体重（辅助治疗期间）","切口与胸壁：切口愈合、皮瓣颜色与温度、有无皮下积液与局部复发结节","引流管：位置、引流量与性状、负压状态","患侧上肢：周径（与对侧对比，固定解剖标志）、肿胀、皮肤紧绷与发红、肩关节活动度","对侧乳房与腋窝：自查与触诊（对侧原发风险）","锁骨上与颈部淋巴结：有无肿大（区域转移）","其他：骨痛（骨转移）、咳嗽（肺转移）、肝区（肝转移）"],"lab_tests":["术后病理与分子分型：ER/PR/HER2/Ki-67（决定辅助治疗）","血常规+肝肾功能：每周期化疗前及随访中复查","心脏超声（LVEF）：蒽环类或曲妥珠单抗治疗前后及每3个月复查","肿瘤标志物（CA15-3、CEA）：术后随访每3～6个月","骨密度（DEXA）+血钙：内分泌治疗（芳香化酶抑制剂）者每年复查","乳腺超声/钼靶：术后每6～12个月（保乳者更需密切）","妇科超声：他莫昔芬治疗者每年复查（子宫内膜增厚风险）；骨扫描（骨痛时）"],"nursing":["引流与切口护理：保持负压引流通畅，记录引流量与性状，观察皮瓣颜色与切口渗液","患肢保护宣教：反复强调患侧上肢禁止测血压、抽血、输液、提重物与皮肤损伤，指导避免蚊虫叮咬","功能锻炼指导：按术后时间拟定渐进康复计划，每日评估肩关节活动度并记录","淋巴水肿监测与护理：定期测量双侧上肢周径，出现肿胀尽早使用弹力袖套并转诊康复科","辅助治疗护理：化疗期间骨髓抑制与感染防护；放疗期间皮肤护理（避免摩擦、暴晒、刺激性洗剂）","心理护理：形体改变与治疗长期性易致焦虑抑郁，提供心理支持、义乳与乳房重建咨询"],"diet":["高蛋白、高维生素、易消化饮食促进切口愈合（鱼、瘦肉、蛋、奶、新鲜蔬果）","控制总热量与体重（肥胖增加复发风险，尤其绝经后）","限制酒精摄入（酒精与乳腺癌风险相关），戒烟","内分泌治疗期间：补钙与维生素D（牛奶、豆制品、深绿色蔬菜），预防骨质疏松","避免高脂高糖饮食与不明成分保健品（尤其含雌激素类）；均衡膳食、适量运动"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1357},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e4e78d54d4234c7c1382a2ada45253c7eef8a54af56a391f54b0928137841490","pinyin":"ruxianaishuhouguanliyukangfu","initials":"rxashglykf","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术后早期：切口疼痛、引流液量多或血清样液、皮瓣坏死（切口边缘发黑）\\n患侧上肢淋巴水肿：上肢肿胀、沉重感、活动受限、皮肤紧绷（多发生于腋窝淋巴结清扫后）\\n患侧上肢功能障碍：肩关节活动受限、抬臂困难、肩周疼痛\\n辅助治疗相关：化疗致恶心脱发、内分泌治疗致潮热关节痛、放疗致皮肤反应\\n复发/转移表现：胸壁结节、腋窝或锁骨上淋巴结肿大、骨痛、咳嗽",60],["摘要","乳腺癌术后管理包括引流管与切口护理、患侧上肢功能康复与淋巴水肿预防、辅助治疗（化疗/放疗/内分泌/靶向）衔接与随访。规范康复可显著改善上肢功能与生活质量，降低淋巴水肿发生率。",30],["疾病编码","C50",30],["原首字母","rxashglkf",60]]},{"id":"orders-bfce1f06f87700eca7f6","key":"v1-c9ccc21dfe2a3058|orders-bfce1f06f87700eca7f6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"主动脉夹层（急诊识别与处理）","category":"血管外科","raw":{"name":"主动脉夹层（急诊识别与处理）","category":"血管外科","summary":"主动脉夹层是主动脉内膜撕裂后血液进入中膜形成假腔，并沿主动脉纵轴延伸的危重急症，48小时内病死率极高。典型表现为突发剧烈撕裂样胸背痛，可伴血压差异、脏器缺血（脑、肾、肠、下肢）。Stanford A型（累及升主动脉）需急诊手术，B型多先内科保守或腔内治疗。","symptoms":["突发前胸、后背或腹部剧烈撕裂样/刀割样疼痛，向腰背部或下肢放射，镇痛药难以缓解","双上肢血压差异>20mmHg 或脉搏不对称（重要体征）","高血压或低血压/休克（提示心包填塞、主动脉破裂）","脏器缺血表现：脑缺血（晕厥、偏瘫）、脊髓缺血（截瘫）、肾缺血（少尿、无尿）、肠缺血（剧烈腹痛）、下肢缺血（肢体凉、麻、无脉）","主动脉瓣关闭不全杂音（A型夹层）、心包摩擦音或颈静脉怒张（心包填塞）"],"diagnosis":["主动脉CTA（首选）：明确分型、范围、真假腔、分支受累与有无心包积液","床旁超声心动图：评估升主动脉、心包积液、主动脉瓣反流（A型夹层快速筛查）","胸部X线：纵隔增宽（敏感性低，不能排除）","心电图：排除急性心肌梗死（夹层可累及冠脉致心电图改变）","D-二聚体：显著升高（>5000ng/ml高度提示），阴性有助排除","血常规+凝血+肝肾功能+心肌酶+乳酸：评估器官缺血与凝血状态","双上肢与双下肢血压、脉搏对比：诊断重要线索（首次接触即应测量）"],"infusion":["⚠️ 抢救用药，须在监护下严格控制！","方案1（控制心率与血压，首要）：","用法：艾司洛尔 负荷0.5mg/kg 静推后 50～200μg/kg/min 泵入（目标心率60次/分以下）；乌拉地尔 12.5～25mg 静推后 100～400μg/min 泵入（目标收缩压100～120mmHg）","方案2（镇痛）：","用法：吗啡 3～5mg 静推（必要时重复）；或芬太尼 0.05mg 静推（充分镇痛可降低交感兴奋与血压）","方案3（休克/心包填塞）：","用法：谨慎补液（避免加重心包填塞）；去甲肾上腺素 0.05～0.5μg/kg/min 泵入维持重要脏器灌注；立即心外科会诊","方案4（A型夹层术前准备）：","用法：0.9%氯化钠 静滴；备血、备皮，紧急手术准备","📌 目标：心率<60次/分、收缩压100～120mmHg（保证脏器灌注的最低有效血压）；禁用抗凝、溶栓与抗血小板药物。"],"oral_medication":["⚠️ 急性期以静脉用药为主；稳定期与出院后长期用药：","药物1（β受体阻滞剂，长期首选）：","用法：美托洛尔缓释片 23.75～47.5mg qd 或 比索洛尔 2.5～5mg qd（目标静息心率55～60次/分）〔调 ★ 严重心动过缓/二度以上AVB禁用；哮喘慎用；★ 不可骤停〕","药物2（降压，联合）：","用法：缬沙坦 80mg qd 或 氨氯地平 5mg qd（目标血压<130/80mmHg）〔调 肝功能不全减量；踝部水肿（剂量相关）〕","药物3（镇痛与通便，防血压波动）：","用法：对乙酰氨基酚 0.5g 必要时；乳果糖 15ml bid（避免用力排便升高血压）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（他汀，稳定斑块）：","用法：阿托伐他汀 20mg qn〔调 ★ 活动性肝病禁用；甲减/肌病史慎用；妊娠哺乳禁用〕","📌 夹层患者需终身严格控制血压与心率，血压波动是再发夹层与动脉瘤破裂的重要诱因。"],"treatment":["A型（累及升主动脉）：确诊后立即急诊外科手术（升主动脉替换±全弓置换+支架象鼻术），术前严格控制心率血压与镇痛","B型（不累及升主动脉）：首选内科保守（控制心率血压、镇痛），出现并发症（破裂、脏器缺血、持续疼痛、血压难控）行腔内支架修复（TEVAR）或开放手术","强化内科治疗：β受体阻滞剂+血管扩张剂控制心率（<60次/分）与血压（100～120mmHg），充分镇痛，绝对卧床","并发症处理：心包填塞（急诊手术/心包穿刺）、急性主动脉瓣反流（手术）、脏器缺血（血管重建或腔内治疗）、截瘫（脑脊液引流）","长期随访：定期CTA（术后1、3、6、12个月，之后每年），监测残余夹层、动脉瘤样扩张与再发夹层","危险因素控制：严格控制血压（<130/80mmHg）、心率、血脂，戒烟，避免剧烈运动与重体力劳动","遗传性结缔组织病筛查（马凡综合征等）：家族史者行基因与家系筛查"],"management":["绝对卧床、住ICU监护：持续心电、血压（有创动脉压更佳）、血氧监护，避免一切增加腹压与血压的活动","疼痛管理：使用吗啡等强效镇痛药，评估疼痛评分，疼痛加剧提示夹层进展或破裂","血压心率控制：按医嘱调整泵入药物剂量，记录每小时尿量（>0.5ml/kg/h）","禁止用力：避免用力排便（用缓泻剂）、剧烈咳嗽与搬动；翻身时保持躯干平直","脏器缺血监测：意识、肢体脉搏与皮温、尿量、腹痛与肠鸣音（肠缺血）、神经功能（截瘫）","术前准备（A型）：迅速完成备血、备皮、禁食、家属沟通与手术同意签署","术后管理：监测血压、引流量、神经功能与肾功能；控制心率血压、镇痛、预防感染"],"notes":["急性主动脉夹层是致命急症，A型48小时内病死率可达50%，确诊后必须争分夺秒手术","双上肢血压差异>20mmHg是重要线索，接诊胸背痛患者应常规测量四肢血压","夹层禁用抗凝、抗血小板与溶栓药物（与急性心肌梗死处理截然不同，需仔细鉴别）","充分镇痛与控制心率血压（而非单纯降压）是急性期最重要的内科措施","长期严格控制血压与心率（<130/80mmHg、静息心率55～60次/分）是预防再发的关键"],"emergency":["突发撕裂样胸背痛伴血压差异、脉搏不对称（疑似夹层）→ 立即控制心率血压、镇痛、急查CTA","心包填塞表现（颈静脉怒张、心音遥远、血压下降）→ 立即心外科急诊手术/心包穿刺","下肢急性缺血（凉、麻、无脉）、少尿无尿（肾缺血）、剧烈腹痛（肠缺血）→ 急诊评估血管重建","意识障碍、偏瘫（脑缺血）→ 立即评估并保护气道"],"pinyin":"zdmjdzsjbsycl","icd10":"I71.0","physical_exam":["生命体征：四肢血压（双侧对比，差异>20mmHg有意义）、心率、呼吸、血氧","一般情况：痛苦面容、烦躁、意识状态（脑缺血）、皮肤湿冷（休克）","心脏：心界、心率心律、主动脉瓣区舒张期杂音（反流）、心音遥远与颈静脉怒张（心包填塞）","血管：颈动脉、桡动脉、股动脉、足背动脉搏动（双侧对比），有无搏动消失与血管杂音","神经系统：意识、瞳孔、肢体肌力（脑缺血/截瘫评估）、脊髓缺血平面","腹部：压痛、肠鸣音（肠缺血可减弱）、有无腹块（动脉瘤）","四肢：皮温、颜色、毛细血管充盈、下肢缺血表现"],"lab_tests":["主动脉CTA（首选）：明确分型、范围、真假腔、分支受累与心包积液","床旁超声心动图：评估升主动脉、心包积液与主动脉瓣反流（A型筛查）","D-二聚体：显著升高支持诊断，阴性有助排除（低危患者）","血常规+凝血功能+血型+交叉配血：术前准备与凝血评估","心肌酶（肌钙蛋白）+心电图：与急性心肌梗死鉴别（夹层可累及冠脉）","肝肾功能+乳酸+血气分析：评估脏器缺血与灌注","尿量+尿常规：肾缺血评估（少尿提示肾受累）"],"nursing":["绝对卧床与监护：住ICU，持续心电血压监护，避免一切用力（翻身平直、禁止下床）","疼痛观察与镇痛：评估疼痛部位、性质与程度，按医嘱给予镇痛药并观察效果（疼痛加剧需立即报告）","血压心率管理：遵医嘱精确调整泵入药物速度，记录每小时血压、心率与尿量","心理安抚：剧烈疼痛与濒死感致极度恐惧，需语言安抚、解释治疗、保持环境安静","术前准备（A型）：快速禁食、备皮、备血、留置尿管，配合完成知情同意","并发症观察：意识改变、肢体脉搏消失、尿量减少、腹痛加剧（脏器缺血）；颈静脉怒张（心包填塞）"],"diet":["急性期禁食禁水（可能急诊手术）","病情稳定后：低盐（<5g/日，血压控制要点）、低脂、易消化软食","保持大便通畅：多饮水、多食蔬菜水果与粗纤维，必要时用缓泻剂（避免用力排便）","避免浓茶、咖啡、酒精与辛辣刺激（防止血压心率波动）","长期：控制体重、戒烟、限酒，规律服药，避免暴饮暴食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1358},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2c17316b0e2a6d912da40d8a3047dce59e7845f6ec8d5ac3f95edc67165f807b","pinyin":"zhudongmaijiaceng（jizhenshibieyuchuli）","initials":"zdmjc（jzsbycl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发前胸、后背或腹部剧烈撕裂样/刀割样疼痛，向腰背部或下肢放射，镇痛药难以缓解\\n双上肢血压差异>20mmHg 或脉搏不对称（重要体征）\\n高血压或低血压/休克（提示心包填塞、主动脉破裂）\\n脏器缺血表现：脑缺血（晕厥、偏瘫）、脊髓缺血（截瘫）、肾缺血（少尿、无尿）、肠缺血（剧烈腹痛）、下肢缺血（肢体凉、麻、无脉）\\n主动脉瓣关闭不全杂音（A型夹层）、心包摩擦音或颈静脉怒张（心包填塞）",60],["摘要","主动脉夹层是主动脉内膜撕裂后血液进入中膜形成假腔，并沿主动脉纵轴延伸的危重急症，48小时内病死率极高。典型表现为突发剧烈撕裂样胸背痛，可伴血压差异、脏器缺血（脑、肾、肠、下肢）。Stanford A型（累及升主动脉）需急诊手术，B型多先内科保守或腔内治疗。",30],["疾病编码","I71.0",30],["原首字母","zdmjdzsjbsycl",60]]},{"id":"orders-9194e295d9a2ce7cf27e","key":"v1-c9ccc21dfe2a3058|orders-9194e295d9a2ce7cf27e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"血液透析动静脉内瘘维护","category":"血管外科","raw":{"name":"血液透析动静脉内瘘维护","category":"血管外科","summary":"动静脉内瘘（AVF）是血液透析患者的“生命线”，通过自体静脉-动脉吻合（多选择前臂桡动脉-头静脉）建立。内瘘需4～8周成熟后方可使用，日常维护重点是保护血管、监测震颤与血流、预防血栓与感染，发生狭窄、血栓或动脉瘤时需及时干预（介入或手术）。","symptoms":["内瘘功能良好：可触及明显震颤（thrill）、闻及血管杂音（bruit），穿刺顺利、透析血流量充足","内瘘血栓：震颤与杂音消失、无法穿刺或血流不足、瘘管变硬","内瘘狭窄：震颤减弱、透析时静脉压升高、反复穿刺失败、透析充分性下降（Kt/V降低）","感染：穿刺部位红肿热痛、脓性分泌物、发热（可致菌血症与心内膜炎）","动脉瘤样扩张：瘘管局部膨隆、皮肤变薄（破裂风险）、压迫致手部缺血"],"diagnosis":["物理检查：触诊震颤（thrill）强度与范围、听诊血管杂音、搏动增强试验（搏动强而震颤弱提示流出道狭窄）","内瘘超声（多普勒）：评估血流量（正常>500ml/min）、狭窄部位与程度、有无血栓与动脉瘤（首选）","透析参数监测：动态静脉压、透析血流量（Qb）、再循环率、Kt/V（透析充分性下降提示内瘘功能不良）","血管造影（DSA）：诊断狭窄金标准，可同时行球囊扩张（PTA）","手臂动脉压与指端血氧：评估窃血综合征（手部缺血）","血培养+穿刺部位分泌物培养：疑感染时","CTA/MRA（必要时）：评估中心静脉狭窄（上肢肿胀、静脉压高）"],"infusion":["⚠️ 按并发症选择方案，切勿全部同时使用！","","方案1（血栓溶栓，急性血栓形成早期）：","  用法：尿激酶 10～25万U + 0.9%氯化钠 20ml 内瘘内缓慢注入（溶栓治疗，需在血管外科/介入指导下进行）；或 rt-PA 2～5mg 局部注入","","方案2（抗凝，透析中与血栓预防）：","  用法：低分子肝素 0.2～0.4ml 皮下注射（透析日，按医嘱）；或普通肝素 首剂0.3～0.5mg/kg（透析管路抗凝）","","方案3（抗感染，内瘘感染）：","  用法：头孢唑林 1g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 万古霉素 1g 静滴 q12h（疑MRSA，按药敏调整，监测血药浓度）〔调 ★★ 按 CrCl 调量并监测谷浓度10-20mg/L；耳肾毒性〕","","方案4（支持与透析）：","  用法：0.9%氯化钠 静滴；必要时输注红细胞（贫血）；促红素（EPO）10000IU 皮下注射（透析后，按医嘱）","","📌 内瘘侧肢体严禁穿刺输液、测血压与压迫；溶栓治疗需警惕出血（尤其近期手术或有出血倾向者）。"],"oral_medication":["⚠️ 长期用药（透析患者需按肾功能调整剂量）：","药物1（抗血小板/抗凝，防血栓）：","用法：阿司匹林肠溶片 100mg qd 或 氯吡格雷 75mg qd（遵医嘱）；华法林（房颤者，监测INR）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","药物2（降压，保护内瘘）：","用法：氨氯地平 5mg qd 或 缬沙坦 80mg qd（避免透析前后低血压致内瘘血栓）〔调 肝功能不全减量；踝部水肿（剂量相关）〕","药物3（磷结合剂与活性维生素D，CKD-MBD）：","用法：碳酸钙 0.6g tid 随餐（或司维拉姆 0.8g tid）；骨化三醇 0.25μg qd（按血钙磷PTH调整）","药物4（促红素与铁剂，肾性贫血）：","用法：重组人促红素 10000IU 皮下注射 每周1～2次；蔗糖铁 100mg 静滴（透析中，按医嘱）","📌 透析患者用药需严格按肾功能调整剂量；避免在内瘘侧上肢注射任何药物。"],"treatment":["内瘘促成熟：术后抬高患肢、做握球运动（术后2周开始）、避免过早使用（一般4～8周，必要时延长）","血栓处理：急性血栓（<48小时）可行溶栓或手术取栓；慢性血栓或狭窄行PTA（球囊扩张）或手术重建","狭窄处理：首选经皮腔内血管成形术（PTA），反复狭窄者用药物涂层球囊或支架；中心静脉狭窄行PTA±支架","感染处理：抗生素+引流，严重者切除感染段内瘘并重建（另侧肢体）","动脉瘤处理：小的观察（避免在同一部位反复穿刺），大的或皮肤变薄者手术修复/切除并行新内瘘","窃血综合征：手部缺血者行缩窄吻合口（banding）或远端血管结扎/重建（DRIL术）","内瘘失败后的通路规划：评估血管条件，选择对侧自体AVF、人工血管移植（AVG）或中心静脉导管（临时）","长期监测：每1～3个月超声评估血流量与狭窄，随访透析参数（静脉压、Kt/V）"],"management":["日常自查宣教：每日触摸震颤、听血管杂音（早晚各一次），发现减弱或消失立即就诊","穿刺护理：绳梯式或扣眼式穿刺（避免区域穿刺致动脉瘤），透析后压迫止血15～20分钟（力度以不出血且能触及震颤为度）","保护内瘘侧肢体：禁止测血压、抽血、输液、置管、提重物、戴紧袖口与手表、受压（睡眠避免压该侧）","透析间期管理：控制体重增长（<干体重3%～5%）、避免脱水致低血压（可引起内瘘血栓）","感染预防：穿刺前皮肤消毒、穿刺后保持干燥，避免内瘘侧肢体接触污水（洗澡后消毒）","血压管理：避免透析中与居家低血压（低血压是内瘘血栓的重要诱因），遵医嘱调整降压药","定期评估：每1～3个月超声评估血流量与狭窄，监测透析充分性（Kt/V）与穿刺难度"],"notes":["内瘘是透析患者的生命线，保护内瘘侧肢体（禁测血压、抽血、输液、受压）必须反复宣教并记录","内瘘震颤减弱或消失提示血栓或狭窄，需在数小时内就诊（血栓6小时内处理成功率最高）","低血压（透析中或居家）是内瘘急性血栓的常见诱因，需控制超滤速度与降压药时机","穿刺应采用绳梯式/扣眼式，避免区域穿刺导致动脉瘤与狭窄","内瘘感染可致菌血症、心内膜炎与致命后果，穿刺部位消毒与皮肤护理非常重要"],"emergency":["内瘘震颤与杂音消失（急性血栓）→ 立即就诊，6小时内溶栓或取栓","穿刺部位大出血（压迫不当/动脉瘤破裂）→ 立即压迫止血并急诊处理，必要时手术","内瘘局部红肿热痛伴发热（感染/脓肿）→ 急诊抗感染并评估切除或重建","透析后手部发凉、疼痛、麻木（窃血综合征）→ 急诊评估，必要时手术矫治"],"pinyin":"xytxdmjlnwh","icd10":"Z99.2","physical_exam":["生命体征：血压（避免低血压）、心率、体温（感染）","内瘘触诊：震颤（thrill）强度与范围、搏动增强试验、瘘管硬度与走行、有无动脉瘤与狭窄段","内瘘听诊：血管杂音（bruit）强度与连续性（高调、收缩期为主提示狭窄）","内瘘侧上肢：肿胀（中心静脉狭窄/回流受阻）、皮温、皮肤完整性、穿刺点愈合","手部血供：指端温度、颜色、毛细血管充盈、桡动脉与尺动脉搏动、Allen试验","神经系统：手部麻木与感觉（窃血致缺血性神经病）","对侧与下肢血管：评估其他血管通路与血管条件（备用通路规划）"],"lab_tests":["内瘘彩色多普勒超声：每1～3个月评估血流量（正常>500ml/min）、狭窄与血栓（首选）","透析参数：动态静脉压、透析血流量（Qb）、再循环率、Kt/V（每1～3个月）","肾功能+电解质+血气分析：透析充分性与酸碱平衡评估（每次透析前后）","血常规+铁代谢+铁蛋白：肾性贫血评估（血红蛋白目标100～120g/L）","血钙+磷+甲状旁腺激素（PTH）：CKD-MBD评估（每1～3个月）","血培养+穿刺部位分泌物培养：疑内瘘感染时（抗生素前留取）","血管造影（DSA）：疑狭窄、血栓或中心静脉病变时（可同时行PTA治疗）"],"nursing":["内瘘保护宣教：严禁内瘘侧肢体测血压、抽血、输液、置管、提重物、受压与戴紧袖口；每日自查震颤与杂音并记录","穿刺与止血护理：绳梯式/扣眼式穿刺，透析后正确压迫（15～20分钟，力度适中），观察穿刺点有无渗血与血肿","震颤与杂音监测：每次透析前后触诊与听诊并记录，发现减弱或消失立即报告","透析中管理：监测血压（避免低血压）、血流量与静脉压，观察内瘘侧手臂有无疼痛、发凉","感染预防：穿刺前严格消毒，透析后保持干燥，指导居家清洁与避免污染","健康宣教：控制透析间期体重增长、遵医嘱服药与饮食（限水限盐限钾限磷）、按时复查内瘘超声"],"diet":["限水：透析间期体重增长控制在干体重的3%～5%（每日饮水约500～800ml+尿量）","限盐：每日钠盐<3～5g，减少口渴与水分摄入","限钾：避免香蕉、橙子、土豆、蘑菇、低钠盐等高钾食物（高钾血症风险）","限磷：避免动物内脏、坚果、全谷物、碳酸饮料、加工肉制品；按医嘱服磷结合剂（随餐）","优质蛋白：每日1.0～1.2g/kg（透析患者蛋白需求增加），以鱼、瘦肉、蛋、奶为主；保证足够热量"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1359},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"709d3282803916805471a0cd84b0dbbaf17ada94a3fd1dd3476c55438f9c0829","pinyin":"xueyetouxidongjingmaineilouweihu","initials":"xytxdjmnlwh","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","内瘘功能良好：可触及明显震颤（thrill）、闻及血管杂音（bruit），穿刺顺利、透析血流量充足\\n内瘘血栓：震颤与杂音消失、无法穿刺或血流不足、瘘管变硬\\n内瘘狭窄：震颤减弱、透析时静脉压升高、反复穿刺失败、透析充分性下降（Kt/V降低）\\n感染：穿刺部位红肿热痛、脓性分泌物、发热（可致菌血症与心内膜炎）\\n动脉瘤样扩张：瘘管局部膨隆、皮肤变薄（破裂风险）、压迫致手部缺血",60],["摘要","动静脉内瘘（AVF）是血液透析患者的“生命线”，通过自体静脉-动脉吻合（多选择前臂桡动脉-头静脉）建立。内瘘需4～8周成熟后方可使用，日常维护重点是保护血管、监测震颤与血流、预防血栓与感染，发生狭窄、血栓或动脉瘤时需及时干预（介入或手术）。",30],["疾病编码","Z99.2",30],["原首字母","xytxdmjlnwh",60]]},{"id":"orders-33d13596068256af91f0","key":"v1-c9ccc21dfe2a3058|orders-33d13596068256af91f0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"食管癌围手术期管理","category":"胸外科","raw":{"name":"食管癌围手术期管理","category":"胸外科","summary":"食管癌以鳞癌与腺癌为主，手术（食管切除+胃代食管颈部/胸内吻合）是主要治疗手段。围手术期重点：术前营养支持与呼吸训练、术后吻合口瘘与肺部并发症防治、早期肠内营养与吞咽功能康复。","symptoms":["术前：进行性吞咽困难（先固体后半流质）、胸骨后疼痛、消瘦、贫血、反流误吸（呛咳、肺部感染）","术后早期：发热、胸痛、引流液浑浊或唾液样（吻合口瘘）、呼吸困难与气促（肺部并发症）、心律失常","术后胃代食管相关：反流（平卧加重）、餐后胸闷、胃排空延迟","吻合口狭窄：术后远期出现进食梗阻、吞咽不畅","营养不良：体重下降、低蛋白、维生素缺乏"],"diagnosis":["术前：胃镜+活检（病理确诊）、超声内镜（T分期）、增强CT/PET-CT（分期与可切除性）、上消化道造影","术前评估：营养状态（NRS2002、白蛋白与前白蛋白）、心肺功能（肺功能、心电图、心脏超声）","术后监测：血常规、CRP、PCT、白蛋白、引流液性状（吻合口瘘多发生于术后5～10天）","上消化道造影（泛影葡胺）：疑吻合口瘘或评估吻合口通畅性","胸部CT：术后肺部并发症（肺炎、肺不张、胸腔积液）评估","病理分期与分子检测：指导术后辅助治疗（PD-L1、HER2等）"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g 静滴 + 甲硝唑 0.5g 静滴（或头孢曲松 2g + 甲硝唑）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术后抗感染）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；吻合口瘘者哌拉西林他唑巴坦 4.5g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案3（营养支持，术后早期）：","  用法：全肠外营养经中心静脉输注；白蛋白 10g 静滴（低蛋白者）；术后24～48小时起经鼻空肠管/空肠造瘘行肠内营养（短肽制剂）","","方案4（抑酸与化痰）：","  用法：艾司奥美拉唑 40mg 静推 q12h；氨溴索 30mg（NS 100ml 或 5%GS 100ml）静滴 bid（化痰促排痰）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","📌 食管癌术后早期肠内营养（经空肠）可降低吻合口瘘发生率与住院时间；避免术后早期经口进食。"],"oral_medication":["⚠️ 术后与恢复期用药，按医嘱选择：","药物1（抑酸，防反流）：","用法：艾司奥美拉唑 20mg qd（晨起）或 雷贝拉唑 10mg qd（疗程3～6个月）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物2（促胃动力）：","用法：莫沙必利 5mg tid（餐前30分钟）或 甲氧氯普胺 10mg tid（餐前）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物3（营养补充）：","用法：口服营养补充剂（ONS）1～2份/日；维生素B12 500μg 肌注 每月1次（必要时）","药物4（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时；塞来昔布 200mg qd（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 术后需长期少量多餐、餐后保持坐位或半卧位30～60分钟以防反流误吸。"],"treatment":["术前准备：营养支持（营养不良者术前7～10天肠内营养）、呼吸训练与戒烟、口腔清洁（减少吻合口感染）","手术方式：颈段/胸上段食管癌行颈胸腹三切口或颈腹两切口；中下段行Ivor-Lewis（胸内吻合）或左胸切口；微创（胸腔镜+腹腔镜）食管切除为优选","消化道重建：胃代食管（管状胃），注意保护胃网膜右血管弓；吻合方式（手工/器械）按术者习惯","术后管理：早期肠内营养、呼吸道管理（拍背排痰、雾化吸入布地奈德 1mg+特布他林 5mg bid、必要时纤支镜吸痰）、镇痛与早期活动","并发症处理：吻合口瘘（禁食、引流、抗感染、营养支持，必要时内镜/手术）、肺部感染与呼吸衰竭（抗感染+呼吸支持）、心律失常（纠正电解质与用药）、乳糜胸（低脂饮食/禁食+奥曲肽 0.1mg 皮下注射 q8h，必要时手术）","术后辅助治疗：按分期行辅助化疗/放化疗或免疫治疗（PD-1抑制剂）","远期处理：吻合口狭窄行内镜下扩张；反流性食管炎行抑酸（奥美拉唑 20mg 口服 qd）与促动力（莫沙必利 5mg 口服 tid）治疗"],"management":["呼吸道管理：术后每1～2小时协助翻身拍背、鼓励深呼吸与有效咳嗽、雾化吸入，必要时吸痰（重点预防肺不张与肺炎）","引流管护理：胸腔引流管与胃管保持通畅，记录引流量与性状（浑浊、唾液样提示吻合口瘘；乳白色提示乳糜胸）","营养管理：术后禁食期间肠外营养，早期经鼻空肠管行肠内营养（温度38～40℃、由慢到快），监测耐受性","疼痛管理：胸痛明显者行硬膜外/肋间神经阻滞+静脉镇痛，保证有效咳嗽","早期活动：术后第1天床上活动，逐步下床（促进肺复张、肠功能恢复与防血栓）","进食管理：吻合口愈合（造影确认无瘘）后经口进食——从温凉流质开始，少量多餐，餐后坐位30～60分钟","出院指导：少量多餐（每日5～6餐）、细嚼慢咽、避免反流（睡前3小时不进食、抬高床头）、定期复查"],"notes":["食管癌术后吻合口瘘是最严重并发症（多发生于术后5～10天），早期肠内营养与充分引流可降低发生率与严重程度","肺部并发症（肺炎、肺不张、呼吸衰竭）是术后主要死亡原因，呼吸道管理是护理重点","术后早期必须经空肠营养（不经胃），避免食物刺激吻合口","进食后反流误吸风险高（胃代食管无括约肌功能），需长期保持餐后坐位与抬高床头","术后需长期营养随访，维生素B12与铁可能缺乏（尤其全胃/近端胃切除者）"],"emergency":["术后高热、胸痛伴引流液浑浊/唾液样（吻合口瘘）→ 禁食、引流、抗感染，必要时手术或内镜处理","呼吸困难、血氧下降伴肺部啰音（呼吸衰竭/重症肺炎）→ 吸氧、抗感染，必要时机械通气","引流液呈乳白色（乳糜胸）→ 禁食+全肠外营养+生长抑素，必要时手术胸导管结扎","心悸、心律失常伴电解质紊乱 → 纠正电解质（钾、镁）并心电监护"],"pinyin":"sagwssqgl","icd10":"C15.9","physical_exam":["生命体征：体温、脉搏、呼吸、血氧、血压（感染与呼吸功能）","一般情况：营养状态、体重、贫血貌、锁骨上淋巴结","胸部：呼吸动度、呼吸音（肺不张/胸腔积液）、皮下气肿、切口愈合","引流管：胸腔引流与胃管位置、引流量与性状、水封瓶波动","腹部：腹部压痛（胃代食管致腹胀）、肠鸣音","吞咽与反流：进食后有无呛咳、反流与胸骨后不适","其他：颈部吻合口有无红肿渗液（颈部吻合口瘘）"],"lab_tests":["术前：血常规（贫血）、白蛋白/前白蛋白（营养）、肝肾功能、凝血、肺功能、心电图、胃镜+活检、增强CT/PET-CT","术后：血常规、CRP、PCT（吻合口瘘与感染）、白蛋白与前白蛋白每2～3天","引流液检查：淀粉酶、胆红素、细菌培养（鉴别吻合口瘘与乳糜胸）","上消化道造影（泛影葡胺）：疑吻合口瘘或评估吻合口通畅","胸部CT：术后肺部并发症与胸腔积液评估","电解质（钾、镁、钙）+血气分析：术后心律失常与酸碱失衡评估","病理与分子检测：TNM分期、PD-L1、HER2（指导辅助治疗）"],"nursing":["呼吸道护理：每1～2小时翻身拍背，雾化吸入后鼓励有效咳嗽，必要时吸痰；监测血氧与呼吸音","引流与胃管护理：妥善固定、记录引流量与性状，胃管减压期间做好口腔护理（每日2～3次）","营养护理：肠内营养（鼻空肠管）注意温度、速度、浓度，观察腹胀腹泻；肠外营养规范输注","疼痛护理：评估疼痛评分，遵医嘱镇痛（促进有效咳嗽与早期活动）","早期活动：术后第1天床上活动与坐起，逐步下床行走（预防肺不张、血栓与肠功能延迟恢复）","进食宣教：少量多餐、细嚼慢咽、餐后坐位30～60分钟、睡前3小时不进食、抬高床头防反流"],"diet":["术后早期：禁食，经空肠管肠内营养+肠外营养支持","吻合口愈合后：温凉流质（米汤、稀藕粉、匀浆膳）→ 半流质 → 软食，少量多餐（每日5～6餐）","每餐量由50ml起始逐渐增加，进食速度慢，充分咀嚼","高蛋白、高热量、易消化、细软少渣；避免粗糙、坚硬、过烫及刺激性食物","防反流：餐后保持坐位或半卧位30～60分钟，睡前3小时不进食，睡眠时抬高床头15～20cm"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1360},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"700388893a502eb50af22e3b6f5047ff99e74830f9da75b42f03b5d9c03d10e2","pinyin":"shiguanaiweishoushuqiguanli","initials":"sgawssqgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术前：进行性吞咽困难（先固体后半流质）、胸骨后疼痛、消瘦、贫血、反流误吸（呛咳、肺部感染）\\n术后早期：发热、胸痛、引流液浑浊或唾液样（吻合口瘘）、呼吸困难与气促（肺部并发症）、心律失常\\n术后胃代食管相关：反流（平卧加重）、餐后胸闷、胃排空延迟\\n吻合口狭窄：术后远期出现进食梗阻、吞咽不畅\\n营养不良：体重下降、低蛋白、维生素缺乏",60],["摘要","食管癌以鳞癌与腺癌为主，手术（食管切除+胃代食管颈部/胸内吻合）是主要治疗手段。围手术期重点：术前营养支持与呼吸训练、术后吻合口瘘与肺部并发症防治、早期肠内营养与吞咽功能康复。",30],["疾病编码","C15.9",30],["原首字母","sagwssqgl",60]]},{"id":"orders-37379b31450edda0dc3c","key":"v1-c9ccc21dfe2a3058|orders-37379b31450edda0dc3c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肺癌围手术期管理","category":"胸外科","raw":{"name":"肺癌围手术期管理","category":"胸外科","summary":"肺癌围手术期管理包括术前分期与心肺功能评估、解剖性肺切除（肺叶/肺段切除+淋巴结清扫，胸腔镜优先）、术后并发症防治（肺不张、肺炎、支气管胸膜瘘、心律失常、持续性漏气）与呼吸道康复，以及术后辅助治疗与随访。","symptoms":["术前：咳嗽、咯血、胸痛、气促、消瘦；早期可无症状（体检发现）","术后早期：气促与低氧（肺功能损失）、咳嗽无力与痰液潴留（肺不张）、发热（肺部感染）","持续漏气：胸腔引流持续大量气泡（>5～7天）","支气管胸膜瘘：术后1～2周出现发热、咳脓痰、胸腔引流液浑浊/气液平（严重并发症）","术后心律失常：房颤（老年患者多见）、心动过速"],"diagnosis":["术前：胸部增强CT（分期与解剖）、PET-CT（淋巴结与远处转移）、支气管镜/穿刺活检（病理与分子分型）、肺功能与心功能评估","术前评估：肺功能（FEV1、DLCO，预计术后值）、动脉血气、心脏超声与心电图、6分钟步行试验","术后：胸片/胸部CT（肺复张、胸腔积液、肺不张）、血常规与CRP","引流评估：漏气程度、引流量与性状（血性、乳糜样、浑浊）","病理与分子检测：TNM分期、EGFR/ALK/ROS1、PD-L1（指导辅助治疗）","随访：术后2年内每3～6个月胸部CT（发现复发与第二原发癌）"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术后抗感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h（24～48小时）；肺部感染者按痰培养调整（如哌拉西林他唑巴坦 4.5g q8h）〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案3（化痰与平喘）：","  用法：氨溴索 30mg 静滴 bid；多索茶碱 0.2g 静滴 qd（支气管痉挛者）；必要时布地奈德+特布他林雾化〔调 妊娠早期禁用；胃溃疡者慎用〕","","方案4（镇痛与支持）：","  用法：氟比洛芬酯 50mg 静滴 q12h；曲马多 100mg 静滴 必要时；0.9%氯化钠/葡萄糖 静滴维持；低蛋白者白蛋白 10g 静滴","","📌 充分镇痛是有效咳嗽排痰的前提；术后避免过量补液（防肺水肿）。"],"oral_medication":["⚠️ 术后用药，按医嘱选择：","药物1（镇痛）：","用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（化痰止咳）：","用法：氨溴索 30mg tid 或 乙酰半胱氨酸 0.6g tid；复方甲氧那明 2粒 tid（咳嗽明显者）〔调 妊娠早期禁用；胃溃疡者慎用〕","药物3（通便）：","用法：乳果糖 15ml bid（避免用力排便，防漏气与出血）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（辅助治疗，按分期）：","用法：EGFR突变者术后奥希替尼 80mg qd（辅助靶向）；或按方案行辅助化疗","📌 术后需戒烟（吸烟影响肺复张与切口愈合）；辅助治疗应在术后4～6周内开始（身体恢复后）"],"treatment":["术前准备：戒烟≥2周、呼吸训练（缩唇呼吸、深呼吸训练器）、治疗呼吸道感染、营养支持","手术方式：解剖性肺切除（肺叶切除为标准，早期周围型可行肺段/亚肺叶切除）+系统性淋巴结清扫；胸腔镜（VATS）或机器人微创优先","术后呼吸道管理：镇痛+有效咳嗽排痰、雾化吸入、早期下床活动、必要时纤支镜吸痰或高频胸壁振荡排痰","胸腔引流管理：保持通畅、观察漏气与水柱波动，漏气停止且肺完全复张、引流<200ml/日可拔管","并发症处理：肺不张（积极排痰+纤支镜）、肺炎（抗感染）、支气管胸膜瘘（引流+抗感染+营养，必要时手术/支气管镜封堵）、心律失常（纠正缺氧与电解质，必要时用药）、持续漏气（延长引流或胸膜固定）","术后辅助治疗：Ⅱ～Ⅲ期行辅助化疗（含铂双药）±免疫治疗；EGFR突变者辅助靶向；PD-L1高表达者辅助免疫","随访：术后2年内每3～6个月CT，之后每6～12个月（早期发现复发与第二原发肺癌）"],"management":["呼吸道护理：每1～2小时翻身拍背、鼓励深呼吸与有效咳嗽；使用诱发性肺量计（incentive spirometry）每小时10次","疼痛管理：多模式镇痛（硬膜外/肋间阻滞+静脉+口服），保证有效咳嗽（疼痛控制不佳是肺不张主因）","胸腔引流护理：保持水封瓶密闭与通畅，观察气泡（漏气）与水柱波动，记录引流量与性状","早期活动：术后第1天床上活动与坐起，第2～3天下床行走（促进肺复张与肠功能恢复）","液体管理：限制晶体液（避免肺水肿），监测出入量与血氧","并发症观察：呼吸困难与血氧下降（肺不张/肺炎/支气管胸膜瘘）、持续漏气、发热与引流液浑浊","出院指导：继续呼吸训练与咳嗽、戒烟、避免感染、逐步恢复活动、按时复查与辅助治疗"],"notes":["术后肺不张与肺炎是最常见并发症，充分镇痛+有效排痰+早期活动是防治关键","支气管胸膜瘘多发生于术后1～2周（全肺切除与术前放疗者风险高），表现为发热、咳脓痰与胸腔引流异常","全肺切除术后胸腔引流需控制引流量（避免纵隔移位），一般不做负压吸引","术后心律失常（房颤）多见于老年与全肺切除患者，需纠正缺氧、电解质与容量状态","肺癌术后需长期随访（复发与第二原发癌风险），戒烟是必须的长期措施"],"emergency":["突发呼吸困难、血氧下降伴患侧呼吸音消失（肺不张/气胸）→ 立即评估、吸氧，必要时纤支镜或胸腔引流","术后引流大量鲜红血液（胸腔内出血）→ 立即评估并急诊手术止血","咳大量脓痰伴发热与胸腔引流浑浊（支气管胸膜瘘）→ 急诊引流+抗感染，必要时手术","心律失常伴血流动力学不稳定（快速房颤、室速）→ 立即处理并心电监护"],"pinyin":"fawssqgl","icd10":"C34.9","physical_exam":["生命体征：体温、呼吸频率、血氧（呼吸功能）、脉搏与血压","一般情况：营养状态、体重、体力状况（ECOG）","胸部：呼吸动度（患侧减弱）、呼吸音（减弱/消失提示肺不张或积液）、皮下气肿、切口情况","引流管：胸管位置、水封瓶气泡（漏气）、水柱波动、引流量与性状","心脏：心率与心律（房颤）、心音","其他：锁骨上淋巴结、颈静脉（上腔静脉综合征）、下肢水肿与疼痛（血栓）","活动耐量：床旁活动后气促程度（评估肺功能恢复）"],"lab_tests":["术前：肺功能（FEV1、DLCO、预计术后值）、动脉血气、心脏超声与心电图、胸部增强CT/PET-CT、支气管镜或穿刺活检","术后：血常规、CRP（感染）、电解质（钾、镁，心律失常风险）每1～2天","胸片/胸部CT：术后肺复张、胸腔积液与肺不张评估","引流液检查：细菌培养、乳糜试验（乳白色引流液）、细胞学（必要时）","病理与分子检测：TNM分期、EGFR/ALK/ROS1、PD-L1（辅助治疗依据）","D-二聚体+下肢静脉超声（疑深静脉血栓）","随访：胸部CT（术后2年内每3～6个月）、肿瘤标志物（CEA、CYFRA21-1等）"],"nursing":["呼吸道护理：每1～2小时协助翻身拍背、雾化后鼓励有效咳嗽；使用诱发性肺量计，监测血氧","胸腔引流护理：保持密闭、通畅、低于胸腔60～100cm；观察气泡与水柱波动，搬动时夹闭管路","疼痛与活动：评估疼痛评分并遵医嘱镇痛，协助早期下床活动（促进肺复张）","体位护理：麻醉清醒后取半卧位，鼓励患侧卧位（利于健侧肺通气与引流）","并发症观察：呼吸频率与血氧变化、痰液性状与量、引流液性状、体温与切口情况","宣教：戒烟、呼吸训练（缩唇呼吸、腹式呼吸）、避免感染、逐步增加活动量、按时复查"],"diet":["术前：高蛋白、高热量、高维生素饮食，纠正营养不良与贫血","术后早期：麻醉清醒后进流质，逐步过渡到半流质、软食、普食","高蛋白（鱼、瘦肉、蛋、奶）促进切口与肺组织修复；充足热量补偿消耗","多饮水（每日1500～2000ml），稀释痰液利于咳出（心功能不全者按医嘱限水）","戒烟、忌辛辣刺激；避免产气食物（减轻腹胀影响呼吸）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1361},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"be879b9944f771243e36191dbd6d0e03a115656e9e55063d84881708fd0e13f9","pinyin":"feiaiweishoushuqiguanli","initials":"fawssqgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术前：咳嗽、咯血、胸痛、气促、消瘦；早期可无症状（体检发现）\\n术后早期：气促与低氧（肺功能损失）、咳嗽无力与痰液潴留（肺不张）、发热（肺部感染）\\n持续漏气：胸腔引流持续大量气泡（>5～7天）\\n支气管胸膜瘘：术后1～2周出现发热、咳脓痰、胸腔引流液浑浊/气液平（严重并发症）\\n术后心律失常：房颤（老年患者多见）、心动过速",60],["摘要","肺癌围手术期管理包括术前分期与心肺功能评估、解剖性肺切除（肺叶/肺段切除+淋巴结清扫，胸腔镜优先）、术后并发症防治（肺不张、肺炎、支气管胸膜瘘、心律失常、持续性漏气）与呼吸道康复，以及术后辅助治疗与随访。",30],["疾病编码","C34.9",30],["原首字母","fawssqgl",60]]},{"id":"orders-caa5852220d58b778095","key":"v1-c9ccc21dfe2a3058|orders-caa5852220d58b778095","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"膀胱肿瘤电切术后与膀胱灌注","category":"泌尿外科","raw":{"name":"膀胱肿瘤电切术后与膀胱灌注","category":"泌尿外科","summary":"经尿道膀胱肿瘤电切术（TURBT）是非肌层浸润性膀胱癌（NMIBC）的标准诊断与治疗方式，术后按危险分层行膀胱灌注化疗（即刻+维持）或卡介苗（BCG）灌注以降低复发。术后管理重点：出血与膀胱痉挛观察、灌注方案执行与不良反应处理、定期膀胱镜随访。","symptoms":["术前/术后共同：无痛性肉眼血尿（间歇性）、尿频尿急尿痛（合并感染或肿瘤刺激）","术后早期：血尿（淡红→清亮为正常过程）、膀胱痉挛（下腹坠痛、尿意频繁）、排尿困难","灌注后：尿频、尿急、尿痛（化学性膀胱炎）、血尿；BCG灌注后可出现发热、流感样症状","灌注严重并发症：高热寒战（BCG全身感染/脓毒症）、严重膀胱刺激症状、输尿管反流致肾盂肾炎","复发表现：再次出现无痛性血尿或膀胱镜检查发现新病灶"],"diagnosis":["术后病理：肿瘤分级（低/高级别）、分期（Ta/T1/Tis）、数目、大小、有无原位癌（决定危险分层与灌注方案）","尿常规+尿培养：灌注前后评估感染与血尿","膀胱镜（术后3个月首次，之后按危险分层：低危每年、中危每3～6个月、高危每3个月）","尿脱落细胞学：高级别肿瘤与原位癌监测（每3～6个月）","上尿路评估（CTU/静脉肾盂造影）：高危患者与血尿持续者","血常规+CRP+PCT：灌注后发热者（警惕BCG全身感染）","影像学（CT/MRI）：肌层浸润评估（T1高危或疑肌层浸润者）"],"infusion":["⚠️ 按灌注方案与不良反应选择，切勿全部同时使用！","方案1（膀胱灌注化疗，即刻灌注）：","用法：吉西他滨 2000mg + 0.9%氯化钠 50ml 膀胱灌注（术后24小时内，保留1小时）；或 表柔比星 50～80mg + 0.9%氯化钠 50ml","方案2（维持灌注化疗，每周1次×8周，后每月1次×10个月）：","用法：吉西他滨 2000mg 或 表柔比星 50mg 膀胱灌注（保留1小时，每15分钟变换体位）","方案3（BCG灌注，高危NMIBC）：","用法：BCG 120mg + 0.9%氯化钠 50ml 膀胱灌注（术后2～4周开始，诱导期每周1次×6周，维持期按方案）","方案4（BCG全身感染/脓毒症，紧急）：","用法：异烟肼 300mg qd + 利福平 600mg qd + 乙胺丁醇 15mg/kg qd（三联抗结核，立即启动，感染科会诊）〔调 ★ 肝功能不全慎用；★ 强CYP450诱导剂（大量相互作用）〕","📌 灌注前须确认无尿路感染与血尿、无膀胱穿孔；灌注后6小时内多饮水并排尿，注意尿液处理（BCG灌注后尿液需消毒处理）。"],"oral_medication":["⚠️ 灌注间期与对症用药，按医嘱选择：","药物1（抗感染，灌注前尿路感染或灌注后膀胱炎）：","用法：左氧氟沙星 0.5g qd 或 头孢克肟 0.1g bid（疗程3～5天）；尿培养阳性按药敏调整〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（缓解膀胱刺激症状）：","用法：索利那新 5mg qd 或 托特罗定 2mg bid（膀胱痉挛、尿频尿急，青光眼者慎用）","药物3（碱化尿液，减轻化学性膀胱炎）：","用法：枸橼酸氢钾钠颗粒 1袋 tid 或 碳酸氢钠 1g tid〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","药物4（止血）：","用法：氨甲环酸片 0.5g tid（血尿明显时，遵医嘱）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","📌 灌注后出现发热（尤其BCG灌注后）需立即就诊，不可自行用退热药掩盖症状。"],"treatment":["术后即刻灌注：TURBT后24小时内行膀胱灌注化疗（吉西他滨/表柔比星），可显著降低复发率","危险分层与方案：低危——即刻灌注+随访；中危——即刻+维持灌注化疗（1年）；高危——BCG诱导+维持灌注（1～3年）","灌注技术要点：灌注前排空膀胱、确认无感染与血尿；灌注液保留1小时，每15分钟变换体位（仰卧、左右侧卧、俯卧、坐位）","BCG灌注注意：术后2～4周开始（避免过早致全身吸收）；灌注后6小时内排尿并消毒处理；出现高热寒战立即抗结核治疗","复发处理：非肌层浸润复发可再次TURBT+灌注；BCG失败（高危、反复复发）行根治性膀胱切除","肌层浸润性膀胱癌：行根治性膀胱切除+尿流改道（回肠膀胱或新膀胱），或保留膀胱综合治疗（TURBT+放化疗）","随访：膀胱镜按危险分层（低危每年、中危每3～6个月、高危每3个月），尿细胞学与上尿路影像"],"management":["术后观察：尿色与血尿程度（淡红→清亮为正常）、有无血块与排尿困难，鼓励多饮水稀释尿液","膀胱痉挛处理：下腹坠痛与频繁尿意者遵医嘱解痉药，避免导尿管气囊过度牵引","灌注护理：灌注前排空膀胱、确认无感染与血尿；灌注后记录留置时间与体位变换，观察不良反应","灌注后宣教：多饮水（每日2000～3000ml）、6小时内排尿、观察尿色与症状（尿频尿急、血尿、发热）","BCG灌注特殊处理：灌注后尿液6小时内需用含氯消毒剂处理（倒入马桶静置后冲），避免与家人共用卫生间；出现发热寒战立即就诊","随访管理：建立膀胱镜随访计划表，强调按时复查的重要性（复发率高）","戒烟与职业暴露防护：吸烟是膀胱癌最主要危险因素，必须戒烟；避免接触芳香胺类化学物质"],"notes":["无痛性肉眼血尿是膀胱癌最典型表现，中老年患者出现应尽快行膀胱镜与尿细胞学检查","TURBT术后24小时内即刻灌注可显著降低复发风险（低危患者可能仅需此一次灌注）","BCG灌注是高危NMIBC的首选，但可引起全身感染（脓毒症），出现高热寒战须立即抗结核治疗","灌注期间避免剧烈活动与性生活（24～48小时），多饮水促进排泄","膀胱癌复发率高（非肌层浸润5年复发率50%～70%），必须坚持膀胱镜随访"],"emergency":["灌注后高热寒战、血压下降（BCG全身感染/脓毒症）→ 立即三联抗结核+抗感染抢救，感染科会诊","大量血尿伴血块致排尿困难与膀胱填塞 → 急诊导尿冲洗、清除血块，必要时电凝止血","灌注后严重膀胱刺激症状伴下腹剧痛 → 解痉镇痛、补液，必要时暂停灌注","术后突发下腹剧痛伴腹膜刺激征（膀胱穿孔）→ 急诊手术探查"],"pinyin":"pgzldqshybgz","icd10":"C67.9","physical_exam":["生命体征：体温（灌注后感染）、脉搏、血压","一般情况：贫血貌（长期血尿）、营养状态","腹部：下腹压痛与膨隆（膀胱充盈/血块）、有无腹块","膀胱区叩诊：浊音界（尿潴留）","直肠/阴道指检（必要时）：膀胱壁浸润与盆腔肿物评估（双合诊）","导尿管：位置、尿色与通畅度、有无血块阻塞","下肢与盆腔淋巴结：水肿、淋巴结肿大（转移评估）"],"lab_tests":["尿常规+尿培养：灌注前必查（排除尿路感染），灌注后评估血尿与感染","尿脱落细胞学：高级别肿瘤与原位癌监测（每3～6个月）","血常规+CRP+PCT：灌注后发热者评估感染（BCG全身感染可致脓毒症）","膀胱镜+活检：术后3个月首次，之后按危险分层（低危每年、高危每3个月）","上尿路影像（CTU/静脉肾盂造影）：高危患者与持续血尿者（排除上尿路肿瘤）","肝功能+肾功能：BCG抗结核治疗与化疗药物监测","CT/MRI（疑肌层浸润）：评估分期与盆腔淋巴结"],"nursing":["术后护理：观察尿色与血尿变化，鼓励多饮水（每日2000～3000ml），记录尿量与有无血块","膀胱痉挛护理：观察下腹胀痛与尿意频繁，遵医嘱解痉，避免导尿管过度牵引与膀胱过度充盈","灌注护理：灌注前排空膀胱、确认无感染与血尿；灌注后记录保留时间与体位变换，观察不良反应","灌注后宣教：多饮水、6小时内排尿、观察尿色与症状（尿频尿急、血尿、发热）；BCG灌注后尿液消毒处理","随访提醒：建立膀胱镜与尿细胞学复查计划并提醒患者，强调复发风险与戒烟","心理护理：膀胱癌易复发，患者焦虑明显，需解释灌注治疗意义与随访方案，提高依从性"],"diet":["多饮水（每日2000～3000ml），稀释尿液、减少化疗药物对膀胱黏膜刺激","多吃新鲜蔬菜水果（尤其十字花科蔬菜），补充维生素A、C、E","限制腌制、熏制与高脂食物；避免含亚硝酸盐的加工食品","绝对戒烟（吸烟是膀胱癌最重要危险因素），避免过量饮酒与咖啡因","灌注期间避免辛辣刺激食物与酒类（加重膀胱刺激症状）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1362},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8bb474f3932b0091f20ba6c470e2bd1aa5d6e017e113059f928a6d32c3392f70","pinyin":"pangguangzhongliudianqieshuhouyupangguangguanzhu","initials":"pgzldqshypggz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术前/术后共同：无痛性肉眼血尿（间歇性）、尿频尿急尿痛（合并感染或肿瘤刺激）\\n术后早期：血尿（淡红→清亮为正常过程）、膀胱痉挛（下腹坠痛、尿意频繁）、排尿困难\\n灌注后：尿频、尿急、尿痛（化学性膀胱炎）、血尿；BCG灌注后可出现发热、流感样症状\\n灌注严重并发症：高热寒战（BCG全身感染/脓毒症）、严重膀胱刺激症状、输尿管反流致肾盂肾炎\\n复发表现：再次出现无痛性血尿或膀胱镜检查发现新病灶",60],["摘要","经尿道膀胱肿瘤电切术（TURBT）是非肌层浸润性膀胱癌（NMIBC）的标准诊断与治疗方式，术后按危险分层行膀胱灌注化疗（即刻+维持）或卡介苗（BCG）灌注以降低复发。术后管理重点：出血与膀胱痉挛观察、灌注方案执行与不良反应处理、定期膀胱镜随访。",30],["疾病编码","C67.9",30],["原首字母","pgzldqshybgz",60]]},{"id":"orders-685597f1229a3d1ae7f5","key":"v1-c9ccc21dfe2a3058|orders-685597f1229a3d1ae7f5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肾损伤（闭合性肾外伤）","category":"泌尿外科","raw":{"name":"肾损伤（闭合性肾外伤）","category":"泌尿外科","summary":"肾损伤多由钝性外伤（撞击、坠落、车祸）或穿透伤引起，按AAST分级Ⅰ～Ⅴ级。绝大多数（约85%）为轻度损伤，可非手术治疗；Ⅳ～Ⅴ级或血流动力学不稳定者需介入或手术。管理重点是血流动力学监测、血尿观察、影像学分期与并发症（尿外渗、迟发性出血、肾性高血压）防治。","symptoms":["腰腹部疼痛与压痛（患侧）、腰肌紧张","肉眼或镜下血尿（血尿程度与损伤程度不完全平行，肾蒂损伤可无血尿）","腰部瘀斑或包块（Grey-Turner征见于腹膜后血肿）","失血性休克表现（面色苍白、脉搏细速、血压下降）","合并伤：肋骨骨折、肝脾破裂、骨盆骨折、颅脑损伤"],"diagnosis":["血流动力学评估：血压、心率、尿量、意识（首要，决定处理策略）","尿常规+尿沉渣：血尿（镜下或肉眼），连续监测","腹部增强CT（含延迟期，首选）：明确肾损伤分级、血肿范围、尿外渗与合并伤（稳定患者必查）","床旁超声（FAST）：快速评估腹腔与腹膜后积液（不稳定患者首选筛查）","血常规+血型+交叉配血+凝血功能：动态监测血红蛋白与备血","肾功能+电解质：评估肾损伤程度与对侧肾功能","静脉肾盂造影（IVP，必要时）：评估肾功能与尿外渗（CT不可及时）"],"infusion":["⚠️ 抢救用药，须在监护下按病情选择！","","方案1（抗休克液体复苏）：","  用法：平衡盐溶液/0.9%氯化钠 快速补液；红细胞悬液、新鲜冰冻血浆按需（目标Hb 70～90g/L、收缩压80～90mmHg，避免过度升压加重出血）","","方案2（止血辅助）：","  用法：氨甲环酸 1g（NS 100ml 或 5%GS 100ml）静滴（伤后3小时内）；维生素K1 10mg 静滴（凝血异常者）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（抗感染，尿外渗/血肿/手术者）：","  用法：头孢呋辛 1.5g 静滴 q8h 或 头孢曲松 2g 静滴 qd（有尿外渗者可加用左氧氟沙星）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","","方案4（镇痛与支持）：","  用法：曲马多 100mg 静滴 必要时；0.9%氯化钠 静滴维持尿量>0.5ml/kg/h","","📌 禁止使用NSAIDs（肾毒性）；避免使用肾毒性抗生素（氨基糖苷类）；监测尿量与肾功能。"],"oral_medication":["⚠️ 恢复期用药，按医嘱选择：","药物1（抗感染序贯）：","用法：头孢克肟 0.1g bid 或 阿莫西林克拉维酸 0.625g tid（疗程5～7天）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时（避免NSAIDs长期使用）；曲马多 50mg（必要时）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物3（碱化尿液/止血，血尿明显）：","用法：碳酸氢钠 1g tid；氨甲环酸片 0.5g tid（遵医嘱）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","药物4（通便）：","用法：乳果糖 15ml bid（避免用力排便诱发出血）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 恢复期避免剧烈运动与腰部撞击（防迟发性出血），绝对卧床至血尿转清后逐步活动。"],"treatment":["血流动力学不稳定：立即抗休克+急诊手术（肾探查、修补或肾切除，肾蒂损伤需及时处理）","血流动力学稳定：按分级处理——Ⅰ～Ⅲ级多非手术治疗（绝对卧床、监测、输液、抗感染、反复影像评估）","Ⅳ级（节段性血管损伤/尿外渗）：多可非手术治疗；持续出血或尿外渗明显者行介入栓塞（超选择性肾动脉栓塞）","Ⅴ级（肾蒂撕裂/粉碎性损伤）：多需手术（肾修补或肾切除，注意对侧肾功能）","介入治疗：选择性肾动脉栓塞适用于持续出血但血流动力学稳定者（保留肾单位）","并发症处理：尿外渗/尿性囊肿（引流或支架）、迟发性出血（介入栓塞）、肾性高血压（随访监测）、肾积水（解除梗阻）","合并伤处理：肝脾破裂、肋骨骨折、骨盆骨折等按相应原则处理"],"management":["绝对卧床休息：非手术治疗者卧床2～4周（至血尿转清后逐步活动），避免用力、搬动与剧烈咳嗽","严密监测：血压、心率、尿量（每小时）、腹围与腰部包块大小，动态复查血红蛋白","尿液观察：记录尿色（淡红→清亮）与尿量，血尿加重或转清后再现提示活动性出血","抗感染：尿外渗与血肿者预防性抗感染（避免肾毒性药物）","影像学随访：伤后48～72小时复查增强CT，评估血肿变化、尿外渗与肾形态；恢复期定期复查超声","疼痛与腹部体征监测：腰痛加剧伴包块增大提示继续出血，需立即报告","出院指导：1～3个月内避免剧烈运动、重体力劳动与腰部撞击；监测血压（肾性高血压可迟发）；复查肾功能与影像"],"notes":["肾损伤处理以『血流动力学状态』为核心：稳定者多可非手术治疗（85%以上），不稳定者需急诊手术","血尿程度与损伤程度不完全平行——肾蒂损伤或输尿管断裂时可无血尿，不能以血尿轻重判断伤情","绝对卧床是保守治疗的关键（一般2～4周），过早活动可致迟发性出血","禁用肾毒性药物（NSAIDs、氨基糖苷类）并监测肾功能与尿量","迟发性出血可发生于伤后数天至数周，需随访观察；合并尿外渗者易形成尿性囊肿与感染"],"emergency":["血压持续下降、腰部包块迅速增大、血红蛋白进行性下降（活动性出血）→ 立即抗休克并急诊手术/介入栓塞","非手术治疗期间突发腰痛加剧伴休克（迟发性出血）→ 立即抢救并介入或手术","高热伴腰痛加重、感染指标升高（尿外渗继发感染/肾周脓肿）→ 引流+抗感染","少尿/无尿（双侧肾损伤或孤立肾损伤）→ 急诊评估并解除梗阻"],"pinyin":"ssjbhxsws","icd10":"S37.0","physical_exam":["生命体征：血压、心率、呼吸、意识（休克评估，每15～30分钟）","一般情况：面色苍白、皮肤湿冷、口渴、尿量减少","腹部与腰部视诊：腰部瘀斑（Grey-Turner征）、腹围增大、开放性伤口","腰部与腹部触诊：患侧腰部压痛、腰肌紧张、包块（腹膜后血肿）、腹膜刺激征（合并腹腔脏器损伤）","腹部叩诊：肾区叩击痛、移动性浊音","合并伤评估：肋骨骨折（下位肋骨）、骨盆骨折、肝脾破裂、脊柱与颅脑损伤","尿量与尿色：留置尿管观察血尿程度与尿量"],"lab_tests":["尿常规+尿沉渣（连续监测）：镜下或肉眼血尿，尿色变化反映出血情况","血常规+血型+交叉配血：动态监测血红蛋白（每1～2小时休克期）与备血","肾功能（肌酐、尿素氮）+电解质：评估肾损伤与对侧肾功能","凝血功能+D-二聚体：创伤性凝血病评估","腹部增强CT（含延迟期）：首选，明确肾损伤分级、血肿、尿外渗与合并伤","床旁超声（FAST）：不稳定患者的快速筛查（腹腔与腹膜后积液）","血气分析+乳酸：评估休克与组织灌注"],"nursing":["休克护理：平卧、保温、建立两条以上静脉通路，遵医嘱补液输血，每15～30分钟监测生命体征与尿量","绝对卧床：非手术治疗者严格卧床，翻身时保持躯干平直，禁止坐起、下床与用力（防迟发性出血）","尿液观察与记录：每小时尿量、尿色（淡红→清亮），血尿加重或再现立即报告","腰部包块与腹围监测：画线标记并定时测量，包块增大提示继续出血","术前准备：拟手术者迅速禁食、备皮、备血、留置尿管，配合完成知情同意","宣教：1～3个月内避免剧烈运动与腰部撞击，监测血压与复查肾功能、定期影像随访"],"diet":["急性期禁食禁水（可能手术或需观察），必要时静脉营养","病情稳定后：清淡易消化饮食，逐步过渡到普食","多饮水（每日2000ml以上）稀释尿液、减少血块形成（无肾功能不全者）","高蛋白、高维生素饮食促进组织修复；避免辛辣刺激食物","禁酒；避免使用肾毒性药物与保健品；肾功能异常者按医嘱限制蛋白与钾"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1363},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c870b499b21f5f9c20e9051ec94724d0362b748752dd4c8d7067bc93d852e940","pinyin":"shensunshang（bihexingshenwaishang）","initials":"sss（bhxsws）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腰腹部疼痛与压痛（患侧）、腰肌紧张\\n肉眼或镜下血尿（血尿程度与损伤程度不完全平行，肾蒂损伤可无血尿）\\n腰部瘀斑或包块（Grey-Turner征见于腹膜后血肿）\\n失血性休克表现（面色苍白、脉搏细速、血压下降）\\n合并伤：肋骨骨折、肝脾破裂、骨盆骨折、颅脑损伤",60],["摘要","肾损伤多由钝性外伤（撞击、坠落、车祸）或穿透伤引起，按AAST分级Ⅰ～Ⅴ级。绝大多数（约85%）为轻度损伤，可非手术治疗；Ⅳ～Ⅴ级或血流动力学不稳定者需介入或手术。管理重点是血流动力学监测、血尿观察、影像学分期与并发症（尿外渗、迟发性出血、肾性高血压）防治。",30],["疾病编码","S37.0",30],["原首字母","ssjbhxsws",60]]},{"id":"orders-fcc556d825985883367f","key":"v1-c9ccc21dfe2a3058|orders-fcc556d825985883367f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"桡骨远端骨折","category":"骨科","raw":{"name":"桡骨远端骨折","category":"骨科","summary":"桡骨远端骨折是最常见的骨折之一（约占全身骨折1/6），多见于老年人跌倒手撑地（Colles骨折）与青年人高能量损伤。按AO/OTA与Frykman分型，治疗包括手法复位石膏/夹板外固定（无移位或稳定型）与手术内固定（掌侧锁定钢板，移位/不稳定型），康复重点是手指与腕关节功能训练、防僵硬与复杂区域性疼痛综合征。","symptoms":["腕部疼痛、肿胀、压痛，活动受限","典型畸形：Colles骨折呈餐叉样畸形（远端向背侧移位）、Smith骨折呈反餐叉畸形（掌侧移位）","手指活动受限、握力下降，可有皮下瘀斑","神经症状：正中神经受压致拇指与示指麻木（急性腕管综合征）","开放性骨折可见伤口与出血（Gustilo分型评估）"],"diagnosis":["腕关节X线（正位+侧位）：首选，评估骨折类型、移位、关节面台阶与桡骨高度/掌倾角/尺偏角","腕关节CT：关节内骨折、粉碎性骨折或术前规划（评估关节面塌陷）","神经功能评估：正中神经（拇指、示指、中指感觉与拇对掌）、尺神经、桡神经","血管评估：桡动脉搏动、末梢毛细血管充盈","血常规+凝血功能+心电图：术前评估（老年患者需评估心肺功能）","骨密度（DEXA）+血钙磷：老年患者骨质疏松评估与后续治疗","必要时MRI：疑舟骨骨折或韧带损伤而X线阴性者"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时，手术者）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（手法复位镇痛/血肿内麻醉）：","  用法：1%利多卡因 5～10ml 血肿内注射（复位前）；或 芬太尼 0.05mg + 咪达唑仑 2mg 静推（镇静镇痛，监护下）","","方案3（消肿）：","  用法：七叶皂苷钠 10mg + 0.9%氯化钠 250ml 静滴 qd（肿胀明显者）；20%甘露醇 125ml 静滴 q12h（严重肿胀）〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","方案4（术后镇痛/抗骨质疏松支持）：","  用法：氟比洛芬酯 50mg 静滴 q12h；葡萄糖酸钙 1g + 维生素C 2g 静滴 qd","","📌 复位后需复查X线确认位置；石膏/夹板固定松紧适宜（观察手指血运、肿胀与麻木）。"],"oral_medication":["⚠️ 按病情与术后用药，同类只选一种：","药物1（镇痛）：","用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（消肿）：","用法：地奥司明片 2片 bid 或 迈之灵 2片 bid；七叶皂苷钠片 1片 bid","药物3（抗骨质疏松，老年患者）：","用法：碳酸钙D3 600mg qd + 骨化三醇 0.25μg qd；阿仑膦酸钠 70mg 每周一次（空腹服后直立30分钟）","药物4（神经营养，有神经症状者）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid","📌 老年患者应同时启动骨质疏松治疗以防再骨折；神经症状持续者需评估腕管减压。"],"treatment":["无移位或稳定型骨折：石膏/夹板外固定4～6周（功能位或轻度屈腕尺偏位），定期复查X线（1周、2周、4周）","移位型骨折：闭合复位+外固定；复位后位置不稳定（再移位）者行手术","手术指征：关节面台阶>2mm、桡骨短缩>3mm、背侧成角>20°、粉碎性骨折、合并神经/血管损伤、开放性骨折、多发伤","手术方式：掌侧入路锁定钢板内固定（首选）；背侧粉碎或背侧移位明显者可用背侧钢板；外固定支架用于严重粉碎性骨折","康复训练：固定期间手指、肘、肩关节主动活动（防止僵硬与肩手综合征）；术后早期（1～2周）开始腕关节与手指功能训练","并发症处理：正中神经受压（评估腕管减压）、骨折畸形愈合（后期截骨矫形）、复杂区域性疼痛综合征（早期识别+镇痛+康复+交感神经阻滞）、肌腱断裂（钢板取出/肌腱修复）","抗骨质疏松治疗：老年患者规范治疗以防再骨折（骨折联络服务）"],"management":["复位与固定后观察：手指血运、肿胀、感觉与被动牵拉痛（警惕骨筋膜室综合征与石膏过紧）","抬高患肢：患肢高于心脏水平（肘上吊带/软枕），减轻肿胀","石膏/夹板护理：保持干燥、观察松紧与皮肤受压（桡骨茎突、尺骨小头处），肿胀消退后及时调整","疼痛管理：评估疼痛评分（突发剧痛伴被动牵拉痛提示骨筋膜室综合征，需立即报告）","功能锻炼指导：固定期间做手指屈伸、握拳、肩肘关节活动；术后遵医嘱逐步开始腕关节活动（避免过早负重）","神经功能监测：观察拇指与示指感觉、拇对掌功能（正中神经受压）","随访：复位后1周、2周、4周复查X线；术后2周、6周、3个月复查评估愈合与功能"],"notes":["复位后的位置维持是关键：1周内复查X线（肿胀消退后石膏变松易再移位）","老年患者桡骨远端骨折提示骨质疏松，应同时启动抗骨质疏松治疗以防再骨折","突发剧烈疼痛、手指被动牵拉痛、麻木（骨筋膜室综合征）是急症，需立即松解外固定并评估","复杂区域性疼痛综合征（CRPS）表现为持续性疼痛、肿胀、皮肤颜色与温度改变、活动受限，需早期识别与综合康复","康复训练应循序渐进，避免过早负重与暴力活动导致内固定失败"],"emergency":["手指剧痛、麻木、苍白、被动牵拉痛（骨筋膜室综合征）→ 立即松解石膏/夹板并急诊评估减压","开放性骨折伴活动性出血与污染 → 急诊清创、抗感染、手术固定","桡动脉搏动消失、手指发凉（血管损伤）→ 急诊血管评估与手术探查","骨折后突发拇指麻木加重伴对掌无力（急性腕管综合征）→ 评估减压指征"],"pinyin":"rgydgz","icd10":"S52.5","physical_exam":["生命体征：血压、心率、有无其他部位损伤（多发伤评估）","局部视诊：腕部畸形（餐叉样/反餐叉样）、肿胀、瘀斑、开放伤口","局部触诊：压痛部位（桡骨远端、舟骨、尺骨茎突）、骨擦感、鼻烟窝压痛（舟骨骨折）","神经检查：正中神经（拇指、示指、中指感觉，拇对掌）、尺神经（小指感觉）、桡神经（虎口区感觉）","血管检查：桡动脉搏动、毛细血管充盈时间、指端温度与颜色","手指活动：主动屈伸（肌腱功能）、被动牵拉痛（骨筋膜室综合征筛查）","其他：同侧肘肩关节活动（合并损伤）、对侧腕关节对比"],"lab_tests":["腕关节X线（正位+侧位）：诊断与分型，复位前后对比（1周、2周、4周复查）","腕关节CT：关节内粉碎性骨折、术前规划与关节面台阶评估","血常规+凝血功能+肝肾功能+心电图：术前评估（老年患者需心肺评估）","骨密度（DEXA）+血钙、磷、碱性磷酸酶+25-羟维生素D：骨质疏松评估与治疗依据","心肌酶+心脏超声（必要时）：老年患者术前心血管风险评估","腕关节MRI（必要时）：疑舟骨骨折、韧带损伤（X线阴性但临床高度怀疑）","血糖+糖化血红蛋白：糖尿病患者（影响愈合与感染风险）"],"nursing":["体位护理：患肢抬高（高于心脏水平），减轻肿胀；注意避免压迫与吊带过紧","外固定护理：观察石膏/夹板松紧、皮肤受压与渗液，保持干燥清洁，肿胀消退后及时报告调整","循环与神经观察：每小时观察手指颜色、温度、毛细血管充盈、桡动脉搏动与感觉运动（警惕骨筋膜室综合征）","疼痛护理：评估疼痛评分与性质，突发剧痛伴被动牵拉痛立即报告","功能锻炼指导：固定期间做手指屈伸、握拳与肩肘活动；术后遵医嘱逐步腕关节训练","健康宣教：石膏固定期间勿自行拆除、保持干燥；按时复查；老年患者加强防跌倒与抗骨质疏松宣教"],"diet":["高蛋白、高钙、高维生素饮食促进骨折愈合（牛奶、鱼虾、豆制品、绿叶蔬菜）","适量补充维生素D（晒太阳、蛋黄、深海鱼），必要时遵医嘱补充","多饮水、多食粗纤维食物，保持大便通畅（防便秘，尤其卧床老年患者）","控制体重与血糖（糖尿病影响骨折愈合与感染风险）","戒烟限酒（吸烟显著延缓骨折愈合）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1364},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"853ffe8b2d61ccfdaa0e311e3d1018dd5d86fd84207bf13cd52557758768ce71","pinyin":"raoguyuanduanguzhe","initials":"rgydgz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腕部疼痛、肿胀、压痛，活动受限\\n典型畸形：Colles骨折呈餐叉样畸形（远端向背侧移位）、Smith骨折呈反餐叉畸形（掌侧移位）\\n手指活动受限、握力下降，可有皮下瘀斑\\n神经症状：正中神经受压致拇指与示指麻木（急性腕管综合征）\\n开放性骨折可见伤口与出血（Gustilo分型评估）",60],["摘要","桡骨远端骨折是最常见的骨折之一（约占全身骨折1/6），多见于老年人跌倒手撑地（Colles骨折）与青年人高能量损伤。按AO/OTA与Frykman分型，治疗包括手法复位石膏/夹板外固定（无移位或稳定型）与手术内固定（掌侧锁定钢板，移位/不稳定型），康复重点是手指与腕关节功能训练、防僵硬与复杂区域性疼痛综合征。",30],["疾病编码","S52.5",30],["原首字母","rgydgz",60]]},{"id":"orders-b17b1de4db6e36eefaf0","key":"v1-c9ccc21dfe2a3058|orders-b17b1de4db6e36eefaf0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"胸腰椎骨折","category":"骨科","raw":{"name":"胸腰椎骨折","category":"骨科","summary":"胸腰椎骨折多由高能量损伤（坠落、车祸）或老年骨质疏松（低能量损伤）所致，按Denis三柱理论与AO分型（A压缩型、B牵张型、C旋转型）评估稳定性。稳定型可保守治疗（卧床+支具），不稳定型、合并神经损伤或椎体压缩>50%者需手术（椎弓根螺钉内固定/椎体成形术PVP/PKP）。","symptoms":["背部或腰部剧烈疼痛，活动受限，翻身困难，局部棘突压痛与叩击痛","脊柱后凸畸形（椎体压缩明显者），棘突间隙增宽（牵张损伤）","神经损伤表现：下肢麻木无力、感觉平面、大小便功能障碍（马尾神经/脊髓损伤）","腹膜后血肿可致腹胀、腹痛、肠麻痹（麻痹性肠梗阻）","老年骨质疏松性骨折：轻微外伤（弯腰、坐倒）后腰背痛，卧床减轻、起身加重"],"diagnosis":["脊柱X线（正位+侧位）：评估椎体压缩程度、后凸角度与序列（首选筛查）","脊柱CT（含三维重建）：明确骨折线、椎体后壁完整性、椎管占位与碎骨片（术前必备）","脊柱MRI：评估脊髓与神经受压、韧带损伤、骨髓水肿（新鲜骨折鉴别）与硬膜外血肿","神经功能评估（ASIA分级）：运动、感觉、反射与括约肌功能","骨密度（DEXA）+骨代谢指标：老年患者骨质疏松评估","胸腹部CT：评估合并肋骨骨折、血气胸、腹腔脏器损伤（高能量损伤需全面筛查）","全身评估：多发伤患者按ATLS原则系统评估"],"infusion":["⚠️ 按病情与围手术期需要选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（消肿/脱水，合并脊髓水肿）：","  用法：20%甘露醇 125ml 静滴 q8～12h（脊髓水肿，监测尿量与肾功能）；甲泼尼龙（伤后8小时内，遵医嘱，争议性）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（镇痛）：","  用法：氟比洛芬酯 50mg（NS 100ml）静滴 q12h 或 曲马多 100mg 静滴 必要时；剧烈疼痛可用吗啡 3～5mg 静推","","方案4（抗骨质疏松与钙剂，老年患者）：","  用法：葡萄糖酸钙 1g + 维生素C 2g 静滴 qd；骨化三醇 0.25μg qd 口服","","📌 搬运与翻身必须保持脊柱轴线一致（轴线翻身）；疑脊髓损伤者禁止坐起与站立，立即脊柱制动。"],"oral_medication":["⚠️ 按病情选择药物，同类只选一种：","药物1（镇痛）：","用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg 或 氨酚曲马多〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（抗骨质疏松，老年患者）：","用法：碳酸钙D3 600mg qd + 骨化三醇 0.25μg qd；阿仑膦酸钠 70mg 每周一次（或唑来膦酸 5mg 每年一次静滴）","药物3（通便，防腹胀与用力）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd；必要时开塞露〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（神经营养，神经损伤者）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid","📌 卧床期间需预防深静脉血栓（抗凝+气压治疗）、压疮（减压床垫+翻身）与肺部感染。"],"treatment":["稳定型骨折（A1/A2压缩型、无神经损伤）：保守治疗——卧硬板床6～8周（轴线翻身）+ 支具外固定（胸腰骶矫形器TLSO）3个月，逐步下床活动","不稳定型骨折（B/C型、三柱损伤）：手术治疗——后路椎弓根螺钉复位内固定±植骨融合；必要时前路重建","合并神经损伤：急诊评估，尽早手术减压+固定（不完全损伤者48～72小时内手术可能获益）","骨质疏松性椎体压缩骨折（无神经损伤）：保守治疗或微创（PVP/PKP椎体成形术，疼痛缓解快）","多发伤患者：遵循损伤控制原则，优先处理危及生命的损伤，脊柱骨折择期或限期手术","并发症防治：深静脉血栓（抗凝+间歇充气加压）、压疮（减压床垫、每2小时轴线翻身）、肺部感染（呼吸训练、拍背）、泌尿系感染（尿管管理）、便秘（通便药）","康复训练：卧床期做四肢主动活动与腰背肌等长收缩；稳定后逐步进行腰背肌功能锻炼（五点支撑、小燕飞）与步行训练"],"management":["脊柱制动与搬运：始终保持轴线一致（滚木式翻身），禁止坐起、站立与屈曲扭转（防神经损伤加重）","神经功能监测：每小时（伤后24～48小时）评估下肢感觉、肌力与大小便功能，记录ASIA分级变化","疼痛与腹部情况：观察腰背痛、腹胀与排便（腹膜后血肿致肠麻痹常见，需胃肠减压与通便）","皮肤护理：使用减压床垫、每2小时轴线翻身，检查骶尾部、足跟等骨突处（防压疮）","呼吸与泌尿护理：鼓励深呼吸与咳痰（防肺部感染）、会阴护理与尿管管理（防泌尿系感染）","支具使用指导：佩戴TLSO支具下床活动（3个月），指导正确佩戴与皮肤保护","康复计划：按骨折稳定程度与手术方式制定个体化康复（腰背肌锻炼、步行训练），避免早期负重与弯腰"],"notes":["搬运与翻身必须保持脊柱轴线一致（滚木式），错误搬运可致神经损伤加重甚至截瘫","骨折稳定性评估（三柱理论与AO分型）决定治疗方式：不稳定型需手术","合并神经损伤者应尽早评估手术减压时机（不完全损伤48～72小时内手术可能获益更多）","老年骨质疏松性骨折患者需同时启动抗骨质疏松治疗与防跌倒措施，预防再骨折","卧床期并发症（深静脉血栓、压疮、肺炎、泌尿系感染）是主要风险，需系统预防"],"emergency":["下肢感觉运动功能进行性恶化或大小便失禁（神经损伤加重）→ 立即脊柱制动并急诊MRI与手术评估","脊髓损伤伴神经源性休克（低血压、心动过缓）→ 立即监护、补液与血管活性药支持","多发伤伴血流动力学不稳定 → 按ATLS原则优先抢救致命损伤","腹胀剧烈伴呕吐、停止排气排便（麻痹性肠梗阻）→ 禁食减压+通便，警惕腹膜后血肿扩大"],"pinyin":"xygz","icd10":"S32.0","physical_exam":["生命体征：血压、心率、呼吸（多发伤与神经源性休克评估）","脊柱视诊：后凸畸形、棘突排列与间隙（增宽提示牵张损伤）、局部肿胀与瘀斑","脊柱触诊：棘突压痛与叩击痛、阶梯状畸形、肌肉痉挛","神经检查（ASIA分级）：下肢肌力（分度）、感觉平面、腱反射、病理反射、肛门括约肌张力与自主收缩","腹部：腹胀、压痛、肠鸣音（腹膜后血肿致肠麻痹）","合并伤：肋骨骨折、血气胸、腹腔脏器损伤、骨盆骨折、四肢骨折","皮肤：骶尾部与足跟受压部位（压疮风险评估）"],"lab_tests":["脊柱X线（正位+侧位）：椎体压缩程度、后凸角与脊柱序列","脊柱CT（三维重建）：骨折线、椎体后壁完整性与椎管占位（术前必备）","脊柱MRI：脊髓与神经受压、韧带损伤、骨髓水肿（新鲜骨折）与硬膜外血肿","血常规+凝血功能+血型+交叉配血：术前准备与出血评估","骨密度（DEXA）+血钙磷+25-羟维生素D+PTH：骨质疏松评估与治疗依据","胸腹部CT：多发伤评估（肋骨骨折、血气胸、肝脾破裂）","心肌酶+心电图（老年患者）：术前心血管评估"],"nursing":["轴线翻身：每2小时滚木式翻身（保持脊柱平直），翻身前后评估神经功能与疼痛","制动与体位：卧硬板床，禁止坐起与屈曲（保守治疗期），必要时使用脊柱支具","神经功能观察：每小时（伤后48小时内）评估下肢感觉、肌力与大小便，异常立即报告","皮肤与呼吸护理：减压床垫、骨突处保护；鼓励深呼吸与咳痰（预防压疮与肺部感染）","排泄护理：留置尿管者会阴护理每日2次；便秘者遵医嘱通便（避免用力排便）","康复指导：卧床期四肢主动活动与踝泵运动，稳定后逐步腰背肌锻炼（五点支撑、小燕飞）与步行训练"],"diet":["急性期：清淡易消化饮食（腹胀者暂禁食或流质），必要时胃肠减压","高蛋白、高钙、高维生素饮食促进骨折愈合（鱼虾、瘦肉、蛋奶、豆制品、绿叶蔬菜）","多饮水（每日2000ml以上）、多食粗纤维食物与水果，保持大便通畅（卧床易便秘）","补充维生素D与钙剂（骨质疏松患者）；必要时遵医嘱使用抗骨质疏松药物","戒烟限酒；控制体重；糖尿病者控制血糖（影响愈合）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1365},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"79f6172bf172cf352a0e45ae49592fee6fcec75624bd732b01cac82b293b820b","pinyin":"xiongyaozhuiguzhe","initials":"xyzgz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","背部或腰部剧烈疼痛，活动受限，翻身困难，局部棘突压痛与叩击痛\\n脊柱后凸畸形（椎体压缩明显者），棘突间隙增宽（牵张损伤）\\n神经损伤表现：下肢麻木无力、感觉平面、大小便功能障碍（马尾神经/脊髓损伤）\\n腹膜后血肿可致腹胀、腹痛、肠麻痹（麻痹性肠梗阻）\\n老年骨质疏松性骨折：轻微外伤（弯腰、坐倒）后腰背痛，卧床减轻、起身加重",60],["摘要","胸腰椎骨折多由高能量损伤（坠落、车祸）或老年骨质疏松（低能量损伤）所致，按Denis三柱理论与AO分型（A压缩型、B牵张型、C旋转型）评估稳定性。稳定型可保守治疗（卧床+支具），不稳定型、合并神经损伤或椎体压缩>50%者需手术（椎弓根螺钉内固定/椎体成形术PVP/PKP）。",30],["疾病编码","S32.0",30],["原首字母","xygz",60]]},{"id":"orders-52e440f2fdf348cab365","key":"v1-c9ccc21dfe2a3058|orders-52e440f2fdf348cab365","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"骨科围手术期静脉血栓栓塞预防","category":"骨科","raw":{"name":"骨科围手术期静脉血栓栓塞预防","category":"骨科","summary":"静脉血栓栓塞症（VTE）包括深静脉血栓（DVT）与肺栓塞（PE），是骨科大手术（髋膝关节置换、髋部骨折手术、脊柱手术、多发创伤）后的常见严重并发症。预防措施包括基本预防（早期活动、抬高患肢、补水）、物理预防（间歇充气加压装置IPC、梯度压力弹力袜）与药物预防（低分子肝素、利伐沙班、阿司匹林），需按风险分层选择。","symptoms":["DVT：患肢肿胀（周径差>3cm）、疼痛与压痛（腓肠肌）、皮温升高、浅静脉扩张、Homan征阳性","PE：突发呼吸困难、胸痛、咯血、心悸、晕厥，重者血压下降与休克（可猝死）","无症状DVT（约50%以上无典型症状，需依靠筛查）","预防措施相关并发症：出血（切口渗血、皮下瘀斑、消化道出血）、肝素诱导血小板减少（HIT）","慢性期：血栓后综合征（PTS）——患肢肿胀、色素沉着、溃疡"],"diagnosis":["风险评估：Caprini评分（手术类型、年龄、BMI、既往VTE史、肿瘤、制动等因素）；中高危需预防","D-二聚体：筛查（阴性预测价值高，阳性结合影像），术后本身可升高（特异性差）","下肢静脉彩色多普勒超声：DVT诊断首选（近端DVT敏感度高），术后常规筛查高危患者","CT肺动脉造影（CTPA）：疑PE时首选","血常规（血小板）+凝血功能：药物预防前后监测（警惕HIT与出血）","下肢周径测量：双侧对比（髌骨上/下10cm），差值>3cm提示DVT可能","心电图+血气分析+心肌酶：疑PE时评估（窦性心动过速、低氧血症）"],"infusion":["⚠️ 按风险分层与出血风险选择，切勿全部同时使用！","方案1（低分子肝素，最常用）：","用法：低分子肝素（依诺肝素）40mg（0.4ml）皮下注射 qd（术前12小时或术后12～24小时开始，按体重与肾功能调整）；或 那屈肝素 0.3ml 皮下注射 qd","方案2（磺达肝癸钠，HIT患者可用）：","用法：磺达肝癸钠 2.5mg 皮下注射 qd（肾功能不全者慎用）","方案3（普通肝素，肾功能不全或需快速逆转）：","用法：普通肝素 5000U 皮下注射 q8～12h（监测APTT与血小板）","方案4（PE抢救，疑PE且血流动力学不稳定）：","用法：普通肝素 80U/kg 静推后 18U/kg/h 泵入（或按体重调整）；组织型纤溶酶原激活剂（rt-PA）50～100mg 静滴（高危PE，需评估出血风险）；立即吸氧、监护与转ICU","📌 药物预防一般持续10～14天（髋部骨折与关节置换可延长至28～35天）；用药期间监测出血与血小板。"],"oral_medication":["⚠️ 口服抗凝预防与序贯用药，按医嘱选择：","药物1（利伐沙班，直接口服抗凝药）：","用法：利伐沙班 10mg qd（术后6～10小时开始，髋膝关节置换术后服14～35天，按医嘱）；或 阿哌沙班 2.5mg bid〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","药物2（阿司匹林，替代方案）：","用法：阿司匹林肠溶片 100mg qd（用于关节置换术后VTE预防的替代，需评估风险）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","药物3（镇痛与消肿）：","用法：塞来昔布 200mg qd（注意与抗凝药合用的出血风险）；地奥司明片 2片 bid〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物4（抗凝逆转，出血时）：","用法：维生素K1 10mg 静推（华法林出血）；鱼精蛋白（普通肝素）；依达赛珠单抗（达比加群）；Andexanet alfa（Xa抑制剂，如可用）〔调 ★ 需监测INR；★ 大量药物食物相互作用；妊娠禁用〕","📌 抗凝药物与NSAIDs、抗血小板药合用时出血风险增加；椎管内麻醉前需按药物特性停药（依诺肝素术前12小时、利伐沙班术前24小时）。"],"treatment":["风险分层与方案选择：Caprini评分≥3分或骨科大手术患者应接受药物+物理联合预防；高出血风险者先用物理预防，出血风险降低后加药物","药物预防：低分子肝素（依诺肝素 40mg 皮下注射 qd，术前12小时或术后12～24小时开始）、利伐沙班 10mg 口服 qd（术后6～10小时）、磺达肝癸钠 2.5mg 皮下注射 qd；疗程10～14天，髋部手术延长至28～35天","物理预防：间歇充气加压装置（IPC）每日≥18小时、梯度压力弹力袜（GCS）；早期活动与踝泵运动","机械取栓/滤器：抗凝禁忌或抗凝期间仍发生PE者置入下腔静脉滤器（临时/永久）","DVT治疗：确诊后抗凝治疗（低分子肝素 依诺肝素 1mg/kg 皮下注射 q12h 或利伐沙班 15mg 口服 bid×21天后续20mg qd，疗程3～6个月）；近端DVT或有症状者考虑导管溶栓或取栓","PE治疗：血流动力学稳定者抗凝；不稳定者溶栓（rt-PA 50-100mg 静滴2h）或介入/手术取栓，转ICU监护","出血并发症处理：停用抗凝药、局部压迫、必要时拮抗剂（维生素K₁ 10mg 静推、鱼精蛋白 1mg 中和 100U 肝素、依达赛珠单抗 5g 静推），严重者输注血制品"],"management":["风险评估与记录：入院24小时内完成Caprini评分并记录，据此选择预防方案","物理预防执行：IPC装置每日使用≥18小时（除下地活动与护理时间），弹力袜正确穿戴（观察皮肤与末梢血运）","药物预防管理：按时给药（严格按术前术后时间点），观察注射部位（腹壁皮下，避免按摩）与出血征象","出血监测：切口渗血、引流液量增多、皮下瘀斑、牙龈出血、黑便、血尿；监测血红蛋白与血小板（警惕HIT）","早期活动：术后第1天床上踝泵运动与主动活动，鼓励早期下床（物理预防与早期活动的联合效果最佳）","症状监测：每日测量双下肢周径并对比、询问小腿疼痛与压痛；出现突发呼吸困难胸痛立即报告（PE）","出院指导：继续口服抗凝（按医嘱）、避免久坐久站与脱水、识别DVT/PE症状并及时就诊、定期复查"],"notes":["骨科大手术后VTE风险高（髋膝关节置换未预防时DVT发生率可达40%～60%），规范预防可显著降低风险","药物预防与椎管内麻醉需注意时间间隔（依诺肝素术前12小时、利伐沙班术前24小时停药），否则增加椎管内血肿风险","约50%以上DVT无症状，高危患者应常规行下肢静脉超声筛查","突发呼吸困难、胸痛、血氧下降需高度警惕肺栓塞（可猝死），应立即处理","抗凝期间监测血小板（警惕肝素诱导血小板减少HIT）与出血征象；肾功能不全者调整低分子肝素剂量"],"emergency":["突发呼吸困难、胸痛、低氧血症或血压下降（肺栓塞）→ 立即吸氧、监护、抗凝或溶栓，转ICU","术后切口大量渗血、引流增多伴血压下降（抗凝致出血）→ 停抗凝、压迫止血、必要时拮抗与输血","下肢肿胀迅速加重伴剧痛、皮肤发绀（股青肿/股白肿，大量血栓）→ 急诊评估取栓或溶栓","血小板进行性下降伴血栓形成（HIT）→ 立即停用肝素，改用磺达肝癸钠或非肝素抗凝"],"pinyin":"gkwssqjmtmsyf","icd10":"Z79.0","physical_exam":["生命体征：体温、心率、呼吸、血压、血氧（PE筛查）","下肢周径测量：双侧髌骨上/下10cm对比（差值>3cm提示DVT）","下肢检查：肿胀、皮温升高、浅静脉扩张、压痛部位（腓肠肌、股三角）、Homan征","末梢循环：足背动脉搏动、毛细血管充盈、皮肤颜色与温度","切口与引流：渗血量、引流量与性状（抗凝致出血）","出血征象：皮下瘀斑、牙龈与鼻腔出血、黑便、血尿、注射部位血肿","心肺：呼吸音、心率与心律（PE）、颈静脉（右心负荷）"],"lab_tests":["血常规+血小板（每2～3天，警惕HIT）+凝血功能（PT、APTT、INR）","D-二聚体：VTE筛查（阴性预测价值高，术后本身可升高）","下肢静脉彩色多普勒超声：高危患者常规筛查及疑DVT时（首选）","CT肺动脉造影（CTPA）：疑PE时首选；通气/灌注扫描（肾功能不全或造影剂过敏）","肾功能（肌酐、肌酐清除率）+电解质：低分子肝素与利伐沙班剂量调整依据","血气分析+心电图+心肌酶+BNP：疑PE时评估（低氧、窦速、右心负荷）","抗Xa因子活性（必要时）：肥胖、肾功能不全或体重异常者监测抗凝强度"],"nursing":["物理预防护理：IPC装置每日使用≥18小时（护理与下地时暂停），弹力袜正确穿戴并观察末梢血运与皮肤","药物预防护理：严格按时间点给药（皮下注射腹壁，注射后不按摩），观察注射部位有无血肿与出血","出血观察：切口渗血、引流液量、皮下瘀斑、牙龈与鼻腔出血、黑便血尿，异常立即报告","早期活动指导：术后第1天指导床上踝泵运动（每小时10～20次）与股四头肌等长收缩，鼓励早期下床","周径测量与症状观察：每日测量双下肢周径并记录，询问小腿疼痛与压痛；突发胸痛气促立即报告","健康教育：告知抗凝治疗重要性（不可漏服停药）、避免久坐久站与脱水、出现DVT/PE症状立即就诊"],"diet":["充足饮水（每日1500～2000ml），避免脱水（血液黏稠度增加促进血栓形成）","清淡低脂饮食，控制体重（肥胖是VTE危险因素）","多食蔬菜水果与粗纤维，保持大便通畅（避免用力排便致血栓脱落）","服用华法林者需稳定摄入维生素K（避免大量绿叶蔬菜骤增骤减），并定期监测INR","戒烟限酒；糖尿病患者控制血糖（高血糖增加血栓风险）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1366},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0e3c78d53c4e6e40ffe7be4156a916cd67c199e1a98cd4dc44933de3b15e1386","pinyin":"gukeweishoushuqijingmaixueshuanshuanseyufang","initials":"gkwssqjmxsssyf","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","DVT：患肢肿胀（周径差>3cm）、疼痛与压痛（腓肠肌）、皮温升高、浅静脉扩张、Homan征阳性\\nPE：突发呼吸困难、胸痛、咯血、心悸、晕厥，重者血压下降与休克（可猝死）\\n无症状DVT（约50%以上无典型症状，需依靠筛查）\\n预防措施相关并发症：出血（切口渗血、皮下瘀斑、消化道出血）、肝素诱导血小板减少（HIT）\\n慢性期：血栓后综合征（PTS）——患肢肿胀、色素沉着、溃疡",60],["摘要","静脉血栓栓塞症（VTE）包括深静脉血栓（DVT）与肺栓塞（PE），是骨科大手术（髋膝关节置换、髋部骨折手术、脊柱手术、多发创伤）后的常见严重并发症。预防措施包括基本预防（早期活动、抬高患肢、补水）、物理预防（间歇充气加压装置IPC、梯度压力弹力袜）与药物预防（低分子肝素、利伐沙班、阿司匹林），需按风险分层选择。",30],["疾病编码","Z79.0",30],["原首字母","gkwssqjmtmsyf",60]]},{"id":"orders-47a6e5db6151a77220fb","key":"v1-c9ccc21dfe2a3058|orders-47a6e5db6151a77220fb","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"脑室外引流术后管理","category":"神经外科","raw":{"name":"脑室外引流术后管理","category":"神经外科","summary":"脑室外引流（EVD）用于急性脑积水、脑室内出血、颅内压增高与颅内感染的治疗与监测。术后管理核心是严格无菌操作、控制引流高度与速度（防过度引流致颅内出血/气颅）、监测引流量与性状（感染预警）、以及及时评估拔管指征。感染（脑室炎）是最严重并发症。","symptoms":["术后早期：头痛、恶心呕吐（颅内压变化）、意识状态波动","过度引流：头痛加重（低颅压）、恶心、心率增快、气颅（意识障碍加重）、硬膜下/脑室内出血","引流不畅：头痛加剧、意识恶化、颅内压升高（引流管堵塞、受压或位置不当）","颅内感染（脑室炎）：发热（常>38.5℃）、颈项强直、意识恶化、脑脊液浑浊（三联征），可致脓毒症","拔管后：脑积水复发（头痛、呕吐、意识下降）、切口脑脊液漏"],"diagnosis":["意识与瞳孔监测：GCS评分每1～2小时（意识恶化是最早的颅内压增高信号）","引流量与性状：每小时记录（正常<20ml/h，24小时<300～400ml），正常脑脊液清亮无色","颅内压监测（如有）：维持ICP<20mmHg、脑灌注压CPP 60～70mmHg","脑脊液检查（每周2次或疑感染时）：细胞数、蛋白、葡萄糖、氯化物、涂片与培养（脑室炎诊断关键）","头颅CT：术后常规复查及意识恶化时（评估脑室大小、出血、气颅、引流管位置）","血常规+CRP+PCT+血培养：疑感染时","引流管位置确认：CT评估管端位于侧脑室额角（理想位置）"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","","方案1（预防/治疗颅内感染，脑室炎时静脉+鞘内/脑室内给药）：","  用法：静脉——美罗培南 2g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 头孢曲松 2g 静滴 q12h + 万古霉素 1g 静滴 q12h（监测血药浓度）；脑室内给药（神经外科/感染科指导）——万古霉素 10～20mg 脑室内注射 qd、阿米卡星 5～10mg 脑室内注射 qd〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案2（降颅压）：","  用法：20%甘露醇 125ml 静滴 q6～8h（监测尿量、肾功能与电解质）；或 3%氯化钠 100～150ml 静滴（低钠时慎用）〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","方案3（止血与营养神经）：","  用法：氨甲环酸 0.5g（NS 100ml 或 5%GS 100ml）静滴 q8h（术后出血风险者）；甲钴胺 0.5mg 静滴 qd；维生素C 2g 静滴 qd〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案4（抗癫痫，脑出血/开颅术后）：","  用法：丙戊酸钠 400mg（NS 100ml 或 5%GS 100ml）静滴 q12h（或左乙拉西坦 500mg 静滴 q12h）；监测血药浓度与肝功能〔调 ★ 必须按 CrCl 减量；老年减量〕","","📌 脑室内给药需严格无菌并控制剂量（避免化学性脑室炎）；甘露醇需监测肾功能与电解质。"],"oral_medication":["⚠️ 恢复期用药，按医嘱选择：","药物1（抗癫痫，预防/治疗）：","用法：左乙拉西坦 500mg bid 或 丙戊酸钠缓释片 500mg bid（监测血药浓度）；疗程按病因决定〔调 ★ 必须按 CrCl 减量；老年减量〕","药物2（营养神经）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid + 胞磷胆碱 0.2g tid","药物3（通便，防用力致颅压升高）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（抗感染序贯，脑室炎恢复期）：","用法：按药敏选择口服抗生素（如利奈唑胺 0.6g bid、复方磺胺甲噁唑），疗程需足（4～6周）","📌 恢复期避免用力排便、剧烈咳嗽与情绪激动（颅压波动）；遵医嘱逐步减停抗癫痫药（不可骤停）。"],"treatment":["引流高度与速度控制：引流管最高点（滴管）置于外耳道上方10～15cm（按医嘱个体化），维持引流量<20ml/h，避免过度引流致颅内出血与气颅","严格无菌管理：三通接口与穿刺点每日消毒换药（无菌敷料），操作时严格无菌（戴无菌手套），减少不必要的管路操作","引流管护理：妥善固定（防止牵拉脱出与移位）、保持通畅（避免受压、扭曲），搬动与转运时夹闭管路","脑脊液监测：每周2次或疑感染时送检（细胞数、生化、涂片与培养），脑室炎时静脉+脑室内联合抗感染","拔管评估：引流3～7天后尝试夹管/抬高引流管（观察颅内压与意识），CT示脑室缩小、无颅内压增高即可拔管（一般留置<7～10天）","拔管后管理：观察意识、头痛、呕吐与切口有无脑脊液漏；脑积水复发者行脑室腹腔分流（VPS）或腰大池引流","并发症处理：脑室炎（抗感染+必要时拔管重置）、出血（CT评估+调整引流）、堵管（冲洗或重置，需无菌操作）、气颅（控制引流高度）","颅压管理：抬高床头15～30°、镇痛镇静、避免躁动与呛咳、必要时脱水剂与过度通气（短期）"],"management":["每小时记录引流量与性状：量（<20ml/h）、颜色（清亮/血性/浑浊）、有无凝块；异常立即报告","意识与瞳孔监测：每1～2小时评估GCS与瞳孔（意识下降、瞳孔不等大提示颅内压增高或脑疝，需紧急处理）","感染预防：严格无菌操作、穿刺点每日换药、减少开放次数；监测体温（每4小时）与脑脊液性状","体位管理：床头抬高15～30°，保持头颈中立位（避免颈静脉受压影响回流），翻身时固定头部","引流管安全：妥善固定、留有余量、防止牵拉脱出与意外拔出；患者躁动者必要时约束或镇静","出入量与电解质：记录24小时出入量，监测血钠（低钠血症常见，警惕脑耗盐综合征与SIADH）","拔管与随访：按医嘱夹管试验并配合CT评估，拔管后观察切口与意识变化，做好分流手术准备与宣教"],"notes":["脑室外引流最严重的并发症是颅内感染（脑室炎，发生率5%～15%），严格无菌与尽早拔管是关键（留置一般不超过7～10天）","引流高度与速度不当可致过度引流（低颅压、气颅、硬膜下/脑室内出血）或引流不足（颅内压增高），需严格按医嘱调节","意识状态恶化是最早、最重要的颅内压增高信号，护理观察中必须优先关注","脑脊液浑浊、发热、颈项强直提示脑室炎，需立即送检并与医师沟通（抗感染+可能拔管）","搬动、转运与护理操作时需夹闭引流管，防止脑脊液逆流与过度引流"],"emergency":["意识迅速恶化、瞳孔不等大、血压升高伴心率减慢（Cushing反应，脑疝）→ 立即报告并紧急降颅压（脱水剂+过度通气+急诊CT）","引流管脱出 → 立即用无菌敷料覆盖穿刺点、平卧、报告医师（禁止自行回插）","高热>38.5℃伴脑脊液浑浊、颈项强直（脑室炎）→ 立即送检脑脊液+经验性抗感染","引流量突然增多且颜色鲜红（颅内出血）→ 立即降低引流高度、复查CT并报告医师"],"pinyin":"nswsylshgl","icd10":"Z98.2","physical_exam":["意识与瞳孔：GCS评分（每小时）、瞳孔大小与对光反射（脑疝筛查）","生命体征：血压、心率、呼吸（Cushing反应：血压升高、心率减慢、呼吸不规则）、体温（感染）","引流管：位置与高度（外耳道上方厘米数）、通畅度、引流量与性状、穿刺点有无渗液与红肿","神经系统：肢体肌力、感觉、病理反射、脑膜刺激征（颈项强直、Kernig征）","头部切口：敷料是否干燥、有无脑脊液漏与渗血","出入量与电解质：尿量、24小时出入量、有无低钠血症表现（乏力、意识改变、抽搐）","皮肤与体位：枕部与骶尾部压疮风险、头颈位置（是否中立位）"],"lab_tests":["脑脊液检查（每周2次及疑感染时）：细胞数（白细胞）、蛋白、葡萄糖、氯化物、涂片革兰染色与培养、必要时PCR","血常规+CRP+PCT+血培养：感染评估（脑室炎可致脓毒症）","电解质（尤其血钠）+肾功能+血气分析：低钠血症（脑耗盐/SIADH）、甘露醇致肾损害监测","凝血功能+血小板：术后出血风险评估","头颅CT：术后常规及意识变化时（脑室大小、出血、气颅、管端位置）","肝功能+血药浓度（丙戊酸钠、万古霉素）：抗癫痫与抗感染药物监测","颅内压监测（如有）：ICP与脑灌注压（CPP=MAP-ICP）"],"nursing":["无菌操作：穿刺点每日换药（无菌敷料）、接头消毒、开放管路时戴无菌手套并尽量减少操作次数","引流量监测：每小时记录引流量与颜色，维持<20ml/h；发现浑浊、血性或量骤增立即报告","意识与瞳孔观察：每小时评估GCS与瞳孔并记录，意识下降或瞳孔异常立即报告","管路安全：妥善固定并留有余量、防止牵拉与意外拔出；转运与搬动时夹闭管路","体位护理：床头抬高15～30°，头颈中立位；每2小时轴线翻身并固定头部，注意压疮预防","感染监测与宣教：每4小时测体温、记录脑膜刺激征；向家属解释限制探视、无菌操作与尽早拔管的重要性"],"diet":["术后早期：禁食或流质（视意识与吞咽功能），必要时鼻饲或静脉营养","意识清醒、吞咽功能正常者：高蛋白、高热量、高维生素易消化饮食促进恢复","限制水分者按医嘱（颅内压增高与低钠血症患者需控制液体入量）","多食蔬菜水果与粗纤维，保持大便通畅（避免用力排便致颅压升高）；必要时用缓泻剂","吞咽障碍者行吞咽评估与康复训练，防误吸；鼻饲者注意营养液温度、速度与体位（床头抬高30～45°）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1367},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f1df9c725e389999545fcabc25c007eee911068a4fd81f6736fd1ec7b5ee7855","pinyin":"naoshiwaiyinliushuhouguanli","initials":"nswylshgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术后早期：头痛、恶心呕吐（颅内压变化）、意识状态波动\\n过度引流：头痛加重（低颅压）、恶心、心率增快、气颅（意识障碍加重）、硬膜下/脑室内出血\\n引流不畅：头痛加剧、意识恶化、颅内压升高（引流管堵塞、受压或位置不当）\\n颅内感染（脑室炎）：发热（常>38.5℃）、颈项强直、意识恶化、脑脊液浑浊（三联征），可致脓毒症\\n拔管后：脑积水复发（头痛、呕吐、意识下降）、切口脑脊液漏",60],["摘要","脑室外引流（EVD）用于急性脑积水、脑室内出血、颅内压增高与颅内感染的治疗与监测。术后管理核心是严格无菌操作、控制引流高度与速度（防过度引流致颅内出血/气颅）、监测引流量与性状（感染预警）、以及及时评估拔管指征。感染（脑室炎）是最严重并发症。",30],["疾病编码","Z98.2",30],["原首字母","nswsylshgl",60]]},{"id":"orders-be36b37c9a7ad1efd1ab","key":"v1-c9ccc21dfe2a3058|orders-be36b37c9a7ad1efd1ab","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化疗相关性腹泻与便秘","category":"化疗","raw":{"name":"化疗相关性腹泻与便秘","category":"化疗","summary":"化疗相关性腹泻（CID）常见于伊立替康、氟尿嘧啶类、卡培他滨、靶向药（EGFR-TKI）方案，可致脱水、电解质紊乱与粒细胞缺乏期感染；化疗相关性便秘多由止吐药（5-HT3拮抗剂）、阿片类镇痛药、长春碱类神经毒性及活动减少所致。管理原则是分级处理、补液、调整饮食与药物。","symptoms":["腹泻：排便次数增多（>3次/日）、稀便或水样便、腹痛与肠鸣音亢进、里急后重（直肠受累）","重度腹泻：>7次/日、血性腹泻、脱水（口渴、皮肤弹性差、少尿）、电解质紊乱（低钾、低钠）、循环衰竭","伊立替康急性胆碱能综合征：输注中或24小时内腹痛、大汗、流涎、水样泻（阿托品可缓解）","便秘：排便次数减少（<3次/周）、排便困难、腹胀腹痛、食欲减退，严重者可致肠梗阻","并发症：中性粒细胞缺乏期腹泻可致脓毒症；便秘可致粪石性肠梗阻与痔出血"],"diagnosis":["腹泻分级（CTCAE）：1级（次数增加<4次/日）、2级（4～6次/日）、3级（≥7次/日或需住院）、4级（危及生命）","电解质+肾功能+血气分析：评估脱水、低钾低钠与酸中毒","血常规+CRP+PCT：中性粒细胞计数（感染风险）与炎症评估","粪便常规+隐血+培养+艰难梭菌毒素：排除感染性腹泻（尤其抗生素使用后）","腹部平片/CT：便秘致肠梗阻、肠穿孔评估（剧烈腹痛时）","评估药物因素：伊立替康（急性胆碱能综合征/延迟性腹泻）、5-HT3拮抗剂与阿片类（便秘）","甲状腺功能：排除甲亢致腹泻"],"infusion":["⚠️ 按腹泻分级与类型选择方案，切勿全部同时使用！","方案1（补液与电解质，2级以上腹泻）：","用法：0.9%氯化钠 1000ml + 10%氯化钾 10～20ml 静滴（按血钾调整）；平衡盐溶液 500～1000ml 静滴（按脱水程度）；必要时补镁","方案2（伊立替康急性胆碱能综合征）：","用法：阿托品 0.25～0.5mg 皮下注射（输注中或24小时内出现症状时，必要时重复）","方案3（严重腹泻/氟尿嘧啶类致腹泻）：","用法：奥曲肽 0.1mg 皮下注射 q8h（3级以上腹泻或洛哌丁胺无效时）；生长抑素 3mg/12h 泵入（必要时）〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","方案4（保护肠黏膜与营养支持）：","用法：0.9%氯化钠 静滴维持；全肠外营养（禁食者）；谷氨酰胺 20g 静滴 qd（肠黏膜修复，遵医嘱）","📌 3～4级腹泻须暂停化疗、禁食、补液并考虑奥曲肽；中性粒细胞缺乏期腹泻需警惕脓毒症（经验性抗生素）。"],"oral_medication":["⚠️ 按症状选择药物，同类只选一种（腹泻与便秘不可同时使用）！","药物1（止泻，伊立替康延迟性腹泻首选）：","用法：洛哌丁胺 4mg 首剂，随后 2mg q2h 直至腹泻停止12小时（每日不超过16mg）；或 蒙脱石散 3g tid〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物2（止泻辅助）：","用法：双歧杆菌三联活菌 2粒 bid（调节菌群）；消旋卡多曲 100mg tid（必要时）","药物3（便秘）：","用法：乳果糖 15～30ml bid 或 聚乙二醇4000散 1袋 qd～bid；必要时开塞露 20ml 纳肛（短期）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（促动力，便秘伴腹胀）：","用法：莫沙必利 5mg tid（餐前）；必要时甲氧氯普胺 10mg tid〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","📌 伊立替康后腹泻禁用阿托品以外的止泻药过量（阿托品仅用于急性胆碱能症状）；便秘者避免长期使用刺激性泻药。"],"treatment":["1级腹泻：观察、饮食调整（低渣低脂）、口服补液（口服补液盐），可继续化疗","2级腹泻：口服洛哌丁胺+补液，监测电解质；腹泻持续>24～48小时或伴脱水者暂停化疗","3～4级腹泻：停用化疗、禁食、静脉补液纠正电解质、奥曲肽（0.1mg 皮下 q8h），评估住院；中性粒细胞缺乏者加用广谱抗生素","伊立替康急性胆碱能综合征：阿托品 0.25～0.5mg 皮下注射，下次化疗前预防性使用阿托品","便秘处理：乳果糖/聚乙二醇（渗透性泻药首选）、增加水分与活动、必要时开塞露；阿片类所致便秘需预防性使用泻药","止吐药相关便秘：调整止吐方案（换用二线药物）、增加通便药","营养支持：腹泻期低渣低脂饮食，必要时肠内/肠外营养；便秘期增加膳食纤维与水分","疗效与安全性评估：腹泻控制后评估是否减量（伊立替康与氟尿嘧啶类按毒性分级减量20%～25%）"],"management":["排便记录：指导患者记录每日排便次数、性状（布里斯托大便分类）、伴随症状与用药，复诊时提供","脱水监测：观察口渴、皮肤弹性、黏膜干燥、尿量与尿色（记录24小时出入量），遵医嘱补液","电解质监测：2级以上腹泻每1～2天复查血钾、钠、镁、氯与肾功能","用药指导：洛哌丁胺按时（q2h）服用并观察疗效（腹泻停止12小时后停药）；便秘者渗透性泻药优先","饮食管理：腹泻期低渣低脂、少量多餐、避免乳制品与生冷；便秘期增加纤维与水分","感染防护：中性粒细胞缺乏期腹泻需监测体温、便常规与培养（排除艰难梭菌感染），必要时隔离","随访与宣教：告知出现血性腹泻、发热、意识改变须立即就诊；化疗后腹泻多在48小时内出现，需提前备药"],"notes":["伊立替康腹泻分两型：急性胆碱能综合征（24小时内，阿托品有效）与延迟性腹泻（24小时后，洛哌丁胺+补液），处理不同","洛哌丁胺用于化疗相关性腹泻需大剂量规律给药（首剂4mg后2mg q2h），并监测肠梗阻与中毒性巨结肠风险","中性粒细胞缺乏期出现腹泻+发热提示脓毒症风险，须立即经验性抗生素并留取培养","便秘多由5-HT3拮抗剂与阿片类药物引起，应从化疗开始即预防性使用渗透性泻药","腹泻控制后下周期化疗应按毒性分级减量（20%～25%），避免严重腹泻复发"],"emergency":["腹泻≥7次/日伴脱水、低血压、少尿（3级以上）→ 立即静脉补液纠正电解质，暂停化疗","血性腹泻伴剧烈腹痛、腹膜刺激征（中毒性巨结肠/肠穿孔）→ 急诊CT与外科评估","发热伴中性粒细胞缺乏（腹泻患者FN）→ 1小时内经验性广谱抗生素","腹胀剧痛伴停止排气排便（粪石性肠梗阻）→ 禁食减压+补液，必要时灌肠或手术"],"pinyin":"hlxgxfyxbm","icd10":"K52.9","physical_exam":["生命体征：体温（感染）、血压（脱水/低血压）、心率（增快）、体重变化","一般情况：脱水征（皮肤弹性、口唇干燥、眼窝凹陷）、精神萎靡、营养状态","腹部：压痛部位、腹胀、肠鸣音（腹泻时亢进，便秘或肠梗阻时减弱）、有无腹膜炎体征","肛周：皮肤刺激与糜烂（频繁腹泻）、痔疮与肛裂（便秘）","直肠指检（便秘）：粪块嵌塞、直肠肿物（避免中性粒细胞缺乏期）","神经与循环：意识（电解质紊乱）、末梢循环与毛细血管充盈","体重与出入量：每日体重（脱水敏感指标）、24小时出入量与尿量"],"lab_tests":["电解质（钾、钠、氯、镁、钙）+肾功能：腹泻致脱水与电解质紊乱，每1～2天复查","血常规（含中性粒细胞）：中性粒细胞缺乏期腹泻感染风险，化疗后每2～3天","CRP+PCT：感染与炎症评估；发热者血培养","粪便常规+隐血+细菌培养+艰难梭菌毒素A/B：排除感染性腹泻与抗生素相关性肠炎","血气分析+乳酸：重度腹泻致代谢性酸中毒与灌注不足评估","腹部平片/CT：便秘致肠梗阻、肠穿孔评估（剧烈腹痛与腹胀时）","白蛋白+前白蛋白：营养状态评估（指导营养支持）"],"nursing":["排便观察与记录：每次排便后记录次数、量、性状（布里斯托分类）与伴随症状，按CTCAE分级报告","补液与电解质：遵医嘱静脉补液，记录出入量与尿量；观察脱水征与电解质紊乱表现（乏力、心悸、意识改变）","肛周皮肤护理：每次排便后温水清洁、涂氧化锌软膏保护；腹泻频繁者使用无刺激湿巾，避免用力擦拭","用药护理：洛哌丁胺按时给药并观察疗效与不良反应（腹胀、便秘、肠梗阻）；便秘者用渗透性泻药并观察排便","饮食护理：腹泻期低渣低脂饮食、少量多餐、避免乳制品与生冷；便秘期增加水分与膳食纤维","感染防护：中性粒细胞缺乏期监测体温、实施保护性隔离与手卫生，观察腹泻性状（血性、黏液样需报告）"],"diet":["腹泻期：低渣、低脂、易消化饮食（白粥、面条、蒸蛋），少量多餐；避免乳制品、生冷、油腻、高纤维与含咖啡因饮料","腹泻期补液：口服补液盐或淡盐水，少量多次（每次50～100ml）","便秘期：增加水分（每日2000ml以上）与膳食纤维（蔬菜、水果、粗粮），适量运动","便秘期避免产气食物（豆类、碳酸饮料）与辛辣刺激；必要时晨起空腹温水或蜂蜜水促进排便","恢复期逐步恢复正常饮食，注意补充蛋白质（鱼、瘦肉、蛋）与维生素，必要时口服营养补充剂"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1368},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"cb626fdfa66f451f3933edaab8f6d877af6eaa3d28727c6644b08348bdd78d21","pinyin":"hualiaoxiangguanxingfuxieyubianmi","initials":"hlxgxfxybm","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹泻：排便次数增多（>3次/日）、稀便或水样便、腹痛与肠鸣音亢进、里急后重（直肠受累）\\n重度腹泻：>7次/日、血性腹泻、脱水（口渴、皮肤弹性差、少尿）、电解质紊乱（低钾、低钠）、循环衰竭\\n伊立替康急性胆碱能综合征：输注中或24小时内腹痛、大汗、流涎、水样泻（阿托品可缓解）\\n便秘：排便次数减少（<3次/周）、排便困难、腹胀腹痛、食欲减退，严重者可致肠梗阻\\n并发症：中性粒细胞缺乏期腹泻可致脓毒症；便秘可致粪石性肠梗阻与痔出血",60],["摘要","化疗相关性腹泻（CID）常见于伊立替康、氟尿嘧啶类、卡培他滨、靶向药（EGFR-TKI）方案，可致脱水、电解质紊乱与粒细胞缺乏期感染；化疗相关性便秘多由止吐药（5-HT3拮抗剂）、阿片类镇痛药、长春碱类神经毒性及活动减少所致。管理原则是分级处理、补液、调整饮食与药物。",30],["疾病编码","K52.9",30],["原首字母","hlxgxfyxbm",60]]},{"id":"orders-b4bcfc5ff7ea0120770b","key":"v1-c9ccc21dfe2a3058|orders-b4bcfc5ff7ea0120770b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化疗相关性口腔黏膜炎","category":"化疗","raw":{"name":"化疗相关性口腔黏膜炎","category":"化疗","summary":"化疗相关性口腔黏膜炎是化疗（尤其氟尿嘧啶类、大剂量甲氨蝶呤、蒽环类）与放疗（头颈部）常见毒性，多在化疗后5～14天出现，表现为口腔黏膜红斑、溃疡与疼痛，影响进食并增加感染风险。防治以口腔护理、局部对症与营养支持为主，严重者需减量或暂停化疗。","symptoms":["口腔黏膜红斑、水肿（1级）、孤立小溃疡（2级）、融合溃疡伴疼痛影响进食（3级）、溃疡伴出血坏死与无法进食（4级）","进食、吞咽疼痛，味觉改变（金属味），口干","流涎、口臭，溃疡表面有白色假膜（需与真菌感染鉴别）","继发感染：单纯疱疹（口唇疱疹）、念珠菌（鹅口疮，白色斑块可擦除）、细菌感染","严重者因疼痛拒绝进食致脱水、营养不良与体重下降"],"diagnosis":["口腔黏膜评估：每日检查黏膜部位（颊、舌、口底、软硬腭、咽部），按WHO/CTCAE分级记录","疼痛评分（NRS）：评估对进食、吞咽与言语功能的影响","口腔拭子/分泌物培养+真菌涂片：疑感染时（念珠菌、单纯疱疹病毒PCR）","血常规（含中性粒细胞）：中性粒细胞缺乏期黏膜炎易继发感染并致菌血症，需每日或隔日监测","电解质+白蛋白+体重：评估脱水与营养状态","鉴别诊断：口腔真菌感染、疱疹性口炎、药物性口腔炎、肿瘤浸润","评估化疗药物与剂量：大剂量MTX需监测血药浓度（亚叶酸钙解救不足加重黏膜炎）"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","","方案1（补液与营养支持，3～4级黏膜炎）：","  用法：0.9%氯化钠/葡萄糖 静滴补液（按进食减少量补充）；全肠外营养（无法进食者）；必要时白蛋白 10g 静滴","","方案2（抗感染，中性粒细胞缺乏伴黏膜炎）：","  用法：哌拉西林他唑巴坦 4.5g（NS 100ml 或 5%GS 100ml）静滴 q8h（或美罗培南 1g q8h）+ 万古霉素 1g 静滴 q12h（疑MRSA/口腔链球菌）〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案3（抗真菌/抗病毒）：","  用法：氟康唑 200mg 静滴 qd（念珠菌）；阿昔洛韦 5mg/kg 静滴 q8h（单纯疱疹病毒感染）","","方案4（黏膜保护与镇痛）：","  用法：0.9%氯化钠 静滴；谷氨酰胺 20g 静滴 qd（肠黏膜与口腔黏膜修复，遵医嘱）；必要时间断静脉镇痛","","📌 3级以上黏膜炎应暂停化疗并加强营养支持；大剂量MTX致黏膜炎需加强亚叶酸钙解救。"],"oral_medication":["⚠️ 局部与口服用药，同类只选一种：","药物1（含漱液）：","用法：复方氯己定含漱液 10ml 含漱 tid（每次1分钟）；康复新液 10ml 含漱 tid（促黏膜修复）；生理盐水+碳酸氢钠含漱（口腔碱化，每日4～6次）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","药物2（局部镇痛）：","用法：2%利多卡因含漱液 5～10ml 含漱（餐前15～20分钟，注意麻木致误吸）；或利多卡因凝胶 局部涂抹","药物3（抗真菌/抗病毒，感染时）：","用法：制霉菌素漱口液 含漱 qid（念珠菌）或 氟康唑 50mg qd 口服；阿昔洛韦 0.2g tid 口服（疱疹）","药物4（营养支持）：","用法：口服营养补充剂（ONS）2～3份/日；维生素B12 0.5mg tid + 维生素C 0.2g tid","📌 避免使用含酒精的漱口液（加重黏膜刺激）；含漱后30分钟内不进食饮水以维持药效。"],"treatment":["口腔护理：每2～4小时用软毛牙刷或海绵棉签清洁口腔，配合生理盐水或碳酸氢钠含漱，餐后与睡前必做","局部对症：含漱液（复方氯己定含漱液 10ml 含漱 tid、康复新液 10ml 含漱 tid）、局部麻醉（2%利多卡因 5-10ml 含漱）缓解疼痛，必要时含冰片/咽部含漱","口腔冷疗（冷冻疗法）：大剂量氟尿嘧啶类化疗期间含冰块可降低黏膜炎发生率与严重程度","抗感染：疑真菌（制霉菌素 50万U 含服 tid/氟康唑 100mg 口服 qd）、病毒（阿昔洛韦 400mg 口服 q8h）感染时针对性治疗；中性粒细胞缺乏者经验性广谱抗生素","营养支持：能进食者用软食、流质与口服营养补充剂；3级以上者静脉营养支持","镇痛：轻中度用局部麻醉含漱，重度用静脉镇痛（吗啡 5-10mg 静推 q4h 或芬太尼 25-50μg 静推），保证进食与休息","化疗方案调整：3级以上黏膜炎暂停化疗，恢复后减量（氟尿嘧啶类减量20%～25%）；使用生长因子（帕利夫明 60μg/kg 皮下注射 qd，重度风险者）","放射相关：头颈部放疗者配合口腔科处理（氟化物防龋、放疗前口腔治疗）"],"management":["每日口腔评估：检查黏膜部位与分级，记录疼痛评分与进食情况（每班评估并报告变化）","口腔护理规范：软毛牙刷+含氟牙膏每日2～3次，海绵棉签辅助；生理盐水或碳酸氢钠含漱每日4～6次，餐后与睡前必做","疼痛管理：评估疼痛对进食的影响，餐前15～20分钟给予局麻含漱，必要时全身镇痛","饮食管理：软食、流质、温凉食物；避免辛辣、酸、粗糙、过烫食物；使用吸管进食减少刺激","营养监测：每日记录进食量与体重，必要时营养科会诊与肠内/肠外营养","感染预防：中性粒细胞缺乏期加强口腔护理与手卫生；观察口腔白色斑块（真菌）、水疱（疱疹）并及时报告","宣教：化疗前即开始口腔护理（预防为主）、避免含酒精漱口液与烟草、保持口腔湿润（多饮水、无糖口香糖刺激唾液）"],"notes":["口腔黏膜炎多在化疗后5～14天（中性粒细胞低谷期）最重，与中性粒细胞减少叠加使感染风险显著增加","预防优于治疗：化疗前开始规范口腔护理、口腔冷疗可显著降低发生率与严重程度","大剂量甲氨蝶呤所致黏膜炎与亚叶酸钙解救不足有关，需监测血药浓度并加强解救","含酒精漱口液、过氧化氢与碘制剂可加重黏膜损伤，应避免使用","3级以上黏膜炎影响进食与生活质量，需暂停化疗、强化营养支持与镇痛"],"emergency":["口腔溃疡伴发热与中性粒细胞缺乏（FN）→ 1小时内经验性广谱抗生素（口腔黏膜屏障破坏易致菌血症）","口腔大量出血或坏死（重度黏膜炎/感染）→ 急诊口腔科与抗感染处理","完全不能进食伴脱水与电解质紊乱 → 立即静脉补液与营养支持","颏下/颈部肿胀伴呼吸困难（口腔感染扩散致颌面部蜂窝织炎/气道受压）→ 急诊评估气道与手术"],"pinyin":"hlxgxkqnyy","icd10":"K12.0","physical_exam":["生命体征：体温（感染）、脉搏、体重变化（营养）","口腔黏膜：颊、舌、口底、腭、咽部红斑/溃疡范围与分级，溃疡数目、大小与深度","口腔感染征象：白色斑块（念珠菌，可擦除）、水疱与口唇疱疹（HSV）、脓性分泌物、口臭","牙齿与牙龈：龋齿、牙龈出血与肿胀（感染源）、口腔卫生状况","疼痛与功能：疼痛评分、吞咽与言语功能、流涎情况","颈部与颌下：淋巴结肿大、颌面部肿胀（感染扩散）","营养与脱水：体重、皮肤弹性、口唇干燥、进食量与饮水量"],"lab_tests":["血常规（含中性粒细胞）：每日或隔日（中性粒细胞缺乏期黏膜炎感染风险最高）","口腔拭子培养+真菌涂片+HSV PCR：疑感染时（念珠菌、单纯疱疹病毒）","血培养（发热者）：中性粒细胞缺乏伴黏膜炎易致菌血症，抗生素前留取","电解质+肾功能+白蛋白+前白蛋白：脱水与营养状态评估","甲氨蝶呤血药浓度（大剂量MTX方案）：指导亚叶酸钙解救（不足可加重黏膜炎）","CRP+PCT：感染评估","体重与进食量记录：营养干预依据"],"nursing":["口腔护理：每日2～3次软毛牙刷清洁+含漱液含漱（餐后、睡前必做），中性粒细胞缺乏期改用海绵棉签与生理盐水","黏膜评估与记录：每班检查口腔黏膜并分级记录（部位、范围、疼痛评分），异常及时报告","疼痛护理：餐前15～20分钟局麻含漱，评估镇痛效果与进食情况；必要时全身镇痛","饮食护理：温凉软食/流质，避免辛辣酸烫粗糙食物；用吸管进食；少量多餐并记录进食量","感染观察：发热、口腔白色斑块、水疱与脓性分泌物，中性粒细胞缺乏期实施保护性隔离与手卫生","宣教：化疗前开始口腔护理（预防为主）、避免含酒精漱口液与烟草、多饮水保持口腔湿润"],"diet":["温凉、细软、少渣、无刺激的流质或半流质（米汤、牛奶、蒸蛋、藕粉、匀浆膳）","避免辛辣、酸、咸、粗糙、坚硬、过烫与油炸食物；避免含酒精饮料与烟草","使用吸管进食液体，减少食物与溃疡面接触；餐后立即漱口清洁","高蛋白、高热量、高维生素（可用口服营养补充剂），少量多餐（每日6～8餐）","严重黏膜炎不能进食者：肠内营养（鼻胃管/鼻肠管）或肠外营养支持，保证热量与蛋白摄入"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1369},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"326cced52b397e35d31b224962991b0bb1bb074ae63a3f1f8e7839c9152ac3bb","pinyin":"hualiaoxiangguanxingkouqiangnianmoyan","initials":"hlxgxkqnmy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","口腔黏膜红斑、水肿（1级）、孤立小溃疡（2级）、融合溃疡伴疼痛影响进食（3级）、溃疡伴出血坏死与无法进食（4级）\\n进食、吞咽疼痛，味觉改变（金属味），口干\\n流涎、口臭，溃疡表面有白色假膜（需与真菌感染鉴别）\\n继发感染：单纯疱疹（口唇疱疹）、念珠菌（鹅口疮，白色斑块可擦除）、细菌感染\\n严重者因疼痛拒绝进食致脱水、营养不良与体重下降",60],["摘要","化疗相关性口腔黏膜炎是化疗（尤其氟尿嘧啶类、大剂量甲氨蝶呤、蒽环类）与放疗（头颈部）常见毒性，多在化疗后5～14天出现，表现为口腔黏膜红斑、溃疡与疼痛，影响进食并增加感染风险。防治以口腔护理、局部对症与营养支持为主，严重者需减量或暂停化疗。",30],["疾病编码","K12.0",30],["原首字母","hlxgxkqnyy",60]]},{"id":"orders-83cfbc3c90eb06cde278","key":"v1-c9ccc21dfe2a3058|orders-83cfbc3c90eb06cde278","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化疗患者静脉通路（PICC/输液港）维护","category":"化疗","raw":{"name":"化疗患者静脉通路（PICC/输液港）维护","category":"化疗","summary":"化疗患者需长期静脉给药、发疱性药物必须经中心静脉输注，常用PICC（经外周静脉置入中心静脉导管）与输液港（PORT）。规范维护包括冲管与封管、敷料更换、并发症（堵管、血栓、感染、导管相关血流感染、导管移位）的识别与处理。","symptoms":["正常：穿刺点无红肿渗液，导管外露长度无变化，输液通畅、回血良好，无疼痛","堵管：输液不畅或无法推注、回抽无血（可为血栓性、药物结晶或纤维蛋白鞘）","静脉血栓：置管侧上肢肿胀、疼痛、皮温升高、浅静脉扩张（PICC相关血栓）","感染：穿刺点红肿、疼痛、渗液或脓性分泌物，发热（导管相关血流感染CRBSI可致脓毒症）","导管移位/脱出：外露长度增加、输液疼痛、渗液（导管异位或破裂）；输液港：穿刺困难、港体翻转","药物外渗（PICC）：穿刺侧疼痛、肿胀、发红（需按外渗处理）"],"diagnosis":["导管功能评估：每次使用前评估外露长度（PICC）、回血、推注阻力与输液速度","穿刺点与置管侧肢体评估：红肿、渗液、压痛、上肢周径（与对侧对比，防血栓）","血管超声：疑PICC相关血栓时（首选）","血培养（外周+导管双份）：疑CRBSI时（导管相关血流感染诊断关键）","导管尖端培养（拔管时）：疑似CRBSI者","胸部X线/CT：疑导管异位（PICC尖端应位于上腔静脉下1/3与右心房上缘之间）与导管破裂","D-二聚体+凝血功能：疑血栓时"],"infusion":["⚠️ 按并发症选择处理用药，切勿全部同时使用！","","方案1（PICC相关血栓，抗凝治疗）：","  用法：低分子肝素 0.4ml 皮下注射 q12h（按体重与肾功能调整）；或利伐沙班 15mg bid×21天→20mg qd（疗程3个月，遵医嘱）〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","","方案2（导管相关血流感染，CRBSI）：","  用法：万古霉素 1g（NS 100ml 或 5%GS 100ml）静滴 q12h（疑MRSA，监测血药浓度）+ 哌拉西林他唑巴坦 4.5g 静滴 q8h；或按血培养药敏调整（疗程至少10～14天，复杂感染4～6周）〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案3（堵管溶栓，PICC血栓性堵塞）：","  用法：尿激酶 5000～10000U + 0.9%氯化钠 2ml 缓慢注入导管内（封管留置30～60分钟，回抽）；或 rt-PA 1～2mg（按规范操作）","","方案4（补液与支持）：","  用法：0.9%氯化钠 静滴（另建外周通路）；对症支持治疗","","📌 溶栓封管须由受过培训的医护人员按规范操作（禁止暴力推注，防止导管破裂或血栓脱落）；感染性导管需评估拔管指征。"],"oral_medication":["⚠️ 维护期与并发症口服用药选择：","药物1（抗凝，导管相关血栓）：","用法：利伐沙班 20mg qd（餐时服，疗程3个月，遵医嘱）或 华法林（监测INR 2～3）〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","药物2（抗感染序贯，CRBSI）：","用法：利奈唑胺 0.6g bid 或 复方磺胺甲噁唑 2片 bid（按药敏选择，足疗程）","药物3（消肿，上肢肿胀）：","用法：地奥司明片 2片 bid 或 迈之灵 2片 bid","药物4（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时 或 布洛芬 0.3g bid（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 抗凝期间观察出血征象（穿刺点、牙龈、皮肤瘀斑）；出现置管侧上肢肿胀立即就诊（血栓评估）。"],"treatment":["冲管与封管规范：每次输液前后用10ml及以上注射器脉冲式冲管（生理盐水10～20ml），输液港用肝素盐水（100U/ml，5ml）封管；治疗间歇期PICC每周冲洗1次、输液港每4周1次","敷料与接头更换：PICC透明敷料每7天更换（纱布敷料每2天），出汗多或敷料潮湿卷边立即更换；输液接头每7天更换或按规范","无菌操作：更换敷料与接头时严格无菌（戴口罩、无菌手套、消毒待干），消毒范围大于敷料面积","堵管处理：先排除机械性因素（导管打折、夹闭），血栓性堵管用尿激酶封管溶栓（见上）；药物结晶性堵管可用稀盐酸（特殊药物需专科指导）","血栓处理：确诊PICC相关血栓后抗凝3个月；是否拔管取决于血栓范围、导管功能与是否需要继续治疗（多数可保留导管并抗凝）","CRBSI处理：血培养阳性或临床高度怀疑时，通常拔除导管并抗感染（输液港可考虑保留+抗生素封管，需感染科评估）","导管移位/破裂：PICC移位需X线确认并调整；导管破裂需修复套件或拔管；输液港翻转需手术复位","宣教：避免置管侧肢体提重物（>5kg）、剧烈活动、测血压与静脉穿刺；洗澡时敷料防水保护；出现红肿、疼痛、发热、外露长度变化立即就诊"],"management":["置管侧肢体保护：避免提重物（>5kg）、剧烈运动、测血压、抽血与静脉穿刺；避免长期受压（睡眠勿压该侧）","敷料管理：透明敷料每7天更换，潮湿/卷边/渗液立即更换；观察穿刺点有无红肿、渗液与疼痛","导管功能维护：每次使用前评估外露长度、回血与推注阻力；输液前后脉冲式冲管、正压封管（防止血液回流堵管）","血栓监测：每日观察置管侧上肢有无肿胀、疼痛、皮温升高，每周测上肢周径并与对侧对比","感染监测：每次维护时评估穿刺点（红肿、渗液、压痛）并记录；监测体温（发热需警惕CRBSI）","维护记录：建立维护档案（置管日期、外露长度、维护日期、并发症），每次维护后记录","宣教与随访：教会患者识别异常（红肿、疼痛、发热、外露长度变化、输液疼痛）并及时就诊；洗澡用防水保护"],"notes":["发疱性化疗药物（蒽环类、长春碱类）必须经中心静脉（PICC/输液港）输注，禁止外周静脉推注","冲管必须用10ml及以上注射器脉冲式进行（小注射器压力过大可致导管破裂），严禁暴力推注","输液港治疗间歇期每4周维护1次、PICC每周1次，逾期未维护增加堵管与血栓风险","PICC相关血栓发生率约5%～10%，出现上肢肿胀需及时超声检查并抗凝，不可自行拔管","导管相关血流感染可致脓毒症，出现不明原因发热需考虑导管因素并做双份血培养"],"emergency":["置管侧上肢突发肿胀、疼痛伴皮温升高（PICC相关血栓）→ 立即超声评估并启动抗凝","穿刺点红肿渗液伴寒战高热、血压下降（CRBSI/脓毒症）→ 立即双份血培养+经验性抗生素，评估拔管","推注时突发胸痛、气促（导管断裂致栓塞/气栓）→ 立即夹闭导管、左侧卧位、吸氧并急诊处理","输液时穿刺点疼痛肿胀（药物外渗）→ 立即停止输注、回抽、按药物特性处理（蒽环类用右雷佐生）"],"pinyin":"hlhzjmtdpiccsfgwh","icd10":"Z45.2","physical_exam":["生命体征：体温（感染/CRBSI）、脉搏、血压","穿刺点：红肿、渗液、脓性分泌物、压痛、结痂（PICC穿刺点或输液港港体部位）","置管侧肢体：上肢周径（与对侧对比）、肿胀、皮温、浅静脉扩张、疼痛（血栓评估）","导管外露：PICC外露长度（与置管记录对比）、敷料固定情况、有无打折与破损","输液港：港体位置（有无翻转）、穿刺困难、皮肤张力与完整性","导管功能：回血、推注阻力、输液速度（通畅度评估）","其他血管通路：对侧肢体与其他置管部位评估（备用通路）"],"lab_tests":["血培养（外周+导管双份）：疑CRBSI时（导管相关血流感染诊断关键，抗生素前留取）","血管超声（置管侧上肢）：疑PICC相关血栓时（首选）","D-二聚体+凝血功能+血小板：血栓与抗凝治疗监测","血常规+CRP+PCT：感染评估（CRBSI可致脓毒症）","胸部X线/CT：确认PICC尖端位置或疑导管异位/破裂","导管尖端培养（拔管时）：疑似CRBSI者送检","肝肾功能+电解质：抗感染与抗凝药物剂量调整"],"nursing":["无菌维护操作：更换敷料/接头时戴口罩与无菌手套，消毒范围大于敷料面积并待干，严格无菌","敷料与固定：透明敷料每7天更换，潮湿卷边立即更换；导管妥善固定、防止牵拉与移位（标记外露长度）","冲管与封管：输液前后用10ml以上注射器脉冲式冲管、正压封管；输液港用肝素盐水封管，治疗间歇期按期维护","并发症观察：每次维护评估穿刺点（红肿渗液）、置管侧上肢（肿胀疼痛）、外露长度与导管功能，异常立即报告","血栓预防宣教：避免置管侧肢体提重物、受压、剧烈活动与测血压；每日观察上肢有无肿胀并记录","患者宣教：洗澡用防水保护（PICC）、保持敷料干燥、识别异常症状（发热、红肿、输液疼痛）并及时就诊、按期维护不可逾期"],"diet":["高蛋白、高维生素饮食促进组织修复与免疫功能（鱼、瘦肉、蛋、奶、新鲜蔬果）","充足饮水（每日1500～2000ml），降低血液黏稠度（有助于预防导管相关血栓）","抗凝治疗期间：稳定摄入维生素K（服用华法林者），避免大量绿叶蔬菜骤增骤减","低脂饮食（预防血栓风险因素），控制体重","避免辛辣刺激与酒类；化疗期间按化疗饮食要求（少量多餐、清淡易消化）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1370},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c12f43814ce778b610d754133919561f4798e3962f199b08488d6e9c03ade55e","pinyin":"hualiaohuanzhejingmaitonglu（PICC/shuyegang）weihu","initials":"hlhzjmtl（syg）wh","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","正常：穿刺点无红肿渗液，导管外露长度无变化，输液通畅、回血良好，无疼痛\\n堵管：输液不畅或无法推注、回抽无血（可为血栓性、药物结晶或纤维蛋白鞘）\\n静脉血栓：置管侧上肢肿胀、疼痛、皮温升高、浅静脉扩张（PICC相关血栓）\\n感染：穿刺点红肿、疼痛、渗液或脓性分泌物，发热（导管相关血流感染CRBSI可致脓毒症）\\n导管移位/脱出：外露长度增加、输液疼痛、渗液（导管异位或破裂）；输液港：穿刺困难、港体翻转\\n药物外渗（PICC）：穿刺侧疼痛、肿胀、发红（需按外渗处理）",60],["摘要","化疗患者需长期静脉给药、发疱性药物必须经中心静脉输注，常用PICC（经外周静脉置入中心静脉导管）与输液港（PORT）。规范维护包括冲管与封管、敷料更换、并发症（堵管、血栓、感染、导管相关血流感染、导管移位）的识别与处理。",30],["疾病编码","Z45.2",30],["原首字母","hlhzjmtdpiccsfgwh",60]]},{"id":"orders-15202dfbc308e3cc214d","key":"v1-c9ccc21dfe2a3058|orders-15202dfbc308e3cc214d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"内分泌治疗与口服靶向药不良反应管理","category":"化疗","raw":{"name":"内分泌治疗与口服靶向药不良反应管理","category":"化疗","summary":"乳腺癌（他莫昔芬、芳香化酶抑制剂）、前列腺癌（GnRH激动剂、阿比特龙、恩扎卢胺）等内分泌治疗与口服靶向药（EGFR-TKI、抗血管生成TKI、CDK4/6抑制剂、PARP抑制剂）需长期服用，不良反应影响依从性。管理重点是识别与处理潮热、关节痛、骨质疏松、皮疹腹泻、高血压蛋白尿、手足综合征等，并保证按时服药与随访。","symptoms":["内分泌治疗：潮热出汗、关节肌肉疼痛僵硬、乏力、情绪波动、阴道干涩（乳腺癌）；性欲减退、勃起功能障碍、骨质流失（前列腺癌）","EGFR-TKI：痤疮样皮疹（面部、胸部）、甲沟炎、腹泻、口腔黏膜炎、皮肤干燥瘙痒","抗血管生成TKI：高血压、蛋白尿、手足综合征、乏力、甲状腺功能减退、出血与血栓风险","CDK4/6抑制剂：中性粒细胞减少、乏力、腹泻、QT间期延长","PARP抑制剂：贫血、血小板减少、恶心呕吐、乏力；阿比特龙：高血压、低钾、水肿（需联用泼尼松）","长期用药：骨质疏松与骨折风险（芳香化酶抑制剂）、子宫内膜增厚（他莫昔芬）、血栓风险"],"diagnosis":["用药依从性评估：询问服药时间、漏服次数与自行停药情况（长期治疗依从性是疗效关键）","血常规：CDK4/6抑制剂与PARP抑制剂需每2～4周监测（中性粒细胞、血红蛋白、血小板）","肝功能+肾功能+电解质：每2～4周（阿比特龙需监测血钾与血压；多数靶向药经肝代谢）","血压与尿常规/尿蛋白定量：抗血管生成药每1～2周监测血压，每周期查尿蛋白","骨密度（DEXA）+血钙+维生素D：芳香化酶抑制剂与GnRH激动剂治疗者每1～2年复查","心电图+心脏超声（LVEF）：部分靶向药（如曲妥珠单抗、部分TKI）需定期监测","甲状腺功能：TKI治疗者每4～8周（甲减常见）","妇科超声：他莫昔芬治疗者每年（子宫内膜增厚与内膜癌风险）"],"infusion":["⚠️ 按不良反应类型选择处理用药，切勿全部同时使用！","方案1（骨转移/骨痛与骨保护，双膦酸盐或地舒单抗）：","用法：唑来膦酸 4mg + 0.9%氯化钠 100ml 静滴 每3～4周（输注>15分钟，监测肾功能与血钙，用药前补水）；或 地舒单抗 120mg 皮下注射 每4周","方案2（抗血管生成药致高血压/蛋白尿）：","用法：0.9%氯化钠 静滴（补液）；必要时静脉降压（乌拉地尔 12.5mg 静推后泵入）——通常以口服降压药为主（ACEI/ARB+钙通道阻滞剂）","方案3（严重皮疹/皮肤毒性，短期激素）：","用法：甲泼尼龙 40mg 静滴 qd（3～5天，严重皮疹时）；0.9%氯化钠 静滴〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案4（补钙与维生素D，骨流失）：","用法：葡萄糖酸钙 1g + 维生素C 2g 静滴 qd（必要时）；口服钙剂与维生素D为主","📌 唑来膦酸需监测肾功能与血钙（低钙者先纠正）；抗血管生成药相关高血压需控制在140/90mmHg以下。"],"oral_medication":["⚠️ 长期口服用药与对症处理，同类只选一种：","药物1（内分泌治疗核心用药）：","用法：他莫昔芬 20mg qd（绝经前，5～10年）或 来曲唑 2.5mg qd／阿那曲唑 1mg qd（绝经后）；前列腺癌：比卡鲁胺 50mg qd 或 阿比特龙 1000mg qd（空腹，联用泼尼松 5mg bid）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物2（潮热与关节痛）：","用法：帕罗西汀 20mg qd 或 文拉法辛 75mg qd（潮热）；塞来昔布 200mg qd（关节痛，餐后）；维生素D+钙剂〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物3（皮疹与皮肤护理，EGFR-TKI）：","用法：多西环素 0.1g bid（痤疮样皮疹）+ 氢化可的松乳膏 外用 bid + 保湿霜；米诺环素 0.1g bid（二选一）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","药物4（腹泻与手足综合征）：","用法：洛哌丁胺 2mg tid（腹泻）；维生素B6 100mg tid + 尿素软膏 外用 bid（手足综合征）","药物5（骨保护）：","用法：碳酸钙D3 600mg qd + 骨化三醇 0.25μg qd；必要时双膦酸盐或地舒单抗（按医嘱）","📌 内分泌治疗需坚持5～10年（乳腺癌）或长期（前列腺癌），不可自行停药；阿比特龙需空腹服用并监测血压血钾。"],"treatment":["依从性管理：解释长期治疗意义、使用服药提醒（手机闹钟、药盒）、定期评估漏服情况与原因","潮热与关节痛：非药物（避免诱因、规律运动、减重）+ 药物（SSRI/SNRI类、塞来昔布、维生素D）","骨健康管理：芳香化酶抑制剂与GnRH激动剂治疗者补充钙与维生素D，每1～2年查骨密度，必要时用双膦酸盐/地舒单抗","皮疹（EGFR-TKI）：保湿+防晒+局部激素+口服多西环素，2级减量、3级暂停并短期口服/静脉激素","抗血管生成药毒性：高血压（降压药物治疗，必要时减量/暂停）、蛋白尿（24小时尿蛋白>2g停药）、手足综合征（尿素软膏+维生素B6+减量）、出血与血栓评估","CDK4/6抑制剂：中性粒细胞减少按分级减量/延迟，监测血常规每2～4周；QT间期延长者监测心电图与电解质","甲状腺功能减退（TKI相关）：左甲状腺素替代治疗（按TSH调整）","定期随访：每2～4周血常规与肝肾功能（靶向药），每3～6个月影像学评估疗效，每年骨密度与妇科超声（他莫昔芬）"],"management":["服药指导：明确服药时间（阿比特龙空腹、他莫昔芬随餐或空腹固定、左甲状腺素晨起空腹），与食物和其他药物的间隔要求","依从性随访：每次复诊询问漏服与停药情况，记录并分析原因（不良反应、经济、忘记），提供解决方案","不良反应分级记录：每次复诊按CTCAE评估皮疹、腹泻、高血压、手足综合征等并记录，据分级决定是否减量/暂停","监测计划执行：血常规、肝肾功能、血压、尿蛋白、甲功、心电图按方案定期复查，建立随访表提醒患者","皮肤与手足护理宣教：保湿、防晒（SPF≥30）、避免热水浸泡与摩擦、穿宽松鞋袜、避免长时间行走","骨健康与跌倒预防：补钙与维生素D、负重运动、防跌倒（骨质疏松者）、避免吸烟饮酒","心理支持：长期治疗与不良反应易致焦虑抑郁，提供心理支持与患者教育，鼓励参加病友支持团体"],"notes":["内分泌治疗（乳腺癌5～10年、前列腺癌长期）依从性直接决定疗效，停药可显著增加复发与死亡风险","芳香化酶抑制剂与GnRH激动剂致骨质流失与骨折风险增加，必须常规补充钙与维生素D并监测骨密度","他莫昔芬增加子宫内膜增厚与内膜癌风险（异常阴道出血需及时就诊）与静脉血栓风险（手术/长期卧床需评估停药）","EGFR-TKI皮疹与疗效有一定相关性，但3级皮疹需积极处理并可能调整剂量","抗血管生成药（TKI）相关高血压与蛋白尿需定期监测，多数通过降压药与减量可控制；出血与血栓风险需评估"],"emergency":["血压急剧升高伴头痛、视力模糊（高血压危象，抗血管生成药）→ 立即降压处理并暂停用药","严重皮疹伴发热、黏膜糜烂、皮肤剥脱（Stevens-Johnson综合征/中毒性表皮坏死松解症）→ 立即停药、皮肤科急会诊、支持治疗","血性腹泻或呕血、黑便（抗血管生成药致出血/穿孔）→ 立即停药并急诊处理","胸闷气促伴下肢肿胀（血栓栓塞）→ 急诊评估并抗凝治疗","阿比特龙致严重低钾与心律失常 → 补钾并监测心电图，调整治疗"],"pinyin":"nfmzlykfbxbygl","icd10":"Z79.8","physical_exam":["生命体征：血压（抗血管生成药、阿比特龙）、心率与心律、体重","皮肤与黏膜：皮疹范围与分级（面部、胸背、头皮）、皮肤干燥、甲沟炎、手足皮肤改变（手足综合征：红斑、脱皮、水疱）","关节与肌肉：关节压痛与活动受限（芳香化酶抑制剂致关节痛）、肌力与步态","骨骼：骨痛部位（骨转移）、脊柱后凸与身高变化（骨质疏松）、有无病理性骨折","心脏：心率心律、心界（心脏毒性）、有无水肿（阿比特龙致水钠潴留）","甲状腺：甲状腺肿大、皮肤干燥与水肿（TKI致甲减）","神经系统与情绪：情绪状态（焦虑抑郁）、潮热出汗频率、认知功能"],"lab_tests":["血常规（含中性粒细胞、血小板）：CDK4/6抑制剂与PARP抑制剂每2～4周复查","肝功能（ALT/AST/胆红素）+肾功能：多数口服靶向药经肝代谢，每2～4周复查","电解质（钾、钠、钙）+血糖：阿比特龙（低钾）、双膦酸盐（低钙）监测","血压+尿常规/24小时尿蛋白定量：抗血管生成药每1～2周监测","骨密度（DEXA）+血钙+25-羟维生素D：内分泌治疗者每1～2年复查","甲状腺功能（TSH、FT4）：TKI治疗者每4～8周（甲减常见）","心电图+心脏超声（LVEF）：蒽环类后内分泌治疗或含心脏毒性靶向药者定期复查；妇科超声（他莫昔芬）每年"],"nursing":["用药指导与依从性：明确服药时间与间隔要求（阿比特龙空腹、左甲状腺素晨起空腹），每次随访评估漏服情况","皮肤护理宣教：保湿霜每日2次、防晒（SPF≥30）、避免热水浸泡与摩擦、穿宽松鞋袜（手足综合征预防）","不良反应观察与记录：皮疹、腹泻、手足皮肤改变、血压、体重与水肿，按CTCAE分级记录并报告","血压与尿蛋白监测：抗血管生成药治疗期间每1～2周测血压并记录，按医嘱复查尿蛋白","骨健康护理：指导钙与维生素D补充、负重运动、防跌倒措施；长期用药者记录骨密度随访","心理护理与宣教：解释长期治疗必要性、缓解对复发与不良反应的焦虑，介绍患者支持资源"],"diet":["均衡饮食：高蛋白、高纤维、低脂，多食蔬菜水果与全谷物，控制体重","骨骼健康：富含钙（牛奶、豆制品、小鱼小虾）与维生素D（深海鱼、蛋黄、晒太阳）的食物","阿比特龙需空腹服用（服药前2小时与后1小时禁食），避免高脂餐（影响吸收）；同时联用泼尼松需低盐饮食","抗血管生成药致高血压者：低盐饮食（每日钠盐<5g），避免腌制与加工食品","腹泻者：低渣低脂饮食；手足综合征者：避免辛辣刺激与酒类；忌烟酒"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1371},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d9029b53c8fb1cda0d099a6f10667bcfb61f385fe8a4c8b50d793fce9824e8aa","pinyin":"neifenmizhiliaoyukoufubaxiangyaobuliangfanyingguanli","initials":"nfmzlykfbxyblfygl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","内分泌治疗：潮热出汗、关节肌肉疼痛僵硬、乏力、情绪波动、阴道干涩（乳腺癌）；性欲减退、勃起功能障碍、骨质流失（前列腺癌）\\nEGFR-TKI：痤疮样皮疹（面部、胸部）、甲沟炎、腹泻、口腔黏膜炎、皮肤干燥瘙痒\\n抗血管生成TKI：高血压、蛋白尿、手足综合征、乏力、甲状腺功能减退、出血与血栓风险\\nCDK4/6抑制剂：中性粒细胞减少、乏力、腹泻、QT间期延长\\nPARP抑制剂：贫血、血小板减少、恶心呕吐、乏力；阿比特龙：高血压、低钾、水肿（需联用泼尼松）\\n长期用药：骨质疏松与骨折风险（芳香化酶抑制剂）、子宫内膜增厚（他莫昔芬）、血栓风险",60],["摘要","乳腺癌（他莫昔芬、芳香化酶抑制剂）、前列腺癌（GnRH激动剂、阿比特龙、恩扎卢胺）等内分泌治疗与口服靶向药（EGFR-TKI、抗血管生成TKI、CDK4/6抑制剂、PARP抑制剂）需长期服用，不良反应影响依从性。管理重点是识别与处理潮热、关节痛、骨质疏松、皮疹腹泻、高血压蛋白尿、手足综合征等，并保证按时服药与随访。",30],["疾病编码","Z79.8",30],["原首字母","nfmzlykfbxbygl",60]]},{"id":"orders-c5dc4b22767e5b3298b9","key":"v1-c9ccc21dfe2a3058|orders-c5dc4b22767e5b3298b9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化疗后随访与复查计划","category":"化疗","raw":{"name":"化疗后随访与复查计划","category":"化疗","summary":"化疗结束后的随访旨在及早发现复发转移、评估治疗远期毒性（心脏、肾、神经、内分泌毒性）与第二原发肿瘤、并提供康复与心理支持。随访频次与内容按瘤种、分期与治疗方案个体化（一般术后/化疗后2年内每3～6个月，3～5年每6～12个月，5年后每年）。","symptoms":["需警惕的复发信号：新发疼痛（骨、腹、胸）、体重下降、乏力加重、发热、咳嗽咯血、呕血黑便、淋巴结肿大、切口或胸壁新发结节","远期毒性：心脏毒性（活动后气促、水肿、心悸）、肾功能损害（水肿、尿量变化）、周围神经毒性（手足麻木）、内分泌功能减退（乏力、畏寒）、骨质疏松（骨痛、骨折）","心理社会问题：焦虑、抑郁、失眠、恐惧复发、回归工作与家庭角色困难","治疗相关后遗症：术后淋巴水肿、造口相关、认知功能下降（化疗脑）","第二原发肿瘤风险：与新发症状或异常检查相关"],"diagnosis":["病史与体检：每次随访询问症状、体重变化、用药情况与心理状态，查体重点关注淋巴结、手术区与脏器体征","血液学检查：血常规、肝肾功能、电解质；按瘤种查肿瘤标志物（CEA/CA19-9/CA125/AFP/PSA/CA15-3/Tg等）","影像学：按瘤种与分期复查（胸部/腹部/盆腔CT、超声、MRI），一般术后2年内每3～6个月，之后逐步延长","内镜/腔镜：结直肠癌术后1年内结肠镜、胃癌术后胃镜、膀胱癌膀胱镜（按各自随访方案）","远期毒性评估：心脏超声（LVEF，蒽环类/曲妥珠单抗后）、肾功能、听力（顺铂）、骨密度（内分泌治疗）、肺功能（博来霉素等）","甲状腺功能与激素水平：免疫治疗与TKI治疗后（甲减、垂体功能减退）","心理评估：焦虑抑郁量表（PHQ-9、GAD-7）筛查"],"infusion":["⚠️ 随访期一般无需常规输液；出现以下情况按需治疗：","方案1（骨转移/骨痛，骨保护治疗）：","用法：唑来膦酸 4mg + 0.9%氯化钠 100ml 静滴 每3～4周（输注>15分钟，用药前补水，监测肾功能与血钙）；或地舒单抗 120mg 皮下注射 每4周","方案2（贫血或营养支持）：","用法：蔗糖铁 100mg + 0.9%氯化钠 100ml 静滴（按医嘱，肾性贫血或铁缺乏）；白蛋白 10g 静滴（低蛋白）；必要时输血","方案3（复发/进展需要再治疗）：","用法：按新方案行化疗/靶向/免疫治疗（按指南与多学科讨论决定）","方案4（骨转移疼痛控制与骨相关事件预防）：","用法：0.9%氯化钠 静滴；帕米膦酸二钠 90mg + 0.9%氯化钠 500ml 静滴 每3～4周（替代唑来膦酸）","📌 随访期治疗决策需多学科讨论；骨保护药物使用前需口腔检查（预防颌骨坏死）并补充钙与维生素D。"],"oral_medication":["⚠️ 随访期长期用药与对症处理：","药物1（内分泌治疗延续，按瘤种）：","用法：他莫昔芬 20mg qd（乳腺癌5～10年）；来曲唑 2.5mg qd（绝经后）；比卡鲁胺 50mg qd（前列腺癌）","药物2（骨健康）：","用法：碳酸钙D3 600mg qd + 骨化三醇 0.25μg qd 或 维生素D 800IU/日","药物3（神经毒性/症状管理）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid；加巴喷丁 0.1～0.3g tid（疼痛性神经病变）","药物4（心理支持）：","用法：舍曲林 50mg qd 或 艾司西酞普兰 10mg qd（抑郁焦虑，需精神科评估）；必要时劳拉西泮 0.5mg 睡前","📌 随访期用药需评估与既往治疗的相互作用；长期用药（内分泌、抗凝、骨保护）不可自行停药。"],"treatment":["建立个体化随访计划：按瘤种、分期、治疗方案与危险分层制定随访频次与检查项目，书面告知患者并录入随访系统","复发监测：症状询问+体检+肿瘤标志物+影像学；发现异常及时进一步检查（PET-CT、活检）","远期毒性管理：心脏（LVEF复查、按心衰指南治疗）、肾（避免肾毒性药物、控制血压）、神经（康复与营养神经）、内分泌（激素替代）","第二原发肿瘤筛查：戒烟、按年龄与性别进行常规癌症筛查（肺、结直肠、乳腺、宫颈、前列腺）","康复与生活方式干预：运动处方（每周150分钟中等强度有氧+抗阻训练）、体重管理、戒烟限酒、均衡饮食","心理社会支持：焦虑抑郁筛查与干预、病友支持团体、回归工作与家庭角色指导","姑息与支持治疗（晚期患者）：疼痛控制、营养支持、症状管理与临终关怀沟通","慢性并发症处理：淋巴水肿（弹力袖套、手法淋巴引流）、造口管理、认知功能康复"],"management":["随访档案：记录每次随访的症状、体重、体检、检查结果与处理，动态对比趋势（体重下降与标志物升高需警惕）","预约与提醒系统：主动为患者预约下次复查（避免依赖患者自行记忆），电话/短信提醒提高依从性","患者教育：教会患者识别复发预警信号（新发疼痛、体重下降、异常出血、淋巴结肿大）并及时就诊","生活方式指导：运动（循序渐进、避免过度）、饮食（均衡、控制体重）、戒烟限酒、规律作息","心理评估与转介：每次随访筛查焦虑抑郁，必要时转介心理科/精神科与病友支持组织","远期毒性监测执行：按方案安排心脏超声、骨密度、甲功、听力、肾功能等检查并记录结果","多学科随访（复杂患者）：肿瘤内科、外科、放疗科、康复科、营养科、心理科协作"],"notes":["随访频次个体化：一般治疗后2年内每3～6个月、3～5年每6～12个月、5年后每年，高危患者更频繁","随访的核心是『症状+体检+必要的检查』，不建议无指征的全身PET-CT（假阳性与辐射负担）","肿瘤标志物单次轻度升高不必恐慌，需动态观察并结合影像；明显升高需进一步检查","远期毒性（心脏、肾、神经、内分泌）可于治疗后数年至十余年出现，需长期随访","健康生活方式（运动、控重、戒烟、限酒）可显著降低复发与第二原发肿瘤风险，应作为随访常规内容"],"emergency":["新发剧烈骨痛伴活动障碍或病理性骨折 → 急诊影像评估并镇痛、放疗或手术固定","突发气促、胸痛、咯血（肺转移/肺栓塞）→ 急诊评估与处理","呕血、黑便或大量阴道出血（消化道/妇科转移或治疗相关）→ 急诊处理","高热伴中性粒细胞缺乏（化疗后近期）→ 1小时内经验性抗生素","意识改变、剧烈头痛伴呕吐（脑转移/颅内压增高）→ 急诊影像与降颅压处理"],"pinyin":"hlhsfyfcyjh","icd10":"Z08","physical_exam":["生命体征：体温、血压、心率、体重（动态变化最重要）","一般情况：营养状态、体力状况（ECOG评分）、有无贫血与黄疸","浅表淋巴结：颈部、锁骨上、腋窝、腹股沟（复发监测）","手术区与局部：切口、胸壁、造口、淋巴水肿（患肢周径）","心肺：呼吸音（肺转移/胸腔积液）、心率心律（心脏毒性）、有无水肿","腹部：肝脾大小、腹块、腹水、压痛","神经系统：周围神经毒性（手足麻木、腱反射）、认知功能、肌力"],"lab_tests":["血常规+肝肾功能+电解质：每3～6个月（随访期）或按用药需要，评估贫血、肝肾功能与远期毒性","肿瘤标志物（按瘤种：CEA、CA19-9、CA125、AFP、PSA、CA15-3、Tg、NSE等）：每3～6个月，动态对比","影像学（胸部/腹部/盆腔CT或超声）：术后2年内每3～6个月，之后逐步延长（按瘤种方案）","内镜/膀胱镜：结直肠癌（术后1年结肠镜）、胃癌（胃镜）、膀胱癌（膀胱镜每3～6个月）","心脏超声（LVEF）+心电图：蒽环类/曲妥珠单抗治疗后定期复查（每6～12个月）","骨密度（DEXA）+血钙+25-羟维生素D：内分泌治疗或骨转移患者每1～2年","甲状腺功能+皮质醇：免疫治疗或TKI治疗后（每3～6个月）"],"nursing":["随访提醒与预约：协助建立复查计划并主动提醒（电话/短信），记录未按时复查患者并追踪","症状评估与记录：每次随访询问新发症状（疼痛、体重下降、出血、气促）并记录，异常及时报告","远期毒性观察：心脏（气促水肿）、神经（麻木）、内分泌（乏力畏寒）、肾功能（水肿尿少）表现并记录","心理筛查与支持：使用PHQ-9/GAD-7筛查焦虑抑郁，提供倾听与心理支持，必要时转介专科","生活方式指导：运动处方与饮食指导（控重、戒烟限酒）、淋巴水肿预防与护理、造口护理","健康教育：教会识别复发预警信号与就医时机；解释随访重要性，提高长期依从性"],"diet":["均衡饮食：高纤维（全谷物、蔬菜、水果）、适量优质蛋白、低脂低糖，控制总热量与体重","限制红肉（<500g/周）与加工肉制品；避免腌制、熏制与霉变食物","补充钙与维生素D（牛奶、豆制品、深海鱼、晒太阳），骨质疏松风险者按医嘱补充","严格戒烟、限制酒精（每日≤1个标准杯或戒酒）","个体化调整：造口或淋巴水肿患者按相应饮食要求；糖尿病与高血压患者控制血糖与钠盐"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1372},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"cca7f0f80ded170dab5c48266257c2222c702e4c8c8c5bb4c076da8e60d50cca","pinyin":"hualiaohousuifangyufuchajihua","initials":"hlhsfyfcjh","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","需警惕的复发信号：新发疼痛（骨、腹、胸）、体重下降、乏力加重、发热、咳嗽咯血、呕血黑便、淋巴结肿大、切口或胸壁新发结节\\n远期毒性：心脏毒性（活动后气促、水肿、心悸）、肾功能损害（水肿、尿量变化）、周围神经毒性（手足麻木）、内分泌功能减退（乏力、畏寒）、骨质疏松（骨痛、骨折）\\n心理社会问题：焦虑、抑郁、失眠、恐惧复发、回归工作与家庭角色困难\\n治疗相关后遗症：术后淋巴水肿、造口相关、认知功能下降（化疗脑）\\n第二原发肿瘤风险：与新发症状或异常检查相关",60],["摘要","化疗结束后的随访旨在及早发现复发转移、评估治疗远期毒性（心脏、肾、神经、内分泌毒性）与第二原发肿瘤、并提供康复与心理支持。随访频次与内容按瘤种、分期与治疗方案个体化（一般术后/化疗后2年内每3～6个月，3～5年每6～12个月，5年后每年）。",30],["疾病编码","Z08",30],["原首字母","hlhsfyfcyjh",60]]},{"id":"orders-acfe28d7ac9706962304","key":"v1-c9ccc21dfe2a3058|orders-acfe28d7ac9706962304","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"放化疗期间营养支持","category":"化疗","raw":{"name":"放化疗期间营养支持","category":"化疗","summary":"放化疗患者营养不良发生率高（可达40%～80%），营养不良降低治疗耐受性与疗效、增加并发症与病死率。营养支持原则：筛查与评估（NRS2002/PG-SGA）→ 膳食指导与口服营养补充（ONS）→ 肠内营养（EN）→ 肠外营养（PN），遵循“只要肠道能用就用肠道”的阶梯原则。","symptoms":["体重下降（6个月内下降>5%或3个月内>2%为营养不良风险）","食欲减退、早饱、味觉改变（金属味）、进食量减少","放化疗相关症状：口腔黏膜炎、吞咽疼痛、恶心呕吐、腹泻、便秘、口干、放射性肠炎","乏力、肌肉减少（少肌症）、活动能力下降","低蛋白血症（白蛋白<35g/L）、贫血、免疫功能下降与治疗中断增加"],"diagnosis":["营养筛查与评估：NRS2002（入院筛查）、PG-SGA（肿瘤患者专用评估）、BMI与体重变化","人体测量：体重（每周）、BMI、上臂围、三头肌皮褶厚度、握力（肌力评估）","实验室：白蛋白、前白蛋白、转铁蛋白、淋巴细胞计数、血红蛋白、电解质与微量元素","能量与蛋白需求评估：能量25～30kcal/kg/日（应激期可至30～35），蛋白1.2～2.0g/kg/日（肿瘤患者1.2～1.5g/kg/日）","吞咽功能评估（头颈部放疗/食管癌）：吞咽造影或内镜评估误吸风险","营养支持途径评估：胃肠道功能（能否经口/肠内）、有无肠梗阻、吸收功能","膳食调查：24小时膳食回顾，评估实际摄入量（<需求60%持续1周需干预）"],"infusion":["⚠️ 按营养支持途径与病情选择，切勿全部同时使用！","方案1（肠外营养，PN，无法肠内喂养或不足时）：","用法：全合一营养液（葡萄糖+复方氨基酸+中长链脂肪乳+电解质+维生素+微量元素）经中心静脉/外周静脉输注；非蛋白热氮比约100～150:1；监测血糖、电解质、肝肾功能与甘油三酯","方案2（补充性肠外营养，SPN，肠内不足时）：","用法：在肠内营养基础上补充葡萄糖与氨基酸（经外周静脉），补足能量与蛋白缺口","方案3（低蛋白/贫血支持）：","用法：白蛋白 10～20g 静滴（白蛋白<30g/L或有症状者）；蔗糖铁 100mg + 0.9%氯化钠 100ml 静滴（铁缺乏性贫血）；必要时输注红细胞","方案4（电解质与维生素补充）：","用法：10%氯化钾 10～20ml + 0.9%氯化钠 500ml 静滴；维生素C 2g + 复合维生素 静滴 qd；必要时补镁、补磷（再喂养综合征预防）","📌 再喂养综合征预防：重度营养不良者起始热量应为目标的50%（10～15kcal/kg/日），缓慢增加并严密监测血磷、钾、镁。"],"oral_medication":["⚠️ 口服营养补充与对症用药，同类只选一种：","药物1（食欲刺激与消化辅助）：","用法：醋酸甲地孕酮 160mg qd（食欲刺激，注意血栓风险）；复方消化酶 2粒 tid 或 胰酶肠溶胶囊 1～2粒 随餐","药物2（口服营养补充剂ONS）：","用法：整蛋白型/短肽型营养制剂 200～400ml/日（或2～3份/日），两餐之间服用（不替代正餐）","药物3（胃肠道症状对症）：","用法：甲氧氯普胺 10mg tid（恶心、早饱）；蒙脱石散 3g tid（腹泻）；乳果糖 15ml bid（便秘）；益生菌 2粒 bid〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物4（微量元素与维生素）：","用法：复合维生素 1片 qd + 维生素D 800IU/日 + 锌剂（味觉改变者，遵医嘱）","📌 甲地孕酮可致血栓与水肿（有血栓史者慎用）；ONS应选择能量密度高（1.0～1.5kcal/ml）的肿瘤专用配方。"],"treatment":["营养筛查与阶梯干预：NRS2002≥3分或PG-SGA≥4分启动营养干预；遵循『膳食指导+ONS → 肠内营养 → 肠外营养』阶梯原则","膳食指导与ONS：少量多餐（每日6～8餐）、能量密度高的食物、两餐间口服营养补充剂，保证能量与蛋白摄入","肠内营养（EN）：经口不足或吞咽障碍者放置鼻胃管/鼻肠管，或行经皮胃造瘘（PEG，头颈部肿瘤放疗者）；选择合适配方（整蛋白/短肽/疾病专用）并监测耐受性","肠外营养（PN）：肠梗阻、严重黏膜炎、短肠综合征或肠内喂养不足时；全合一配方经中心静脉输注，监测代谢并发症","症状针对性处理：口腔黏膜炎（局部麻醉+口腔护理）、恶心呕吐（止吐方案）、腹泻（洛哌丁胺）、便秘（通便药）、吞咽痛（镇痛+软食）","再喂养综合征防治：重度营养不良者缓慢增加热量（起始10～15kcal/kg/日），监测并补充磷、钾、镁，监测心律","运动与康复：在营养支持基础上配合抗阻运动（每周3次）以维持肌肉量","治疗期监测：每周测体重、每1～2周复查白蛋白与前白蛋白、电解质与血糖；及时调整营养方案"],"management":["体重监测：每周固定时间测体重（同一秤、空腹、相似着装），体重下降>2%/周需强化营养干预","进食量记录：记录每日进食量与ONS摄入量，评估是否达需求（<60%持续1周须升级支持）","肠内营养护理：鼻饲时床头抬高30～45°、输注温度38～40℃、速度由慢到快（起始20～50ml/h），监测腹胀腹泻与胃潴留","肠外营养护理：规范配置与输注（现配现用、定时定量、避免突然停用）、监测血糖与电解质、观察穿刺部位与导管并发症","代谢监测：血糖（每日或隔日）、电解质（钾、磷、镁，尤其再喂养期）、肝肾功能与甘油三酯","口腔与吞咽护理：口腔护理每日2～3次、吞咽功能训练、防误吸（进食坐位、小口慢咽）","心理与家庭支持：解释营养对治疗耐受性的重要性，指导家属准备高能量高蛋白食物与ONS的正确使用"],"notes":["营养支持是肿瘤治疗的重要组成部分：营养不良降低治疗耐受性与疗效、增加并发症与病死率","遵循阶梯原则：能吃就经口（+ONS），不能吃就肠内（EN），肠道不能用才肠外（PN）","肿瘤患者蛋白需求高于普通患者（1.2～1.5g/kg/日），仅靠普通饮食常难以达到，需ONS补充","重度营养不良者开始营养支持时应警惕再喂养综合征（低磷、低钾、低镁与心律失常），需缓慢增加热量并监测电解质","肠外营养不宜长期单独使用（肠黏膜萎缩、肝功能损害、感染风险），应尽早过渡到肠内营养"],"emergency":["严重营养不良者营养支持后出现心律失常、肌无力、意识改变（再喂养综合征）→ 立即查血磷、钾、镁并补充，心电监护","进食或鼻饲后突发呛咳、气促、发热（误吸）→ 立即停止喂养、清理气道、吸氧，评估吸入性肺炎","血糖严重异常（<3.9mmol/L 或 >16.7mmol/L 伴酮症）→ 立即处理并调整营养液配方","肠外营养期间突发气促、胸痛（导管相关血栓/气栓）→ 立即夹闭导管、左侧卧位、吸氧并急诊处理"],"pinyin":"fhlqjyyzc","icd10":"Z51.5","physical_exam":["生命体征：体温、血压、心率、体重与BMI（每周测量）","一般情况：营养状态（消瘦、肌肉萎缩、皮下脂肪减少）、皮肤弹性与水肿（低蛋白）","头颈部：口腔黏膜炎、吞咽功能、唾液分泌（口干）、颈部放疗后皮肤改变","腹部：腹胀、肠鸣音、有无腹水与肝脾肿大（肿瘤负荷）、压痛（放射性肠炎）","四肢与肌肉：上臂围、握力（肌力评估）、下肢水肿（低蛋白）、肌肉量（少肌症评估）","皮肤与毛发：维生素缺乏表现（口角炎、舌炎、皮疹）、脱发","功能状态：ECOG评分、日常活动能力、跌倒风险"],"lab_tests":["白蛋白+前白蛋白+转铁蛋白：营养状态评估（前白蛋白半衰期短，更敏感），每1～2周复查","血常规（血红蛋白、淋巴细胞计数）：贫血与免疫状态评估","电解质（钾、钠、氯、钙、镁、磷）+血糖：肠外营养与再喂养综合征监测（前1～2周每日或隔日）","肝功能+肾功能+甘油三酯：肠外营养代谢并发症监测（每1～2周）","微量元素（锌、硒）+维生素（B12、叶酸、维生素D）：长期营养支持与放疗患者监测","肌酐身高指数+握力：肌肉量与功能评估（少肌症）","24小时膳食回顾+能量摄入计算：评估实际摄入量与需求差距"],"nursing":["体重与进食量监测：每周固定条件测体重，记录每日进食量与ONS摄入，评估达标情况并报告","口服营养护理：少量多餐（每日6～8餐）、高能量高蛋白食物、ONS两餐间服用，观察胃肠耐受性","肠内营养护理：鼻饲床头抬高30～45°、温度38～40℃、速度由慢到快，每4小时监测胃潴留量，防误吸与腹泻","肠外营养护理：规范配置、按时输注、避免骤停；监测血糖与电解质；观察穿刺点与导管情况","口腔与吞咽护理：口腔护理每日2～3次（尤其黏膜炎者）、吞咽功能训练与进食体位指导（防误吸）","宣教与心理支持：解释营养对治疗的重要性、指导家属准备饮食与ONS使用、鼓励记录饮食日记，缓解焦虑"],"diet":["少量多餐（每日6～8餐），每餐量少而能量密度高（如加用橄榄油、坚果碎、奶粉增能）","高蛋白：鱼、瘦肉、蛋、奶、豆制品，必要时用蛋白粉补充（每日1.2～1.5g/kg）","口服营养补充剂（ONS）2～3份/日，两餐之间服用（不影响正餐食欲）","针对症状调整：口腔黏膜炎/吞咽痛→软食流质、温凉、避免酸辣；腹泻→低渣低脂、避免乳制品；便秘→增加纤维与水分；口干→多饮水、汤汁泡饭、酸性食物刺激唾液","避免生冷、不洁食物（免疫力低）；彻底加热食物、水果削皮、不饮生水；忌烟酒"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1373},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"875eb1429098f297a3895cf0aa45bf2a35216ebf616fb28d6eeabc92e313eaa5","pinyin":"fanghualiaoqijianyingyangzhichi","initials":"fhlqjyyzc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","体重下降（6个月内下降>5%或3个月内>2%为营养不良风险）\\n食欲减退、早饱、味觉改变（金属味）、进食量减少\\n放化疗相关症状：口腔黏膜炎、吞咽疼痛、恶心呕吐、腹泻、便秘、口干、放射性肠炎\\n乏力、肌肉减少（少肌症）、活动能力下降\\n低蛋白血症（白蛋白<35g/L）、贫血、免疫功能下降与治疗中断增加",60],["摘要","放化疗患者营养不良发生率高（可达40%～80%），营养不良降低治疗耐受性与疗效、增加并发症与病死率。营养支持原则：筛查与评估（NRS2002/PG-SGA）→ 膳食指导与口服营养补充（ONS）→ 肠内营养（EN）→ 肠外营养（PN），遵循“只要肠道能用就用肠道”的阶梯原则。",30],["疾病编码","Z51.5",30],["原首字母","fhlqjyyzc",60]]},{"id":"orders-d893406ee2a4912373f2","key":"v1-c9ccc21dfe2a3058|orders-d893406ee2a4912373f2","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性腹膜炎（继发性）","category":"胃肠外科","raw":{"name":"急性腹膜炎（继发性）","category":"胃肠外科","summary":"继发性腹膜炎是最常见的腹膜炎类型，由腹腔内脏器穿孔、坏死、破裂或炎症扩散（阑尾炎穿孔、消化道溃疡穿孔、胆囊穿孔、肠坏死、胰腺炎）致细菌与消化液进入腹腔引起。表现为腹痛、腹膜刺激征、发热与脓毒症，多数需急诊手术处理原发病灶。","symptoms":["持续性全腹或局限性剧烈腹痛，变动体位时加重（患者常屈膝侧卧不愿移动）","恶心、呕吐、腹胀，停止排气排便（麻痹性肠梗阻）","腹膜刺激征：压痛、反跳痛、腹肌紧张（板状腹）","发热、心率增快、呼吸急促；重者血压下降、意识改变（脓毒症休克）","腹部叩诊：肝浊音界消失（气腹）、移动性浊音；听诊肠鸣音减弱或消失"],"diagnosis":["立位腹部平片/胸部平片：膈下游离气体提示消化道穿孔","腹部增强CT：首选，明确原发病灶、腹腔积液/积气与脓肿范围","诊断性腹腔穿刺/灌洗：抽出脓性、胆汁样、粪样或血性液体有助定位与病因判断","血常规+CRP+PCT+血培养：评估感染与脓毒症；乳酸与血气分析评估灌注","腹部超声：腹腔积液与胆囊、阑尾等脏器病变评估（可引导穿刺）","肝功能+胆红素+淀粉酶：鉴别胆源性、胰腺炎性病因","血流动力学与器官功能评估：血压、心率、尿量、乳酸（决定手术紧迫性）"],"infusion":["⚠️ 抢救与术前用药，按病情选择！","","方案1（抗感染，覆盖G-杆菌+厌氧菌+肠球菌）：","  用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 头孢哌酮舒巴坦 3g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；重症：美罗培南 1g 静滴 q8h ± 万古霉素〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案2（液体复苏）：","  用法：平衡盐溶液 30ml/kg 快速补液（首个30～60分钟），按血压、尿量与乳酸调整；必要时白蛋白或血制品","","方案3（脓毒症休克）：","  用法：去甲肾上腺素 0.05～0.5μg/kg/min 泵入（维持MAP≥65mmHg，须在充分补液基础上）；氢化可的松 200mg/日（5%GS 50ml；泵入，按体重配）静滴（难治性休克，遵医嘱）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案4（抑酸与支持）：","  用法：艾司奥美拉唑 40mg 静推 q12h；维生素C 2g（NS 100ml 或 5%GS 100ml）静滴 qd；必要时输血〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","📌 抗菌药物使用前留取血培养；腹膜炎治疗核心是『处理原发病灶+引流』，抗生素不能替代手术。"],"oral_medication":["⚠️ 急性期禁食禁水、以静脉用药为主；术后恢复期遵医嘱：","药物1（抗感染序贯）：","用法：阿莫西林克拉维酸 0.625g tid + 甲硝唑 0.4g tid 或 头孢克肟 0.1g bid + 甲硝唑〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（抑酸）：","用法：艾司奥美拉唑 20mg qd〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物3（肠道功能恢复）：","用法：双歧杆菌三联活菌 2粒 bid；莫沙必利 5mg tid（腹胀、肠功能恢复慢者）〔调 ★ 消化道出血/穿孔/梗阻禁用；QT延长者慎用〕","药物4（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时；塞来昔布 200mg qd（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 术后肠功能恢复后逐步进食；避免过早进食加重腹胀与吻合口负担。"],"treatment":["急诊手术（主要治疗）：处理原发病灶（穿孔修补、阑尾/胆囊切除、坏死肠段切除、胆道引流），彻底冲洗腹腔并放置引流","液体复苏与器官支持：快速补液纠正低血容量，必要时血管活性药、机械通气与CRRT","抗感染：早期足量静脉给药覆盖肠道菌群，据培养调整，疗程7～14天（依病灶控制情况）","非手术治疗（严格选择）：原发性腹膜炎、局限性腹膜炎已形成包裹、病情轻且病灶已控制者——禁食、胃肠减压、抗感染、补液观察","引流与脓肿处理：术后腹腔脓肿经皮穿刺引流；引流管保持通畅并记录性状","营养支持：早期肠外营养，肠功能恢复后尽早肠内营养","并发症处理：腹腔脓肿、肠瘘、切口感染、粘连性肠梗阻、多器官功能障碍"],"management":["严密监测：生命体征每1～2小时、尿量（目标≥0.5ml/kg/h）、乳酸、腹部体征范围变化","禁食与胃肠减压：留置胃管减压，记录引流液性状（血性、咖啡色、粪样需报告）","体位：取半卧位（利于渗液局限与引流，减轻中毒症状），休克者平卧","引流管护理：妥善固定、保持通畅、记录24小时引流量与性状，观察引流口皮肤","抗感染执行：按时给药，观察疗效（体温、白细胞、PCT下降）与药物不良反应","术前准备：快速完成禁食、备皮、备血、留置尿管，做好急诊手术与家属沟通","术后观察：腹痛与腹膜刺激征是否缓解、肠鸣音恢复、排气排便时间、切口愈合情况"],"notes":["继发性腹膜炎多需急诊手术处理原发病灶，抗生素与引流不能替代手术","老年人、糖尿病与免疫抑制患者腹膜刺激征可不典型，须结合影像与炎症指标判断","术中彻底冲洗与充分引流是降低术后腹腔脓肿的关键","术后持续发热与感染指标不降需警惕腹腔脓肿、吻合口瘘与切口感染（复查增强CT）","重症腹膜炎常合并脓毒症与多器官功能障碍，需ICU支持治疗"],"emergency":["全腹压痛反跳痛伴板状腹、血压下降（弥漫性腹膜炎/脓毒症休克）→ 立即抢救并急诊手术","膈下游离气体伴剧烈腹痛（消化道穿孔）→ 急诊手术","引流管引出粪样液体（肠瘘）→ 禁食减压、引流、抗感染，评估手术","腹痛缓解后再次加重伴发热（腹腔脓肿形成）→ 增强CT并穿刺引流"],"pinyin":"jxfmyjx","icd10":"K65.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压、血氧（脓毒症评估）","一般情况：痛苦面容、屈膝侧卧、脱水征、意识状态","腹部视诊：腹胀、腹式呼吸减弱或消失、手术瘢痕、肠型","腹部触诊：压痛与反跳痛范围、腹肌紧张（板状腹）、有无包块","腹部叩诊：肝浊音界消失（气腹）、移动性浊音（腹腔积液）","腹部听诊：肠鸣音减弱或消失（麻痹性肠梗阻）","直肠指检：直肠前壁触痛、盆腔积液或包块（盆腔脓肿）"],"lab_tests":["血常规+CRP+PCT：感染程度评估，治疗中每2～3天复查","血培养×2套+腹腔积液/脓液培养及药敏：抗生素前留取，指导目标治疗","血气分析+乳酸+电解质：组织灌注、酸碱失衡与脓毒症评估","肝功能+胆红素+淀粉酶+脂肪酶：鉴别胆源性、胰腺炎性病因","肾功能+尿量：急性肾损伤监测","腹部增强CT+立位腹部平片：明确原发病灶（穿孔、积液积气）与脓肿范围","凝血功能+D-二聚体+血小板：脓毒症致凝血功能障碍（DIC）评估"],"nursing":["病情观察：每1～2小时监测生命体征、尿量与腹部体征范围，腹痛加剧或范围扩大立即报告","禁食减压护理：保持胃管通畅、记录引流液性状与量，口腔护理每日2～3次","体位与活动：取半卧位利于引流，休克者取休克体位；病情稳定后鼓励床上活动","引流管护理：妥善固定、防止脱出与扭曲，记录引流量与性状，保持引流口清洁","补液与用药护理：快速建立静脉通路，遵医嘱补液与抗感染，观察尿量与电解质","术前准备与心理护理：快速完成术前准备，安抚患者与家属情绪，解释手术必要性"],"diet":["急性期与术后早期严格禁食禁水（胃肠减压）","肠功能恢复（排气/肠鸣音正常）后：从少量温开水→清流质→流质逐步过渡","恢复期：低脂、易消化、高蛋白软食，少量多餐","避免产气食物（牛奶、豆浆、豆类、碳酸饮料）与辛辣刺激、油腻食物","多饮水、多食蔬菜水果与粗纤维食物，保持大便通畅（防便秘增加腹压）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1374},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a683264874ffa4aa7f86c7001f4de5f88a1687098c153da3795bc961d46e596a","pinyin":"jixingfumoyan（jifaxing）","initials":"jxfmy（jfx）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","持续性全腹或局限性剧烈腹痛，变动体位时加重（患者常屈膝侧卧不愿移动）\\n恶心、呕吐、腹胀，停止排气排便（麻痹性肠梗阻）\\n腹膜刺激征：压痛、反跳痛、腹肌紧张（板状腹）\\n发热、心率增快、呼吸急促；重者血压下降、意识改变（脓毒症休克）\\n腹部叩诊：肝浊音界消失（气腹）、移动性浊音；听诊肠鸣音减弱或消失",60],["摘要","继发性腹膜炎是最常见的腹膜炎类型，由腹腔内脏器穿孔、坏死、破裂或炎症扩散（阑尾炎穿孔、消化道溃疡穿孔、胆囊穿孔、肠坏死、胰腺炎）致细菌与消化液进入腹腔引起。表现为腹痛、腹膜刺激征、发热与脓毒症，多数需急诊手术处理原发病灶。",30],["疾病编码","K65.0",30],["原首字母","jxfmyjx",60]]},{"id":"orders-1a06fb80ef19d1b5b7a4","key":"v1-c9ccc21dfe2a3058|orders-1a06fb80ef19d1b5b7a4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"绞窄性肠梗阻","category":"胃肠外科","raw":{"name":"绞窄性肠梗阻","category":"胃肠外科","summary":"绞窄性肠梗阻是肠管因血运障碍（肠扭转、肠套叠、嵌顿疝、粘连带压迫、肠系膜血管栓塞）导致的急性肠梗阻，可在数小时内发展为肠坏死、穿孔与腹膜炎，病死率高，须尽快手术。与单纯性机械性梗阻的区别在于存在肠壁缺血。","symptoms":["腹痛剧烈呈持续性并阵发性加重（单纯梗阻多为阵发性绞痛）","呕吐出现早且频繁，可呕吐血性或咖啡样物（肠管血运障碍）","腹胀不对称（闭襻肠段），可触及压痛性包块（扭转肠段）","呕吐物或肛门排出物为血性（重要警示，提示肠坏死）","发热、心率增快、白细胞升高、乳酸升高；重者休克、意识改变"],"diagnosis":["腹部增强CT（首选）：肠壁强化减弱/消失、肠壁积气（肠壁气肿）、门静脉积气、肠系膜血管异常、闭襻征象","腹部立位平片：肠管扩张与气液平面（不典型者可见'咖啡豆征'、'假肿瘤征'）","腹部超声：肠壁厚度、肠蠕动消失、腹腔积液（可床旁快速评估）","血常规+CRP+PCT+乳酸：白细胞升高、乳酸升高提示肠缺血坏死（关键指标）","D-二聚体+凝血功能：肠系膜血管栓塞与DIC评估","诊断性腹腔穿刺：血性腹腔积液提示肠绞窄坏死","电解质+血气分析：评估脱水、酸碱失衡与灌注"],"infusion":["⚠️ 抢救与术前用药，须尽快手术！","方案1（液体复苏与电解质纠正）：","用法：平衡盐溶液 30ml/kg 快速补液；10%氯化钾 10～20ml + 0.9%氯化钠 500ml 静滴（见尿补钾）；必要时白蛋白或血制品","方案2（抗感染，覆盖肠道菌群）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；或头孢呋辛 1.5g q8h + 甲硝唑〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案3（胃肠减压与抑酸）：","用法：0.9%氯化钠 静滴；艾司奥美拉唑 40mg 静推 q12h〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","方案4（休克支持）：","用法：去甲肾上腺素 0.05～0.5μg/kg/min 泵入（维持MAP≥65mmHg）；必要时输血","📌 绞窄性肠梗阻为外科急症，补液与抗感染为术前准备，不可因等待而延误手术（肠坏死超过6小时不可逆）。"],"oral_medication":["⚠️ 急性期禁食禁水，不宜口服给药；术后恢复期遵医嘱：","药物1（肠道功能恢复）：","用法：双歧杆菌三联活菌 2粒 bid；莫沙必利 5mg tid（腹胀、恢复慢者）〔调 ★ 消化道出血/穿孔/梗阻禁用；QT延长者慎用〕","药物2（抗感染序贯）：","用法：阿莫西林克拉维酸 0.625g tid + 甲硝唑 0.4g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物3（通便，防粘连性梗阻复发）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 术后尽早下床活动，减少腹腔粘连；出现腹痛、腹胀、停止排气排便需及时就诊（粘连性梗阻复发可能）。"],"treatment":["急诊手术：剖腹探查+肠管活力评估（颜色、蠕动、系膜血管搏动），坏死肠段切除吻合，必要时二次探查（24～48小时）","肠扭转复位+固定：如乙状结肠扭转复位后行择期切除固定（复发率高）","嵌顿疝所致：解除嵌顿+疝修补（坏死肠段切除）","肠系膜血管栓塞：取栓/血管重建（血管外科协作），切除坏死肠段","术前准备：快速补液纠正脱水与电解质紊乱、胃肠减压、抗感染、备血","术后支持：ICU监护、器官功能支持（脓毒症）、营养支持（肠外→肠内）","并发症处理：短肠综合征（广泛切除者）、吻合口瘘、腹腔脓肿、肠外瘘","术后随访：粘连性梗阻复发风险，指导饮食与排便管理"],"management":["严密监测：生命体征每30～60分钟、尿量、乳酸、腹部体征与疼痛变化（疼痛加剧与腹膜炎体征提示坏死）","禁食与胃肠减压：保持通畅并记录引流液性状（血性/咖啡样提示肠坏死）","补液与电解质：快速补液并监测电解质与血气，记录24小时出入量","术前准备：迅速完成备血、备皮、留置尿管与胃管，做好急诊手术与家属沟通（术前告知可能需要肠造口）","术后观察：腹痛腹胀缓解、肠鸣音恢复、排气排便时间、引流液性状（粪样提示吻合口瘘）","营养管理：术后早期肠外营养，肠功能恢复后经口或肠内营养（短肽制剂）","活动与康复：术后早期下床活动（减少粘连），短肠综合征者长期营养支持与随访"],"notes":["绞窄性肠梗阻与单纯性梗阻的关键区别是肠壁血运障碍：出现持续剧痛、血性呕吐物/便、发热、白细胞与乳酸升高须急诊手术","肠管缺血超过6小时即可发生不可逆坏死，不可长时间保守观察","术中肠管活力判断困难时可采用『二次探查』策略（24～48小时后再评估）","广泛肠切除可致短肠综合征，需长期肠内/肠外营养支持与随访","老年患者肠系膜血管栓塞风险高（房颤、动脉硬化），出现剧烈腹痛与体征不符须警惕"],"emergency":["持续剧烈腹痛、血性呕吐物或便、腹膜炎体征（肠坏死）→ 立即急诊手术","腹胀不对称伴压痛性包块（肠扭转）→ 急诊手术复位","休克伴乳酸明显升高（肠坏死致脓毒症）→ 立即抢救并急诊手术","腹部立位平片见'咖啡豆征'或CT示肠壁积气/门静脉积气 → 急诊手术（肠坏死征象）"],"pinyin":"jzxcgg","icd10":"K56.2","physical_exam":["生命体征：体温、脉搏、呼吸、血压（休克评估）","一般情况：痛苦面容、脱水征、意识状态","腹部视诊：腹胀（可不对称）、胃肠型与蠕动波、手术瘢痕","腹部触诊：压痛部位与范围、反跳痛与肌紧张、压痛性包块（扭转肠段）","腹部叩诊：鼓音（肠管扩张）、移动性浊音（腹腔渗液）、肝浊音界","腹部听诊：肠鸣音亢进伴气过水声（早期）或减弱消失（绞窄晚期/肠麻痹）","直肠指检：指套染血（肠坏死出血）或触及包块"],"lab_tests":["乳酸+血气分析：乳酸升高提示肠缺血坏死（关键动态指标），每2～4小时复查","血常规+CRP+PCT：白细胞与感染指标，绞窄时显著升高","电解质（钾、钠、氯）+肾功能：呕吐与脱水致电解质紊乱，术前必查","腹部增强CT：首选，评估肠壁强化、肠壁积气、门静脉积气与血管情况","腹部立位平片：肠管扩张、气液平面、'咖啡豆征'（肠扭转）","凝血功能+D-二聚体+血型+交叉配血：术前准备与血管栓塞评估","诊断性腹腔穿刺（必要时）：血性积液提示肠绞窄"],"nursing":["病情观察：每30～60分钟评估腹痛性质与程度、腹部体征、呕吐物性状与生命体征，异常立即报告","禁食减压护理：保持胃管通畅、记录引流液（血性/咖啡样提示坏死），口腔护理每日2次","补液护理：快速建立两条静脉通路，遵医嘱补液与补钾，记录出入量与尿量","术前准备：迅速完成备皮、备血、留置尿管，做好急诊手术准备与术前宣教（可能行肠造口）","术后护理：观察腹痛腹胀缓解情况、引流液性状、肠鸣音与排气排便；鼓励早期下床活动","健康宣教：少食多餐、充分咀嚼、避免暴饮暴食与餐后剧烈运动；出现腹痛腹胀及时就诊"],"diet":["急性期严格禁食禁水（胃肠减压）","术后肠功能恢复（排气）后：少量温开水→清流质→流质逐步过渡","恢复期：低渣、低脂、易消化软食，少量多餐，避免暴饮暴食与餐后剧烈运动","避免产气食物（牛奶、豆类、碳酸饮料）与粗糙高纤维食物（早期）","短肠综合征者：少量多餐、低渣低脂、补充维生素B12与脂溶性维生素，遵医嘱营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1375},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4d0bb06f45d103463a7f59644a23bf9adcb520eea73b82cf36777814c8bf013d","pinyin":"jiaozhaixingchanggengzu","initials":"jzxcgz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹痛剧烈呈持续性并阵发性加重（单纯梗阻多为阵发性绞痛）\\n呕吐出现早且频繁，可呕吐血性或咖啡样物（肠管血运障碍）\\n腹胀不对称（闭襻肠段），可触及压痛性包块（扭转肠段）\\n呕吐物或肛门排出物为血性（重要警示，提示肠坏死）\\n发热、心率增快、白细胞升高、乳酸升高；重者休克、意识改变",60],["摘要","绞窄性肠梗阻是肠管因血运障碍（肠扭转、肠套叠、嵌顿疝、粘连带压迫、肠系膜血管栓塞）导致的急性肠梗阻，可在数小时内发展为肠坏死、穿孔与腹膜炎，病死率高，须尽快手术。与单纯性机械性梗阻的区别在于存在肠壁缺血。",30],["疾病编码","K56.2",30],["原首字母","jzxcgg",60]]},{"id":"orders-384f55bfc83f4a22891c","key":"v1-c9ccc21dfe2a3058|orders-384f55bfc83f4a22891c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"腹腔间隔室综合征","category":"胃肠外科","raw":{"name":"腹腔间隔室综合征","category":"胃肠外科","summary":"腹腔间隔室综合征（ACS）是腹腔内压（IAP）持续升高（>20mmHg）并伴新发器官功能障碍的危重状态，多见于重症胰腺炎、腹部创伤、大面积烧伤、腹腔感染与大量液体复苏后。IAP升高致膈肌上抬（呼吸衰竭）、肾血流下降（少尿/无尿）、心输出量下降与肠道缺血，病死率高，需紧急减压。","symptoms":["腹部高度膨隆、腹壁紧张发亮、按压僵硬（'板状腹'样但为张力性）","呼吸困难、气道压升高、低氧血症与高碳酸血症（膈肌上抬）","少尿或无尿（肾灌注下降，早期即可出现）","心率增快、血压下降、中心静脉压升高（心输出量下降）","肠道缺血表现：腹胀、肠鸣音消失、消化道出血、乳酸升高"],"diagnosis":["腹内压测量（膀胱压法）：最常用，IAP>12mmHg为腹内高压（IAH），>20mmHg伴器官功能障碍为ACS（分级Ⅰ～Ⅳ）","器官功能评估：尿量（<0.5ml/kg/h）、气道峰压、氧合指数、心输出量与乳酸","腹部CT：腹腔积液、肠管扩张、腹壁紧张、下腔静脉受压（'圆腹征'）","床旁超声：腹腔积液与肠管扩张、下腔静脉变异度","血气分析+乳酸：呼吸衰竭与组织灌注评估","肾功能+电解质：少尿与急性肾损伤评估","腹部X线：肠管扩张、膈肌上抬"],"infusion":["⚠️ 抢救用药，须在ICU监护下进行！","方案1（液体管理，限制性复苏）：","用法：限制晶体液（避免加重水肿），平衡盐溶液按需；高渗盐水（3%氯化钠 100～150ml 静滴）或白蛋白/利尿剂（呋塞米 20～40mg 静推）促进液体排出〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","方案2（镇痛镇静与肌松）：","用法：芬太尼 0.05mg 静推后泵入；咪达唑仑 2～5mg 静推后泵入；必要时维库溴铵 0.1mg/kg 静推（降低腹壁张力，短期）","方案3（器官支持）：","用法：去甲肾上腺素 0.05～0.5μg/kg/min 泵入（维持MAP≥65mmHg）；必要时CRRT（肾替代与液体清除）","方案4（抗感染，腹腔感染/脓毒症）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 美罗培南 1g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","📌 避免过量液体复苏（加重腹内高压）；及时胃肠减压、引流腹腔积液与经皮穿刺减压可降低IAP。"],"oral_medication":["⚠️ 危重期不宜口服给药；恢复期遵医嘱：","药物1（肠道功能恢复）：","用法：莫沙必利 5mg tid 或 甲氧氯普胺 10mg tid（腹胀、肠麻痹）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物2（通便）：","用法：乳果糖 15ml bid；必要时甘油灌肠剂〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（营养补充）：","用法：口服营养补充剂 1～2份/日（恢复期）；胰酶制剂（胰腺炎后）","📌 恢复期需长期随访肾功能与营养状态；避免暴饮暴食与大量补液。"],"treatment":["非手术减压：胃肠减压（鼻胃管/肛管）、腹腔积液引流（超声引导穿刺）、限制液体、利尿、镇痛镇静与肌松","体位与护理：床头抬高≤30°（过高增加IAP），避免腹部加压包扎","经皮穿刺引流：腹腔大量积液时超声引导下置管引流（可显著降低IAP）","手术减压（开腹减压术）：IAP>25mmHg伴器官功能障碍、非手术减压无效时，行剖腹探查减压+临时关腹（Bogota袋、负压封闭引流）","器官功能支持：机械通气（高气道压者调整参数）、CRRT（少尿/无尿）、循环支持","病因治疗：重症胰腺炎（抑酶、肠内营养）、腹腔感染（引流+抗感染）、出血（止血）","临时关腹与二期缝合：待腹内高压缓解、器官功能改善后（一般3～7天）行二期关腹","并发症防治：肠缺血坏死、切口疝（二期关腹后）、感染与脓毒症"],"management":["腹内压监测：每4～6小时（危重者每1～2小时）测膀胱压并记录，评估分级与趋势","器官功能监测：每小时尿量（目标≥0.5ml/kg/h）、气道压、氧合、乳酸与血流动力学","减压护理：保持胃肠减压与腹腔引流管通畅，记录引流量与性状；避免腹部加压（松解腹带）","液体管理：严格记录出入量，限制晶体液，遵医嘱利尿或CRRT，监测电解质","体位与镇静：床头抬高≤30°，按医嘱镇痛镇静与肌松，评估镇静深度（RASS）","术前/术后护理（开腹减压）：观察减压后尿量与呼吸改善、临时关腹敷料渗液与感染征象","营养支持：早期肠外营养，肠功能恢复后尽早肠内营养（监测腹内压变化）"],"notes":["ACS的诊断依据『腹内压>20mmHg + 新发器官功能障碍』，单纯腹内高压（IAH）不等于ACS","膀胱压测量是最简便可靠的IAP监测方法，危重患者应常规监测","过量液体复苏是IAP升高的重要医源性因素，应遵循限制性液体策略并尽早清除多余液体","非手术减压无效且出现器官功能恶化时应果断开腹减压，延迟手术病死率显著升高","临时关腹后需计划性二期关腹，避免强行缝合导致IAP再次升高"],"emergency":["腹内压>20mmHg伴少尿、气道压升高与低氧（器官功能障碍）→ 立即非手术减压，无效则急诊开腹减压","腹内压>25mmHg伴休克或乳酸明显升高（肠缺血）→ 急诊开腹减压","腹胀迅速加重伴呼吸困难与气道压骤升 → 立即减压并评估机械通气调整","腹腔引流管引出大量血液或肠内容物（出血/肠瘘）→ 急诊处理"],"pinyin":"fqjgxzhz","icd10":"K65.9","physical_exam":["生命体征：血压、心率、呼吸频率与形态、血氧（呼吸衰竭与休克）","腹部视诊：高度膨隆、腹壁紧张发亮、皮肤张力性水疱、静脉扩张","腹部触诊：全腹张力增高（僵硬但非炎性板状腹）、压痛、有无包块","腹部叩诊：鼓音（肠管扩张）、移动性浊音（腹腔积液）","腹部听诊：肠鸣音减弱或消失（肠麻痹/肠缺血）","呼吸系统：呼吸动度减弱（膈肌上抬）、呼吸音减弱、气道压升高","肾功能相关：尿量（尿袋/尿管记录）、下肢与颜面水肿（液体负荷）"],"lab_tests":["腹内压（膀胱压）测定：每4～6小时，分级评估（Ⅰ级12～15、Ⅱ级16～20、Ⅲ级21～25、Ⅳ级>25mmHg）","血气分析+乳酸：呼吸衰竭（高碳酸血症）与组织灌注（乳酸升高）评估，每4～6小时","肾功能+电解质+尿量：急性肾损伤评估（每小时尿量记录）","血常规+CRP+PCT+血培养：感染与脓毒症评估","肝功能+白蛋白+凝血功能：多器官功能障碍评估","腹部CT/床旁超声：腹腔积液、肠管扩张、下腔静脉受压与下腔静脉变异度","心肌酶+BNP：心脏受累与容量状态评估（必要时）"],"nursing":["腹内压监测：按时测量膀胱压并记录（危重者每1～2小时），发现升高立即报告","减压护理：保持胃管、肛管与腹腔引流管通畅，记录引流量与性状；松解腹带等加压物","液体管理：严格记录24小时出入量，遵医嘱限制晶体液、利尿或CRRT，监测电解质","器官功能观察：每小时尿量、呼吸频率与血氧、气道压、意识与乳酸变化","体位护理：床头抬高≤30°，避免压迫腹部与增加腹压的操作，协助翻身（避免屈曲腹部）","心理与家属沟通：病情危重，及时沟通病情与治疗方案，配合完成知情同意"],"diet":["急性期严格禁食禁水（胃肠减压），全肠外营养支持","腹内压下降、肠功能恢复后尽早肠内营养（鼻空肠管，缓慢滴注并监测腹内压）","限制液体与钠盐摄入（配合液体管理），避免加重水肿","恢复期高蛋白、高热量、易消化饮食，少量多餐","避免产气食物与暴饮暴食；胰腺炎患者长期低脂饮食、禁酒"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1376},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c8908a2564281f66937511e7fbf038478b116c3d30b7b950149aca5e605596a2","pinyin":"fuqiangjiangeshizonghezheng","initials":"fqjgszhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹部高度膨隆、腹壁紧张发亮、按压僵硬（'板状腹'样但为张力性）\\n呼吸困难、气道压升高、低氧血症与高碳酸血症（膈肌上抬）\\n少尿或无尿（肾灌注下降，早期即可出现）\\n心率增快、血压下降、中心静脉压升高（心输出量下降）\\n肠道缺血表现：腹胀、肠鸣音消失、消化道出血、乳酸升高",60],["摘要","腹腔间隔室综合征（ACS）是腹腔内压（IAP）持续升高（>20mmHg）并伴新发器官功能障碍的危重状态，多见于重症胰腺炎、腹部创伤、大面积烧伤、腹腔感染与大量液体复苏后。IAP升高致膈肌上抬（呼吸衰竭）、肾血流下降（少尿/无尿）、心输出量下降与肠道缺血，病死率高，需紧急减压。",30],["疾病编码","K65.9",30],["原首字母","fqjgxzhz",60]]},{"id":"orders-a6b1351f9f721573a496","key":"v1-c9ccc21dfe2a3058|orders-a6b1351f9f721573a496","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"股疝","category":"疝与腹壁外科","raw":{"name":"股疝","category":"疝与腹壁外科","summary":"股疝是腹腔内脏器经股环、股管向卵圆窝突出形成的疝，多见于中年以上经产妇（女性占多数）。股环狭小、周围韧带坚韧，股疝极易嵌顿与绞窄（嵌顿率可达40%以上），一经确诊应尽早手术（McVay修补或补片修补，多经腹股沟或腹腔镜入路）。","symptoms":["腹股沟韧带下方卵圆窝处半球形包块，多较小、不易回纳","局部胀痛或坠胀感，久站或用力后加重","嵌顿：包块变硬、疼痛加剧伴恶心呕吐、腹胀（肠梗阻）","部分患者以急性肠梗阻为首发表现（无明确包块主诉，易漏诊）","绞窄：发热、心率增快、腹膜刺激征与休克"],"diagnosis":["体格检查：卵圆窝处包块（腹股沟韧带下方、耻骨结节外下方），咳嗽冲击感不明显（股环狭小）","腹股沟区超声：明确疝内容物与疝环位置，鉴别淋巴结肿大、脂肪瘤、大隐静脉曲张结节","腹部CT（含Valsalva）：肥胖、复发或拟腹腔镜手术者，明确解剖与内容物","腹部立位平片：嵌顿伴肠梗阻时可见气液平面","血常规+CRP+乳酸：嵌顿/绞窄时白细胞与乳酸升高","鉴别诊断：腹股沟斜疝（位于韧带上方、可入阴囊）、大隐静脉曲张、淋巴结炎、脂肪瘤"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时，补片修补者必用）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（嵌顿/绞窄术前）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；平衡盐溶液 500～1000ml 静滴补液〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案3（术后支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；老年患者注意补液速度","","📌 股疝嵌顿风险高，确诊后应尽早择期手术；嵌顿/绞窄者急诊手术。"],"oral_medication":["⚠️ 术后用药，按医嘱选择：","药物1（镇痛）：","用法：塞来昔布 200mg qd 或 洛索洛芬钠 60mg tid（餐后）〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（通便，防腹压增高）：","用法：乳果糖 15ml bid〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（镇咳，慢性咳嗽者）：","用法：复方甲氧那明 2粒 tid 或 氨溴索 30mg tid〔调 妊娠早期禁用；胃溃疡者慎用〕","📌 术后避免用力排便、剧烈咳嗽与提重物1～3个月（防复发）。"],"treatment":["手术治疗（唯一有效方法）：经腹股沟入路（McVay修补：将腹股沟韧带与耻骨梳韧带缝合）或用补片行无张力修补","腹腔镜修补（TAPP/TEP）：适用于双侧、复发或需探查对侧者，注意股环的关闭","嵌顿疝：手法复位（嵌顿<4～6小时、无绞窄）后择期手术；失败或疑绞窄者急诊手术","绞窄疝：急诊手术，切除坏死肠管（感染情况下不做补片修补）","术前优化：控制慢性咳嗽、便秘与前列腺增生，减重，控制血糖","术后并发症处理：血清肿（多自行吸收）、慢性疼痛（神经痛处理）、切口感染（换药引流，必要时取补片）","随访：术后1个月复查，观察有无复发与慢性疼痛"],"management":["术前准备：完善检查、控制咳嗽与便秘、备皮、术前排空膀胱","术后体位与活动：麻醉清醒后取平卧位，术后6小时可下床轻度活动，避免过早剧烈活动","切口与局部观察：观察渗血、渗液、红肿与局部肿胀（血清肿）","腹压管理：避免剧烈咳嗽、用力排便与提重物，必要时用镇咳通便药","疼痛评估与处理：评估疼痛评分，遵医嘱镇痛，术后持续疼痛者评估神经痛","出院指导：保持切口清洁干燥、术后1～3个月避免重体力劳动、按时复查、复发及时就诊"],"notes":["股疝虽小但嵌顿率最高（可达40%以上），且易以急性肠梗阻为首发表现，女性急腹症患者应常规检查卵圆窝","股疝不会自愈，疝气带无效且增加嵌顿风险，确诊后应尽早手术","嵌顿疝手法复位成功率低（股环狭小），多需急诊手术","绞窄时感染风险高，不宜放置补片（可用组织修补）","老年女性患者常合并便秘与慢性咳嗽，术后需同步治疗以减少复发"],"emergency":["卵圆窝包块不能回纳伴腹痛呕吐（嵌顿）→ 急诊手术","发热、腹膜刺激征、乳酸升高（绞窄坏死）→ 立即急诊手术","以急性肠梗阻就诊且检及卵圆窝包块 → 按嵌顿疝急诊手术处理","手法复位后腹痛加重（假性复位）→ 立即手术探查"],"pinyin":"gs","icd10":"K41.3","physical_exam":["生命体征：体温、脉搏、血压（嵌顿/绞窄评估）","一般情况：年龄、生育史、慢性咳嗽与便秘史、BMI","站立位视诊：卵圆窝处（腹股沟韧带下方、耻骨结节外下方）包块，多较小呈半球形","卧位触诊：包块能否回纳、质地、压痛、疝环（股环）大小与位置","咳嗽冲击感：股疝多不明显（与斜疝鉴别）","腹部检查：有无腹胀、肠型与腹膜刺激征（合并肠梗阻）","对侧与腹股沟区：有无双侧疝、腹股沟斜疝或直疝并存"],"lab_tests":["血常规+CRP：术前基线，嵌顿时白细胞升高","乳酸+血气分析：嵌顿/绞窄时乳酸升高提示肠缺血坏死","电解质+肾功能：呕吐致脱水与电解质紊乱","腹部立位平片：合并肠梗阻时可见气液平面","腹股沟区超声/腹部CT：明确疝内容物、疝环与有无肠壁缺血（CT灵敏度高）","凝血功能+心电图+胸片：术前常规（老年患者心肺评估）","血糖+糖化血红蛋白：糖尿病患者术前控糖"],"nursing":["术前护理：评估嵌顿风险与症状，控制咳嗽与便秘，术前排空膀胱、备皮","嵌顿观察：观察包块大小、质地、疼痛与腹部症状（腹痛、呕吐、腹胀），异常立即报告","术后体位与活动：平卧位、麻醉清醒后6小时下床轻度活动，避免剧烈活动与提重物","切口观察：注意渗血渗液与局部肿胀（血清肿），保持敷料清洁干燥","腹压管理宣教：避免用力排便、剧烈咳嗽与提重物，必要时用镇咳通便药","出院宣教：术后1～3个月避免重体力劳动，按时复查，出现包块复发或疼痛及时就诊"],"diet":["术前禁食禁水6～8小时","术后6小时可进流质，逐步过渡到半流质、软食、普食","高蛋白、高维生素饮食促进切口愈合","多饮水、多食蔬菜水果与粗纤维，保持大便通畅（防便秘）","忌辛辣刺激与产气食物；老年患者注意控制体重与慢性咳嗽治疗"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1377},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5a81af50687ef5def0e881f62898d662f9480a13defa3f1686359f9eaec81f21","pinyin":"gushan","initials":"gs","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹股沟韧带下方卵圆窝处半球形包块，多较小、不易回纳\\n局部胀痛或坠胀感，久站或用力后加重\\n嵌顿：包块变硬、疼痛加剧伴恶心呕吐、腹胀（肠梗阻）\\n部分患者以急性肠梗阻为首发表现（无明确包块主诉，易漏诊）\\n绞窄：发热、心率增快、腹膜刺激征与休克",60],["摘要","股疝是腹腔内脏器经股环、股管向卵圆窝突出形成的疝，多见于中年以上经产妇（女性占多数）。股环狭小、周围韧带坚韧，股疝极易嵌顿与绞窄（嵌顿率可达40%以上），一经确诊应尽早手术（McVay修补或补片修补，多经腹股沟或腹腔镜入路）。",30],["疾病编码","K41.3",30],["原首字母","gs",60]]},{"id":"orders-47eeeaaf75e831c56288","key":"v1-c9ccc21dfe2a3058|orders-47eeeaaf75e831c56288","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"脐疝与白线疝（成人）","category":"疝与腹壁外科","raw":{"name":"脐疝与白线疝（成人）","category":"疝与腹壁外科","summary":"成人脐疝多因腹壁薄弱（肥胖、多次妊娠、腹水、慢性咳嗽）致腹腔内容物经脐环突出，白线疝（腹上疝）则经腹白线纤维间隙突出。两者均可逐渐增大并发生嵌顿，成人脐疝嵌顿率较高（尤其合并腹水者），确诊后一般建议手术修补（补片无张力修补为主）。","symptoms":["脐部或上腹中线处可复性包块，站立、用力与咳嗽时增大，平卧可回纳","局部胀痛或坠胀感，包块增大时明显；白线疝疼痛常位于上腹正中","嵌顿：包块不能回纳、变硬、疼痛加剧，伴恶心呕吐与腹胀（肠梗阻）","合并腹水者：脐疝可迅速增大、皮肤变薄发亮，破裂风险高（可致腹水外漏）","部分白线疝仅表现为上腹疼痛而无明显包块（易误诊为胃病）"],"diagnosis":["体格检查：脐部/腹白线处包块、能否回纳、疝环大小与压痛（站立位与卧位对比）","腹部超声：明确疝内容物（肠管、网膜）与疝环，鉴别脐部脂肪瘤与脐尿管囊肿","腹部CT（含Valsalva）：肥胖、复发性或多发疝者，明确疝环大小与腹壁缺损范围（术前规划）","腹部立位平片：嵌顿伴肠梗阻时可见气液平面","血常规+CRP+乳酸：嵌顿/绞窄时白细胞与乳酸升高","合并腹水者：肝功能、腹部超声/CT评估腹水与门静脉高压（需先控制腹水再手术）"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（嵌顿/绞窄术前）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；补液（平衡盐溶液 500～1000ml）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案3（肝硬化腹水患者围手术期）：","  用法：白蛋白 10g 静滴（低蛋白/腹水者）；呋塞米 20～40mg 静推 + 螺内酯（利尿，按医嘱）；必要时补充凝血因子〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","方案4（术后支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；镇痛与营养支持","","📌 合并大量腹水者应先控制腹水（利尿、限盐、必要时放腹水+白蛋白）再手术，否则修补失败率高。"],"oral_medication":["⚠️ 术后与合并症用药，按医嘱选择：","药物1（镇痛）：","用法：塞来昔布 200mg qd 或 洛索洛芬钠 60mg tid（餐后）〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（通便）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（利尿，腹水者）：","用法：螺内酯 40mg qd + 呋塞米 20mg qd（按尿量、体重与电解质调整）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","药物4（降门脉压，肝硬化者）：","用法：普萘洛尔 10mg bid 起（按心率调整，遵医嘱）","📌 腹水患者术后应继续控制腹水与腹内压，避免腹压骤增致修补失败。"],"treatment":["手术治疗：疝环较小、缺损<3cm可行单纯缝合修补；缺损>3cm或复发者行补片无张力修补（开放或腹腔镜IPOM）","术前优化：减重、控制慢性咳嗽与便秘、控制腹水（肝硬化患者）、戒烟、控制血糖","嵌顿/绞窄：急诊手术，切除坏死肠管并修补（感染时不用补片）","肝硬化腹水患者：术前控制腹水与改善肝功能，术后加强利尿与白蛋白支持，警惕修补失败与腹水漏","术后管理：腹带加压3个月、避免腹压增高、控制体重","白线疝：小的可缝合修补，多发缺损（Swiss cheese型）需补片修补","并发症处理：血清肿（多自行吸收）、切口感染（换药引流，必要时取出补片）、复发（再次修补）"],"management":["术前准备：控制腹水（肝硬化者）、减重、控制咳嗽与便秘、备皮、术前排空膀胱","术后体位与活动：平卧位、腹带加压，麻醉清醒后6小时可下床轻度活动","切口与腹部观察：观察渗血渗液、局部肿胀与腹围变化（腹水患者警惕腹水漏）","腹压管理：避免剧烈咳嗽、用力排便与提重物，必要时镇咳通便；腹带使用3个月","腹水管理（肝硬化者）：每日测体重与腹围、记录尿量，遵医嘱利尿与补充白蛋白，监测电解质","出院指导：控制体重、戒烟、治疗慢性咳嗽与便秘、按时复查、复发及时就诊"],"notes":["成人脐疝不会自愈，且嵌顿风险随缺损增大而增加（尤其合并腹水者），建议择期手术","合并大量腹水的脐疝修补失败率高，术前应先控制腹水；破裂风险高者需紧急处理","白线疝可仅表现为上腹疼痛而无明显包块，反复上腹痛患者应仔细触诊腹白线","缺损>3cm者应使用补片修补（单纯缝合复发率高）","术后控制腹内压增高因素（咳嗽、便秘、肥胖、腹水）是防复发关键"],"emergency":["脐部包块不能回纳伴剧烈腹痛与呕吐（嵌顿）→ 急诊手术","脐疝皮肤变薄发亮伴渗液（腹水外漏/破裂）→ 立即急诊处理并补充白蛋白与抗感染","发热、腹膜刺激征、乳酸升高（绞窄坏死）→ 立即急诊手术","肝硬化腹水患者脐疝快速增大伴疼痛 → 急诊评估（破裂风险）"],"pinyin":"qsyybxs","icd10":"K42.9","physical_exam":["生命体征：体温、脉搏、血压、体重与腹围（腹水评估）","一般情况：BMI、营养状态、有无慢性咳嗽和便秘、有无肝硬化体征","腹部视诊：脐部/上腹中线包块（大小、形态）、腹壁静脉曲张、腹围、皮肤张力","腹部触诊：包块能否回纳、疝环大小（可容指数）、压痛、腹壁缺损范围；肝脾大小","腹部叩诊：移动性浊音（腹水）、包块叩诊","腹部听诊：肠鸣音（嵌顿时亢进或减弱）","合并症评估：下肢水肿、黄疸、蜘蛛痣（肝硬化）"],"lab_tests":["血常规+CRP：术前基线，嵌顿时白细胞升高","肝功能+白蛋白+胆红素+凝血功能：腹水患者肝储备评估（决定手术时机）","电解质+肾功能：利尿治疗与腹水管理监测","腹部超声/CT（含Valsalva）：明确疝环大小、腹壁缺损范围与疝内容物（术前规划）","乳酸+腹部立位平片：嵌顿/绞窄与肠梗阻评估","血糖+糖化血红蛋白+心电图：术前常规评估（肥胖与老年患者）","腹水检查（必要时）：细胞数、蛋白、SAAG（鉴别门静脉高压性腹水与其他原因）"],"nursing":["术前护理：腹水患者限制钠盐与液体、监测体重腹围与尿量；控制咳嗽与便秘；备皮与术前准备","术后观察：切口渗血渗液、局部肿胀（血清肿）、腹围与体重变化（警惕腹水漏）","腹带使用：术后腹带加压固定3个月，指导正确佩戴与皮肤保护","腹压管理宣教：避免剧烈咳嗽、用力排便与提重物，必要时镇咳通便药","腹水护理（肝硬化者）：每日测体重与腹围、记录尿量，遵医嘱利尿并监测电解质与肾功能","出院宣教：控制体重、戒烟、治疗慢性咳嗽与便秘、按时复查、出现复发或疼痛及时就诊"],"diet":["术前禁食禁水6～8小时","术后6小时进流质，逐步过渡到半流质、软食、普食","腹水患者：严格限制钠盐（每日<2g）、适量限制液体，高蛋白饮食（肝性脑病风险者遵医嘱调整）","多饮水（无腹水者）、多食蔬菜水果与粗纤维，保持大便通畅","控制体重（肥胖是脐疝重要诱因）；忌烟酒与辛辣刺激食物"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1378},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"68646d83d3c70c00003ee6ecf21b30f524a67889fc2797821d80d04e090dee50","pinyin":"qishanyubaixianshan（chengren）","initials":"qsybxs（cr）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","脐部或上腹中线处可复性包块，站立、用力与咳嗽时增大，平卧可回纳\\n局部胀痛或坠胀感，包块增大时明显；白线疝疼痛常位于上腹正中\\n嵌顿：包块不能回纳、变硬、疼痛加剧，伴恶心呕吐与腹胀（肠梗阻）\\n合并腹水者：脐疝可迅速增大、皮肤变薄发亮，破裂风险高（可致腹水外漏）\\n部分白线疝仅表现为上腹疼痛而无明显包块（易误诊为胃病）",60],["摘要","成人脐疝多因腹壁薄弱（肥胖、多次妊娠、腹水、慢性咳嗽）致腹腔内容物经脐环突出，白线疝（腹上疝）则经腹白线纤维间隙突出。两者均可逐渐增大并发生嵌顿，成人脐疝嵌顿率较高（尤其合并腹水者），确诊后一般建议手术修补（补片无张力修补为主）。",30],["疾病编码","K42.9",30],["原首字母","qsyybxs",60]]},{"id":"orders-3207513a08ee2b28ca59","key":"v1-c9ccc21dfe2a3058|orders-3207513a08ee2b28ca59","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"胸部创伤（急诊评估与处理）","category":"胸外科","raw":{"name":"胸部创伤（急诊评估与处理）","category":"胸外科","summary":"胸部创伤是创伤致死的常见原因，可分为危及生命的即刻损伤（气道梗阻、张力性气胸、开放性气胸、连枷胸、心脏压塞、大出血）与潜在致命损伤（食管破裂、膈肌破裂、肺挫伤、心肌挫伤）。处理遵循ATLS原则：气道→呼吸→循环，多数胸部创伤可通过胸腔闭式引流等简单措施处理，仅少数需急诊开胸。","symptoms":["胸痛、呼吸困难、呼吸急促、发绀","咯血、皮下气肿（握雪感）、气管偏移","血压下降、心率增快、颈静脉怒张（心脏压塞/张力性气胸）","胸部伤口（开放伤可见吸吮性伤口）、胸廓畸形与反常呼吸（连枷胸）","合并伤表现：腹部压痛（肝脾破裂）、意识改变（颅脑损伤）、骨盆与四肢骨折"],"diagnosis":["初级评估（ABCDE，ATLS）：气道通畅性、呼吸音与呼吸动度、循环（脉搏、血压、颈静脉）、意识与瞳孔","床旁超声（FAST+eFAST）：快速判断心包积液（心脏压塞）、胸腔积液（血胸）与气胸（肺滑动征消失）","胸部X线：气胸、血胸、肋骨骨折、纵隔增宽（主动脉损伤）、膈肌破裂","胸部增强CT：稳定患者首选，评估肺挫伤、气胸血胸量、肋骨骨折、纵隔与血管损伤","心电图+心肌酶：心肌挫伤与心律失常评估","血气分析+乳酸：低氧血症与组织灌注评估","胸腔闭式引流结果：引流血性液体量（>1500ml或>200ml/h持续3小时提示需开胸探查）"],"infusion":["⚠️ 抢救用药，须在监护下按病情选择！","","方案1（抗休克液体复苏，控制性复苏）：","  用法：平衡盐溶液/0.9%氯化钠 快速补液（晶体为主）；红细胞悬液、新鲜冰冻血浆按1:1:1输注；目标Hb 70～90g/L、收缩压80～90mmHg（活动性出血未控制时避免过度升压）","","方案2（止血辅助）：","  用法：氨甲环酸 1g（NS 100ml 或 5%GS 100ml）静滴（伤后3小时内）；维生素K1 10mg 静滴〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（镇痛与呼吸支持）：","  用法：曲马多 100mg（NS 100ml）静滴 或 氟比洛芬酯 50mg 静滴 q12h（充分镇痛以利于咳嗽排痰）；必要时无创通气","","方案4（抗感染）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（开放性损伤/胸腔引流后）〔调 CrCl<30 减量；青霉素过敏禁用〕","","📌 张力性气胸与心脏压塞需立即穿刺减压，不能等待影像学检查；限制晶体液避免加重肺挫伤。"],"oral_medication":["⚠️ 稳定后遵医嘱，同类只选一种：","药物1（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时 或 塞来昔布 200mg qd；必要时曲马多 50mg〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（化痰排痰）：","用法：氨溴索 30mg tid 或 乙酰半胱氨酸 0.6g tid〔调 妊娠早期禁用；胃溃疡者慎用〕","药物3（抗感染序贯）：","用法：头孢呋辛酯 0.25g bid 或 阿莫西林克拉维酸 0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物4（通便镇咳）：","用法：乳果糖 15ml bid；复方甲氧那明 2粒 tid（干咳明显者）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 充分镇痛是有效排痰与预防肺部感染的关键；肋骨骨折患者应避免抑制呼吸的强效镇静药。"],"treatment":["立即处理危及生命的损伤：气道梗阻（清理气道/气管插管）、张力性气胸（锁骨中线第2肋间粗针穿刺减压）、开放性气胸（凡士林敷料封闭+闭式引流）、连枷胸（镇痛+固定+必要时机械通气）","心脏压塞：床旁超声确诊后立即心包穿刺或急诊开胸（剑突下心包开窗）","大量血胸/进行性血胸：胸腔闭式引流+抗休克；引流>1500ml或>200ml/h持续3小时行开胸探查","肺挫伤：限制液体、充分镇痛排痰、必要时机械通气（小潮气量保护性通气）","食管/膈肌破裂：急诊手术修补（胸腔镜或开胸）","肋骨骨折：多根多处骨折（连枷胸）行胸壁固定或手术内固定","抗感染与破伤风预防（开放性损伤）","并发症处理：脓胸（引流+抗感染）、肺不张与肺炎（排痰+抗感染）、ARDS（保护性通气）"],"management":["按ABC顺序评估与处理，边处理边评估（创伤救治的'黄金十分钟'）","呼吸管理：吸氧、监测血氧与呼吸音，鼓励深呼吸与有效咳嗽，必要时吸痰与无创通气","胸腔闭式引流护理：保持密闭与通畅，观察水封瓶气泡（漏气）与水柱波动，记录引流量与性状（血性、乳糜样）","液体管理：限制晶体液（避免肺挫伤加重肺水肿），监测出入量与尿量","镇痛管理：多模式镇痛（硬膜外/椎旁阻滞+静脉），评估疼痛评分并保证有效咳嗽","合并伤评估：腹部（FAST/CT）、颅脑、脊柱与四肢（避免漏诊）","观察病情变化：呼吸与循环状态、皮下气肿范围、疼痛与腹部体征（迟发性血气胸、膈肌破裂）"],"notes":["胸部创伤处理遵循ATLS的ABCDE原则：气道与呼吸问题优先，多数通过穿刺减压、闭式引流等简单措施即可稳定","张力性气胸与心脏压塞是'立即致命'损伤，必须临床诊断并立即处理，不能等待影像学","限制晶体液是肺挫伤处理的重要原则（过量补液加重肺水肿与呼吸衰竭）","肺挫伤常在伤后24～48小时进展，需动态观察血氧与影像","迟发性血气胸可发生于伤后数小时至数天，需随访胸片"],"emergency":["极度呼吸困难、气管偏移、患侧呼吸音消失伴血压下降（张力性气胸）→ 立即穿刺减压+闭式引流","颈静脉怒张、心音遥远、血压下降（心脏压塞）→ 立即心包穿刺或急诊开胸","胸腔引流>1500ml或>200ml/h持续3小时、血压不稳（进行性血胸）→ 急诊开胸探查","开放性胸壁伤口有吸吮声（开放性气胸）→ 立即封闭伤口并置管引流","呼吸困难加重伴血氧下降（肺挫伤致ARDS）→ 立即机械通气支持"],"pinyin":"xbcsjzpgdycl","icd10":"S29.9","physical_exam":["生命体征：呼吸频率与形态、血氧、心率、血压、意识（ATLS评估）","气道：口腔与气道内有无异物、血液、分泌物与骨折（气道梗阻）","颈部：气管位置（向健侧移位提示张力性气胸/大量血胸）、颈静脉充盈（怒张提示心脏压塞/张力性气胸）、皮下气肿","胸部视诊：胸廓畸形、呼吸动度（双侧对比）、反常呼吸（连枷胸）、开放性伤口与吸吮声","胸部触诊：肋骨压痛与骨擦感、皮下气肿（握雪感）、语颤（减弱提示气胸/血胸）","胸部叩诊与听诊：鼓音（气胸）/浊音（血胸）、呼吸音减弱或消失、心音遥远","合并伤：腹部压痛（肝脾破裂）、骨盆与四肢骨折、脊柱与颅脑损伤"],"lab_tests":["血常规+血型+交叉配血+凝血功能：急查并动态监测血红蛋白，备血（胸部创伤常需输血）","血气分析+乳酸：低氧血症、通气障碍与组织灌注评估","心肌酶（CK-MB、肌钙蛋白）+心电图：心肌挫伤与心律失常评估","床旁超声（FAST+eFAST）：心包积液、胸腔积液与气胸的快速评估（创伤首选）","胸部X线+胸部增强CT：气胸血胸量、肋骨骨折、肺挫伤、纵隔血肿与膈肌破裂","淀粉酶+肝功能：合并腹部损伤评估","尿常规+尿量：组织灌注与泌尿系损伤筛查"],"nursing":["急救护理：配合气道管理与穿刺减压，快速建立静脉通路，遵医嘱补液输血，监测生命体征每5～15分钟","呼吸护理：吸氧、保持气道通畅、鼓励深呼吸与有效咳嗽、协助体位排痰（充分镇痛前提下）","闭式引流护理：保持密闭与通畅、低于胸腔60～100cm，观察气泡与引流量、记录性状，搬动时夹闭","疼痛护理：评估疼痛评分，遵医嘱多模式镇痛（保证有效咳嗽与活动）","并发症观察：呼吸与血氧变化、皮下气肿范围、腹痛（迟发性膈肌破裂/腹腔出血）、发热与引流液浑浊（脓胸）","功能锻炼与宣教：早期活动、呼吸功能锻炼、戒烟、避免剧烈活动与感染，按时复查"],"diet":["急性期禁食禁水（可能急诊手术或需观察），必要时静脉营养","病情稳定后：高蛋白、高热量、高维生素饮食促进创伤修复","多饮水（心功能与液体管理允许下），稀释痰液利于咳出","避免产气食物与辛辣刺激食物；戒烟","贫血者增加含铁与优质蛋白食物（瘦肉、动物肝脏、蛋奶）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1379},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b5a562b21f7b5498c1dc5571cd0fc35c7d4113cda830319b74722e8721283dd9","pinyin":"xiongbuchuangshang（jizhenpingguyuchuli）","initials":"xbcs（jzpgycl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","胸痛、呼吸困难、呼吸急促、发绀\\n咯血、皮下气肿（握雪感）、气管偏移\\n血压下降、心率增快、颈静脉怒张（心脏压塞/张力性气胸）\\n胸部伤口（开放伤可见吸吮性伤口）、胸廓畸形与反常呼吸（连枷胸）\\n合并伤表现：腹部压痛（肝脾破裂）、意识改变（颅脑损伤）、骨盆与四肢骨折",60],["摘要","胸部创伤是创伤致死的常见原因，可分为危及生命的即刻损伤（气道梗阻、张力性气胸、开放性气胸、连枷胸、心脏压塞、大出血）与潜在致命损伤（食管破裂、膈肌破裂、肺挫伤、心肌挫伤）。处理遵循ATLS原则：气道→呼吸→循环，多数胸部创伤可通过胸腔闭式引流等简单措施处理，仅少数需急诊开胸。",30],["疾病编码","S29.9",30],["原首字母","xbcsjzpgdycl",60]]},{"id":"orders-5eba78f1b6a7261841e8","key":"v1-c9ccc21dfe2a3058|orders-5eba78f1b6a7261841e8","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"甲状旁腺功能亢进（外科治疗）","category":"甲状腺乳腺外科","raw":{"name":"甲状旁腺功能亢进（外科治疗）","category":"甲状腺乳腺外科","summary":"甲状旁腺功能亢进（甲旁亢）分原发性（甲状旁腺腺瘤/增生致PTH分泌过多，血钙升高）、继发性（慢性肾病所致低钙刺激PTH升高）与三发性。原发性甲旁亢表现为高钙血症相关症状（骨痛、肾结石、消化道症状）与骨质疏松，手术切除病变甲状旁腺是唯一根治手段。","symptoms":["骨骼系统：骨痛（腰背、四肢）、骨质疏松、病理性骨折、骨囊性变（棕色瘤）","泌尿系统：反复肾结石（肾绞痛、血尿）、多尿、多饮、肾钙化","消化系统：食欲减退、恶心、便秘、腹痛、消化性溃疡、急性胰腺炎","神经精神：乏力、嗜睡、情绪改变、记忆力下降、抑郁","高钙危象（血钙>3.5mmol/L）：恶心呕吐、脱水、意识障碍、心律失常（急症）"],"diagnosis":["血钙（含离子钙）+血磷+碱性磷酸酶：高钙（>2.75mmol/L）伴低磷、ALP升高提示原发性甲旁亢","甲状旁腺激素（PTH）：升高或不被抑制（原发性）；继发性者PTH明显升高伴低钙或正常钙（CKD）","24小时尿钙+尿磷：排除家族性低尿钙性高钙血症（FHH）","颈部超声：定位增大的甲状旁腺（腺瘤多>1cm），术前定位首选","核素显像（99mTc-sestamibi 双时相显像/SPECT-CT）：定位腺瘤（尤其异位甲状旁腺），与超声联合提高准确率","颈部增强CT/MRI：超声与核素定位不一致或复发者","骨密度（DEXA）+肾脏超声/X线：评估骨质疏松、肾结石与骨囊性变；肾功能+肌酐（鉴别继发性）"],"infusion":["⚠️ 围手术期与高钙危象处理用药，切勿全部同时使用！","方案1（高钙危象抢救，血钙>3.5mmol/L）：","用法：0.9%氯化钠 1000～2000ml 静滴（快速补液扩容，首24小时3～4L）；呋塞米 20～40mg 静推 q6～12h（补液后利尿）；唑来膦酸 4mg + 0.9%氯化钠 100ml 静滴（>15分钟）或 帕米膦酸二钠 60～90mg 静滴（抑制骨吸收）；必要时降钙素 4IU/kg 皮下注射 q12h","方案2（术后低钙，饥饿骨综合征）：","用法：10%葡萄糖酸钙 10～20ml + 5%葡萄糖 20ml 缓慢静推（>10分钟，必要时重复）；继以 10%葡萄糖酸钙 30～60ml + 0.9%氯化钠 500ml 静滴维持（监测血钙与心电图QT间期）","方案3（术前准备与支持）：","用法：0.9%氯化钠 静滴（维持充分水化，降低血钙）；维生素D 与钙剂按医嘱","方案4（术后补钙与维生素D）：","用法：0.9%氯化钠 静滴；葡萄糖酸钙 1g + 维生素C 2g 静滴 qd（必要时）","📌 高钙危象补液是关键（禁用噻嗪类利尿剂，可加重高钙）；术后低钙多在24～72小时出现，需密切监测血钙。"],"oral_medication":["⚠️ 术前术后与长期用药，按医嘱选择：","药物1（术前降钙与骨保护）：","用法：碳酸钙 0.6g tid 随餐（继发性甲旁亢降磷用）；西那卡塞 25～50mg qd（继发性/不能手术者，监测血钙）","药物2（术后补钙与维生素D，低钙者）：","用法：碳酸钙D3 600mg bid～tid + 骨化三醇 0.25～0.5μg qd（按血钙调整，饥饿骨综合征需较大剂量，疗程数周至数月）","药物3（骨质疏松治疗）：","用法：阿仑膦酸钠 70mg 每周一次（空腹服后直立30分钟）或 唑来膦酸 5mg 每年一次静滴；碳酸钙D3 600mg qd + 维生素D 800IU/日","药物4（通便与对症）：","用法：乳果糖 15ml bid（高钙致便秘）；必要时镇痛〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 术后低钙可呈'饥饿骨综合征'（持续数周至数月），需按血钙与症状调整补钙剂量并定期复查。"],"treatment":["手术治疗（原发性甲旁亢的根治手段）：单发腺瘤行微创甲状旁腺切除（术中PTH监测，切除后10分钟PTH下降>50%提示成功）；增生者行次全切除或全切+自体移植；甲状旁腺癌行整块切除","手术指征：有症状者（骨、肾、消化道、神经精神）；无症状但血钙>0.25mmol/L超过正常上限、年龄<50岁、骨密度T值<-2.5、肾结石/肾钙化、24小时尿钙明显升高、肌酐清除率下降","术前定位：超声+核素显像联合定位，必要时4D-CT或选择性静脉采血（再手术者）","高钙危象处理：大量补液+利尿+双膦酸盐+降钙素，必要时血液透析（合并肾衰者），监测心电与意识","术后管理：监测血钙（术后24～72小时每6～12小时）、补钙与维生素D（饥饿骨综合征）、监测PTH与肾功能","不能手术者：西那卡塞（拟钙剂）控制血钙，监测血钙与肝功能；充分水化与避免高钙饮食","长期随访：血钙、PTH、肾功能、骨密度（术后1年及此后每1～2年）"],"management":["术前管理：充分水化（鼓励饮水，必要时静脉补液）降低血钙；避免噻嗪类利尿剂、含钙抗酸剂与长期卧床（加重高钙）","术后血钙监测：术后24～72小时内每6～12小时测血钙，观察口周麻木、手足抽搐（低钙）与Chvostek征","术后补钙执行：按血钙与症状调整静脉/口服补钙与骨化三醇剂量，记录剂量与反应","颈部术后观察：颈部肿胀、呼吸、声音与引流（同甲状腺术后护理，警惕血肿压迫气道）","肾脏与骨骼随访：术后评估肾结石与骨密度变化，指导长期钙与维生素D摄入","宣教：遵医嘱补钙与复查（不可自行停药）、充分饮水（防结石）、避免长期卧床与高钙饮食（不能手术者）"],"notes":["原发性甲旁亢常为'偶然发现'（体检血钙升高），典型表现为'骨痛、肾结石、消化道症状与神经精神改变'","高钙危象（血钙>3.5mmol/L）是急症：补液为首要措施，禁用噻嗪类利尿剂","术后低钙（饥饿骨综合征）常见且可持续数周至数月，需充分补钙与活性维生素D并密切监测","术中PTH监测（切除后10分钟下降>50%）可提高手术成功率、减少不必要的双侧探查","继发性甲旁亢（CKD）以药物治疗为主（磷结合剂、活性维生素D、西那卡塞），手术仅用于难治性病例"],"emergency":["血钙>3.5mmol/L伴恶心呕吐、脱水、意识障碍或心律失常（高钙危象）→ 立即大量补液+利尿+双膦酸盐，必要时透析","术后手足抽搐、喉痉挛（重度低钙）→ 立即缓慢静推葡萄糖酸钙并心电监护","术后颈部迅速肿胀伴呼吸困难（血肿压迫气道）→ 立即床旁拆线清除血肿，必要时气管切开","肾绞痛伴少尿（肾结石梗阻）→ 急诊评估并解除梗阻"],"pinyin":"jzpxgnkjwkzl","icd10":"E21.0","physical_exam":["生命体征：血压（高血压常见）、心率与心律（高钙致心律失常）、体重","颈部：有无甲状旁腺区肿块（多不可触及）、甲状腺大小与结节、颈部手术瘢痕","骨骼：骨痛部位（腰背、四肢）、脊柱后凸与身高变化、病理性骨折、骨囊性变（局部膨隆与压痛）","泌尿系统：肾区叩击痛（结石）、多尿与脱水征","神经肌肉：乏力、嗜睡、情绪与认知改变、腱反射、Chvostek征（术后低钙）","消化系统：腹部压痛（胰腺炎/溃疡）、便秘与腹胀","眼科与软组织：带状角膜病变（钙沉积）、皮肤钙化（严重者）"],"lab_tests":["血钙（含离子钙）+血磷+白蛋白（校正血钙）+碱性磷酸酶：诊断与随访核心指标","甲状旁腺激素（PTH）：升高或不被抑制（原发性），与血钙同步评估","24小时尿钙+尿磷+肌酐：鉴别FHH、评估结石风险与肾功能","肾功能（肌酐、肌酐清除率）+电解质（钾、镁）：鉴别继发性甲旁亢与围手术期评估","维生素D（25-羟维生素D）+1,25-二羟维生素D：评估维生素D缺乏与代谢状态","颈部超声+99mTc-sestamibi核素显像（±SPECT-CT）：术前定位（首选联合）","骨密度（DEXA）+肾脏超声/尿路平片：骨质疏松、肾结石与肾钙化评估"],"nursing":["术前护理：鼓励充分饮水（每日2000～3000ml）降低血钙；避免含钙抗酸剂与噻嗪类利尿剂；评估高钙症状","术后血钙监测与观察：术后24～72小时每6～12小时测血钙，观察口周麻木、手足抽搐与Chvostek征，异常立即报告","补钙护理：按医嘱给予静脉/口服钙剂与骨化三醇，记录剂量与反应（葡萄糖酸钙静推速度需缓慢并监测心电图）","颈部术后护理：观察颈部肿胀、呼吸、声音与引流液，床旁备气管切开包（同甲状腺术后）","骨骼与肾脏护理：评估骨痛与活动能力，指导防跌倒（骨质疏松）、充分饮水与低钙饮食宣教","出院宣教：坚持补钙与维生素D（不可自行停药）、定期复查血钙与PTH、出现麻木抽搐立即就诊"],"diet":["术前：充分饮水（每日2000～3000ml）稀释尿钙、预防结石；避免高钙食物（大量牛奶、钙片）与含钙抗酸剂","避免长期卧床（加重骨钙流失与高钙），鼓励适度活动","术后：高钙饮食（牛奶、豆制品、小鱼虾）配合钙剂与维生素D补充（饥饿骨综合征期需求增加）","限制钠盐（减少尿钙排泄）与咖啡因、酒精","肾结石患者：充足饮水、低草酸饮食（避免菠菜、坚果、巧克力）、适量钙摄入（不过度限制）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1380},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4e32941b08ed59001fd18d8ed5738400fa182e5d3c8b3edee7e209193266f901","pinyin":"jiazhuangpangxiangongnengkangjin（waikezhiliao）","initials":"jzpxgnkj（wkzl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","骨骼系统：骨痛（腰背、四肢）、骨质疏松、病理性骨折、骨囊性变（棕色瘤）\\n泌尿系统：反复肾结石（肾绞痛、血尿）、多尿、多饮、肾钙化\\n消化系统：食欲减退、恶心、便秘、腹痛、消化性溃疡、急性胰腺炎\\n神经精神：乏力、嗜睡、情绪改变、记忆力下降、抑郁\\n高钙危象（血钙>3.5mmol/L）：恶心呕吐、脱水、意识障碍、心律失常（急症）",60],["摘要","甲状旁腺功能亢进（甲旁亢）分原发性（甲状旁腺腺瘤/增生致PTH分泌过多，血钙升高）、继发性（慢性肾病所致低钙刺激PTH升高）与三发性。原发性甲旁亢表现为高钙血症相关症状（骨痛、肾结石、消化道症状）与骨质疏松，手术切除病变甲状旁腺是唯一根治手段。",30],["疾病编码","E21.0",30],["原首字母","jzpxgnkjwkzl",60]]},{"id":"orders-2a9098a1ba39b114641b","key":"v1-c9ccc21dfe2a3058|orders-2a9098a1ba39b114641b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肺栓塞（急诊识别与处理）","category":"血管外科","raw":{"name":"肺栓塞（急诊识别与处理）","category":"血管外科","summary":"肺栓塞（PE）是内源性或外源性栓子（多为下肢深静脉血栓）阻塞肺动脉及其分支引起的临床综合征，是静脉血栓栓塞症（VTE）的严重表现形式。典型表现为突发呼吸困难、胸痛、咯血（三联征少见），重者血流动力学不稳定可猝死。按危险分层（高危/中危/低危）决定抗凝、溶栓或介入治疗。","symptoms":["突发呼吸困难（最常见）、呼吸急促（>20次/分）、胸痛（胸膜性或胸骨后）","咯血（肺梗死）、咳嗽、晕厥（大面积PE致心输出量骤降）","心悸、心率增快（>100次/分）、血压下降（高危PE）","下肢深静脉血栓表现：单侧下肢肿胀、疼痛、压痛（提示栓子来源）","体征可与症状不匹配（呼吸困难明显但肺部听诊无明显异常）"],"diagnosis":["临床可能性评分（Wells评分/Geneva评分）：低度可能者先查D-二聚体，高度可能者直接影像学","D-二聚体：阴性（<500ng/ml）在低中度可能者中可排除PE；阳性无特异性（需影像确认）","CT肺动脉造影（CTPA）：首选确诊手段，显示肺动脉充盈缺损","下肢静脉超声：评估DVT（阳性支持诊断并指导治疗）","心脏超声：右心室扩大、肺动脉高压（疑高危PE或血流动力学不稳定者床旁评估）","心电图：窦性心动过速、SⅠQⅢTⅢ、右束支传导阻滞（无特异性）","血气分析+乳酸+BNP/肌钙蛋白：低氧血症、肺泡-动脉氧分压差增大、右心负荷与心肌损伤评估（危险分层）","肺通气/灌注扫描（V/Q）：肾功能不全或造影剂过敏者替代CTPA"],"infusion":["⚠️ 抢救用药，须在监护下按危险分层选择！","方案1（抗凝治疗，非高危PE）：","用法：低分子肝素 0.1ml/10kg 皮下注射 q12h（或依诺肝素 1mg/kg q12h）；或 普通肝素 80U/kg 静推后 18U/kg/h 泵入（监测APTT 1.5～2.5倍）；或 磺达肝癸钠 7.5mg 皮下注射 qd（体重50～100kg）","方案2（溶栓治疗，高危PE即血流动力学不稳定）：","用法：rt-PA 50～100mg 静滴 2小时（或0.6mg/kg，最大50mg，15分钟静推）；或 尿激酶 20000U/kg 静滴 2小时；用药前评估出血风险并备血","方案3（循环支持，高危PE）：","用法：去甲肾上腺素 0.05～0.5μg/kg/min 泵入（维持MAP≥65mmHg）；0.9%氯化钠 500ml 静滴（谨慎补液，避免加重右心负荷）；吸氧/机械通气","方案4（后续过渡抗凝）：","用法：利伐沙班 15mg bid ×21天 → 20mg qd（或阿哌沙班 10mg bid ×7天 → 5mg bid）〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","📌 高危PE溶栓越早越好（症状出现14天内）；溶栓禁忌者行介入取栓或外科取栓；抗凝疗程一般3～6个月（依病因决定）。"],"oral_medication":["⚠️ 抗凝维持与对症用药，按医嘱选择：","药物1（口服抗凝，直接口服抗凝药）：","用法：利伐沙班 20mg qd（餐时服）或 阿哌沙班 5mg bid；或 达比加群 150mg bid（需先静脉抗凝5天）〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","药物2（华法林，需监测INR）：","用法：华法林 3mg qd 起（与肝素重叠5天至INR 2～3，监测INR）〔调 ★ 需监测INR；★ 大量药物食物相互作用；妊娠禁用〕","药物3（镇痛与支持）：","用法：对乙酰氨基酚 0.5g 必要时；必要时吗啡 3～5mg 静推（剧烈胸痛，注意呼吸抑制）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（抗凝拮抗，出血时）：","用法：维生素K1 5～10mg 静推（华法林）；鱼精蛋白（肝素）；依达赛珠单抗 5g 静滴（达比加群）〔调 ★ 需监测INR；★ 大量药物食物相互作用；妊娠禁用〕","📌 抗凝疗程：一过性诱因3个月，特发性或反复发作6个月至长期；肿瘤相关PE建议长期抗凝。"],"treatment":["危险分层与治疗选择：高危（休克/低血压）——溶栓或介入/外科取栓；中危（右心功能不全或心肌损伤但血流动力学稳定）——抗凝+密切监测，恶化时溶栓；低危——抗凝治疗","抗凝治疗：低分子肝素/磺达肝癸钠/普通肝素起始，尽早过渡到口服抗凝（利伐沙班/阿哌沙班/华法林）","溶栓治疗：rt-PA 50～100mg，用于高危PE（发病14天内）；注意出血风险（颅内出血约1%～3%）","介入治疗：导管定向溶栓、机械取栓（溶栓禁忌或失败者）","外科取栓：急诊肺动脉血栓清除术（高危PE伴溶栓禁忌，需体外循环）","下腔静脉滤器：抗凝禁忌、抗凝期间仍发生PE或近端DVT伴高危出血者（临时或永久）","支持治疗：吸氧、循环支持、限制补液（避免加重右心负荷）、镇痛","抗凝疗程与随访：一过性诱因3个月，特发性6个月以上，肿瘤或反复发作长期抗凝；定期评估出血风险与复发"],"management":["绝对卧床与制动：急性期卧床，避免用力、剧烈活动与按摩患肢（防止栓子脱落），病情稳定后逐步活动","生命体征监测：持续心电、血压、血氧监护，高危PE住ICU；观察意识、尿量与乳酸","氧疗与呼吸支持：吸氧维持SpO2>90%，必要时无创/有创机械通气（注意正压通气对右心影响）","抗凝执行与观察：按时给药，观察注射部位、切口、牙龈与皮肤出血征象，监测血小板（警惕HIT）与APTT/INR","出血监测：颅内（意识、瞳孔、头痛）、消化道（黑便、呕血）、泌尿（血尿）与穿刺点，异常立即报告并停抗凝","下肢管理：测量双下肢周径、观察肿胀与疼痛，弹力袜与抬高患肢（DVT患者）","宣教与随访：抗凝疗程与依从性（不可自行停药）、避免创伤与剧烈运动、识别出血与复发症状（呼吸困难、胸痛）"],"notes":["PE的临床表现多样且缺乏特异性，对突发呼吸困难伴低氧、心动过速与下肢肿胀者应高度警惕","高危PE（休克/低血压）需立即溶栓或取栓，不能仅抗凝；溶栓窗口为发病14天内","D-二聚体阴性在低中度临床可能者中可排除PE，高度可能者应直接行CTPA","抗凝期间出现意识改变、头痛、黑便或血尿提示出血（尤其颅内出血），需立即停药并评估","抗凝疗程需个体化：一过性诱因3个月、特发性或反复发作6个月以上、肿瘤相关建议长期抗凝"],"emergency":["突发呼吸困难、低氧伴血压下降或晕厥（高危PE）→ 立即抗凝并启动溶栓（rt-PA），循环支持，转ICU","溶栓后突发头痛、意识障碍、瞳孔不等大（颅内出血）→ 立即停药、急诊头颅CT、输注凝血因子与血小板","抗凝期间出现呕血、黑便或血尿（消化道/泌尿出血）→ 停药、补液、内镜评估与拮抗处理","心脏骤停（大面积PE）→ 立即心肺复苏，考虑溶栓与体外膜肺（ECMO）支持"],"pinyin":"fszbsjzsycl","icd10":"I26.9","physical_exam":["生命体征：呼吸频率与形态、血氧、心率、血压（血流动力学不稳定提示高危）、体温","一般情况：焦虑、烦躁、出汗、晕厥后状态、颈静脉充盈","心脏：心率增快、肺动脉瓣区第二心音亢进（P2>A2）、三尖瓣区收缩期杂音、颈静脉怒张（右心衰）","肺部：呼吸音（可正常，与呼吸困难程度不匹配）、湿啰音（肺梗死）、胸膜摩擦音、喘鸣","下肢：单侧肿胀、周径差（>3cm）、压痛（腓肠肌）、皮温升高、浅静脉扩张（DVT证据）","神经系统：意识状态（晕厥、低氧致意识改变）","皮肤黏膜：发绀、出血点（抗凝后）"],"lab_tests":["D-二聚体：阴性（<500ng/ml）在低中度可能者中可排除PE，需结合临床评分","CT肺动脉造影（CTPA）：确诊首选（肺动脉充盈缺损）","下肢静脉彩色多普勒超声：评估DVT（栓子来源，阳性支持诊断）","血气分析+乳酸：低氧血症（PaO2下降、PCO2下降、肺泡-动脉氧分压差增大）与组织灌注评估","肌钙蛋白+BNP/NT-proBNP：右心心肌损伤与负荷评估（危险分层依据）","心电图：窦性心动过速、SⅠQⅢTⅢ、右束支传导阻滞（每小时或症状变化时复查）","血常规+凝血功能（APTT、INR）+血小板：抗凝治疗基线与监测（警惕HIT）"],"nursing":["急救护理：绝对卧床、吸氧、建立静脉通路，持续心电血压血氧监护，遵医嘱抗凝/溶栓并观察反应","氧疗护理：持续吸氧维持SpO2>90%，观察呼吸频率与形态，必要时配合机械通气","抗凝与溶栓观察：监测穿刺点渗血、牙龈出血、皮肤瘀斑、黑便与血尿；溶栓期间每2～4小时监测凝血指标与意识","下肢护理：测量双下肢周径并记录、抬高患肢、避免按摩与热敷（防栓子脱落），弹力袜使用指导","出血护理：密切观察颅内出血征象（头痛、呕吐、意识改变、瞳孔不等大），发现立即报告并停药","宣教：抗凝疗程与不可自行停药、避免创伤与剧烈运动、识别复发症状（呼吸困难、胸痛）与出血症状、定期复查"],"diet":["急性期：清淡易消化饮食，避免过饱（减轻右心负荷）；必要时禁食（拟溶栓或介入者）","充足饮水（无右心衰与液体限制者），避免脱水致血液黏稠","服用华法林者：稳定摄入维生素K（绿叶蔬菜量保持相对恒定），避免大量变动；限制酒精","低脂饮食、控制体重（肥胖为VTE危险因素），多食蔬菜水果","避免辛辣刺激与咖啡因过量；戒烟"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1381},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3ea7fcbc4f9e508b44a2192000c04c6c2e1edcb6674da3f99481714c1ab00ba5","pinyin":"feishuanse（jizhenshibieyuchuli）","initials":"fss（jzsbycl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发呼吸困难（最常见）、呼吸急促（>20次/分）、胸痛（胸膜性或胸骨后）\\n咯血（肺梗死）、咳嗽、晕厥（大面积PE致心输出量骤降）\\n心悸、心率增快（>100次/分）、血压下降（高危PE）\\n下肢深静脉血栓表现：单侧下肢肿胀、疼痛、压痛（提示栓子来源）\\n体征可与症状不匹配（呼吸困难明显但肺部听诊无明显异常）",60],["摘要","肺栓塞（PE）是内源性或外源性栓子（多为下肢深静脉血栓）阻塞肺动脉及其分支引起的临床综合征，是静脉血栓栓塞症（VTE）的严重表现形式。典型表现为突发呼吸困难、胸痛、咯血（三联征少见），重者血流动力学不稳定可猝死。按危险分层（高危/中危/低危）决定抗凝、溶栓或介入治疗。",30],["疾病编码","I26.9",30],["原首字母","fszbsjzsycl",60]]},{"id":"orders-11f4fe029a37fb91c9c3","key":"v1-c9ccc21dfe2a3058|orders-11f4fe029a37fb91c9c3","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肛瘘（手术与术后管理）","category":"肛肠外科","raw":{"name":"肛瘘（手术与术后管理）","category":"肛肠外科","summary":"肛瘘是肛管直肠与肛周皮肤之间的异常通道，多由肛周脓肿破溃或切开引流后形成，按Parks分型为括约肌间型、经括约肌型、括约肌上型与括约肌外型。治疗以手术为主（瘘管切开、挂线、LIFT、肛瘘栓），关键是彻底清除瘘管同时保护肛门功能（避免大便失禁），术后换药与坐浴是愈合的关键。","symptoms":["肛周反复流脓、渗液（脓液、粪水或气体），有异味，内裤常有污渍","肛周硬结或条索状管道，按压有分泌物流出","局部疼痛（外口闭合时可形成脓肿致剧痛）","外口周围皮肤湿疹、瘙痒与色素沉着（长期分泌物刺激）","全身症状少；复杂肛瘘或急性感染期可有发热"],"diagnosis":["肛门视诊与指检：外口位置、数目、分泌物性状；指检可触及条索状瘘管与内口硬结（Goodsall规则判断瘘管走行）","肛门镜/直肠镜：寻找内口（齿线附近肛窦）、排除直肠病变与肿瘤","经肛门超声/磁共振（MRI）：复杂肛瘘（高位、多发、复发）术前评估瘘管走行、与括约肌关系及有无脓腔（MRI为首选）","瘘管造影/X线造影：必要时评估瘘管走行（已较少用）","血常规+CRP：急性感染期评估","鉴别诊断：克罗恩病肛瘘（需肠镜与病理）、结核性肛瘘、肛管癌、化脓性汗腺炎、藏毛窦"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","方案1（术前预防性抗感染，切皮前0.5～1小时）：","用法：头孢呋辛 1.5g 静滴 + 甲硝唑 0.5g 静滴；或头孢曲松 2g 静滴 + 甲硝唑〔调 CrCl<30 减量；青霉素过敏禁用〕","方案2（急性感染期/复杂肛瘘）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（按病情与药敏调整）〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案3（术后支持）：","用法：0.9%氯化钠/葡萄糖 静滴；维生素C 2g 静滴 qd（促进创面愈合）","方案4（克罗恩病相关肛瘘，生物制剂）：","用法：英夫利西单抗 5mg/kg 静滴（0、2、6周诱导后每8周维持，消化科指导）","📌 肛瘘治疗以手术为核心，抗生素不能替代手术；克罗恩病肛瘘需药物（生物制剂）与手术联合，避免损伤括约肌。"],"oral_medication":["⚠️ 术后与恢复期用药，按医嘱选择：","药物1（抗感染序贯）：","用法：阿莫西林克拉维酸 0.625g tid + 甲硝唑 0.4g tid（疗程5～7天）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（通便，避免便秘与硬便损伤创面）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd（保持每日1～2次软便）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时；塞来昔布 200mg qd（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（局部用药）：","用法：复方角菜酸酯栓 1枚 纳肛 bid；痔疮膏/生肌玉红膏 外用（换药后）","📌 术后保持排便通畅与创面引流通畅是关键；避免用力排便与久坐（影响愈合）。"],"treatment":["肛瘘切开术：低位肛瘘（括约肌间型、低位经括约肌型）直接切开瘘管（敞开引流、二期愈合）","挂线疗法（seton）：高位经括约肌型或括约肌上型，用挂线缓慢切割（保护括约肌功能），可分期手术","LIFT术（括约肌间瘘管结扎术）：保留括约肌的术式，适用于经括约肌型肛瘘","肛瘘栓/纤维蛋白胶封堵：微创、保留括约肌，但成功率较低（复发率较高）","直肠黏膜瓣推进术：高位复杂肛瘘或克罗恩病肛瘘","术后处理：创面开放引流、每日坐浴（1:5000高锰酸钾，2～3次/日）、换药（由内向外）、保持引流通畅","克罗恩病肛瘘：控制肠道炎症（生物制剂±免疫抑制剂）+引流（避免急诊手术损伤括约肌）","并发症处理：创面愈合延迟（查克罗恩病、结核、糖尿病）、肛门狭窄（定期扩肛）、复发（再次手术）、大便失禁（括约肌损伤，需评估与康复）"],"management":["术后创面护理：每日换药1～2次（由内向外），观察创面肉芽生长与分泌物，保持引流通畅（避免外口过早闭合致复发）","坐浴指导：每日温水/1:5000高锰酸钾坐浴2～3次（每次15～20分钟，水温40℃），便后追加一次","排便管理：保持每日1～2次软便（乳果糖等），避免便秘与腹泻；便后温水清洗并坐浴","饮食管理：多饮水、高纤维饮食（恢复后）、忌辛辣与酒类；克罗恩病患者按炎症性肠病饮食要求","疼痛与活动：充分镇痛；避免久坐与久蹲，术后早期避免剧烈运动与重体力劳动","引流与挂线护理：挂线患者按医嘱定期收紧（一般每1～2周），观察挂线处疼痛与分泌物","随访：术后1～2周复查评估创面愈合，之后每2～4周复查至愈合；复发者重新评估（MRI）"],"notes":["肛瘘治疗的核心是『彻底清除瘘管+保护肛门功能』，高位瘘管切忌盲目切开（可致大便失禁）","术前MRI/超声评估瘘管与括约肌关系是选择术式的关键（复杂肛瘘必查）","肛周脓肿切开引流后约50%形成肛瘘，需二期手术处理（急性期不做肛瘘根治术）","术后创面由内向外愈合是防止复发的关键（外口过早闭合可致脓肿复发）","反复发作或愈合不良的肛瘘需排除克罗恩病、结核与糖尿病（影响愈合）"],"emergency":["肛周红肿剧痛伴发热（脓肿形成）→ 急诊切开引流（急性期不做肛瘘根治术）","肛周大量出血（创面出血）→ 压迫止血、必要时缝合或电凝止血","创面感染扩散伴会阴部广泛红肿、皮肤发黑（坏死性筋膜炎）→ 急诊广泛清创+抗感染","术后剧烈疼痛伴排尿困难（创面水肿/肛管痉挛）→ 镇痛、坐浴与导尿处理"],"pinyin":"glssySHgl","icd10":"K60.3","physical_exam":["生命体征：体温（急性感染）、脉搏、血压","肛周视诊：外口位置与数目、分泌物性状（脓性、粪水、气体）、周围皮肤湿疹与色素沉着、手术瘢痕","肛周触诊：条索状瘘管走行（Goodsall规则）、硬结与压痛、有无脓腔","直肠指检：内口位置（齿线附近肛窦硬结与压痛）、括约肌张力（评估功能）、有无直肠肿物","肛门镜/直肠镜：观察内口与直肠黏膜（排除肿瘤与炎症）","括约肌功能评估：嘱患者收缩肛门，评估张力（术前基线，重要）","克罗恩病相关体征：口腔溃疡、腹痛与腹块、肛周皮赘与溃疡、肠外表现（关节、皮肤）"],"lab_tests":["血常规+CRP：急性感染期与术后感染监测","肛周MRI（复杂/复发肛瘘首选）+经肛门超声：评估瘘管走行、内口位置、与括约肌关系及脓腔","肠镜+病理（疑克罗恩病）：评估肠道炎症与病变范围（反复肛瘘、伴腹泻腹痛者必查）","结核相关检查（PPD、T-SPOT、胸部影像，疑结核性肛瘘）：排除结核","血糖+糖化血红蛋白：糖尿病影响创面愈合（反复不愈者必查）","分泌物细菌培养+药敏：复杂或反复感染时（指导抗生素）","肛门直肠测压（必要时）：括约肌功能评估（高位瘘管术前）"],"nursing":["创面护理：每日换药1～2次、由内向外清洁，观察肉芽与分泌物，保持引流通畅（防外口过早闭合）","坐浴护理：每日温水/高锰酸钾坐浴2～3次（40℃、15～20分钟），便后追加；观察创面情况","排便管理：指导保持软便（遵医嘱用乳果糖），便后清洗坐浴；避免用力排便与久蹲","疼痛与体位护理：评估疼痛评分并镇痛；指导侧卧位减轻肛周受压，避免久坐","挂线护理：观察挂线处疼痛与分泌物，按医嘱协助定期收紧，记录创面变化","健康宣教：多饮水、多纤维饮食（恢复期）、忌辛辣与酒；保持肛周清洁干燥；按时复查；出现肛周肿痛及时就诊"],"diet":["术后早期：清淡易消化、低渣饮食（减少排便刺激），多饮水","恢复期：高纤维饮食（蔬菜、水果、粗粮）保持大便通畅，高蛋白促进创面愈合","严格忌辛辣刺激食物与酒类（刺激肛门直肠充血、影响愈合）","避免坚硬粗糙、油炸与产气食物；避免暴饮暴食与腹泻","克罗恩病患者：按炎症性肠病饮食要求（低渣、易消化、必要时肠内营养）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1382},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2038d88ea48b95ac08f6750bbf9a61c9c319e6710b28f8a6e95bc00df824330b","pinyin":"ganglou（shoushuyushuhouguanli）","initials":"gl（ssyshgl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肛周反复流脓、渗液（脓液、粪水或气体），有异味，内裤常有污渍\\n肛周硬结或条索状管道，按压有分泌物流出\\n局部疼痛（外口闭合时可形成脓肿致剧痛）\\n外口周围皮肤湿疹、瘙痒与色素沉着（长期分泌物刺激）\\n全身症状少；复杂肛瘘或急性感染期可有发热",60],["摘要","肛瘘是肛管直肠与肛周皮肤之间的异常通道，多由肛周脓肿破溃或切开引流后形成，按Parks分型为括约肌间型、经括约肌型、括约肌上型与括约肌外型。治疗以手术为主（瘘管切开、挂线、LIFT、肛瘘栓），关键是彻底清除瘘管同时保护肛门功能（避免大便失禁），术后换药与坐浴是愈合的关键。",30],["疾病编码","K60.3",30],["原首字母","glssySHgl",60]]},{"id":"orders-18353deb638ef1a9beee","key":"v1-c9ccc21dfe2a3058|orders-18353deb638ef1a9beee","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"睾丸扭转（急诊处理）","category":"泌尿外科","raw":{"name":"睾丸扭转（急诊处理）","category":"泌尿外科","summary":"睾丸扭转是精索扭转致睾丸血供中断的泌尿外科急症，多见于青少年（12～18岁高发，新生儿期亦可见）。扭转超过6小时睾丸存活率显著下降，超过12小时多坏死。表现为突发患侧睾丸剧痛伴恶心呕吐，须立即手术探查与复位固定（对侧睾丸同时固定）。","symptoms":["突发患侧睾丸（阴囊）剧烈疼痛，可向下腹、腹股沟或大腿内侧放射","恶心、呕吐、面色苍白、出汗（反射性，易误诊为急腹症）","阴囊肿胀、触痛明显，睾丸位置上抬（横位）或抬高试验（Prehn征）阴性","提睾反射消失（患侧，重要体征）","新生儿/婴幼儿表现为哭闹不安、拒奶、阴囊红肿发硬（易漏诊）"],"diagnosis":["体格检查：睾丸位置（上抬/横位）、触痛、提睾反射消失、Prehn征（抬高阴囊疼痛不缓解）","彩色多普勒超声（首选）：患侧睾丸血流信号减少或消失（敏感性高，但不能因等待检查延误手术）","核素扫描（必要时）：血流灌注减少（诊断准确但耗时，紧急情况不推荐）","尿常规：多正常（与附睾炎鉴别，后者可有白细胞）","血常规+CRP：多正常或轻度升高（附睾炎常升高）","鉴别诊断：急性附睾炎（更多见于成人、发热、尿路感染表现、血流增多）、睾丸附件扭转、嵌顿疝、精索静脉曲张、睾丸肿瘤出血"],"infusion":["⚠️ 急诊术前用药与镇痛，切勿全部同时使用！","","方案1（镇痛）：","  用法：曲马多 100mg（NS 100ml）静滴 或 氟比洛芬酯 50mg 静滴；剧痛者哌替啶 50mg 肌注（诊断明确后）","","方案2（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案3（补液与止吐）：","  用法：0.9%氯化钠 静滴；甲氧氯普胺 10mg 静推（呕吐明显者）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","","方案4（术前支持与电解质纠正）：","  用法：平衡盐溶液 500～1000ml 静滴（呕吐脱水者）；必要时补钾（见尿补钾）","","📌 睾丸扭转是急症，确诊或高度怀疑时应立即手术探查（不因等待超声而延误）；扭转过久者需行睾丸切除。"],"oral_medication":["⚠️ 术后用药，按医嘱选择：","药物1（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时 或 塞来昔布 200mg qd（餐后）；必要时曲马多 50mg〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（抗感染序贯）：","用法：头孢呋辛酯 0.25g bid 或 阿莫西林克拉维酸 0.625g tid（疗程3～5天）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物3（消肿）：","用法：地奥司明片 2片 bid 或 迈之灵 2片 bid（阴囊水肿）","药物4（通便）：","用法：乳果糖 15ml bid〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 术后需长期随访睾丸发育与生育功能（尤其青春期患者），并告知扭转复发与对侧固定情况。"],"treatment":["急诊手术探查（金标准）：阴囊切口探查，扭转复位后观察睾丸血运（温盐水湿敷、利多卡因封闭精索），血运恢复者行双侧睾丸固定术（3点固定）；坏死无血运者行睾丸切除+对侧固定","手术时机：发病6小时内手术睾丸存活率高（>90%），超过12小时多坏死（存活率<10%）","手法复位（暂无手术条件时的临时措施）：向外侧方向旋转复位（不能替代手术，复位后仍需手术固定）","新生儿睾丸扭转：多已坏死，行睾丸切除+对侧固定（保留的可能性极低）","术后处理：阴囊托高、冷敷减轻水肿、镇痛（布洛芬 5-10mg/kg 口服 q6-8h）与抗感染（头孢呋辛 1.5g 静滴 q12h），观察阴囊肿胀与切口","生育与内分泌功能评估：术后长期随访（精液分析、性激素水平），尤其单侧切除者","对侧预防性固定：所有病例均应对侧固定（解剖异常多为双侧，复发风险高）"],"management":["时间管理：确诊或高度怀疑后立即联系手术室与麻醉，缩短术前等待（缺血时间与睾丸存活直接相关）","疼痛与术前护理：禁食禁水、镇痛、建立静脉通路、备皮、做好急诊手术准备与家属沟通（告知可能切除睾丸）","术后阴囊护理：阴囊托高（软垫/阴囊托）、术后24～48小时冷敷减轻水肿，观察肿胀与渗血","切口观察：注意渗血、渗液与红肿，保持敷料清洁干燥","活动指导：术后1～2周避免剧烈运动与重体力劳动，避免骑跨动作与久坐","心理护理与宣教：向患者与家属解释手术必要性（尤其是睾丸切除者），缓解焦虑与对生育的担忧","随访：术后1个月复查，评估睾丸大小与血运；青春期患者长期随访睾丸发育与生育功能"],"notes":["睾丸扭转是泌尿外科急症：缺血6小时内手术睾丸存活率>90%，超过12小时多坏死","提睾反射消失与Prehn征阴性是重要体征；彩色多普勒超声有助诊断但不得延误手术","所有病例均须行双侧睾丸固定（解剖异常多为双侧，对侧复发风险高）","青少年突发睾丸剧痛伴恶心呕吐易误诊为急腹症（阑尾炎、肾绞痛），须常规检查阴囊","新生儿阴囊红肿发硬需警惕睾丸扭转（多已坏死），应及时评估"],"emergency":["青少年突发睾丸剧痛伴提睾反射消失（疑似扭转）→ 立即急诊手术探查（不等待检查）","睾丸扭转复位后血运不恢复、睾丸发黑（坏死）→ 行睾丸切除+对侧固定","术后阴囊迅速肿胀伴剧痛与渗血（血肿）→ 急诊评估并处理","新生儿阴囊红肿发硬 → 急诊超声与手术评估"],"pinyin":"gwnz","icd10":"N44","physical_exam":["生命体征：体温（附睾炎可有发热）、脉搏、血压（疼痛应激）","一般情况：痛苦面容、强迫体位、恶心呕吐、年龄（青少年高发）","阴囊视诊：患侧肿胀、皮肤发红或发亮、睾丸位置（上抬、横位）","阴囊触诊：睾丸压痛、质地、位置与轴向，附睾有无肿大与压痛","提睾反射：患侧消失（与对侧对比，重要体征）","Prehn征：抬高阴囊疼痛不缓解（与附睾炎鉴别，后者抬高后疼痛减轻）","腹部检查：有无腹膜刺激征（排除急腹症）；腹股沟区有无包块（嵌顿疝）"],"lab_tests":["彩色多普勒超声（首选）：患侧睾丸血流信号减少或消失（急诊首选，但不能延误手术）","尿常规：多正常（附睾炎常有白细胞与脓尿）","血常规+CRP：扭转多正常或轻度升高，附睾炎常升高","必要时核素扫描：血流灌注减少（准确但耗时，紧急时不推荐）","性激素（LH、FSH、睾酮）+精液分析：术后长期随访（生育与内分泌功能）","肿瘤标志物（AFP、hCG、LDH）：排除睾丸肿瘤（中老年或睾丸肿块者）","凝血功能+心电图：术前常规评估"],"nursing":["急诊护理：快速完成术前准备（禁食禁水、备皮、备血），建立静脉通路，遵医嘱镇痛与补液","时间意识：明确记录发病时间与手术开始时间（缺血时间直接影响睾丸存活），配合加快流程","术后阴囊护理：阴囊托高、冷敷（24～48小时）、观察肿胀与渗血，保持敷料清洁","疼痛与活动护理：评估疼痛评分并镇痛；指导术后1～2周避免剧烈运动、骑跨与久坐","心理护理：青少年患者与家长焦虑明显（尤其睾丸切除者），需耐心解释手术必要性、对侧固定与随访计划","健康宣教：告知复发与对侧扭转风险（已固定）、随访睾丸发育与生育功能、出现阴囊疼痛立即就诊"],"diet":["术前禁食禁水6～8小时","术后6小时可进流质，逐步过渡到半流质、软食、普食","高蛋白、高维生素饮食促进切口愈合","多饮水、多食蔬菜水果，保持大便通畅（避免用力排便增加腹压与疼痛）","忌辛辣刺激与酒类；避免产气食物（减轻腹胀不适）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1383},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7f5a9fdcc04b141622301086a59e1afa91e773c73d2fb332fe261e596606841e","pinyin":"gaowanniuzhuan（jizhenchuli）","initials":"gwnz（jzcl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发患侧睾丸（阴囊）剧烈疼痛，可向下腹、腹股沟或大腿内侧放射\\n恶心、呕吐、面色苍白、出汗（反射性，易误诊为急腹症）\\n阴囊肿胀、触痛明显，睾丸位置上抬（横位）或抬高试验（Prehn征）阴性\\n提睾反射消失（患侧，重要体征）\\n新生儿/婴幼儿表现为哭闹不安、拒奶、阴囊红肿发硬（易漏诊）",60],["摘要","睾丸扭转是精索扭转致睾丸血供中断的泌尿外科急症，多见于青少年（12～18岁高发，新生儿期亦可见）。扭转超过6小时睾丸存活率显著下降，超过12小时多坏死。表现为突发患侧睾丸剧痛伴恶心呕吐，须立即手术探查与复位固定（对侧睾丸同时固定）。",30],["疾病编码","N44",30],["原首字母","gwnz",60]]},{"id":"orders-b383de50d0cef26deb59","key":"v1-c9ccc21dfe2a3058|orders-b383de50d0cef26deb59","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"锁骨骨折","category":"骨科","raw":{"name":"锁骨骨折","category":"骨科","summary":"锁骨骨折多由跌倒时肩部着地或手撑地所致，是最常见的骨折之一，中1/3最多见。多数无明显移位者可行保守治疗（8字绷带/锁骨带或前臂吊带），移位明显、短缩>2cm、粉碎性或合并神经血管损伤者需手术（钢板或髓内钉内固定）。","symptoms":["肩部疼痛、肿胀、压痛（锁骨中段最明显），上肢活动受限","患侧肩部下垂并向前内倾斜，健手托扶患侧肘部（典型姿势）","局部畸形与骨擦感，可触及骨折端","皮下瘀斑（伤后数天出现）","合并损伤：臂丛神经损伤（上肢麻木无力）、锁骨下血管损伤（血肿、脉搏减弱）、气胸（少见）"],"diagnosis":["锁骨正位X线（必要时加照上倾位）：诊断与分型（中1/3、远端、近端），评估移位与短缩","锁骨CT（含三维重建）：粉碎性骨折、远端骨折或术前规划","神经血管检查：上肢感觉、肌力、桡动脉搏动与末梢循环（排除合并损伤）","胸部X线：疑合并气胸、血胸或多发肋骨骨折时","血常规+凝血功能+心电图：术前评估（老年患者）","骨密度（老年患者）：骨质疏松评估与治疗依据"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时，手术者）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（镇痛）：","  用法：氟比洛芬酯 50mg（NS 100ml）静滴 q12h 或 曲马多 100mg 静滴 必要时","","方案3（消肿）：","  用法：七叶皂苷钠 10mg + 0.9%氯化钠 250ml 静滴 qd","","方案4（支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；老年患者补充钙剂（葡萄糖酸钙 1g + 维生素C 2g 静滴 qd）","","📌 保守治疗者需注意8字绷带/锁骨带的松紧（过紧影响腋部血运与神经，过松失去固定作用）。"],"oral_medication":["⚠️ 按病情与术后用药，同类只选一种：","药物1（镇痛）：","用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（消肿）：","用法：地奥司明片 2片 bid 或 迈之灵 2片 bid","药物3（抗骨质疏松，老年患者）：","用法：碳酸钙D3 600mg qd + 骨化三醇 0.25μg qd","药物4（神经营养，合并神经损伤）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid","📌 保守治疗期间严格佩戴固定装置4～6周，复查X线确认位置（防再次移位）。"],"treatment":["保守治疗（无移位或轻度移位）：8字绷带/锁骨带或前臂吊带固定4～6周，早期做腕肘与手指活动，禁忌过早抬肩","手术指征：骨折短缩>2cm、移位明显、粉碎性骨折（有刺破皮肤风险）、合并神经血管损伤、漂浮肩（同侧肩胛颈骨折）、患者要求快速恢复（如运动员）","手术方式：切开复位钢板内固定（首选）或髓内钉固定；远端骨折可用钩钢板或喙锁韧带重建","术后康复：术后1～2周开始钟摆运动与被动活动，逐步过渡到主动活动（4～6周），3个月后逐步力量训练","并发症处理：骨折不愈合（手术植骨）、畸形愈合（影响功能者截骨矫形）、内固定物刺激（取出）、神经血管损伤（评估与修复）","老年患者：同时抗骨质疏松治疗与防跌倒宣教"],"management":["固定装置护理：8字绷带/锁骨带松紧适宜（能插入1～2指），观察腋部皮肤、上肢血运与手指麻木（过紧需调整）","体位与活动：半卧位或平卧（肩下垫软枕使肩后展），避免侧卧压迫患侧；患肢用前臂吊带悬吊","疼痛管理：评估疼痛评分并镇痛，翻身与活动时托扶患肢减少疼痛","神经血管观察：每小时（早期）观察手指颜色、温度、毛细血管充盈、桡动脉搏动与感觉运动","功能锻炼指导：固定期间做手指、腕、肘关节活动与握拳，避免抬肩与上肢负重","随访：固定后1周、2周、4周复查X线；术后2周、6周、3个月复查评估愈合与功能"],"notes":["锁骨骨折多数可通过保守治疗获得良好愈合，手术主要用于移位明显、短缩>2cm或合并神经血管损伤者","8字绷带固定的效果依赖正确使用与松紧适宜，需定期复查与调整（肿胀消退后易变松）","复位后1周内复查X线很重要（移位加重需及时改手术）","保守治疗期间禁忌过早抬肩与上肢负重（可致骨折再移位）","老年患者合并骨质疏松，应同时启动抗骨质疏松治疗以防再骨折"],"emergency":["患肢麻木无力、桡动脉搏动减弱（臂丛或锁骨下血管损伤）→ 急诊血管神经评估与手术探查","骨折端刺破皮肤（开放性骨折）→ 急诊清创、抗感染与手术固定","合并气胸或血胸（呼吸困难、血氧下降）→ 急诊胸部评估与处理","固定装置过紧致手指发凉麻木（腋部压迫）→ 立即松解并评估血运"],"pinyin":"sgz","icd10":"S42.0","physical_exam":["生命体征：血压、心率、呼吸（合并多发伤评估）","姿势与视诊：患侧肩下垂内倾、健手托肘、局部肿胀与畸形、皮下瘀斑、开放性伤口","触诊：锁骨压痛与骨擦感、骨折端位置、皮下气肿（合并气胸）","神经检查：上肢感觉（腋神经、桡神经、正中神经、尺神经）、肌力、握力","血管检查：桡动脉搏动、毛细血管充盈、上肢皮温与颜色","肩关节活动：主动与被动活动受限程度（疼痛所致）","合并伤评估：肋骨骨折、肩胛骨骨折、气胸、颈椎损伤"],"lab_tests":["锁骨正位X线（必要时上倾位）：诊断、分型与复查（复位前后对比）","锁骨CT+三维重建：粉碎性骨折、远端骨折与术前规划","血常规+凝血功能+肝肾功能+心电图：术前评估（老年患者心肺评估）","骨密度（DEXA）+血钙磷+25-羟维生素D：老年患者骨质疏松评估","胸部X线/CT：疑合并气胸、血胸或肋骨骨折时","肌电图/神经传导（必要时）：合并神经损伤评估","血糖+糖化血红蛋白：糖尿病患者（影响愈合与感染风险）"],"nursing":["固定护理：观察8字绷带/锁骨带松紧（能插入1～2指）、腋部皮肤受压与上肢血运，过紧立即报告调整","体位护理：半卧位或平卧（肩下垫枕使肩后展），避免侧卧压迫患侧；患肢前臂吊带悬吊","神经血管观察：每小时观察手指颜色、温度、毛细血管充盈、桡动脉搏动与感觉运动","疼痛护理：评估疼痛评分并遵医嘱镇痛，移动时托扶患肢","功能锻炼指导：固定期间手指、腕、肘主动活动与握拳；禁止抬肩与上肢负重","健康宣教：按时复查X线（1周、2周、4周）、保持固定装置清洁、注意防跌倒（老年患者）"],"diet":["高蛋白、高钙、高维生素饮食促进骨折愈合（牛奶、鱼虾、豆制品、绿叶蔬菜）","适量补充维生素D（晒太阳、深海鱼、蛋黄）","多饮水、多食蔬菜水果与粗纤维，保持大便通畅（防便秘）","控制体重与血糖；老年患者按骨质疏松要求补钙","戒烟限酒（吸烟显著延缓骨折愈合）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1384},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7dba999696864515e3a4602aaec67e9e32a924d293afe848537159f4b7aaf4a1","pinyin":"suoguguzhe","initials":"sggz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肩部疼痛、肿胀、压痛（锁骨中段最明显），上肢活动受限\\n患侧肩部下垂并向前内倾斜，健手托扶患侧肘部（典型姿势）\\n局部畸形与骨擦感，可触及骨折端\\n皮下瘀斑（伤后数天出现）\\n合并损伤：臂丛神经损伤（上肢麻木无力）、锁骨下血管损伤（血肿、脉搏减弱）、气胸（少见）",60],["摘要","锁骨骨折多由跌倒时肩部着地或手撑地所致，是最常见的骨折之一，中1/3最多见。多数无明显移位者可行保守治疗（8字绷带/锁骨带或前臂吊带），移位明显、短缩>2cm、粉碎性或合并神经血管损伤者需手术（钢板或髓内钉内固定）。",30],["疾病编码","S42.0",30],["原首字母","sgz",60]]},{"id":"orders-bad2d3335fafc150d158","key":"v1-c9ccc21dfe2a3058|orders-bad2d3335fafc150d158","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"膝关节骨关节炎（全膝关节置换）","category":"骨科","raw":{"name":"膝关节骨关节炎（全膝关节置换）","category":"骨科","summary":"膝关节骨关节炎是中老年最常见的退行性关节病，表现为膝关节疼痛、僵硬与活动受限。治疗遵循阶梯原则：基础治疗（减重、运动、物理治疗）→ 药物治疗（NSAIDs、关节腔注射）→ 手术治疗（关节镜、截骨、全膝关节置换TKA）。TKA适用于终末期病变、疼痛严重影响生活且保守治疗无效者。","symptoms":["膝关节疼痛（负重与上下楼梯时加重，休息后减轻），可有夜间痛","关节僵硬（晨起或久坐后起步困难，活动后缓解，一般<30分钟）","关节活动受限（屈伸范围减小），下蹲困难","关节肿胀、摩擦感（骨摩擦音）、畸形（膝内翻或外翻）","病程晚期：关节不稳、行走困难、肌肉萎缩与生活质量显著下降"],"diagnosis":["膝关节X线（负重正位+侧位+髌骨轴位）：关节间隙变窄、骨赘形成、软骨下骨硬化与囊性变（Kellgren-Lawrence分级）","膝关节MRI（必要时）：评估软骨、半月板与韧带（X线不典型或疑合并损伤）","膝关节功能评分（HSS、WOMAC、KSS）：术前评估与疗效评价","血常规+CRP+血沉+类风湿因子+抗CCP抗体：排除感染性关节炎与类风湿关节炎","关节液检查（必要时）：细胞数、结晶（排除痛风与感染）","双下肢全长X线：评估下肢力线（畸形程度，术前规划）","骨密度+心肺功能评估（老年患者）：术前风险评估"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴；过敏者克林霉素 0.6g 或万古霉素 1g〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（氨甲环酸减少出血，术前/术中）：","  用法：氨甲环酸 1g（NS 100ml 或 5%GS 100ml）静滴（切皮前15～30分钟）或 1～2g 关节腔内注射（关闭切口前）；必要时术后3小时追加1g〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（术后镇痛）：","  用法：氟比洛芬酯 50mg（NS 100ml）静滴 q12h；曲马多 100mg 静滴 必要时；必要时静脉镇痛泵（多模式镇痛）","","方案4（抗凝预防VTE）：","  用法：低分子肝素 0.4ml 皮下注射 qd（术后12～24小时开始，疗程10～14天，可延长至35天）；或利伐沙班 10mg qd〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","","📌 氨甲环酸可显著减少TKA出血与输血需求；所有患者均需VTE预防（药物+物理）。"],"oral_medication":["⚠️ 术后与长期用药，按医嘱选择：","药物1（镇痛）：","用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg；注意与抗凝药合用的出血风险〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（抗凝序贯）：","用法：利伐沙班 10mg qd（术后35天，按医嘱）或 阿司匹林 100mg qd（替代方案）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","药物3（钙与维生素D）：","用法：碳酸钙D3 600mg qd + 维生素D 800IU/日","药物4（通便）：","用法：乳果糖 15ml bid（术后卧床与阿片类致便秘）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 术后避免NSAIDs与抗凝药大剂量合用（出血风险）；糖尿病与高血压患者围手术期需控制基础病。"],"treatment":["阶梯治疗：基础治疗（减重、股四头肌与臀中肌力量训练、有氧运动、物理治疗、支具）→ 药物治疗（外用/口服NSAIDs、关节腔注射玻璃酸钠或糖皮质激素）→ 手术","全膝关节置换（TKA）指征：中重度疼痛影响睡眠与日常活动、保守治疗无效、X线示关节间隙明显消失（K-L 3～4级）、畸形（内/外翻>10°）或关节不稳","手术方式：后稳定型（PS）或后交叉韧带保留型（CR）假体；骨水泥固定为标准；双侧病变可分期或同期置换（评估风险）","围手术期管理（ERAS）：术前宣教与功能训练、氨甲环酸减少出血、多模式镇痛、早期下床（术后6～24小时）、早期功能锻炼","术后康复：术后第1天开始踝泵、股四头肌等长收缩与被动屈伸；逐步过渡到主动活动与步行（助行器→手杖→独立行走），争取6周内屈膝≥90°、伸直0°","并发症处理：深静脉血栓（抗凝+物理预防）、感染（假体周围感染需清创或二期翻修）、僵硬（麻醉下手法松解或关节镜）、神经血管损伤、假体周围骨折","长期随访：术后6周、3个月、6个月、1年复查（X线与功能评分），之后每年或每2年；假体寿命一般15～20年"],"management":["术前准备：宣教（手术流程、康复计划）、功能训练（踝泵、股四头肌训练）、控制基础病（血糖、血压）、戒烟、皮肤准备（防感染）","术后体位与制动：患肢抬高（垫软枕，膝下勿垫高枕以防屈曲挛缩）、必要时用CPM机辅助屈伸","切口与引流观察：观察渗血、渗液与引流量，保持敷料清洁干燥；警惕假体周围感染（持续渗液、发热）","疼痛管理：多模式镇痛（神经阻滞+静脉+口服），评估疼痛评分（疼痛控制好是早期活动的前提）","早期活动：术后6～24小时坐起与床边站立，术后第1～2天助行器下地行走；每日康复训练（屈伸、直腿抬高、步态训练）","VTE预防执行：药物抗凝+间歇充气加压装置+踝泵运动，观察下肢肿胀与疼痛（DVT/PE）","出院指导：继续康复训练（每日3～4次）、避免深蹲与跪姿、控制体重、按时复查；警惕感染征象（红肿热痛、发热）"],"notes":["膝关节骨关节炎治疗应遵循阶梯原则，TKA仅用于终末期病变且保守治疗无效者","围手术期VTE预防是必需的（药物+物理），髋膝关节置换术后DVT风险高","早期功能锻炼（术后24小时内开始）是获得良好关节活动度的关键，延迟康复易致关节僵硬","假体周围感染是最严重的并发症（发生率1%～2%），需注意口腔与皮肤感染灶的处理（术前牙科治疗）","肥胖患者应先减重（BMI>40者术后并发症与假体磨损风险显著升高）"],"emergency":["术后突发呼吸困难、胸痛、血氧下降（肺栓塞）→ 立即抢救、抗凝或溶栓，转ICU","切口大量渗液伴发热与关节红肿热痛（急性假体周围感染）→ 急诊关节穿刺培养+抗感染，评估清创","术后患肢肿胀迅速加重伴剧痛、足背动脉搏动减弱（血管损伤/骨筋膜室综合征）→ 急诊评估处理","膝关节屈伸时突发剧痛伴畸形（假体周围骨折/脱位）→ 急诊影像与处理"],"pinyin":"gjygjyqxjzgz","icd10":"M17.9","physical_exam":["生命体征：血压、心率、体温、BMI（肥胖评估）","步态与姿势：跛行、步幅、下肢力线（膝内翻/外翻畸形）","膝关节视诊：肿胀、积液、畸形、肌肉萎缩（股四头肌）、手术瘢痕","膝关节触诊：关节线压痛、髌骨研磨试验、皮温（感染筛查）、浮髌试验（积液）","关节活动度：屈曲与伸展范围（记录角度），有无屈曲挛缩","稳定性：前后抽屉试验（交叉韧带）、侧方应力试验（侧副韧带）、有无关节不稳","神经血管：足背动脉搏动、末梢感觉与运动；腰椎检查（排除腰源性膝痛）"],"lab_tests":["膝关节负重X线（正位+侧位+髌骨轴位）+双下肢全长片：分级、畸形与力线评估（术前规划）","血常规+CRP+血沉+类风湿因子+抗CCP抗体：排除感染性与类风湿性关节炎","关节液检查（必要时）：细胞数、结晶、细菌培养（排除痛风与感染）","凝血功能+肝肾功能+心电图+心脏超声+肺功能：老年患者术前风险评估","骨密度（DEXA）+血钙磷+维生素D：骨质疏松评估与治疗依据","血糖+糖化血红蛋白：糖尿病患者术前控糖（感染与愈合风险）","下肢静脉超声（术前，高危患者）：评估DVT（既往VTE史者）"],"nursing":["术前护理：功能训练宣教（踝泵、股四头肌等长收缩、直腿抬高）、皮肤准备、戒烟、控制基础病","术后体位：患肢抬高（垫软枕，膝下勿垫高枕防屈曲挛缩），保持膝关节中立位","切口与引流护理：观察渗血渗液与引流量，保持敷料清洁干燥，记录引流量与性状","疼痛管理：多模式镇痛并按评分给药，疼痛控制满意后协助早期活动","早期活动与康复：术后6～24小时坐起站立，第1～2天助行器行走，指导踝泵（每小时10～20次）与屈伸训练","并发症观察与宣教：下肢肿胀疼痛（DVT）、呼吸困难（PE）、切口红肿渗液与发热（感染）、膝关节活动度进展；出院后继续康复训练与按时复查"],"diet":["术前：高蛋白、高钙、高维生素饮食，控制体重（减重可减轻关节负荷）","术后：高蛋白饮食促进切口愈合与康复（鱼、瘦肉、蛋、奶、豆制品）","多饮水（每日1500～2000ml），预防脱水与血栓","多食蔬菜水果与粗纤维，保持大便通畅（防便秘致腹压增高与VTE风险）","控制血糖与体重；戒烟限酒；补充钙与维生素D"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1385},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b5bd0b4da923f9a9ec37e6e141a1c389f6aa360e2f397cbc3012bceea5220db5","pinyin":"xiguanjieguguanjieyan（quanxiguanjiezhihuan）","initials":"xgjggjy（qxgjzh）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","膝关节疼痛（负重与上下楼梯时加重，休息后减轻），可有夜间痛\\n关节僵硬（晨起或久坐后起步困难，活动后缓解，一般<30分钟）\\n关节活动受限（屈伸范围减小），下蹲困难\\n关节肿胀、摩擦感（骨摩擦音）、畸形（膝内翻或外翻）\\n病程晚期：关节不稳、行走困难、肌肉萎缩与生活质量显著下降",60],["摘要","膝关节骨关节炎是中老年最常见的退行性关节病，表现为膝关节疼痛、僵硬与活动受限。治疗遵循阶梯原则：基础治疗（减重、运动、物理治疗）→ 药物治疗（NSAIDs、关节腔注射）→ 手术治疗（关节镜、截骨、全膝关节置换TKA）。TKA适用于终末期病变、疼痛严重影响生活且保守治疗无效者。",30],["疾病编码","M17.9",30],["原首字母","gjygjyqxjzgz",60]]},{"id":"orders-7ea1a2f9382eeedcea5b","key":"v1-c9ccc21dfe2a3058|orders-7ea1a2f9382eeedcea5b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"股骨头坏死（全髋关节置换）","category":"骨科","raw":{"name":"股骨头坏死（全髋关节置换）","category":"骨科","summary":"股骨头坏死（ONFH）是股骨头血供中断致骨细胞死亡的疾病，常见病因：创伤（股骨颈骨折、髋脱位）、激素（长期大剂量糖皮质激素）、酒精、减压病（潜水员）与特发性。按ARCO/Ficat分期，早期可行保髋治疗（减压、植骨），晚期（Ficat Ⅲ～Ⅳ期、股骨头塌陷）行全髋关节置换（THA）以缓解疼痛、恢复功能。","symptoms":["髋部疼痛（腹股沟区为主，可放射至臀部、大腿内侧与膝部），负重与行走时加重","髋关节活动受限（尤其内旋与屈曲），穿袜与剪趾甲困难，跛行","疼痛逐渐加重，休息与夜间亦可痛（晚期）","髋关节僵硬与功能障碍，行走距离缩短（需扶拐）","病程晚期：患肢短缩、Trendelenburg征阳性（臀中肌无力）"],"diagnosis":["髋关节X线（正位+蛙式位）：股骨头硬化、囊性变、新月征（软骨下骨折）与塌陷（Ficat分期）","髋关节MRI（首选，早期敏感）：T1低信号带、T2双线征（'双线征'为特征性表现），可发现X线阴性早期病变","髋关节CT：评估股骨头塌陷程度与骨结构（术前规划）","骨扫描（ECT）：早期血流灌注与代谢改变（敏感性高、特异性低）","病因筛查：激素使用史、饮酒史、外伤史、减压病史；凝血功能（易栓症）、血脂、肝功能","髋关节功能评分（Harris评分）：术前评估与疗效评价","骨密度+双下肢全长X线：评估骨质与下肢长度差异"],"infusion":["⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴；过敏者克林霉素 0.6g 或万古霉素 1g〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（氨甲环酸减少出血）：","  用法：氨甲环酸 1g（NS 100ml 或 5%GS 100ml）静滴（切皮前15～30分钟）；必要时术后3小时追加1g（减少输血需求）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（术后镇痛）：","  用法：氟比洛芬酯 50mg（NS 100ml）静滴 q12h 或 曲马多 100mg 静滴 必要时；必要时静脉镇痛泵","","方案4（抗凝预防VTE）：","  用法：低分子肝素 0.4ml 皮下注射 qd（术后12～24小时开始）；或利伐沙班 10mg qd（疗程28～35天）〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","","📌 THA术后VTE预防疗程较长（28～35天）；酒精性与激素性ONFH患者需同时处理病因（戒酒、调整激素）。"],"oral_medication":["⚠️ 术后与长期用药，按医嘱选择：","药物1（镇痛）：","用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（抗凝序贯）：","用法：利伐沙班 10mg qd（术后28～35天，按医嘱）或 阿司匹林 100mg qd〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","药物3（钙与维生素D）：","用法：碳酸钙D3 600mg qd + 骨化三醇 0.25μg qd","药物4（病因治疗，激素性ONFH）：","用法：与风湿科/相关科室协作调整激素剂量（不可自行停药）；戒酒（酒精性）","📌 术后3个月内避免患髋过度屈曲、内收与内旋（防脱位）；避免深蹲、盘腿与坐矮凳。"],"treatment":["早期保髋治疗（Ficat Ⅰ～Ⅱ期、股骨头未塌陷）：髓心减压+自体骨/异体骨植骨、带血管蒂腓骨/髂骨移植、钽棒植入（支撑股骨头）","药物与物理治疗：双膦酸盐、扩血管药（前列地尔）、高压氧、体外冲击波（辅助延缓进展）","全髋关节置换（THA）指征：Ficat Ⅲ～Ⅳ期（股骨头塌陷）、疼痛严重影响生活、保髋治疗失败、年龄较大者","手术方式：骨水泥或非骨水泥固定（生物型）；髋臼与股骨柄假体选择依骨质与年龄；年轻患者可选表面置换（适应证有限）","围手术期管理（ERAS）：术前宣教与功能训练、氨甲环酸减少出血、多模式镇痛、术后早期下床（24小时内）","术后康复：术后第1天下床（助行器），逐步过渡（3个月内避免过度屈曲内收内旋，防脱位），加强臀中肌与股四头肌训练","并发症处理：脱位（复位或翻修，注意体位限制）、感染（清创或二期翻修）、假体周围骨折、神经损伤（坐骨神经）、下肢不等长、VTE","病因治疗与随访：戒酒、激素调整、避免减压作业；术后6周、3个月、6个月、1年复查X线，之后每年"],"management":["术前准备：宣教（体位限制、康复计划）、功能训练、控制基础病、戒烟、皮肤准备；评估病因（激素、酒精）并干预","术后体位与制动：两腿间放置外展枕（保持患髋外展中立位），禁忌交叉双腿与过度屈曲（<90°）","切口与引流观察：观察渗血渗液与引流量，保持敷料清洁干燥，警惕感染","疼痛管理：多模式镇痛，疼痛控制满意后协助早期下床活动","早期活动与体位限制：术后24小时内坐起站立与助行器行走；3个月内避免屈髋>90°、内收内旋、深蹲、盘腿与坐矮凳","VTE预防：药物抗凝（28～35天）+间歇充气加压装置+踝泵运动，观察下肢肿胀与疼痛","出院指导：坚持臀中肌与股四头肌训练、控制体重、避免剧烈运动与跌倒、按时复查、警惕脱位（突发髋痛伴活动受限）与感染征象"],"notes":["股骨头坏死的关键是早期诊断（MRI敏感）与去除病因（戒酒、调整激素）；塌陷后保守治疗无效","股骨颈骨折后股骨头坏死风险高（尤其移位型），需定期随访（早期发现）","THA术后脱位是常见早期并发症，体位限制（避免屈髋>90°、内收内旋）是预防关键","酒精性与激素性ONFH多为双侧（约50%），术前应评估对侧髋关节（MRI）","术后避免高冲击运动（跑步、跳跃）以延长假体寿命；假体寿命一般15～20年"],"emergency":["术后突发髋部剧痛伴患肢短缩外旋、不能活动（假体脱位）→ 立即制动、影像评估并复位","术后呼吸困难、胸痛、血氧下降（肺栓塞）→ 立即抢救、抗凝或溶栓","切口大量渗液伴发热与髋部红肿热痛（急性感染）→ 急诊穿刺培养+抗感染，评估清创","术后患肢突发肿胀剧痛、足背动脉搏动减弱（血管损伤/骨筋膜室综合征）→ 急诊评估处理"],"pinyin":"ggthtqxjzgz","icd10":"M87.0","physical_exam":["生命体征：血压、心率、体温、BMI","步态：跛行类型（疼痛性/臀中肌步态Trendelenburg征）、是否需要助行器","髋关节视诊：有无畸形、肌萎缩（臀肌、股四头肌）、手术瘢痕、下肢长度（对比）","髋关节触诊：腹股沟中点压痛（关节前方）、大转子叩击痛、皮温（感染）","关节活动度：屈曲、内旋（最早受限）、外展与后伸角度（记录并与对侧对比）","特殊检查：Trendelenburg征（臀中肌功能）、Thomas征（屈曲挛缩）、滚动试验（关节内病变）","神经血管：坐骨神经与股神经功能、足背动脉搏动；腰椎检查（排除腰源性髋痛）"],"lab_tests":["髋关节X线（正位+蛙式位）+髋关节MRI（首选早期诊断，双线征）+CT（塌陷与术前规划）","血常规+CRP+血沉：术前基线与感染筛查（髋关节感染需排除）","凝血功能+血脂+肝功能+血糖：病因评估与术前检查","易栓症筛查（凝血因子、蛋白C/S、抗磷脂抗体，年轻或反复血栓者）","骨密度（DEXA）+血钙磷+维生素D：骨质评估与治疗依据","心电图+心脏超声+肺功能：老年患者术前风险评估","对侧髋关节MRI（酒精性/激素性ONFH）：评估双侧病变（约50%为双侧）"],"nursing":["术前护理：功能训练宣教（踝泵、股四头肌与臀中肌训练）、戒烟、皮肤准备、评估激素与饮酒史并宣教干预","术后体位护理：两腿间放置外展枕，保持患髋外展中立位；禁忌交叉双腿与屈髋>90°","切口与引流护理：观察渗血渗液与引流量，保持敷料清洁干燥，记录性状","疼痛与早期活动：多模式镇痛并按评分给药，术后24小时内协助坐起站立与助行器行走","VTE预防与观察：遵医嘱抗凝、间歇充气加压装置与踝泵运动；观察下肢肿胀、疼痛与呼吸困难","出院宣教：坚持肌肉力量训练、避免深蹲/盘腿/坐矮凳（3个月）、控制体重、避免跌倒、按时复查；警惕脱位与感染的征象"],"diet":["术前：高蛋白、高钙饮食，控制体重；酒精性ONFH者严格戒酒","术后：高蛋白饮食促进切口愈合与康复（鱼、瘦肉、蛋、奶）","多饮水（每日1500～2000ml）预防脱水与血栓","多食蔬菜水果与粗纤维，保持大便通畅","激素性ONFH者：遵医嘱调整饮食（低盐低糖，控制血糖与体重）；补充钙与维生素D"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1386},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5d08b1eed0858e51000e7caed8ff28dcaf08243519809ecc8d667c27e3f92001","pinyin":"gugutouhuaisi（quankuanguanjiezhihuan）","initials":"ggths（qkgjzh）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","髋部疼痛（腹股沟区为主，可放射至臀部、大腿内侧与膝部），负重与行走时加重\\n髋关节活动受限（尤其内旋与屈曲），穿袜与剪趾甲困难，跛行\\n疼痛逐渐加重，休息与夜间亦可痛（晚期）\\n髋关节僵硬与功能障碍，行走距离缩短（需扶拐）\\n病程晚期：患肢短缩、Trendelenburg征阳性（臀中肌无力）",60],["摘要","股骨头坏死（ONFH）是股骨头血供中断致骨细胞死亡的疾病，常见病因：创伤（股骨颈骨折、髋脱位）、激素（长期大剂量糖皮质激素）、酒精、减压病（潜水员）与特发性。按ARCO/Ficat分期，早期可行保髋治疗（减压、植骨），晚期（Ficat Ⅲ～Ⅳ期、股骨头塌陷）行全髋关节置换（THA）以缓解疼痛、恢复功能。",30],["疾病编码","M87.0",30],["原首字母","ggthtqxjzgz",60]]},{"id":"orders-aea5f253a855d0be9367","key":"v1-c9ccc21dfe2a3058|orders-aea5f253a855d0be9367","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"骨与关节结核","category":"骨科","raw":{"name":"骨与关节结核","category":"骨科","summary":"骨与关节结核是结核分枝杆菌经血行播散至骨骼或关节引起的慢性特异性感染，以脊柱结核（最常见）、髋关节与膝关节结核多见。表现为局部疼痛、肿胀、活动受限与全身结核中毒症状（低热、盗汗、消瘦）。治疗以规范抗结核化疗为基础，合并脓肿、死骨、脊柱不稳或神经压迫者需手术。","symptoms":["全身结核中毒症状：低热（午后为主）、盗汗、乏力、消瘦、食欲减退、贫血","局部疼痛（脊柱结核为腰背痛，髋/膝关节结核为关节痛），夜间痛与活动痛","局部肿胀、压痛、肌肉痉挛与关节活动受限","寒性脓肿（冷脓肿）：局部波动性包块，可穿破形成窦道长期流脓","神经损害（脊柱结核）：下肢麻木无力、感觉平面、大小便功能障碍（截瘫风险）"],"diagnosis":["脊柱/关节X线：椎体骨质破坏、椎间隙变窄、椎旁脓肿影（脊柱结核）；关节间隙变窄、骨质疏松与骨破坏","CT（含三维重建）：显示骨质破坏、死骨、椎旁脓肿范围与椎管占位","MRI（首选）：评估椎体骨髓水肿、椎间盘受累、椎旁脓肿、硬膜外脓肿与脊髓受压（脊柱结核必查）","结核病原学：痰/脓液/组织抗酸染色、结核培养、Xpert MTB/RIF（分子检测，快速诊断与耐药判断）","结核免疫学：PPD试验、T-SPOT.TB/IGRA、结核抗体","病理活检：CT/超声引导下穿刺活检或手术取材（确诊与鉴别肿瘤）","血常规+血沉+CRP：血沉与CRP升高（疗效监测指标）"],"infusion":["⚠️ 抗结核治疗须规范足疗程（由结核专科/感染科指导），切勿自行调整！","","方案1（初治标准方案，2HRZE/4-7HRE 或 2HRZE/10HRE）：","  用法：异烟肼 0.3g qd（NS 100ml 或 5%GS 100ml）静滴/口服 + 利福平 0.45～0.6g qd 静滴/口服（空腹）+ 吡嗪酰胺 1.5g qd + 乙胺丁醇 0.75～1.0g qd（强化期2个月，巩固期遵医嘱）〔调 ★ 肝功能不全慎用；★ 强CYP450诱导剂（大量相互作用）〕","","方案2（营养与支持治疗）：","  用法：0.9%氯化钠/葡萄糖 静滴；复方氨基酸、白蛋白（营养不良者）；维生素B6 10mg tid（预防异烟肼神经毒性）","","方案3（抗感染，合并化脓性感染/术后）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h（按药敏调整）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案4（对症与术前准备）：","  用法：镇痛（曲马多 100mg（NS 100ml 或 5%GS 100ml）静滴 必要时）；纠正贫血（铁剂/输血）；肝功能异常者保肝治疗（还原型谷胱甘肽 1.2g 静滴 qd）","","📌 抗结核治疗需规律、全程（骨关节结核总疗程一般12～18个月），定期监测肝功能、视力（乙胺丁醇）与听力（链霉素）；不可自行停药（致耐药与复发）。"],"oral_medication":["⚠️ 抗结核口服药物是治疗核心（须结核专科指导，注意不良反应监测）：","药物1（抗结核核心用药）：","用法：异烟肼 0.3g qd（晨起空腹）+ 利福平 0.45～0.6g qd（晨起空腹）+ 吡嗪酰胺 1.5g qd + 乙胺丁醇 0.75～1.0g qd；巩固期按医嘱调整（常用异烟肼+利福平）〔调 ★ 肝功能不全慎用；★ 强CYP450诱导剂（大量相互作用）〕","药物2（预防药物不良反应）：","用法：维生素B6 10mg tid（预防异烟肼周围神经病变）；还原型谷胱甘肽片 0.4g tid 或 多烯磷脂酰胆碱 456mg tid（保肝）","药物3（镇痛与支持）：","用法：对乙酰氨基酚 0.5g 必要时；碳酸钙D3 600mg qd（骨质破坏者）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（止痛与改善症状）：","用法：塞来昔布 200mg qd（餐后，注意肝功能）〔调 ★ eGFR<30 禁用；心血管血栓风险〕","📌 利福平可使尿液、汗液呈橙红色（正常现象）；与多种药物有相互作用（口服避孕药失效、抗凝药减效）；服药期间禁酒。"],"treatment":["抗结核化疗（基础治疗）：规范联合用药、足量足疗程（脊柱结核12～18个月），定期监测肝肾功能、血沉与影像","手术指征：脊柱结核伴神经功能障碍（脊髓受压/截瘫）、脊柱不稳或后凸畸形、巨大脓肿或窦道形成、死骨明显、化疗无效或耐药、诊断不明确需活检","手术方式：前路/后路病灶清除+植骨融合+内固定（脊柱结核）；关节结核行病灶清除+关节融合或置换（晚期）","制动与支具：脊柱结核用支具/石膏床制动（术前术后），髋关节结核行皮牵引（防畸形与脱位）","脓肿处理：寒性脓肿穿刺抽脓+抗结核药物注入；巨大脓肿需引流或手术清除","营养支持与全身治疗：高蛋白高热量饮食、纠正贫血与低蛋白、卧床休息（活动期）","并发症处理：截瘫（急诊减压+固定）、窦道继发感染（抗感染+引流）、病理性骨折/脱位、关节强直（功能重建）","随访：治疗期间每2～3个月复查血沉、CRP与影像；疗程结束后随访2年（复发监测）"],"management":["抗结核用药管理：严格按时按量给药（利福平、异烟肼晨起空腹），记录漏服；观察药物不良反应（肝功能损害、视力下降、周围神经病变、皮疹）","肝功能监测：每月（或按医嘱）复查肝功能（利福平、异烟肼、吡嗪酰胺均有肝毒性），出现黄疸、恶心呕吐立即报告","制动与体位：脊柱结核卧硬板床（轴线翻身）、佩戴支具；髋关节结核皮牵引制动（防病理性脱位）","神经功能观察（脊柱结核）：每小时（急性期）或每日评估下肢感觉、肌力与大小便功能，恶化立即报告","营养与全身支持：高蛋白高热量饮食、补充维生素；监测体重、白蛋白与血红蛋白","窦道与脓肿护理：保持引流通畅、无菌换药、观察分泌物的量与性状；脓肿穿刺后观察局部情况","消毒隔离与宣教：活动期患者（痰菌阳性）需呼吸道隔离、戴口罩、痰液消毒处理；宣教规律服药与全程治疗的重要性，禁酒"],"notes":["骨关节结核治疗的核心是『规范抗结核化疗+必要的病灶清除』，化疗必须规律、足量、全程（脊柱结核12～18个月）","不可自行停药或减量（导致耐药与复发，治疗极为困难）；耐药结核需结核专科调整方案","脊柱结核出现下肢麻木无力或大小便障碍提示脊髓受压，需紧急MRI评估与手术减压","抗结核药物肝毒性常见，需定期监测肝功能；利福平使尿液呈橙红色属正常现象","活动期（痰菌阳性）患者需呼吸道隔离；卧床休息与营养支持是治疗的重要组成部分"],"emergency":["脊柱结核患者下肢肌力迅速下降或大小便失禁（脊髓压迫/截瘫）→ 立即MRI评估并急诊手术减压","突发剧烈腰背痛伴畸形加重（病理性骨折/脊柱不稳）→ 立即制动并急诊评估手术","抗结核治疗中出现黄疸、意识改变（急性肝衰竭）→ 立即停药、保肝治疗并急诊评估","寒性脓肿破溃大量流脓伴高热（继发感染）→ 抗感染、引流与换药处理"],"pinyin":"gygjh","icd10":"A18.0","physical_exam":["生命体征：体温（午后低热）、脉搏、体重与营养状态（消瘦）、贫血貌","脊柱（脊柱结核）：后凸畸形、棘突压痛与叩击痛、脊柱活动受限、肌肉痉挛（拾物试验阳性）","髋/膝关节（关节结核）：关节肿胀（梭形肿胀）、压痛、皮温（多不高）、活动受限、肌肉萎缩、下肢长度差异","寒性脓肿：脊柱结核的椎旁/腰大肌脓肿（腹部包块）、髋关节结核的腹股沟脓肿、膝关节结核的腘窝脓肿","神经功能：下肢感觉、肌力、腱反射、病理反射与括约肌功能（ASIA分级）","窦道：部位、数目、分泌物性状与周围皮肤情况","其他部位结核：肺部（呼吸音、啰音）、淋巴结（颈部）、泌尿系（尿路刺激症状）"],"lab_tests":["血常规+血沉+CRP：血沉与CRP升高是活动性指标，治疗中动态监测疗效（每2～3个月）","结核病原学：脓液/组织抗酸染色、结核培养（需4～8周）、Xpert MTB/RIF（快速诊断与耐药检测）","结核免疫学：PPD试验、T-SPOT.TB/IGRA","病理活检（CT/超声引导穿刺或手术取材）：确诊与鉴别肿瘤（干酪样坏死、肉芽肿）","肝功能（每月）+肾功能+视力（乙胺丁醇）+听力（链霉素）：抗结核药物不良反应监测","脊柱/关节X线+CT+MRI：MRI为首选（脓肿、脊髓受压与早期病变）；CT评估死骨与骨破坏；X线随访骨愈合","胸部X线/CT+痰结核菌检查：排除肺结核（活动性判断与隔离依据）"],"nursing":["抗结核用药护理：严格按时给药（利福平、异烟肼空腹服用），观察药物不良反应（恶心、黄疸、视力模糊、手足麻木、皮疹）并报告","制动与体位护理：脊柱结核卧硬板床、轴线翻身、佩戴支具；髋关节结核皮牵引制动（保持外展中立位）","神经功能观察：评估下肢感觉、肌力与大小便功能（脊柱结核每日或每班），异常立即报告","营养与支持：鼓励高蛋白高热量饮食（鱼、瘦肉、蛋、奶）、少量多餐，必要时营养支持；记录体重与进食量","脓肿与窦道护理：保持引流通畅、无菌换药、记录分泌物性状与量；注意皮肤保护（分泌物刺激）","消毒隔离与宣教：痰菌阳性者呼吸道隔离、戴口罩、痰液消毒（焚烧或含氯消毒剂）；宣教规律全程服药、禁酒、按时复查与接触者筛查"],"diet":["高蛋白、高热量、高维生素饮食（结核为消耗性疾病）：鱼、瘦肉、蛋、奶、豆制品、新鲜蔬果","充足热量（每日30～35kcal/kg）与蛋白（1.5～2.0g/kg/日）纠正消耗与低蛋白","补充钙与维生素D（骨质破坏者）、铁剂与维生素B12（贫血者）","严格禁酒（酒精加重肝毒性并影响治疗）；抗结核治疗期间避免辛辣刺激食物","少量多餐、易消化；必要时口服营养补充剂或肠内营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1387},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"079ca742cbebf67e2bf7441d54e228403b3d528dde7cf93250f154947cd5ff4d","pinyin":"guyuguanjiejiehe","initials":"gygjjh","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","全身结核中毒症状：低热（午后为主）、盗汗、乏力、消瘦、食欲减退、贫血\\n局部疼痛（脊柱结核为腰背痛，髋/膝关节结核为关节痛），夜间痛与活动痛\\n局部肿胀、压痛、肌肉痉挛与关节活动受限\\n寒性脓肿（冷脓肿）：局部波动性包块，可穿破形成窦道长期流脓\\n神经损害（脊柱结核）：下肢麻木无力、感觉平面、大小便功能障碍（截瘫风险）",60],["摘要","骨与关节结核是结核分枝杆菌经血行播散至骨骼或关节引起的慢性特异性感染，以脊柱结核（最常见）、髋关节与膝关节结核多见。表现为局部疼痛、肿胀、活动受限与全身结核中毒症状（低热、盗汗、消瘦）。治疗以规范抗结核化疗为基础，合并脓肿、死骨、脊柱不稳或神经压迫者需手术。",30],["疾病编码","A18.0",30],["原首字母","gygjh",60]]},{"id":"orders-306549bd73c34fb6597c","key":"v1-c9ccc21dfe2a3058|orders-306549bd73c34fb6597c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"脑脓肿","category":"神经外科","raw":{"name":"脑脓肿","category":"神经外科","summary":"脑脓肿是化脓性细菌侵入脑组织形成的局限性化脓性炎症与脓腔，多继发于中耳炎/乳突炎、鼻窦炎、牙源性感染、颅脑外伤或血行播散（肺脓肿、感染性心内膜炎）。表现为颅内压增高（头痛、呕吐、视乳头水肿）、局灶性神经功能缺损与感染中毒症状，治疗包括抗感染、穿刺引流或手术切除。","symptoms":["颅内压增高：头痛（持续性、晨起加重）、喷射性呕吐、视乳头水肿、意识障碍","感染中毒症状：发热（可低热或高热）、寒战、乏力、食欲减退（慢性者可不明显）","局灶性神经缺损：偏瘫、失语、视野缺损、癫痫发作（依脓肿部位）","脑膜刺激征：颈项强直、Kernig征（合并脑膜炎时）","病情进展可出现脑疝（瞳孔不等大、呼吸不规则、意识迅速恶化）"],"diagnosis":["头颅增强CT：低密度灶伴环形强化、周围水肿带（首选快速筛查）","头颅MRI（增强+DWI）：更敏感，DWI高信号（脓液）与环形强化，可鉴别肿瘤与脓肿（首选）","腰椎穿刺（慎重）：颅内压明显增高者禁做（脑疝风险）；脑脊液细胞数升高、蛋白升高、糖降低；涂片与培养（阳性率低）","血培养+感染灶培养：寻找病原菌与感染来源（耳、鼻窦、牙、肺）","耳鼻喉科与口腔科检查：寻找原发感染灶（中耳炎、鼻窦炎、牙源性）","胸片/胸部CT+心脏超声：排除肺脓肿与感染性心内膜炎（血行播散来源）","血常规+CRP+PCT+血沉：感染程度评估"],"infusion":["⚠️ 抗感染是基础，须足量足疗程并穿透血脑屏障！","","方案1（经验性抗感染，覆盖链球菌、葡萄球菌、厌氧菌与肠杆菌科）：","  用法：头孢曲松 2g 静滴 q12h（或头孢噻肟 2g q6h）+ 甲硝唑 0.5g 静滴 q8h + 万古霉素 1g 静滴 q12h（疑MRSA，监测血药浓度）；重症/术后：美罗培南 2g 静滴 q8h〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案2（降颅压）：","  用法：20%甘露醇 125～250ml 静滴 q6～8h（快速静滴，监测尿量、肾功能与电解质）；或 3%氯化钠 100～150ml 静滴；地塞米松 10mg 静推（水肿明显者，短期，注意免疫抑制）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（抗癫痫）：","  用法：左乙拉西坦 500mg（NS 100ml 或 5%GS 100ml）静滴 q12h 或 丙戊酸钠 400mg 静滴 q12h（有癫痫发作或颞叶脓肿者），监测血药浓度〔调 ★ 必须按 CrCl 减量；老年减量〕","","方案4（支持治疗）：","  用法：0.9%氯化钠/葡萄糖 静滴；白蛋白（低蛋白/水肿者）；营养支持；维持水电解质平衡","","📌 抗菌疗程长（4～8周或更长，依影像与临床），须静脉给药后序贯口服；脑疝征象出现时立即降颅压并急诊处理。"],"oral_medication":["⚠️ 恢复期序贯用药（须按药敏与专科指导）：","药物1（抗感染序贯）：","用法：阿莫西林克拉维酸 0.625g tid + 甲硝唑 0.4g tid；或 利奈唑胺 0.6g bid（MRSA/耐药球菌，注意血常规）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（抗癫痫维持）：","用法：左乙拉西坦 500mg bid 或 丙戊酸钠缓释片 500mg bid（疗程依病因：脓肿治愈后一般继续3～6个月，遵医嘱）〔调 ★ 必须按 CrCl 减量；老年减量〕","药物3（脱水与激素减量）：","用法：泼尼松（按医嘱逐渐减量，不可骤停）；必要时甘油果糖口服〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物4（营养神经与支持）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid；碳酸钙D3 600mg qd（长期激素者）","📌 抗感染与抗癫痫药物均不可自行停药（脓肿复发与癫痫发作风险）；定期复查影像与血药浓度。"],"treatment":["抗感染治疗：经验性广谱（穿透血脑屏障，如头孢曲松 2g 静滴 q12h + 甲硝唑 500mg 静滴 q8h）+ 病原学指导，疗程4～8周或更长（影像显示脓肿缩小/消失），静脉为主后序贯口服","穿刺抽脓/置管引流（首选手术方式）：脓肿直径>2.5cm、占位效应明显或抗感染效果不佳者，CT/MRI引导下穿刺抽脓+置管引流（创伤小、可反复抽吸）","开颅脓肿切除：多房性、厚壁脓肿、异物或外伤性脓肿、穿刺失败或颅压危象者","原发灶处理：中耳炎/乳突炎（耳科手术）、鼻窦炎（鼻窦引流）、牙源性感染（口腔处理）、肺脓肿（呼吸科）","降颅压与抗癫痫：甘露醇 0.25～1g/kg 静滴 q4～6h、高渗盐水、短期激素、抗癫痫药物（如左乙拉西坦 500～1000mg 静推/口服 q12h）","支持治疗：营养支持、纠正水电解质紊乱、控制血糖（糖尿病者）","康复治疗：神经功能缺损（偏瘫、失语）行康复训练；癫痫长期随访","随访：治疗期间每2～4周复查增强CT/MRI，直至脓肿消失；之后每3～6个月随访（复发监测）"],"management":["意识与瞳孔监测：每1～2小时（急性期）评估GCS与瞳孔，意识恶化或瞳孔不等大立即报告（脑疝预警）","颅内压管理：床头抬高15～30°、保持头颈中立、避免用力与躁动、遵医嘱脱水治疗，记录尿量与电解质","引流管护理（穿刺置管者）：妥善固定、保持通畅、记录引流液量与性状（脓性、血性），严格无菌操作","体温与感染监测：每4小时测体温，观察感染中毒症状与血象变化，及时发现感染灶（耳、鼻窦、牙、肺）","抗癫痫护理：观察癫痫发作类型与频率，遵医嘱按时给药、监测血药浓度；发作时保护气道与安全（防坠床与舌咬伤）","营养与基础护理：高蛋白高热量饮食（能进食者）/鼻饲或静脉营养；口腔护理与压疮预防；高热护理","宣教与随访：强调足疗程抗感染与按时复查影像的重要性；癫痫患者长期服药与随访；控制原发感染灶（耳鼻喉与口腔卫生）"],"notes":["脑脓肿的诊断首选增强MRI（DWI可鉴别脓肿与肿瘤）；腰椎穿刺在颅内压明显增高时禁做（脑疝风险）","抗感染必须穿透血脑屏障且疗程足够（4～8周或更长），过早停药可致复发","脓肿>2.5cm或有明显占位效应者应穿刺引流（创伤小，优于开颅切除）","必须寻找并处理原发感染灶（中耳炎、鼻窦炎、牙源性、肺脓肿），否则易复发","脑脓肿可致癫痫（尤其颞叶脓肿），需长期抗癫痫治疗与随访"],"emergency":["意识迅速恶化、瞳孔不等大、血压升高伴心率减慢（脑疝）→ 立即降颅压（甘露醇/高渗盐水）并急诊CT/手术","癫痫持续状态（发作>5分钟或反复发作）→ 立即静推地西泮/咪达唑仑+抗癫痫药负荷量，保护气道","脓肿破入脑室（高热、意识障碍、脑膜刺激征加重）→ 急诊脑室外引流+抗感染","引流管引出大量新鲜血液（脓肿内出血）→ 立即复查CT并报告医师处理"],"pinyin":"nnz","icd10":"G06.0","physical_exam":["意识与瞳孔：GCS评分、瞳孔大小与对光反射（脑疝筛查）","生命体征：体温（感染）、血压与心率（Cushing反应：血压升高、心率减慢提示颅内压增高）、呼吸","神经系统：肢体肌力、感觉、病理反射、脑膜刺激征（颈项强直、Kernig征、Brudzinski征）","局灶体征：失语、视野缺损、共济失调、颅神经麻痹（依脓肿部位）","眼底：视乳头水肿（颅内压增高）","耳鼻喉与口腔：中耳炎/乳突炎体征、鼻窦压痛、牙源性感染灶（原发灶寻找）","心肺与皮肤：肺部感染体征（肺脓肿）、心脏杂音（心内膜炎）、皮肤感染灶（血行播散来源）"],"lab_tests":["头颅增强MRI（DWI+增强，首选）+增强CT：脓肿部位、大小、数目、环形强化与周围水肿","血常规+CRP+PCT+血沉：感染程度与治疗反应监测（每2～3天）","血培养×2套+脓液培养及药敏（穿刺或手术时）：病原学诊断（抗生素前留取）","脑脊液检查（无颅内压增高者可谨慎腰穿）：细胞数、蛋白、糖、氯化物、涂片与培养","电解质+肾功能+尿量：甘露醇脱水监测（每1～2天）","抗癫痫药物血药浓度（丙戊酸钠、左乙拉西坦）+肝功能：用药监测","胸部CT+心脏超声+耳鼻喉/口腔检查：寻找原发感染灶"],"nursing":["意识与瞳孔观察：每1～2小时评估GCS与瞳孔并记录，意识恶化或瞳孔异常立即报告（脑疝预警）","颅内压护理：床头抬高15～30°、头颈中立、避免用力排便与躁动（必要时镇静）、遵医嘱脱水并监测电解质","引流管护理：穿刺置管者妥善固定、保持通畅、记录引流液量与性状，严格无菌操作（换药、接头消毒）","体温与感染护理：每4小时测体温，高热时物理降温与补液；观察感染灶（耳道流脓、鼻窦压痛、牙痛）","癫痫护理：观察发作类型与频率，按时给予抗癫痫药；发作时保护气道、防坠床与舌咬伤，记录发作时间与表现","营养与康复护理：能进食者高蛋白高热量饮食，吞咽障碍者鼻饲（床头抬高30～45°防误吸）；指导肢体功能康复训练"],"diet":["能进食者：高蛋白、高热量、高维生素易消化饮食（鱼、瘦肉、蛋、奶、蔬果），少量多餐","意识障碍或吞咽困难者：鼻饲营养液（床头抬高30～45°防误吸）或静脉营养支持","限制水分者按医嘱（颅内压增高与脱水治疗期间需控制入量）","多食蔬菜水果与粗纤维，保持大便通畅（避免用力排便致颅压升高），必要时用缓泻剂","控制血糖（糖尿病患者）、戒烟酒；癫痫患者避免咖啡因与酒精"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1388},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6f33cef283572fdbc497bab0a0b21d03fba65cdd173f2e68dd31bb1129a9720d","pinyin":"naonongzhong","initials":"nnz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","颅内压增高：头痛（持续性、晨起加重）、喷射性呕吐、视乳头水肿、意识障碍\\n感染中毒症状：发热（可低热或高热）、寒战、乏力、食欲减退（慢性者可不明显）\\n局灶性神经缺损：偏瘫、失语、视野缺损、癫痫发作（依脓肿部位）\\n脑膜刺激征：颈项强直、Kernig征（合并脑膜炎时）\\n病情进展可出现脑疝（瞳孔不等大、呼吸不规则、意识迅速恶化）",60],["摘要","脑脓肿是化脓性细菌侵入脑组织形成的局限性化脓性炎症与脓腔，多继发于中耳炎/乳突炎、鼻窦炎、牙源性感染、颅脑外伤或血行播散（肺脓肿、感染性心内膜炎）。表现为颅内压增高（头痛、呕吐、视乳头水肿）、局灶性神经功能缺损与感染中毒症状，治疗包括抗感染、穿刺引流或手术切除。",30],["疾病编码","G06.0",30],["原首字母","nnz",60]]},{"id":"orders-647d6a0cb7fbb95e18b9","key":"v1-c9ccc21dfe2a3058|orders-647d6a0cb7fbb95e18b9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"垂体瘤（外科治疗）","category":"神经外科","raw":{"name":"垂体瘤（外科治疗）","category":"神经外科","summary":"垂体瘤是起源于垂体前叶的良性肿瘤，按功能分为功能性（泌乳素瘤、生长激素瘤、ACTH瘤、TSH瘤）与无功能性腺瘤，按大小分为微腺瘤（<1cm）与大腺瘤（≥1cm）。表现为内分泌功能异常（闭经泌乳、肢端肥大、库欣综合征）、占位压迫（视力视野缺损、头痛）与垂体功能减退。治疗包括药物（泌乳素瘤首选多巴胺激动剂）、经鼻蝶手术与放疗。","symptoms":["内分泌症状：闭经、泌乳、不孕（泌乳素瘤）；肢端肥大（手足增大、面容改变、下颌突出）；向心性肥胖、紫纹（ACTH瘤）","占位压迫：头痛（持续性）、视力下降、视野缺损（典型为双颞侧偏盲）","垂体功能减退：乏力、畏寒、性欲减退、月经紊乱、低血压（肾上腺功能减退）","垂体卒中（急症）：突发剧烈头痛、视力急剧下降、眼肌麻痹、意识障碍（瘤内出血）","尿崩症：多饮、多尿（垂体柄受累或术后）"],"diagnosis":["垂体激素全套：泌乳素（PRL）、生长激素（GH）+IGF-1、ACTH+皮质醇、TSH+FT3/FT4、FSH/LH、睾酮/雌二醇","动态试验：葡萄糖抑制试验（GH瘤）、地塞米松抑制试验（ACTH瘤）、TRH/GnRH刺激试验（必要时）","垂体增强MRI（含薄层扫描）：首选，评估肿瘤大小、部位、有无侵犯海绵窦与视交叉压迫","眼科检查：视力、视野（金标准为自动视野计）与眼底（术前基线，评估视神经受压）","头颅CT（含骨窗）：评估蝶窦发育与骨质破坏（经鼻蝶手术规划）","电解质+尿量+尿比重：尿崩症评估（术后监测）","病理与免疫组化：术后确诊与分型（PRL、GH、ACTH、TSH、FSH/LH、Ki-67）"],"infusion":["⚠️ 围手术期用药（激素替代与电解质管理为主），切勿全部同时使用！","","方案1（围手术期糖皮质激素，防肾上腺危象）：","  用法：氢化可的松 100mg（NS 100ml 或 5%GS 100ml）静滴（术前1小时与术中）；术后 50mg 静滴 q8h（第1天）→ 逐渐减量至口服维持量（按皮质醇水平调整）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案2（垂体卒中/急性肾上腺危象）：","  用法：氢化可的松 100mg 静推后 100～200mg/24h 静滴；0.9%氯化钠 快速补液（纠正低血压与低钠）；必要时去甲肾上腺素泵入；急诊经鼻蝶减压〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案3（尿崩症，术后多尿）：","  用法：0.9%氯化钠 静滴（按尿量等量补液，监测血钠）；去氨加压素 1～2μg 皮下注射/静推（或 0.1～0.2mg 口服，按尿量与血钠调整）","","方案4（电解质紊乱，低钠血症）：","  用法：3%氯化钠 100～150ml 静滴（症状性低钠，缓慢纠正，血钠上升<8～10mmol/L/24h，防渗透性脱髓鞘）；限水（SIADH）","","📌 经鼻蝶手术需监测尿量与血钠（尿崩症与SIADH均可出现）；不可漏用围手术期激素（可致肾上腺危象）。"],"oral_medication":["⚠️ 术后长期激素替代与药物治疗（按内分泌科指导）：","药物1（糖皮质激素替代，垂体功能减退者）：","用法：泼尼松 5mg 晨起 + 2.5mg 下午（或氢化可的松 20mg 晨 + 10mg 下午，按皮质醇与症状调整）；应激时（感染、手术）需加量〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","药物2（甲状腺激素替代）：","用法：左甲状腺素钠 25～50μg qd 起（晨起空腹，按FT4/TSH调整；须在糖皮质激素之后开始，避免诱发肾上腺危象）","药物3（泌乳素瘤，药物首选）：","用法：溴隐亭 1.25mg qn 起（逐渐加量至2.5～5mg bid）或 卡麦角林 0.5mg 每周1～2次（按PRL调整，多数可缩小肿瘤）","药物4（性激素替代/促生育）：","用法：按性别与需求（雌激素/孕激素、睾酮）；促排卵（克罗米芬/促性腺激素，生殖医学指导）","📌 激素替代须在内分泌科指导下个体化调整，不可自行停药；应激状态（发热、手术、外伤）需增加糖皮质激素剂量。"],"treatment":["药物治疗：泌乳素瘤首选多巴胺激动剂（溴隐亭 1.25～2.5mg 口服 qd 起始、渐加至 2.5～15mg/d 分次；或卡麦角林 0.25～0.5mg 口服 每周1～2次），多数肿瘤可缩小、PRL 恢复正常；生长激素瘤可用生长抑素类似物（奥曲肽 50～100μg 皮下 q8h 渐加量；或兰瑞肽 30mg 肌注 每10～14天）或培维索孟 10～30mg 皮下 qd","经鼻蝶手术（主要手术方式）：适用于药物无效或不耐受的泌乳素瘤、GH瘤/ACTH瘤、无功能性大腺瘤伴视交叉压迫、垂体卒中；微创、恢复快","开颅手术：巨大肿瘤向鞍上/鞍旁广泛侵犯、经鼻蝶难以切除者","放射治疗：手术残留或复发、药物无效者（立体定向放疗/伽马刀），起效慢（数月至数年）","垂体卒中：急诊糖皮质激素（氢化可的松 100mg 静推 继以 100～200mg/d 静滴）+补液，视力急剧下降者急诊经鼻蝶减压","术后激素管理：监测皮质醇、甲状腺功能与性激素，缺乏者行替代治疗（氢化可的松 15～25mg/d 口服 分次）；监测尿量与血钠（尿崩症与SIADH）","术后随访：术后1、3、6个月及此后每年复查垂体MRI与激素全套、视力视野；功能性腺瘤需评估生化缓解","并发症处理：脑脊液鼻漏（卧床、腰大池引流，必要时修补）、尿崩症（去氨加压素 0.1～0.2mg 口服 q8h 或 1～2μg 皮下/静推）、垂体功能减退（激素替代）、鼻出血与鼻窦感染"],"management":["围手术期激素管理：严格按医嘱给予糖皮质激素（不可漏用），术后按皮质醇水平调整并过渡到口服维持量","尿量与电解质监测：术后每1～4小时记录尿量（尿量>200ml/h持续2小时提示尿崩症），监测血钠与尿比重，遵医嘱补液或用去氨加压素","经鼻蝶术后护理：半卧位（利于引流与减少脑脊液漏）、观察鼻腔填塞物渗血与渗液（清水样液体提示脑脊液鼻漏）、避免用力擤鼻与咳嗽","视力视野观察：术后评估视力与视野（改善或恶化），异常立即报告（鞍区血肿压迫需急诊处理）","脑脊液鼻漏护理：绝对卧床、头部抬高、避免用力；遵医嘱腰大池引流；观察漏液量与性状，必要时手术修补","电解质与容量管理：低钠血症（SIADH）限水；尿崩症补液与去氨加压素；记录24小时出入量","出院宣教：激素替代不可自行停药、应激时加量、定期复查激素与MRI、出现多尿烦渴/头痛视力下降立即就诊"],"notes":["泌乳素瘤首选药物治疗（多巴胺激动剂），多数无需手术；其他类型以经鼻蝶手术为主","经鼻蝶手术后常见并发症为尿崩症、SIADH（低钠血症）与脑脊液鼻漏，需密切监测尿量与血钠","围手术期糖皮质激素不可漏用（可致肾上腺危象），术后需按皮质醇水平调整并长期替代（垂体功能减退者）","垂体卒中（瘤内出血）是急症：突发剧烈头痛、视力下降与意识障碍，需急诊激素与手术减压","甲状腺激素替代须在糖皮质激素之后开始（先补糖皮质激素，避免诱发肾上腺危象）"],"emergency":["突发剧烈头痛、视力急剧下降、眼肌麻痹与意识障碍（垂体卒中）→ 立即糖皮质激素+补液，急诊MRI与经鼻蝶减压","术后尿量骤增（>200ml/h）伴烦渴（尿崩症）→ 补液并遵医嘱去氨加压素，监测血钠","术后出现清水样鼻漏（脑脊液鼻漏）→ 绝对卧床、头部抬高、报告医师（必要时腰大池引流或修补）","低血压、乏力、意识改变伴低钠或低血糖（肾上腺危象）→ 立即氢化可的松+补液抢救","术后视力迅速恶化（鞍区血肿）→ 立即报告并急诊CT/手术探查"],"pinyin":"ctlwkkzl","icd10":"D35.2","physical_exam":["生命体征：血压（肾上腺功能减退可低血压）、体重、体温","面容与肢端：肢端肥大面容（额部隆起、下颌突出、手足增大）、向心性肥胖与紫纹（库欣）、面色苍白（垂体功能减退）","视力与视野：视力下降、双颞侧偏盲（自动视野计检查）、眼底视乳头水肿或萎缩","眼肌与颅神经：眼睑下垂、复视（海绵窦侵犯，Ⅲ/Ⅳ/Ⅵ颅神经）","内分泌相关：甲状腺（肿大或萎缩）、乳房（泌乳）、生殖器（发育与性征）、皮肤（色素沉着、多毛）","神经系统：肢体肌力、感觉、病理反射（大腺瘤压迫）","尿量与饮水：多尿与多饮（尿崩症）"],"lab_tests":["垂体激素全套：PRL、GH+IGF-1、ACTH+皮质醇（晨8时）、TSH+FT3/FT4、FSH/LH、睾酮/雌二醇","动态试验：口服葡萄糖抑制试验（GH瘤）、小剂量/大剂量地塞米松抑制试验（ACTH瘤）","垂体增强MRI（薄层）：肿瘤大小、部位、海绵窦侵犯与视交叉压迫（首选）","视力与视野检查（自动视野计）+眼底：术前基线与术后随访（视神经受压评估）","电解质（钠、钾）+尿量+尿比重+血浆渗透压：尿崩症与SIADH监测（术后每4～6小时）","血糖+糖化血红蛋白+血脂：GH瘤（糖尿病与血脂异常常见）与库欣评估","术后病理+免疫组化（PRL/GH/ACTH/TSH/FSH/LH/Ki-67）：确诊与分型"],"nursing":["尿量与电解质监测：术后每1～4小时记录尿量与尿比重，观察烦渴与多尿（尿崩症）或尿量减少（SIADH），异常立即报告","经鼻蝶术后护理：半卧位、观察鼻腔填塞物渗血与清水样渗液（脑脊液鼻漏）、避免用力擤鼻、咳嗽与打喷嚏（张口呼吸）","激素用药护理：按医嘱准时给予糖皮质激素（不可漏用），观察血压、血糖与精神状态；记录替代治疗剂量","视力与意识观察：评估视力与视野变化、意识状态与头痛（鞍区血肿/颅内压增高预警）","出入量与补液护理：准确记录24小时出入量与电解质，遵医嘱补液、限水（SIADH）或使用去氨加压素（尿崩症）","宣教：激素替代不可自行停药、应激状态（发热/手术/外伤）需加量、定期复查激素与MRI、出现多尿烦渴或视力下降立即就诊"],"diet":["术前：均衡饮食，控制血糖（GH瘤与库欣患者常有糖尿病）、限制钠盐与液体（高血压者）","经鼻蝶术后：清醒后从流质开始，避免过热食物（减少鼻腔渗血）；避免用力咀嚼与刺激性食物","尿崩症者：按医嘱饮水与补液，避免过量饮水；低钠血症（SIADH）者限制液体入量","长期激素替代者：适当增加钙与维生素D（防骨质疏松），控制体重与血糖","避免酒精与咖啡因（刺激多尿与影响激素代谢）；高蛋白、高维生素饮食促进术后恢复"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1389},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a9d16d3605e2f96abd9e940ef67616eb9508c110af1180ba03cddd95278be561","pinyin":"chuitiliu（waikezhiliao）","initials":"ctl（wkzl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","内分泌症状：闭经、泌乳、不孕（泌乳素瘤）；肢端肥大（手足增大、面容改变、下颌突出）；向心性肥胖、紫纹（ACTH瘤）\\n占位压迫：头痛（持续性）、视力下降、视野缺损（典型为双颞侧偏盲）\\n垂体功能减退：乏力、畏寒、性欲减退、月经紊乱、低血压（肾上腺功能减退）\\n垂体卒中（急症）：突发剧烈头痛、视力急剧下降、眼肌麻痹、意识障碍（瘤内出血）\\n尿崩症：多饮、多尿（垂体柄受累或术后）",60],["摘要","垂体瘤是起源于垂体前叶的良性肿瘤，按功能分为功能性（泌乳素瘤、生长激素瘤、ACTH瘤、TSH瘤）与无功能性腺瘤，按大小分为微腺瘤（<1cm）与大腺瘤（≥1cm）。表现为内分泌功能异常（闭经泌乳、肢端肥大、库欣综合征）、占位压迫（视力视野缺损、头痛）与垂体功能减退。治疗包括药物（泌乳素瘤首选多巴胺激动剂）、经鼻蝶手术与放疗。",30],["疾病编码","D35.2",30],["原首字母","ctlwkkzl",60]]},{"id":"orders-2daaa827c3233b11a8b9","key":"v1-c9ccc21dfe2a3058|orders-2daaa827c3233b11a8b9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"开颅术后管理","category":"神经外科","raw":{"name":"开颅术后管理","category":"神经外科","summary":"开颅术后管理重点是颅内压与意识监测、引流管（脑室外引流、硬膜下/瘤床引流）护理、癫痫与感染防治、电解质紊乱（尿崩症/SIADH）与早期康复。常见并发症包括术后出血（硬膜外/硬膜下/瘤床）、脑水肿、颅内感染、脑脊液漏、癫痫与深静脉血栓，早期识别与处理直接影响预后。","symptoms":["意识改变（嗜睡、烦躁、昏迷）——颅内压增高或术后出血的最早信号","头痛加重、呕吐（喷射性）、血压升高伴心率减慢（Cushing反应）","瞳孔不等大、对光反射迟钝（脑疝征象，急症）","癫痫发作（全身性/局灶性），术后24～72小时为高发期","发热（术后吸收热多<38.5℃且24～48小时内；持续或高热提示感染）、切口渗液（脑脊液漏）、癫痫、肢体活动障碍"],"diagnosis":["意识与瞳孔监测：每1～2小时GCS与瞳孔（术后24～48小时最密切）","头颅CT（术后常规及意识恶化时）：评估术区出血、脑水肿、脑室大小、气颅与引流管位置","引流量与性状记录：硬膜下/瘤床引流（血性→淡血性→淡黄），脑室外引流（清亮脑脊液，<20ml/h）","电解质+尿量+尿比重（每4～6小时）：尿崩症（多尿、高钠）与SIADH（少尿、低钠）监测","血常规+CRP+PCT+血培养+脑脊液检查（疑感染）：颅内感染（脑膜炎/脑室炎）诊断","血气分析+血糖：通气与代谢状态评估","D-二聚体+下肢静脉超声：深静脉血栓筛查（术后卧床者）"],"infusion":["⚠️ 按术后情况选择方案，切勿全部同时使用！","","方案1（降颅压与脑水肿）：","  用法：20%甘露醇 125～250ml 静滴 q6～8h（监测尿量、肾功能与电解质）；或 3%氯化钠 100～150ml 静滴；地塞米松 10mg 静推 q12h（脑水肿/肿瘤术后，短期）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（抗癫痫预防/治疗）：","  用法：左乙拉西坦 500mg（NS 100ml 或 5%GS 100ml）静滴 q12h 或 丙戊酸钠 400mg 静滴 q12h（预防用药一般术后7天，治疗用药按发作情况延长）；监测血药浓度〔调 ★ 必须按 CrCl 减量；老年减量〕","","方案3（抗感染，术前预防与术后治疗）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h（术前0.5～1小时起，术后24～48小时）；颅内感染者 美罗培南 2g 静滴 q8h + 万古霉素 1g 静滴 q12h（±脑室内给药）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案4（激素与电解质管理）：","  用法：氢化可的松 100mg 静滴 q8h（鞍区手术，防肾上腺危象）；尿崩症者去氨加压素 1～2μg 皮下注射（监测血钠）；低钠（SIADH）者限水，必要时 3%氯化钠〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","📌 术后出血多发生于24～48小时，意识恶化需立即复查CT；脑室外引流留置时间一般不超过7～10天。"],"oral_medication":["⚠️ 术后恢复期用药，按医嘱选择：","药物1（抗癫痫维持）：","用法：左乙拉西坦 500mg bid 或 丙戊酸钠缓释片 500mg bid（疗程依病因与术式，不可骤停）〔调 ★ 必须按 CrCl 减量；老年减量〕","药物2（营养神经与支持）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid + 胞磷胆碱 0.2g tid","药物3（激素减量，鞍区手术/脑水肿）：","用法：泼尼松 5mg 晨起（按医嘱逐渐减量）；氢化可的松（肾上腺功能减退者长期替代）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","药物4（通便与对症）：","用法：乳果糖 15ml bid（避免用力排便致颅压升高）；对乙酰氨基酚 0.5g 必要时（镇痛退热）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 术后避免用力排便、剧烈咳嗽与情绪激动（颅压波动）；抗癫痫药不可自行停药。"],"treatment":["术后监护：术后24～48小时重点监护（ICU或神经外科监护室），监测意识、瞳孔、生命体征与引流量","颅内压管理：床头抬高15～30°、镇痛镇静、避免用力与躁动、脱水治疗（甘露醇/高渗盐水），必要时脑室外引流或去骨瓣减压","引流管管理：硬膜下/瘤床引流低压引流（避免过度负压），脑室外引流控制高度与速度（<20ml/h），尽早拔管（感染风险）","抗癫痫：术后预防性用药（一般7天，依术式与病因），有发作者延长疗程；监测血药浓度","并发症处理：术后出血（复查CT，血肿量大或意识恶化者急诊清除）、脑水肿（脱水+激素）、颅内感染（抗感染±引流）、脑脊液漏（卧床+腰大池引流，必要时修补）、癫痫（抗癫痫药+病因处理）","电解质与内分泌管理：尿崩症（补液+去氨加压素）、SIADH（限水）、鞍区手术者激素替代","早期康复：病情稳定后尽早肢体功能训练、语言训练与认知康复，预防深静脉血栓（抗凝+气压治疗）与压疮","随访：术后1～3个月复查头颅CT/MRI与神经功能评估，依病因决定后续治疗（放疗/化疗）"],"management":["意识与瞳孔监测：每1～2小时（术后24～48小时）评估GCS与瞳孔并记录，意识下降或瞳孔异常立即报告并复查CT","体位护理：床头抬高15～30°、头颈中立位（避免颈静脉受压），翻身时保持头部稳定，避免剧烈搬动","引流管护理：标识与固定、保持通畅、记录引流量与性状（血性增多提示出血、浑浊提示感染）、防止逆流与脱出；脑室外引流控制高度（外耳道上方10～15cm）","颅压增高预防：镇痛镇静、避免用力排便（乳果糖）、避免剧烈咳嗽与躁动、保持呼吸道通畅","癫痫观察与护理：观察发作类型与频率，按时给药，发作时保护气道（头偏一侧）、防坠床与舌咬伤，记录发作时间与表现并报告","切口与脑脊液漏观察：保持敷料清洁干燥，观察渗液（清水样提示脑脊液漏）、红肿与皮下积液；避免用力擤鼻与打喷嚏（张口）","出入量与电解质：记录24小时出入量与尿量，监测血钠（尿崩症/SIADH）、血糖与肾功能"],"notes":["开颅术后24～48小时是并发症高发期：意识改变是最重要的预警信号，须立即复查CT","术后出血是严重并发症（硬膜外/硬膜下/瘤床），表现为意识恶化、瞳孔变化与引流量骤增","脑室外引流留置时间一般不超过7～10天（感染风险随时间增加），拔管前需评估与夹管试验","抗癫痫药物不可骤停（可诱发癫痫持续状态）；术后预防用药疗程依术式与病因决定","鞍区手术需警惕尿崩症与SIADH（均可致严重电解质紊乱）与肾上腺危象（激素不可漏用）"],"emergency":["意识迅速恶化、瞳孔不等大（术后出血/脑疝）→ 立即报告并急诊复查CT，必要时急诊清除血肿","引流量骤增且颜色鲜红（术后出血）→ 立即报告、监测生命体征并复查CT","癫痫持续状态（发作>5分钟或反复发作）→ 立即静推地西泮/咪达唑仑+抗癫痫药负荷量，保护气道","清水样鼻漏或切口渗液伴头痛发热（脑脊液漏+颅内感染）→ 卧床、报告医师，抗感染与引流处理","尿量骤增伴高钠或尿量减少伴低钠（尿崩症/SIADH）→ 立即评估电解质并遵医嘱处理"],"pinyin":"klshgl","icd10":"Z98.8","physical_exam":["意识与瞳孔：GCS评分（每小时）、瞳孔大小与对光反射（脑疝筛查）","生命体征：血压、心率、呼吸（Cushing反应）、体温与血氧","神经系统：肢体肌力与感觉（对比术前）、病理反射、颅神经功能（瞳孔、眼球运动、面瘫）","切口与头颅：敷料渗血渗液、局部肿胀、皮下积液、骨窗张力（去骨瓣者）","引流管：位置与高度、引流量与性状、通畅度","出入量与电解质：尿量、尿比重、有无多尿烦渴（尿崩症）或水肿（SIADH）","并发症相关：下肢肿胀（DVT）、肺部听诊（肺炎）、压疮（骶尾与枕部）"],"lab_tests":["头颅CT（术后常规及意识变化时）：术区出血、脑水肿、脑室大小、气颅与引流管位置","电解质（钠、钾）+尿量+尿比重+血浆渗透压（每4～6小时）：尿崩症与SIADH监测","血常规+CRP+PCT：感染监测；疑颅内感染时脑脊液检查（细胞数、生化、涂片与培养）+血培养","凝血功能+D-二聚体+血小板：术后出血与DVT风险评估","血气分析+血糖：通气与代谢状态（血糖控制目标7.8～10mmol/L）","抗癫痫药物血药浓度+肝功能：用药监测（丙戊酸钠、左乙拉西坦）","下肢静脉超声（高危患者）：DVT筛查"],"nursing":["意识与瞳孔观察：每1～2小时评估GCS与瞳孔并记录，异常立即报告（术后出血与脑疝预警）","体位与颅压管理：床头抬高15～30°、头颈中立，避免用力排便、剧烈咳嗽与躁动；遵医嘱脱水治疗","引流管护理：标识固定、保持通畅、记录引流量与性状；脑室外引流按医嘱控制高度（避免过度引流致气颅/出血）","切口护理：保持敷料清洁干燥，观察渗液（清水样提示脑脊液漏）与红肿，避免挠抓与污染","癫痫护理：观察发作并记录，按时给药；发作时头偏一侧、防坠床与舌咬伤，保持气道通畅","基础护理与康复：每2小时轴线翻身（防压疮）、口腔护理、肢体被动/主动活动（防DVT与关节僵硬）、早期床旁康复训练；出入量与电解质监测"],"diet":["术后早期：禁食或流质（视意识与吞咽功能），必要时鼻饲（床头抬高30～45°防误吸）或静脉营养","意识清醒、吞咽正常者：高蛋白、高热量、高维生素易消化饮食促进恢复与切口愈合","限制水分者按医嘱（颅内压增高、SIADH）；尿崩症者按尿量补液并避免过量饮水","多食蔬菜水果与粗纤维，保持大便通畅（避免用力排便致颅压升高），必要时用缓泻剂","控制血糖（高血糖加重脑损伤）、戒烟酒；癫痫患者避免酒精与咖啡因"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1390},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2911217031c817b2cc3d105adf89c692e35487c1e3e147b48e07ac6bb29be4f5","pinyin":"kailushuhouguanli","initials":"klshgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","意识改变（嗜睡、烦躁、昏迷）——颅内压增高或术后出血的最早信号\\n头痛加重、呕吐（喷射性）、血压升高伴心率减慢（Cushing反应）\\n瞳孔不等大、对光反射迟钝（脑疝征象，急症）\\n癫痫发作（全身性/局灶性），术后24～72小时为高发期\\n发热（术后吸收热多<38.5℃且24～48小时内；持续或高热提示感染）、切口渗液（脑脊液漏）、癫痫、肢体活动障碍",60],["摘要","开颅术后管理重点是颅内压与意识监测、引流管（脑室外引流、硬膜下/瘤床引流）护理、癫痫与感染防治、电解质紊乱（尿崩症/SIADH）与早期康复。常见并发症包括术后出血（硬膜外/硬膜下/瘤床）、脑水肿、颅内感染、脑脊液漏、癫痫与深静脉血栓，早期识别与处理直接影响预后。",30],["疾病编码","Z98.8",30],["原首字母","klshgl",60]]},{"id":"orders-d9db6c4b22763c3f16ab","key":"v1-c9ccc21dfe2a3058|orders-d9db6c4b22763c3f16ab","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肿瘤急症（上腔静脉综合征/脊髓压迫/颅内高压/高钙血症）","category":"化疗","raw":{"name":"肿瘤急症（上腔静脉综合征/脊髓压迫/颅内高压/高钙血症）","category":"化疗","summary":"肿瘤急症需立即识别与处理，常见包括：上腔静脉综合征（SVCS，纵隔肿瘤压迫致面颈上肢肿胀与呼吸困难）、脊髓压迫（硬膜外转移致背痛、肢体无力与大小便障碍）、颅内高压（脑转移致头痛呕吐与意识改变）、高钙血症（骨转移或PTHrP分泌）与肿瘤溶解综合征（已单列）。及时识别与紧急处理可避免不可逆神经损伤与死亡。","symptoms":["上腔静脉综合征：面颈部与上肢肿胀、颈静脉怒张、胸壁静脉曲张、呼吸困难、头晕头痛、声音嘶哑（平卧加重）","脊髓压迫：持续性背痛（夜间与平卧加重）、肢体麻木无力、感觉平面、大小便功能障碍（尿潴留/失禁）","颅内高压：晨起头痛、喷射性呕吐、视物模糊、意识改变、癫痫发作、瞳孔不等大","高钙血症：恶心呕吐、便秘、多尿多饮、乏力嗜睡、意识障碍、心律失常（'结石、骨痛、腹痛、精神症状'）","共性：症状进展迅速（数小时至数天），需紧急评估与干预"],"diagnosis":["上腔静脉综合征：胸部增强CT（明确阻塞部位与病因）、上腔静脉造影（必要时）、胸部X线（纵隔增宽）","脊髓压迫：全脊柱MRI增强（首选，明确压迫节段与程度，须在出现症状后24小时内完成）；脊柱X线/CT（骨破坏）","颅内高压：头颅增强CT/MRI（脑转移、水肿、脑疝征象）、眼底检查（视乳头水肿）","高钙血症：血钙（含离子钙+白蛋白校正）、PTH、PTHrP、碱性磷酸酶、25-羟维生素D、肾功能与电解质","肿瘤相关评估：原发肿瘤类型与分期、肿瘤标志物、必要时活检（明确病理以指导治疗）","血常规+凝血功能+电解质+肾功能+血气分析：综合评估与治疗监测","神经系统评估：肌力分级、感觉平面、反射与括约肌功能（脊髓压迫需每1～2小时评估并记录）"],"infusion":["⚠️ 肿瘤急症抢救用药，须立即处理并多学科协作！","方案1（上腔静脉综合征，减轻水肿与压迫）：","用法：地塞米松 10～20mg 静推后 4～6mg q6h（减轻纵隔水肿）；呋塞米 20～40mg 静推（减轻水负荷）；0.9%氯化钠 静滴（谨慎补液，上肢输液受限应下肢或中心静脉置管）；吸氧〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案2（脊髓压迫，保护神经功能）：","用法：地塞米松 10mg 静推后 4mg q6h（立即开始，减轻脊髓水肿）；甘露醇 125ml 静滴 q8～12h（必要时）；0.9%氯化钠 静滴维持灌注；尽快放疗或手术减压〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案3（颅内高压）：","用法：20%甘露醇 125～250ml 静滴 q6～8h（快速静滴）；地塞米松 10mg 静推 q6h（脑转移水肿）；3%氯化钠 100～150ml 静滴（难治性颅压增高）；必要时急诊放疗或手术〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案4（高钙血症）：","用法：0.9%氯化钠 1000～2000ml 静滴（快速补液，首24小时3～4L）；呋塞米 20～40mg 静推 q6～12h（补液后利尿）；唑来膦酸 4mg + 0.9%氯化钠 100ml 静滴（>15分钟）或 帕米膦酸二钠 60～90mg 静滴；降钙素 4IU/kg 皮下注射 q12h（快速起效，短期）；必要时血液透析","📌 肿瘤急症处理需多学科（肿瘤科、放疗科、神经外科、骨科、ICU）协作；激素用于减轻水肿但不能替代抗肿瘤治疗。"],"oral_medication":["⚠️ 急症稳定后的口服用药与支持：","药物1（激素减量，按医嘱逐渐减停）：","用法：地塞米松 4mg q6h → 逐渐减量（防颅压/水肿反跳，不可骤停）；同时护胃（艾司奥美拉唑 20mg qd）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物2（镇痛，脊髓压迫/骨转移疼痛）：","用法：吗啡缓释片 10～30mg q12h（按疼痛滴定）+ 即释吗啡 5～10mg 必要时；或羟考酮缓释片 10mg q12h；同时预防便秘（乳果糖 15ml bid）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（骨转移骨保护）：","用法：唑来膦酸 4mg 静滴 每3～4周 或 地舒单抗 120mg 皮下注射 每4周；碳酸钙D3 600mg qd + 维生素D 800IU/日","药物4（抗癫痫与对症）：","用法：左乙拉西坦 500mg bid（脑转移伴癫痫）；乳果糖 15ml bid（阿片类致便秘）〔调 ★ 必须按 CrCl 减量；老年减量〕","📌 激素减量需缓慢（数周），突然停药可致脑水肿反跳；骨保护药物使用前需口腔检查（预防颌骨坏死）。"],"treatment":["上腔静脉综合征：抬高床头、吸氧、激素（地塞米松 10～20mg 静推 后 4～6mg 静滴 q6h）+利尿（呋塞米 20～40mg 静推）减轻水肿；紧急放疗（放疗敏感肿瘤如小细胞肺癌、淋巴瘤）或化疗；血管内支架置入（快速缓解，尤其放疗不敏感者）；抗凝（合并血栓时）","脊髓压迫：立即激素（地塞米松 10mg 静推 继以 4～10mg 静滴/口服 q6h）+尽快放疗（放疗敏感肿瘤）或手术减压固定（脊柱不稳、单发压迫、病理不明或放疗无效者）；理想治疗窗口为症状出现后24～48小时内","颅内高压：激素+甘露醇 0.25～1g/kg 静滴 q4～6h/高渗盐水降颅压；全脑放疗（多发脑转移）或立体定向放疗（寡转移）；手术切除（单发大病灶、颅压危象）；抗癫痫治疗","高钙血症：大量补液（0.9%氯化钠 200～500ml/h 静滴）+利尿（呋塞米 20～40mg 静推）+双膦酸盐（唑来膦酸 4mg 静滴 15分钟，±降钙素 4～8IU/kg 皮下 q12h），控制原发病（化疗/激素治疗），避免制动与噻嗪类利尿剂","抗肿瘤治疗：明确病理后尽快启动针对性治疗（化疗/靶向/免疫/放疗），是根本解决肿瘤急症的手段","支持治疗与并发症防治：镇痛（阿片类按三阶梯，如吗啡 5～10mg 口服/皮下 q4h 按需）、抗凝（VTE风险）、营养支持、感染防治、心理支持","多学科协作：肿瘤科、放疗科、神经外科、骨科、ICU与影像科共同决策（多数急症需急诊放疗或手术）","随访与宣教：告知患者与家属急症预警症状（背痛、肢体无力、大小便障碍、气促、意识改变）并立即就诊"],"management":["紧急评估与分诊：评估生命体征、神经功能（肌力、感觉、括约肌）与气道安全，急症优先处理（脊髓压迫与颅压危象不可延误）","神经功能监测（脊髓压迫/脑转移）：每1～2小时评估肌力、感觉平面与大小便功能并记录，恶化立即报告（决定手术/放疗时机）","激素与降颅压执行：按医嘱准时给药，观察疗效（症状缓解）与不良反应（血糖升高、消化道出血、感染、失眠），监测血糖与电解质","补液与电解质管理：高钙血症大量补液并记录出入量；颅压增高者限制液体；监测血钠、血钙、肾功能与尿量","气道与呼吸管理：上腔静脉综合征者抬高床头、吸氧、避免上肢输液（选下肢或中心静脉），观察呼吸困难与声音嘶哑（气道受压）","疼痛与症状管理：按三阶梯镇痛并预防便秘，评估疼痛评分；观察大小便功能与皮肤完整性（截瘫风险者防压疮）","放疗/手术前准备与宣教：快速完成定位、备血与术前准备；向患者家属解释治疗紧迫性与风险并完成知情同意"],"notes":["肿瘤急症的共同特点是进展快、可致不可逆损伤或死亡，需在数小时内识别与处理","脊髓压迫须在24小时内明确诊断并治疗（激素+放疗或手术），延迟治疗常致永久性截瘫与大小便功能障碍","激素是减轻水肿的重要手段但不能替代抗肿瘤治疗；激素减量需缓慢（防水肿反跳）","高钙血症处理首要是补液（禁用噻嗪类利尿剂与制动），双膦酸盐为一线降钙药物（需监测肾功能与血钙）","脑转移患者抗癫痫药仅用于有发作者（预防性用药不推荐）；激素与抗癫痫药有相互作用需注意"],"emergency":["脊髓压迫（背痛+肢体无力+大小便障碍）→ 立即激素+全脊柱MRI，24小时内放疗或手术减压","上腔静脉综合征伴呼吸困难、意识改变或气道受压 → 抬高床头、吸氧、激素+利尿，紧急放疗或支架置入","颅内高压伴意识恶化、瞳孔不等大（脑疝）→ 立即甘露醇/高渗盐水+激素，急诊放疗或手术减压","高钙危象（血钙>3.5mmol/L伴意识障碍或心律失常）→ 立即大量补液+利尿+双膦酸盐，必要时透析","癫痫持续状态（脑转移患者）→ 立即静推地西泮/咪达唑仑+抗癫痫药负荷量，保护气道"],"pinyin":"zljzsjcmyzslngxgx","icd10":"C80.0","physical_exam":["生命体征：血压、心率、呼吸频率与形态、血氧（气道受压与循环评估）、体温","上腔静脉综合征体征：面颈部与上肢肿胀、颈静脉怒张、胸壁静脉曲张、口唇发绀、声嘶","神经系统：意识（GCS）、肌力分级、感觉平面、腱反射、病理反射、括约肌功能（直肠指检评估张力）","脊柱：棘突压痛与叩击痛、脊柱畸形、活动受限（脊髓压迫定位）","眼底与颅神经：视乳头水肿、瞳孔、眼球运动（颅内高压与颅神经受累）","高钙相关：脱水征、心律失常（心率与心律）、意识状态、肌肉无力与腱反射减弱","肿瘤体征：浅表淋巴结肿大、原发灶相关体征（肺部体征、腹块）、骨转移局部压痛"],"lab_tests":["血钙（含离子钙+白蛋白校正）+PTH+PTHrP+碱性磷酸酶+25-羟维生素D：高钙血症诊断与病因鉴别","电解质（钠、钾、钙）+肾功能+尿量：补液与利尿治疗监测（每4～6小时，高钙/颅压增高时）","全脊柱MRI增强（脊髓压迫首选）：明确压迫节段、程度与有无多发转移（症状出现后24小时内完成）","头颅增强CT/MRI（颅内高压）：脑转移灶、水肿范围与脑疝征象","胸部增强CT（上腔静脉综合征）：阻塞部位、纵隔肿块与血管受压情况（必要时上腔静脉造影）","血常规+凝血功能+肝肾功能+血气分析：综合评估与治疗准备","肿瘤标志物+病理活检：明确原发肿瘤类型（指导针对性治疗）"],"nursing":["急症监测与报告：评估生命体征与神经功能（肌力、感觉、括约肌）每1～2小时并记录，恶化立即报告（脊髓压迫与颅压危象预警）","激素与脱水用药护理：按医嘱准时给药，观察疗效与不良反应（血糖、血压、消化道出血、感染），监测血糖与电解质","体位与呼吸护理：上腔静脉综合征者抬高床头、吸氧、避免上肢输液（选下肢或中心静脉）；颅内高压者床头抬高15～30°","出入量与电解质监测：准确记录24小时出入量与尿量，高钙血症者补液充足、颅压增高者限制液体，监测血钠与血钙","疼痛与舒适护理：按三阶梯镇痛并预防便秘，评估疼痛评分；截瘫/活动障碍者每2小时轴线翻身防压疮，保持皮肤清洁干燥","心理与家属沟通：急症病情危重，及时沟通病情与治疗紧迫性，安抚情绪并配合完成知情同意与治疗转运"],"diet":["高钙血症：充足饮水（每日2000～3000ml，心肾功能允许下）、低钙饮食（避免大量牛奶与钙剂）、限制钠盐","颅内高压：按医嘱限制液体入量，避免大量饮水；低盐饮食","脊髓压迫/卧床患者：高纤维饮食与充足水分（防便秘，避免用力排便）、高蛋白饮食防压疮与肌肉萎缩","激素治疗期间：低盐低糖饮食、控制体重、补充钙与维生素D（预防骨质疏松）、保护胃黏膜","总体原则：高蛋白、高热量、易消化，少量多餐；必要时口服营养补充剂或肠内营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1391},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"be63b70e972f11f2e55e05058f7374c4aaf0c4253808cdf2a5c54801c26e4f85","pinyin":"zhongliujizheng（shangqiangjingmaizonghezheng/jisuiyapo/luneigaoya/gaogaixuezheng）","initials":"zljz（sqjmzhz/jsyp/lngy/ggxz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","上腔静脉综合征：面颈部与上肢肿胀、颈静脉怒张、胸壁静脉曲张、呼吸困难、头晕头痛、声音嘶哑（平卧加重）\\n脊髓压迫：持续性背痛（夜间与平卧加重）、肢体麻木无力、感觉平面、大小便功能障碍（尿潴留/失禁）\\n颅内高压：晨起头痛、喷射性呕吐、视物模糊、意识改变、癫痫发作、瞳孔不等大\\n高钙血症：恶心呕吐、便秘、多尿多饮、乏力嗜睡、意识障碍、心律失常（'结石、骨痛、腹痛、精神症状'）\\n共性：症状进展迅速（数小时至数天），需紧急评估与干预",60],["摘要","肿瘤急症需立即识别与处理，常见包括：上腔静脉综合征（SVCS，纵隔肿瘤压迫致面颈上肢肿胀与呼吸困难）、脊髓压迫（硬膜外转移致背痛、肢体无力与大小便障碍）、颅内高压（脑转移致头痛呕吐与意识改变）、高钙血症（骨转移或PTHrP分泌）与肿瘤溶解综合征（已单列）。及时识别与紧急处理可避免不可逆神经损伤与死亡。",30],["疾病编码","C80.0",30],["原首字母","zljzsjcmyzslngxgx",60]]},{"id":"orders-48130f81641cee5c46c8","key":"v1-c9ccc21dfe2a3058|orders-48130f81641cee5c46c8","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"癌痛规范化治疗（三阶梯与阿片类滴定）","category":"化疗","raw":{"name":"癌痛规范化治疗（三阶梯与阿片类滴定）","category":"化疗","summary":"癌痛是肿瘤患者最常见症状之一（发生率约50%～70%），规范镇痛可显著改善生活质量。遵循WHO三阶梯原则：轻度疼痛用非甾体抗炎药（NSAIDs）±辅助药，中度用弱阿片类（曲马多/可待因），重度用强阿片类（吗啡/羟考酮/芬太尼）。核心原则：按阶梯、按时、个体化给药，口服优先，注意阿片类不良反应防治与滴定。","symptoms":["疼痛（部位、性质、强度：NRS 0～10分或面部表情量表），影响睡眠、活动与情绪","阿片类不良反应：便秘（最常见且不随时间耐受）、恶心呕吐、嗜睡、瘙痒、尿潴留、呼吸抑制（过量）","阿片类耐受与依赖：需增加剂量才能镇痛（耐受）；突然停药出现戒断症状（依赖）","爆发痛：基础镇痛良好时出现的短暂剧烈疼痛发作（每日≥3次提示基础剂量不足）","心理社会问题：焦虑、抑郁、恐惧、睡眠障碍（疼痛的放大因素）"],"diagnosis":["疼痛评估：部位、性质（伤害性/神经病理性/混合）、强度（NRS评分）、时间规律、诱因与缓解因素、对生活的影响","疼痛分类：伤害性疼痛（躯体/内脏）对阿片类反应好；神经病理性疼痛需加用辅助药（加巴喷丁/普瑞巴林/三环类）","阿片类滴定：未用过阿片类者从小剂量开始（吗啡即释片5～10mg q4h，按疼痛评分调整）","剂量换算：口服吗啡与羟考酮、芬太尼贴剂（μ g/h 与口服吗啡日剂量换算）的等效剂量换算表","评估镇痛疗效：疼痛评分下降程度、爆发痛次数、睡眠与活动改善、不良反应（每24小时评估）","辅助检查：疼痛部位影像（骨转移、病理性骨折、脊髓压迫）、电解质与肝肾功能（药物代谢）","心理评估：焦虑抑郁量表（PHQ-9、GAD-7）与睡眠评估"],"infusion":["⚠️ 急性重度疼痛与滴定用药，须遵医嘱并监测呼吸！","方案1（急性重度疼痛，阿片类静脉滴定）：","用法：吗啡 2～5mg 静推（缓慢，>5分钟），每10～15分钟评估疼痛与呼吸，必要时重复（最大不超过初始剂量的3倍）；或芬太尼 25～50μg 静推（按医嘱）","方案2（阿片类不良反应处理）：","用法：0.9%氯化钠 静滴；甲氧氯普胺 10mg 静推 q8h（恶心呕吐）；纳洛酮 0.1～0.4mg 静推（呼吸抑制，须谨慎滴定以免诱发急性戒断与剧痛）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","方案3（神经病理性疼痛，辅助用药静滴）：","用法：0.9%氯化钠 静滴；必要时 利多卡因 1～2mg/kg 静滴（神经病理性疼痛，心电监护下）；或 氯胺酮 0.1～0.3mg/kg/h 泵入（难治性疼痛，麻醉科指导）","方案4（骨转移疼痛与其他支持）：","用法：唑来膦酸 4mg + 0.9%氯化钠 100ml 静滴 每3～4周（骨转移疼痛与骨相关事件）；地塞米松 10mg 静推（脊髓压迫/颅内压增高致痛）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","📌 阿片类滴定以口服为主（即释吗啡 q4h），按时给药而非按需；呼吸抑制（呼吸<8次/分）为急症需立即处理。"],"oral_medication":["⚠️ 按疼痛阶梯选择，逐步升级，按时给药！","第一阶梯（轻度疼痛，NRS 1～3分）：","用法：对乙酰氨基酚 0.5～1.0g q6h（每日不超过4g）；或布洛芬 0.3g bid／塞来昔布 200mg qd（餐后，注意胃肠道与肾毒性）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","第二阶梯（中度疼痛，NRS 4～6分）：","用法：曲马多缓释片 100mg q12h（或可待因 30mg q6h）± 对乙酰氨基酚〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","第三阶梯（重度疼痛，NRS 7～10分）：","用法：吗啡缓释片 10～30mg q12h（起始）或 羟考酮缓释片 10mg q12h；爆发痛时用即释吗啡 5～10mg（日剂量为基础量的10%～15%）；芬太尼透皮贴剂 25μg/h q72h（不能口服者）","辅助用药（神经病理性疼痛/骨痛）：","用法：加巴喷丁 0.1～0.3g tid（逐渐加量）或 普瑞巴林 75mg bid；阿米替林 10～25mg qn；地塞米松 4mg qd（骨转移/颅内压增高）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","预防阿片类不良反应（除便秘外多数可耐受）：","用法：乳果糖 15～30ml bid（便秘预防，必须同时开始）；甲氧氯普胺 10mg tid（恶心，短期）；必要时止吐药〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","📌 阿片类必须按时给药（不可等疼痛加重再给）；便秘需同时预防性用药；剂量按疼痛评分与不良反应个体化调整。"],"treatment":["阿片类滴定（快速镇痛）：未用过阿片类者口服即释吗啡 5～10mg q4h，24小时内评估疗效与不良反应，按需追加，次日计算总剂量转换为缓释剂型（q12h）","剂量调整原则：疼痛未控制（NRS>3）且无严重不良反应时按25%～50%递增；出现不可耐受不良反应（嗜睡、呼吸抑制）时减量或换药（阿片轮换）","给药途径选择：口服优先→皮下/静脉（不能口服或需快速滴定）→芬太尼透皮贴（慢性稳定疼痛）→椎管内给药（难治性疼痛）","神经病理性疼痛：阿片类基础上加用辅助药（加巴喷丁/普瑞巴林/三环类/SNRI）","阿片类不良反应防治：便秘（预防性使用乳果糖，必要时甲基纳曲酮）、恶心呕吐（甲氧氯普胺/昂丹司琼，短期）、嗜睡（多在1周内耐受，注意鉴别过度镇静）、呼吸抑制（纳洛酮+吸氧+监护）、瘙痒（抗组胺药/换药）","阿片轮换与减量：出现耐受或不良反应时按等效剂量换算换用其他阿片类（考虑不完全交叉耐受，减少25%～50%剂量）；疼痛缓解后缓慢减量（每日减10%～20%），不可骤停","多模式镇痛：非药物措施（放疗、骨保护药、神经阻滞/椎管内镇痛、心理干预、物理治疗）与药物联合","患者与家属宣教：按时服药、不可自行增减或停药、不良反应识别（呼吸抑制、过度镇静）、爆发痛处理方法与便秘预防"],"management":["疼痛评估与记录：每日评估疼痛评分（静息与活动时）、爆发痛次数与对睡眠的影响，每24小时记录并据此调整方案","给药执行：严格按时给药（阿片类不可等疼痛加重再给），观察镇痛效果与不良反应，记录用药与疼痛变化","不良反应监测：呼吸频率（<8次/分提示呼吸抑制需紧急处理）、镇静程度、恶心呕吐、便秘、尿潴留、瘙痒与皮疹","便秘预防：从阿片类治疗开始即预防性使用缓泻剂（乳果糖±刺激性泻药），记录排便次数与性状","心理与睡眠支持：评估焦虑抑郁与睡眠，提供心理支持；必要时抗抑郁/抗焦虑治疗（注意与阿片类相互作用）","宣教与依从性：向患者与家属解释规范镇痛的重要性、按时服药、不可自行停药（防戒断）；提供爆发痛处理指导与便秘预防方法","多学科协作：肿瘤科、疼痛科、姑息治疗、心理科、康复科与护理团队协作制定个体化镇痛方案"],"notes":["癌痛治疗遵循WHO三阶梯原则：按阶梯、按时、个体化给药，口服优先，注意阿片类不良反应防治","阿片类药物无'天花板效应'（除部分药物外），可根据疼痛与不良反应滴定剂量；'成瘾'在癌痛患者中罕见（<1%）","便秘是阿片类最常见且不随时间耐受的不良反应，必须从治疗开始即预防性使用缓泻剂","呼吸抑制为阿片类过量表现，需立即处理（纳洛酮+吸氧+监护）；纳洛酮需小剂量缓慢给药以避免诱发剧痛与戒断","神经病理性疼痛对单纯阿片类反应差，需联合辅助药（加巴喷丁/普瑞巴林/三环类/SNRI）","疼痛缓解后减量需缓慢（每日减10%～20%），突然停药可致戒断症状与疼痛反跳"],"emergency":["呼吸抑制（呼吸<8次/分或血氧下降）伴嗜睡/昏迷（阿片类过量）→ 立即吸氧、纳洛酮 0.1～0.4mg 静推（小剂量缓慢）、监护并减少阿片剂量","突发剧烈疼痛伴肢体无力与大小便障碍（脊髓压迫）→ 立即激素+MRI，紧急放疗或手术","剧痛伴病理性骨折或活动障碍 → 急诊制动、镇痛与影像评估（放疗或手术固定）","恶心呕吐致脱水与电解质紊乱 → 补液、纠正电解质并调整止吐方案"],"pinyin":"atgfhzlssjttyad","icd10":"G89.3","physical_exam":["生命体征：呼吸频率与形态（阿片类呼吸抑制）、血压、心率、体温","疼痛评估：疼痛部位、性质、强度（NRS）、诱发因素与对活动/睡眠的影响","意识与镇静程度：警觉/嗜睡/昏睡（Pasero镇静评分，过度镇静提示阿片过量）","皮肤与瞳孔：针尖样瞳孔（阿片类效应）、瘙痒与皮疹、注射部位（芬太尼贴剂）","腹部与肠道：腹胀、肠鸣音与排便情况（阿片类致便秘与肠梗阻风险）","神经系：感觉、肌力与反射（骨转移致脊髓压迫评估）、疼痛分布与神经病理性体征","骨与关节：骨转移部位压痛、病理性骨折体征、活动受限"],"lab_tests":["肝肾功能+电解质+血钙：阿片类代谢与骨转移/高钙血症评估（每1～3个月或按病情）","血常规+CRP：肿瘤状态与感染评估","疼痛部位影像（X线/CT/MRI/骨扫描）：骨转移、病理性骨折与脊髓压迫评估","阿片类药物血药浓度（必要时）：疗效不佳或疑中毒时（吗啡、芬太尼）","粪便常规+腹部平片（便秘/肠梗阻疑诊）：评估阿片类致肠梗阻","心理评估量表（PHQ-9、GAD-7）+睡眠评估：疼痛的心理共病评估","肾功能（肌酐清除率）：吗啡代谢产物蓄积风险（肾功能不全者需调整剂量）"],"nursing":["疼痛评估与记录：每班评估疼痛评分（静息与活动）、爆发痛次数与睡眠，及时报告未控制的疼痛","给药护理：严格按时给药（不可按需等待），观察疗效与不良反应；芬太尼贴剂需记录粘贴时间与部位（q72h更换，避免热敷）","呼吸与镇静监测：观察呼吸频率（<8次/分立即报告）与镇静程度（过度镇静提示剂量过高）","便秘防治：预防性使用缓泻剂、记录排便次数与性状、鼓励饮水与活动，必要时灌肠","心理与舒适护理：倾听患者疼痛主诉（'疼痛是患者的主观感受'）、缓解焦虑、协助舒适体位与睡眠环境改善","宣教：按时服药与不可自行增减/停药、识别呼吸抑制与过度镇静、爆发痛处理方法、便秘预防与阿片类常见不良反应（多数1周内耐受）"],"diet":["高蛋白、高热量、易消化饮食，少量多餐（肿瘤消耗状态需营养支持）","充足饮水（每日1500～2000ml）与高纤维饮食（蔬菜、水果、粗粮）预防阿片类所致便秘","恶心呕吐者：清淡温凉、少量多餐，避免油腻与强烈气味；必要时口服营养补充剂","骨转移患者：补充钙与维生素D（配合骨保护治疗）；肾功能不全者按医嘱限制蛋白与钾","避免酒精（加重镇静与肝损伤）、咖啡因过量；便秘严重时避免产气与坚硬食物"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1392},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"68a7d76fbefbdac85342689855aaff41af152ae568680c8df43c2b0652c8a05e","pinyin":"aitongguifanhuazhiliao（sanjietiyuapianleididing）","initials":"atgfhzl（sjtyapldd）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","疼痛（部位、性质、强度：NRS 0～10分或面部表情量表），影响睡眠、活动与情绪\\n阿片类不良反应：便秘（最常见且不随时间耐受）、恶心呕吐、嗜睡、瘙痒、尿潴留、呼吸抑制（过量）\\n阿片类耐受与依赖：需增加剂量才能镇痛（耐受）；突然停药出现戒断症状（依赖）\\n爆发痛：基础镇痛良好时出现的短暂剧烈疼痛发作（每日≥3次提示基础剂量不足）\\n心理社会问题：焦虑、抑郁、恐惧、睡眠障碍（疼痛的放大因素）",60],["摘要","癌痛是肿瘤患者最常见症状之一（发生率约50%～70%），规范镇痛可显著改善生活质量。遵循WHO三阶梯原则：轻度疼痛用非甾体抗炎药（NSAIDs）±辅助药，中度用弱阿片类（曲马多/可待因），重度用强阿片类（吗啡/羟考酮/芬太尼）。核心原则：按阶梯、按时、个体化给药，口服优先，注意阿片类不良反应防治与滴定。",30],["疾病编码","G89.3",30],["原首字母","atgfhzlssjttyad",60]]},{"id":"orders-9808368ec80b9b7c5b85","key":"v1-c9ccc21dfe2a3058|orders-9808368ec80b9b7c5b85","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"高钠血症处理方案","category":"电解质紊乱","raw":{"name":"高钠血症处理方案","category":"电解质紊乱","summary":"高钠血症指血钠>145mmol/L，多因水丢失多于钠丢失（发热、大汗、腹泻、尿崩症、意识障碍不能饮水）或钠摄入过多（高渗盐水、碳酸氢钠）所致。纠正原则：先纠正容量不足，血钠下降速度不超过每小时0.5mmol/L、每24小时不超过10～12mmol/L（防脑水肿）。","symptoms":["口渴（早期主要症状，但意识障碍或老年患者可缺如）","神经系统：烦躁、嗜睡、肌张力增高、腱反射亢进、抽搐、昏迷（血钠>155～160mmol/L）","尿量改变（尿崩症者多尿、尿比重低）","脱水征：皮肤弹性差、黏膜干燥、眼窝凹陷、心率增快、血压下降","原发病表现：发热、腹泻、糖尿病高渗状态"],"diagnosis":["血钠+血渗透压（每2～4小时复查，纠正期间）：评估程度与速度","尿量+尿比重+尿钠+尿渗透压：鉴别失水途径（尿崩症、渗透性利尿）","血糖+肾功能+电解质：排除糖尿病高渗状态与肾性原因","血气分析：评估酸碱失衡","容量状态评估：血压、心率、尿量、皮肤弹性与中心静脉压（决定补液种类）","病因学：有无发热、腹泻、利尿剂、甘露醇、碳酸氢钠使用史","体重与出入量：每日记录（指导补液量计算）"],"infusion":["⚠️ 按容量状态与病因选择方案，纠正速度必须缓慢！","方案1（低容量性高钠，首选等渗液纠正容量）：","用法：0.9%氯化钠 1000～2000ml 静滴（先纠正循环容量不足）；随后按失水量用 0.45%氯化钠（半张液）或 5%葡萄糖 静滴补充自由水","方案2（等容量/高容量性高钠，补自由水）：","用法：5%葡萄糖 静滴（提供自由水）；高容量者（如高渗盐水过量）需同时利尿：呋塞米 20～40mg 静推；必要时血液透析（肾衰合并高钠）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","方案3（尿崩症所致）：","用法：0.45%氯化钠 或 5%葡萄糖 静滴补液；去氨加压素 1～2μg 皮下注射/静推（中枢性尿崩）或口服 0.1～0.2mg","方案4（抽搐/严重神经系统症状）：","用法：5%葡萄糖 静滴快速降低血钠（仅限急性高钠，降速仍需控制）；抽搐者地西泮 10mg 缓慢静推〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","📌 纠正速度：每小时血钠下降≤0.5mmol/L、24小时≤10～12mmol/L；补液种类需按容量状态选择（先晶体后自由水）。"],"oral_medication":["⚠️ 意识清醒、能口服者优先口服补液：","药物1（口服补液）：","用法：口服补液盐 或 白开水（自由水补充）少量多次，按口渴与尿量调整","药物2（病因治疗）：","用法：去氨加压素片 0.1～0.2mg bid～tid（中枢性尿崩症，按尿量调整）；卡马西平 0.1g bid（部分肾性尿崩，遵医嘱）","药物3（利尿剂相关调整）：","用法：停用或减量噻嗪类/袢利尿剂（遵医嘱）；氢氯噻嗪（肾性尿崩的特殊用法，遵医嘱）","📌 老年与意识障碍患者需主动喂水（口渴感减退）；尿崩症者需长期随访血钠与尿量。"],"treatment":["评估容量状态：低容量者先补等渗液恢复循环，高容量者限制钠并利尿","计算缺水量：缺水量(L)=体重(kg)×0.6×(血钠/140－1)（男性；女性×0.5），24～48小时均匀补充","选择补液种类：低容量用0.9%氯化钠；自由水补充用0.45%氯化钠或5%葡萄糖","纠正速度控制：每小时降钠≤0.5mmol/L（急性高钠可稍快但不超过1mmol/L/h），每2～4小时复查血钠","病因治疗：尿崩症（去氨加压素）、糖尿病高渗状态（胰岛素+补液）、停用致病药物（甘露醇、高渗盐水、碳酸氢钠）","并发症防治：纠正过快致脑水肿（头痛、意识恶化、抽搐）——应立即减慢速度并用甘露醇","监测：每2～4小时血钠、每小时尿量与出入量、神经系统症状（意识、抽搐）","营养与护理：意识障碍者鼻饲补水、口腔护理（黏膜干燥易破损）、皮肤护理"],"management":["血钠监测：纠正期间每2～4小时复查，达到目标后每6～12小时，稳定后每日","出入量与体重：准确记录24小时出入量，每日固定时间测体重（评估补液效果）","神经系统观察：意识、抽搐、肌张力与腱反射（高钠本身与纠正过快均可致神经症状）","补液执行：严格按医嘱速度与种类输液（不可自行加快），观察穿刺部位与输液反应","口腔与皮肤护理：口腔黏膜干燥者每2～4小时湿润护理；皮肤弹性差者加强皮肤护理防破损","宣教：口渴者主动饮水（不能等到口渴）、避免高钠食物与含钠输液、尿崩症患者遵医嘱用药与复查"],"notes":["高钠血症的死亡率与纠正速度密切相关：纠正过快可致脑水肿与永久性神经损害","计算缺水量仅作参考，实际补液需结合尿量、出入量、血压与血钠变化动态调整","老年、意识障碍、气管插管患者是高钠血症高危人群（口渴感减退、不能主动饮水）","治疗过程中出现头痛、意识恶化或抽搐提示脑水肿（纠正过快），应立即减慢速度并脱水治疗","尿崩症所致高钠需同时补充自由水并使用去氨加压素（血钠与尿量监测）"],"emergency":["血钠>160mmol/L伴意识障碍或抽搐 → 立即缓慢补液纠正（降速≤1mmol/L/h），抽搐予地西泮","纠正过程中突发头痛、意识恶化、抽搐（脑水肿）→ 立即停止快速纠正、给甘露醇并复查血钠","高钠伴低血压与少尿（严重脱水/高渗状态）→ 立即补等渗液复苏并寻找病因","糖尿病高渗状态（血糖>33mmol/L+高钠+意识障碍）→ 胰岛素+大量补液，转ICU"],"pinyin":"gnxzclfa","icd10":"E87.0","physical_exam":["生命体征：血压（低容量可下降）、心率（增快）、体温（发热致失水）、呼吸","意识与神经系统：意识状态、肌张力、腱反射、抽搐（高钠脑病）","脱水征：皮肤弹性、黏膜干燥、眼窝凹陷、腋下干燥、毛细血管充盈时间","体重与出入量：体重变化（急性失水者显著下降）","尿量与尿色：多尿（尿崩症）或尿量减少（脱水）","病因相关：发热、腹泻、糖尿病表现（多饮多尿、体重下降）","口腔：口腔黏膜干燥程度、有无溃疡（脱水与口腔护理不足）"],"lab_tests":["血钠+血渗透压（每2～4小时，纠正期间）：评估程度与纠正速度","尿量+尿比重+尿钠+尿渗透压：鉴别尿崩症（低比重、低渗透压）与渗透性利尿","血糖+糖化血红蛋白：排除糖尿病高渗状态","肾功能+电解质（钾、氯、钙、镁）+血气分析：评估脱水、酸碱失衡与合并电解质紊乱","血常规+红细胞压积+白蛋白：评估血液浓缩程度","肝功能+凝血功能：严重脱水可致肝功能异常","必要时头颅MRI：纠正过快致脑水肿或渗透性脱髓鞘评估"],"nursing":["血钠与出入量监测：按医嘱定时复查血钠，准确记录24小时出入量与每小时尿量，异常立即报告","补液护理：严格按医嘱速度与液体种类输注（高钠纠正须缓慢），观察输液反应与穿刺部位","神经系统观察：每1～2小时评估意识、抽搐与肌张力，出现脑水肿征象立即报告","口腔与皮肤护理：口腔湿润护理每2～4小时、皮肤保湿与减压（脱水患者皮肤脆弱易损）","饮水指导：能口服者鼓励主动饮水（少量多次），不能口服者鼻饲补自由水","宣教：尿崩症患者遵医嘱用去氨加压素并记录尿量、避免高钠饮食、定期复查血钠"],"diet":["能口服者：少量多次饮水（自由水补充），避免高钠食物（腌制品、咸菜、加工肉）","低容量者：口服补液盐按说明冲服；腹泻发热者及时补充水分与电解质","恢复期：清淡饮食，适量蛋白质与蔬果，避免过量含钠调料","意识障碍或吞咽困难者：鼻饲（含足够水分），监测电解质","尿崩症患者：按医嘱饮水与用药，避免脱水与过量饮水交替"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1393},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f56e0c31e36afbb48b6f95031a1f462d1bc3115b70024cc7d9643a000fd0505f","pinyin":"gaonaxuezhengchulifangan","initials":"gnxzclfa","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","口渴（早期主要症状，但意识障碍或老年患者可缺如）\\n神经系统：烦躁、嗜睡、肌张力增高、腱反射亢进、抽搐、昏迷（血钠>155～160mmol/L）\\n尿量改变（尿崩症者多尿、尿比重低）\\n脱水征：皮肤弹性差、黏膜干燥、眼窝凹陷、心率增快、血压下降\\n原发病表现：发热、腹泻、糖尿病高渗状态",60],["摘要","高钠血症指血钠>145mmol/L，多因水丢失多于钠丢失（发热、大汗、腹泻、尿崩症、意识障碍不能饮水）或钠摄入过多（高渗盐水、碳酸氢钠）所致。纠正原则：先纠正容量不足，血钠下降速度不超过每小时0.5mmol/L、每24小时不超过10～12mmol/L（防脑水肿）。",30],["疾病编码","E87.0",30],["原首字母","gnxzclfa",60]]},{"id":"orders-1c622d8d0333690fe268","key":"v1-c9ccc21dfe2a3058|orders-1c622d8d0333690fe268","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"低钙血症处理方案","category":"电解质紊乱","raw":{"name":"低钙血症处理方案","category":"电解质紊乱","summary":"低钙血症指血钙（白蛋白校正后）<2.1mmol/L，常见于甲状旁腺功能减退（甲状腺/甲状旁腺术后）、维生素D缺乏、急性胰腺炎、慢性肾病、低镁血症与大量输血（枸橼酸螯合钙）。表现为神经肌肉兴奋性增高（手足搐搦、Chvostek征、Trousseau征）、QT间期延长与心律失常。","symptoms":["口周与指端麻木、手足搐搦（腕足痉挛）、肌肉痉挛与疼痛","Chvostek征（叩击面神经致面肌抽搐）与Trousseau征（束臂试验阳性）","神经系统：焦虑、烦躁、抽搐（重度）、喉痉挛（危急，可致窒息）","心血管：QT间期延长、心律失常（尖端扭转型室速）、低血压","慢性者：皮肤干燥、指甲脆、白内障、骨质疏松、精神状态改变"],"diagnosis":["血钙（含离子钙）+白蛋白（校正血钙）：校正钙=实测钙+0.02×(40－白蛋白g/L)","血镁+血磷+碱性磷酸酶：低镁可致难治性低钙（需同时补镁）；高磷见于甲旁减与肾衰","甲状旁腺激素（PTH）：低钙伴低PTH提示甲旁减；低钙伴高PTH提示维生素D缺乏或肾衰","25-羟维生素D+1,25-二羟维生素D：维生素D缺乏评估","心电图：QT间期延长、T波改变、心律失常（每6～12小时或症状变化时复查）","肾功能+电解质+血气分析：慢性肾病、酸碱失衡与合并症评估","病因学：甲状腺/甲状旁腺手术史、胰腺炎、大量输血、药物（双膦酸盐、化疗）"],"infusion":["⚠️ 按症状严重程度选择方案，葡萄糖酸钙静推必须缓慢！","方案1（症状性低钙/手足搐搦，静脉补钙）：","用法：10%葡萄糖酸钙 10～20ml + 5%葡萄糖 20ml 缓慢静推（>10分钟，速度<2ml/min）；随后 10%葡萄糖酸钙 30～60ml + 0.9%氯化钠 500ml 静滴维持（按血钙调整）","方案2（重度/持续低钙或喉痉挛）：","用法：10%葡萄糖酸钙 60～100ml + 0.9%氯化钠 1000ml 持续静滴（每小时监测血钙与心电图）；必要时补镁：25%硫酸镁 10ml + 0.9%氯化钠 250ml 静滴","方案3（急性胰腺炎/大量输血相关低钙）：","用法：10%葡萄糖酸钙 10ml 缓慢静推（按离子钙水平重复）；输血时每输4～6U血制品补钙10ml","方案4（维生素D缺乏与慢性低钙）：","用法：0.9%氯化钠 静滴；活性维生素D（骨化三醇）与口服钙剂为主","📌 静推葡萄糖酸钙须缓慢并心电监护（快速推注可致心脏抑制、低血压与心律失常）；低镁血症必须先/同时纠正否则低钙难以纠正。"],"oral_medication":["⚠️ 长期口服补钙与维生素D是慢性低钙治疗的核心：","药物1（钙剂）：","用法：碳酸钙D3 600mg bid～tid（随餐服，吸收好）；或枸橼酸钙 0.5g tid（胃酸缺乏或服用PPI者优先）","药物2（活性维生素D）：","用法：骨化三醇 0.25～0.5μg qd（甲旁减首选，按血钙调整）；或阿法骨化醇 0.25～0.5μg qd","药物3（补镁，低镁者）：","用法：门冬氨酸钾镁片 2片 tid 或 氧化镁 0.5g tid（按血镁调整）","药物4（噻嗪类利尿剂，减少尿钙排泄，甲旁减患者）：","用法：氢氯噻嗪 25mg qd（遵医嘱，注意监测血钾与血压）","📌 目标血钙为正常低值（2.0～2.1mmol/L），避免过度补钙致高钙尿与肾结石；定期监测血钙、尿钙与肾功能。"],"treatment":["急性症状性低钙：静脉补钙（10%葡萄糖酸钙 10～20ml 稀释后缓慢静推，继以 0.5～1.5mg/kg/h 元素钙维持静滴），同时纠正低镁","病因治疗：甲旁减（骨化三醇 0.25～0.5μg 口服 qd + 碳酸钙 1～2g 元素钙/d 长期替代）、维生素D缺乏（补充维生素D与钙）、胰腺炎（治疗胰腺炎）、停用致病药物（双膦酸盐、利尿剂）、大量输血时预防性补钙","监测与调整：每4～6小时（急性期）或每周（慢性期）复查血钙，据结果调整补钙剂量","低镁血症纠正：硫酸镁 1～2g 静滴（缓慢）或口服补镁（低镁使PTH分泌受抑且靶器官抵抗，单独补钙无效）","并发症处理：喉痉挛（立即静脉补钙+吸氧，必要时气管插管）、心律失常（补钙+纠正电解质，必要时抗心律失常药）、抽搐（补钙+地西泮 10mg 缓慢静推）","慢性低钙长期管理：活性维生素D（骨化三醇 0.25～1μg/d）+钙剂，维持血钙在正常低值，监测尿钙与肾功能（防肾结石与肾钙化）","术后甲旁减：甲状腺/甲状旁腺术后监测血钙，症状性低钙予静脉补钙，多数暂时性（数周内恢复）","随访：血钙、磷、PTH、尿钙与骨密度（长期替代治疗者）"],"management":["血钙监测：急性期每4～6小时、稳定后每日或每周复查，记录症状与心电图变化","症状观察：口周麻木、手足搐搦、肌肉痉挛、喉痉挛与抽搐（每班评估），异常立即报告","静脉补钙护理：葡萄糖酸钙缓慢静推（>10分钟）、心电监护、严防外渗（可致组织坏死）","心电图监测：QT间期延长与心律失常（重度低钙或快速纠正时）","口服补钙执行：按时给药并与餐同服（碳酸钙）或空腹（枸橼酸钙），与左甲状腺素、铁剂间隔4小时","宣教：长期服药不可自行停药（甲旁减需终身）、识别低钙症状及时就诊、饮食补钙（牛奶、豆制品、绿叶蔬菜）与维生素D（晒太阳）"],"notes":["白蛋白校正血钙是判断的关键（低白蛋白血症时实测总钙偏低但离子钙可正常）","低镁血症可致难治性低钙：不纠正低镁时单纯补钙效果差，必须同时补镁","葡萄糖酸钙静推必须缓慢（<2ml/min）并心电监护（快速推注可致心脏抑制与心律失常）","甲旁减患者需终身活性维生素D与钙剂替代，目标血钙为正常低值，避免高钙尿与肾结石","大量输血、急性胰腺炎与化疗（顺铂、双膦酸盐）是住院患者低钙的常见原因，需主动监测"],"emergency":["喉痉挛、呼吸困难（重度低钙致气道痉挛）→ 立即静脉缓慢推注葡萄糖酸钙+吸氧，必要时气管插管","全身抽搐（低钙致癫痫样发作）→ 立即静脉补钙（缓慢）+地西泮 10mg 缓慢静推","尖端扭转型室速或QT明显延长 → 立即静脉补钙并补镁，心电监护与抗心律失常处理","甲状腺术后出现手足搐搦伴呼吸困难 → 立即静脉补钙并评估颈部血肿（双重危险）"],"pinyin":"dgxzclfa","icd10":"E83.5","physical_exam":["生命体征：血压（低钙可致低血压）、心率与心律（心律失常）、呼吸（喉痉挛）","神经肌肉兴奋性：Chvostek征（叩击面神经）、Trousseau征（束臂试验）、手足搐搦与肌肉痉挛","意识与精神状态：焦虑、烦躁、抽搐、慢性者情绪与认知改变","皮肤与附属器：皮肤干燥、指甲脆裂、脱发（慢性低钙）","颈部：甲状腺/甲状旁腺手术瘢痕、颈部肿胀（术后血肿）","眼部：白内障（慢性低钙）、视乳头水肿（罕见）","心脏：心音、心律不齐（QT延长致心律失常）"],"lab_tests":["血钙（含离子钙）+白蛋白（校正血钙）：诊断与监测核心（急性期每4～6小时）","血镁+血磷+碱性磷酸酶：低镁致难治性低钙、甲旁减与肾衰鉴别","甲状旁腺激素（PTH）：低钙伴低PTH为甲旁减；低钙伴高PTH为维生素D缺乏或肾衰","25-羟维生素D+1,25-二羟维生素D：维生素D缺乏评估","心电图：QT间期延长与心律失常（每6～12小时或症状变化时）","肾功能+电解质+血气分析：慢性肾病、酸碱失衡评估","尿钙+尿钙/肌酐比：长期补钙治疗监测（防高钙尿与肾结石）"],"nursing":["症状观察：每班询问口周麻木、手足搐搦与肌肉痉挛，观察Chvostek征与Trousseau征，异常立即报告","静脉补钙护理：严格按医嘱缓慢静推（>10分钟）并心电监护；选择通畅静脉、严防外渗（外渗可致组织坏死，一旦发生立即停止并局部处理）","心电图监测：观察QT间期与心律失常，备好抢救药品与除颤仪","口服补钙护理：按时给药（碳酸钙随餐、枸橼酸钙空腹），与左甲状腺素/铁剂间隔4小时，观察便秘等不良反应","气道观察（重度低钙）：警惕喉痉挛（吸气性喉鸣、呼吸困难），床旁备钙剂与气道设备","宣教：甲旁减需终身服药不可自行停药、识别低钙症状（麻木、抽搐）及时就诊、饮食补钙与补充维生素D、定期复查血钙与尿钙"],"diet":["高钙饮食：牛奶、酸奶、豆制品、小鱼小虾（连骨）、深绿色蔬菜、芝麻酱","适量优质蛋白与维生素D（深海鱼、蛋黄、晒太阳），促进钙吸收","避免高磷食物（碳酸饮料、加工肉、动物内脏）——甲旁减与肾衰患者需控制磷摄入","避免过量咖啡因、酒精与高盐饮食（增加尿钙排泄）","慢性低钙者少量多餐，必要时口服营养补充剂；服用钙剂时避免与富含草酸食物（菠菜）同服（影响吸收）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1394},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b4207dace76cb91944b277e14ece3a437f27f35d4b81b8eb9ff5f63f67f22da8","pinyin":"digaixuezhengchulifangan","initials":"dgxzclfa","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","口周与指端麻木、手足搐搦（腕足痉挛）、肌肉痉挛与疼痛\\nChvostek征（叩击面神经致面肌抽搐）与Trousseau征（束臂试验阳性）\\n神经系统：焦虑、烦躁、抽搐（重度）、喉痉挛（危急，可致窒息）\\n心血管：QT间期延长、心律失常（尖端扭转型室速）、低血压\\n慢性者：皮肤干燥、指甲脆、白内障、骨质疏松、精神状态改变",60],["摘要","低钙血症指血钙（白蛋白校正后）<2.1mmol/L，常见于甲状旁腺功能减退（甲状腺/甲状旁腺术后）、维生素D缺乏、急性胰腺炎、慢性肾病、低镁血症与大量输血（枸橼酸螯合钙）。表现为神经肌肉兴奋性增高（手足搐搦、Chvostek征、Trousseau征）、QT间期延长与心律失常。",30],["疾病编码","E83.5",30],["原首字母","dgxzclfa",60]]},{"id":"orders-f528efc18c78f32c223a","key":"v1-c9ccc21dfe2a3058|orders-f528efc18c78f32c223a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"低镁血症处理方案","category":"电解质紊乱","raw":{"name":"低镁血症处理方案","category":"电解质紊乱","summary":"低镁血症指血镁<0.75mmol/L，常见于长期利尿剂/PPI使用、腹泻、酒精中毒、糖尿病控制不佳、顺铂化疗与重症患者。表现为神经肌肉兴奋性增高（震颤、抽搐）、心律失常（尖端扭转型室速）、难治性低钾与低钙。血镁正常不能排除体内镁缺乏（仅2%存在于细胞外）。","symptoms":["神经肌肉：肌震颤、肌肉痉挛、手足搐搦、腱反射亢进、抽搐","心血管：心悸、心律失常（房颤、尖端扭转型室速）、QT延长、洋地黄毒性增强","神经精神：乏力、淡漠、谵妄、抑郁、眼球震颤","合并电解质紊乱：难治性低钾（补钾无效）与低钙（补钙无效）","胃肠道：恶心、呕吐、食欲减退、腹胀"],"diagnosis":["血镁（每6～12小时，补镁治疗期间）：<0.75mmol/L为低镁，<0.5mmol/L为重度","电解质全套（钾、钙、钠、磷）：低镁常伴低钾与低钙（须同时评估）","心电图：QT间期延长、T波平坦、U波、心律失常","肾功能+尿量：补镁剂量调整依据（肾功能不全易致高镁血症）","血气分析+血糖：酸碱失衡与糖尿病评估","病因学：利尿剂（呋塞米、噻嗪类）、PPI（奥美拉唑长期使用）、腹泻、酒精、化疗药物（顺铂）","24小时尿镁（必要时）：鉴别肾性丢失与胃肠道丢失"],"infusion":["⚠️ 补镁须缓慢静滴并监测肾功能与腱反射！","方案1（中重度低镁，静脉补镁）：","用法：25%硫酸镁 10ml（2.5g）+ 0.9%氯化钠 250～500ml 静滴（2～4小时）；或 10%硫酸镁 20～40ml + 0.9%氯化钠 500ml 静滴（缓慢）","方案2（重度/尖端扭转型室速）：","用法：25%硫酸镁 8～10ml（2～2.5g）稀释后缓慢静推（10～20分钟，心电监护）；随后 25%硫酸镁 20～30ml + 0.9%氯化钠 500ml 静滴（6～12小时）；同时纠正低钾","方案3（合并低钾，须同时纠正）：","用法：10%氯化钾 15～20ml + 0.9%氯化钠 500ml 静滴（见尿补钾，速度≤1g/h）；低镁不纠正时低钾难以纠正","方案4（难治性低镁/持续丢失）：","用法：25%硫酸镁 10ml + 0.9%氯化钠 500ml 静滴 q12h（持续数天）；同时治疗病因（停用致病药物、控制腹泻）","📌 补镁速度过快可致低血压、呼吸抑制与心脏抑制（静推时须缓慢并心电监护）；肾功能不全者剂量减半并密切监测血镁与腱反射。"],"oral_medication":["⚠️ 轻中度低镁与长期维持用药：","药物1（口服补镁）：","用法：门冬氨酸钾镁片 2片 tid（同时补钾镁）或 氧化镁 0.5g tid（注意腹泻）；枸橼酸镁 1袋 tid","药物2（肠溶镁剂，减少腹泻）：","用法：门冬氨酸镁片 2片 tid（胃肠刺激较轻）","药物3（病因治疗）：","用法：停用或替换长期PPI（如必须使用可改用H2受体拮抗剂，遵医嘱）；调整利尿剂剂量；控制腹泻","药物4（合并低钾/低钙）：","用法：氯化钾缓释片 1g bid（低钾）；碳酸钙D3 600mg qd（低钙，须在补镁后）","📌 口服镁剂可致腹泻（氧化镁明显），腹泻加重反而丢失更多镁（优先选择门冬氨酸镁）；长期PPI使用者应定期监测血镁。"],"treatment":["补镁治疗：中重度静脉补镁（硫酸镁缓慢静滴），轻度口服补镁（每日补镁量约0.5mmol/kg）","同时纠正低钾与低钙：低镁不纠正时低钾与低钙难以纠正（补镁优先或同时进行）","病因治疗：停用/替换致病药物（利尿剂、PPI、氨基糖苷类）、控制腹泻与呕吐、戒酒、调整糖尿病治疗","心律失常处理：尖端扭转型室速——静脉补镁（缓慢静推）+补钾+必要时超速起搏或利多卡因；停用致QT延长药物","监测与调整：血镁每6～12小时（静脉补镁期间）、心电图与腱反射（补镁过量的早期表现：腱反射消失）","洋地黄中毒协同：低镁增强洋地黄毒性（心律失常），须纠正低镁并监测洋地黄血药浓度","营养与长期管理：酒精中毒者补充B族维生素与营养支持；长期PPI使用者定期监测血镁","随访：血镁、钾、钙与心电图（慢性低镁者）"],"management":["血镁与电解质监测：静脉补镁期间每6～12小时复查血镁、钾、钙，记录心电图变化","补镁护理：硫酸镁静滴速度严格按医嘱（过快致低血压与呼吸抑制），心电监护，备葡萄糖酸钙（镁中毒拮抗剂）","腱反射与呼吸观察：补镁过程中每1～2小时评估腱反射（消失提示镁过量）、呼吸频率与血压","尿量监测：肾功能不全者补镁需减量（尿量<30ml/h时慎用或减量），记录每小时尿量","症状评估：观察肌震颤、抽搐、心悸与心律失常，及时报告","宣教：避免长期滥用PPI（按需使用）、酒精中毒者戒酒、饮食补镁（坚果、绿叶蔬菜、全谷物、豆类）、定期复查电解质"],"notes":["血镁正常不能排除镁缺乏（血清镁仅占体内总镁的1%～2%），临床高度怀疑时应试验性补镁","低镁是难治性低钾与低钙的常见原因：不补镁时补钾补钙效果差","补镁速度过快可致低血压、呼吸抑制、心脏抑制——静推须缓慢并心电监护，备葡萄糖酸钙拮抗","长期使用PPI（尤其>1年）可致低镁血症，应定期监测血镁","顺铂化疗、氨基糖苷类抗生素、两性霉素B与环孢素均可致肾性失镁（用药期间监测）"],"emergency":["尖端扭转型室速（QT延长+宽QRS波群扭转）→ 立即静脉缓慢推注硫酸镁 2～2.5g + 补钾，心电监护","抽搐（低镁致神经肌肉兴奋性增高）→ 静脉补镁（缓慢）+地西泮，纠正合并低钙","补镁过程中出现腱反射消失、呼吸抑制或低血压（镁中毒）→ 立即停用并静脉推注10%葡萄糖酸钙 10ml","严重心律失常伴血流动力学不稳定 → 补镁补钾+电复律（必要时）"],"pinyin":"dmxzclfa","icd10":"E83.4","physical_exam":["生命体征：血压（低镁致低血压）、心率与心律（心律失常）、呼吸频率","神经肌肉兴奋性：肌震颤、腱反射亢进（低镁）或消失（镁过量）、手足搐搦、Chvostek征","意识与精神：淡漠、谵妄、抑郁、眼球震颤","心脏：心律不齐、心音（QT延长与心律失常）","胃肠道：腹胀、肠鸣音（低镁致肠麻痹）","病因相关：利尿剂使用、PPI长期服用、腹泻、酒精中毒体征（肝掌、蜘蛛痣、震颤）","尿量与脱水：尿量记录与脱水征（补镁剂量调整依据）"],"lab_tests":["血镁（每6～12小时，补镁期间）：<0.75mmol/L为低镁，<0.5mmol/L为重度","电解质全套（钾、钙、钠、磷）：低镁常合并低钾低钙，须同步评估与纠正","心电图：QT延长、T波平坦、U波与心律失常（补镁期间每6～12小时）","肾功能（肌酐、肌酐清除率）+每小时尿量：补镁剂量调整（肾功能不全易致高镁）","血气分析+血糖+肝功能：酸碱失衡、糖尿病与酒精性肝病评估","24小时尿镁（必要时）：鉴别肾性丢失与胃肠道丢失","洋地黄血药浓度（服用者）：低镁增强洋地黄毒性"],"nursing":["补镁护理：严格按医嘱速度静滴硫酸镁（缓慢），心电监护，备10%葡萄糖酸钙（镁中毒拮抗剂）","腱反射与呼吸监测：补镁期间每1～2小时评估腱反射、呼吸频率与血压（腱反射消失提示镁过量）","电解质与尿量监测：按时复查血镁、钾、钙；记录每小时尿量（肾功能不全者补镁需减量）","心律观察：持续心电监护，观察QT间期与心律失常，异常立即报告","症状护理：观察肌震颤、抽搐与心悸；抽搐时保护气道与安全（防坠床与舌咬伤）","宣教：避免长期滥用PPI、戒酒、补镁饮食（坚果、绿叶蔬菜、豆类、全谷物）、定期复查血镁与电解质"],"diet":["富镁食物：坚果（杏仁、腰果）、whole谷物（燕麦、糙米）、豆类、深绿色蔬菜（菠菜）、香蕉、黑巧克力","避免过量饮酒与咖啡因（增加镁排泄）","腹泻者避免高纤维与乳制品（加重腹泻与镁丢失），必要时肠内营养支持","长期PPI使用者：定期监测血镁并按医嘱补镁","均衡饮食、少量多餐；酒精中毒者补充B族维生素与营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1395},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c97bb14e53ded4d4c1e42b3bf3fee381c9bc495b6c173415c17acb624a811592","pinyin":"dimeixuezhengchulifangan","initials":"dmxzclfa","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","神经肌肉：肌震颤、肌肉痉挛、手足搐搦、腱反射亢进、抽搐\\n心血管：心悸、心律失常（房颤、尖端扭转型室速）、QT延长、洋地黄毒性增强\\n神经精神：乏力、淡漠、谵妄、抑郁、眼球震颤\\n合并电解质紊乱：难治性低钾（补钾无效）与低钙（补钙无效）\\n胃肠道：恶心、呕吐、食欲减退、腹胀",60],["摘要","低镁血症指血镁<0.75mmol/L，常见于长期利尿剂/PPI使用、腹泻、酒精中毒、糖尿病控制不佳、顺铂化疗与重症患者。表现为神经肌肉兴奋性增高（震颤、抽搐）、心律失常（尖端扭转型室速）、难治性低钾与低钙。血镁正常不能排除体内镁缺乏（仅2%存在于细胞外）。",30],["疾病编码","E83.4",30],["原首字母","dmxzclfa",60]]},{"id":"orders-fd898b209d166af04ba3","key":"v1-c9ccc21dfe2a3058|orders-fd898b209d166af04ba3","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"代谢性酸中毒处理原则","category":"电解质紊乱","raw":{"name":"代谢性酸中毒处理原则","category":"电解质紊乱","summary":"代谢性酸中毒是HCO₃⁻原发性降低（<22mmol/L）伴pH下降的酸碱失衡，按阴离子间隙（AG）分为高AG型（乳酸酸中毒、酮症酸中毒、尿毒症、中毒）与正常AG型（腹泻致碳酸氢盐丢失、肾小管酸中毒、大量生理盐水输注致高氯性酸中毒）。治疗原则是治疗病因、改善组织灌注，谨慎补碱。","symptoms":["呼吸深快（Kussmaul呼吸，代偿性过度通气），呼气有酮味（酮症酸中毒）","乏力、食欲减退、恶心呕吐、腹痛（酮症酸中毒常见）","意识改变：嗜睡、谵妄、昏迷（重度酸中毒或原发病）","心血管：心率增快、血压下降、心律失常（酸中毒抑制心肌收缩力并对儿茶酚胺反应下降）","原发病表现：休克（乳酸酸中毒）、多饮多尿与脱水（酮症）、腹泻（高氯性）、尿毒症症状"],"diagnosis":["动脉血气分析（pH、PaCO₂、HCO₃⁻、BE、乳酸）：区分代谢性/呼吸性，计算代偿是否适当（Winter公式：预计PaCO₂=1.5×HCO₃⁻+8±2）","电解质（Na⁺、Cl⁻、K⁺）+阴离子间隙（AG=Na⁺－Cl⁻－HCO₃⁻，正常8～16）：区分高AG与正常AG型；白蛋白低时需校正AG","乳酸（每2～4小时）：乳酸酸中毒（>2mmol/L）与组织灌注评估","血糖+血酮/尿酮+糖化血红蛋白：糖尿病酮症酸中毒（DKA）诊断","肾功能+尿素氮：尿毒症性酸中毒","血渗透压+毒物筛查（必要时）：甲醇、乙二醇、水杨酸中毒（高AG伴渗透压间隙增大）","尿pH+尿酮+尿铵（必要时）：肾小管酸中毒鉴别"],"infusion":["⚠️ 以治疗病因为主，补碱需谨慎（仅限重度酸中毒或特定病因）！","方案1（液体复苏与病因治疗，首要）：","用法：平衡盐溶液（乳酸钠林格，注意乳酸酸中毒者慎用大量含乳酸液体）或 0.9%氯化钠 500～1000ml 快速补液（评估后调整）；休克者按脓毒症/失血性休克处理","方案2（糖尿病酮症酸中毒，DKA标准治疗）：","用法：0.9%氯化钠 1000ml/h（首1小时）→ 按脱水程度调整；胰岛素 0.1U/kg/h 泵入（血糖降至13.9mmol/L后改用5%葡萄糖+胰岛素）；补钾：10%氯化钾 10～20ml + 0.9%氯化钠 500ml 静滴（血钾<5.5mmol/L且有尿时）","方案3（碳酸氢钠，仅用于pH<7.1或特定情况）：","用法：5%碳酸氢钠 100～250ml 静滴（缓慢，按血气调整）；适应证：pH<7.1、严重高钾血症、三环类抗抑郁药/水杨酸中毒、丢失碳酸氢盐的肾小管酸中毒；禁用于乳酸酸中毒（除非pH<7.0）与酮症酸中毒（一般不需补碱）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","方案4（病因治疗，按病因选择）：","用法：感染性休克——抗感染+液体复苏+血管活性药；尿毒症——血液透析；中毒——特效解毒剂（甲醇/乙二醇用乙醇或甲吡唑+透析，水杨酸用碱化尿液+透析）；腹泻——补液与止泻","📌 补碱须缓慢并监测血气与电解质（过快致低钾、低钙、代谢性碱中毒反跳、脑水肿与CO₂蓄积）；乳酸酸中毒与DKA以治疗病因为主，不常规补碱。"],"oral_medication":["⚠️ 急性期以静脉治疗为主；恢复期与慢性酸中毒口服用药：","药物1（口服碱剂，慢性代谢性酸中毒/肾小管酸中毒）：","用法：碳酸氢钠片 1～2g tid（按血气调整）；枸橼酸钠钾溶液 10～20ml tid（肾小管酸中毒首选，同时补钾）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","药物2（补钾，酸中毒纠正后常需）：","用法：枸橼酸钾颗粒 1袋 tid 或 氯化钾缓释片 1g bid（监测血钾与肾功能）","药物3（病因治疗）：","用法：二甲双胍相关乳酸酸中毒者停药；糖尿病者胰岛素与降糖方案调整；腹泻者对症治疗","药物4（营养与支持）：","用法：碳酸钙 0.6g tid（慢性肾病降磷与轻度补碱）；维生素D 与钙剂（肾性骨病）","📌 慢性肾病患者的碱剂与钾剂需按血气、血钾与肾功能个体化调整；避免自行长期服用大剂量碳酸氢钠（钠负荷与碱中毒风险）。"],"treatment":["病因治疗为核心：感染性休克（抗感染+液体复苏+升压药）、DKA（补液+胰岛素+补钾）、腹泻（补液止泻）、尿毒症（透析）、中毒（解毒剂±透析）","改善组织灌注：液体复苏维持MAP≥65mmHg与尿量≥0.5ml/kg/h（乳酸酸中毒的关键）","补碱指征与原则：pH<7.1、严重高钾血症、水杨酸/三环类中毒、碳酸氢盐丢失性疾病；碳酸氢钠缓慢静滴并监测血气（避免过量）","DKA管理：补液（首小时1L生理盐水）、胰岛素泵入（0.1U/kg/h）、补钾（血钾<5.5且有尿时）、监测血糖与酮体（每1～2小时）、避免血糖下降过快（脑水肿风险）","电解质管理：酸中毒纠正后血钾下降（需补钾）、离子钙下降（注意补钙）、避免低磷（DKA者补磷）","监测：血气每2～4小时（急性期）、乳酸、电解质、血糖、尿量与意识状态","并发症防治：脑水肿（纠正过快，尤其儿童DKA）、低钾血症、低钙血症、代谢性碱中毒反跳、容量过负荷","慢性代谢性酸中毒：口服碱剂（碳酸氢钠/枸橼酸盐）长期治疗并随访血气与肾功能"],"management":["血气与电解质监测：急性期每2～4小时复查血气、电解质与乳酸，记录AG与代偿情况","补液与出入量：准确记录24小时出入量与每小时尿量（目标≥0.5ml/kg/h），监测血压与心率","意识与呼吸观察：Kussmaul呼吸、意识状态变化（重度酸中毒与脑水肿预警）","DKA专项护理：每小时测血糖（血糖下降速度≤4～6mmol/L/h）、记录胰岛素泵入速度、监测血钾（每2～4小时）、观察意识与呼吸（脑水肿）","补碱护理：严格按医嘱缓慢静滴碳酸氢钠，避免外渗（可致组织坏死），监测血气与电解质（防过量）","宣教：糖尿病患者的胰岛素与饮食管理（预防DKA）、慢性肾病者遵医嘱口服碱剂、避免自行停药、识别酸中毒症状（深大呼吸、乏力、意识改变）及时就诊"],"notes":["代谢性酸中毒治疗的核心是『治疗病因与改善组织灌注』，而非单纯补碱","乳酸酸中毒与酮症酸中毒一般不补碱（补碱可加重细胞内酸中毒与容量负荷），仅pH<7.0～7.1时谨慎使用","补碱过快可致低钾、低钙、代谢性碱中毒反跳、CO₂蓄积（呼吸抑制者）与脑水肿","DKA纠正过程中血糖下降过快可致脑水肿（儿童风险最高），应控制下降速度并监测意识","高AG伴渗透压间隙增大提示中毒（甲醇、乙二醇），需紧急毒物筛查与特效治疗"],"emergency":["pH<7.1伴血流动力学不稳定或严重高钾 → 谨慎补碱（碳酸氢钠缓慢静滴）+积极治疗病因，转ICU","DKA伴意识障碍、Kussmaul呼吸与严重脱水 → 立即补液+胰岛素+补钾，每小时监测血糖与电解质","乳酸明显升高伴休克（乳酸酸中毒）→ 立即液体复苏+升压药+治疗感染灶，监测乳酸清除率","意识障碍伴高AG与渗透压间隙增大（甲醇/乙二醇中毒）→ 紧急毒物筛查、特效解毒剂与血液透析","纠正过程中突发头痛、意识恶化（脑水肿）→ 立即减慢纠正速度、复查血气与血钠，必要时甘露醇"],"pinyin":"dxsxzdclfa","icd10":"E87.2","physical_exam":["生命体征：呼吸频率与深度（Kussmaul呼吸）、血压（低血压）、心率（增快）、体温","意识与神经系统：意识状态、谵妄、昏迷、肌张力与反射","脱水征：皮肤弹性、黏膜干燥、眼窝凹陷、体重变化","呼吸气味：烂苹果味（酮症酸中毒）、酒精味、异常气味（中毒）","心血管：心律不齐、心音低钝、末梢循环（毛细血管充盈时间延长）","腹部：腹痛与压痛（DKA常见，易误诊为急腹症）、肠鸣音","原发病相关：感染灶（肺部、泌尿系）、糖尿病表现、肾病体征（水肿、贫血）"],"lab_tests":["动脉血气分析（pH、PaCO₂、HCO₃⁻、BE、乳酸）：每2～4小时（急性期），计算AG与代偿情况","电解质（Na、K、Cl）+阴离子间隙（AG）：区分高AG与正常AG型酸中毒（低白蛋白时校正AG）","乳酸（每2～4小时）：乳酸酸中毒与组织灌注评估（乳酸清除率是复苏指标）","血糖+血酮（β-羟丁酸）+尿酮+糖化血红蛋白：DKA诊断与疗效监测","肾功能（肌酐、尿素氮）+尿常规：尿毒症性酸中毒与肾小管酸中毒评估","血渗透压+毒物筛查（必要时）：甲醇、乙二醇、水杨酸中毒","尿pH+尿铵+尿钾（必要时）：肾小管酸中毒分型"],"nursing":["血气与电解质监测：按时复查血气、电解质与乳酸并记录趋势，异常立即报告","补液与尿量护理：快速建立静脉通路（必要时两条），记录每小时尿量与24小时出入量，监测血压与心率","意识与呼吸观察：观察Kussmaul呼吸与意识变化（重度酸中毒、脑水肿预警）","DKA护理：每小时监测血糖（控制下降速度4～6mmol/L/h）、按医嘱调整胰岛素泵速、监测血钾与尿量、观察意识与呼吸","补碱护理：严格按医嘱缓慢静滴碳酸氢钠并观察外渗（可致组织坏死），监测血气与电解质","宣教：糖尿病患者胰岛素不可自行停用、规律监测血糖、识别DKA症状（多饮多尿、恶心呕吐、深大呼吸）及时就诊；慢性肾病者遵医嘱服碱剂并复查"],"diet":["急性期：禁食或流质（视病情），静脉补液为主；DKA患者禁食至酮体转阴与血糖稳定（遵医嘱）","DKA恢复期：逐步从流质→半流质过渡，按糖尿病饮食控制碳水（每日热量按理想体重计算）","慢性肾病酸中毒：低蛋白优质蛋白饮食（按肾功能分期）、限制磷与钾、口服碱剂与钙剂","腹泻所致酸中毒：清淡易消化、少量多餐，避免高纤维与乳制品，必要时口服补液盐","均衡饮食、避免过量酒精（酒精性酮症酸中毒）；多饮水（无心肾功能不全者）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1396},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"12568830dde27e78da7aa4bf3ea02b726abc0f16ab1fada505495f83ea22e2de","pinyin":"daixiexingsuanzhongduchuliyuanze","initials":"dxxszdclyz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","呼吸深快（Kussmaul呼吸，代偿性过度通气），呼气有酮味（酮症酸中毒）\\n乏力、食欲减退、恶心呕吐、腹痛（酮症酸中毒常见）\\n意识改变：嗜睡、谵妄、昏迷（重度酸中毒或原发病）\\n心血管：心率增快、血压下降、心律失常（酸中毒抑制心肌收缩力并对儿茶酚胺反应下降）\\n原发病表现：休克（乳酸酸中毒）、多饮多尿与脱水（酮症）、腹泻（高氯性）、尿毒症症状",60],["摘要","代谢性酸中毒是HCO₃⁻原发性降低（<22mmol/L）伴pH下降的酸碱失衡，按阴离子间隙（AG）分为高AG型（乳酸酸中毒、酮症酸中毒、尿毒症、中毒）与正常AG型（腹泻致碳酸氢盐丢失、肾小管酸中毒、大量生理盐水输注致高氯性酸中毒）。治疗原则是治疗病因、改善组织灌注，谨慎补碱。",30],["疾病编码","E87.2",30],["原首字母","dxsxzdclfa",60]]},{"id":"orders-c3010c49a08b76c94eb4","key":"v1-c9ccc21dfe2a3058|orders-c3010c49a08b76c94eb4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"代谢性碱中毒处理原则","category":"电解质紊乱","raw":{"name":"代谢性碱中毒处理原则","category":"电解质紊乱","summary":"代谢性碱中毒是HCO₃⁻原发性升高（>26mmol/L）伴pH上升的酸碱失衡，常伴低氯与低钾。按对氯反应性分为：对氯反应性（呕吐、胃肠减压、利尿剂致低氯低钾性碱中毒——补生理盐水可纠正）与对氯抵抗性（原醛、库欣、Bartter综合征、严重低钾——需治疗病因与补钾）。","symptoms":["神经肌肉兴奋性增高：手足麻木、肌肉抽搐、腱反射亢进（碱中毒致离子钙下降）","呼吸浅慢（代偿性通气不足），严重者呼吸抑制","心律失常（常伴低钾：房性/室性早搏、QT延长）","乏力、淡漠、意识改变（重度碱中毒）","原发病表现：反复呕吐（幽门梗阻）、利尿剂使用、腹胀与胃肠减压"],"diagnosis":["动脉血气分析（pH、HCO₃⁻、PaCO₂）：HCO₃⁻升高伴pH升高，PaCO₂代偿性升高（预计PaCO₂=0.7×HCO₃⁻+21±2）","电解质（K⁺、Cl⁻、Na⁺）+尿氯（<20mmol/L提示对氯反应性；>20mmol/L提示对氯抵抗性）","尿钾+尿钠：评估肾性丢失","血容量与脱水评估：血压、心率、皮肤弹性、尿量（呕吐/利尿剂致容量不足）","肾功能+白蛋白：评估基础病与离子钙水平","心电图：低钾相关改变（U波、QT延长、心律失常）","病因学：呕吐/胃肠减压史、利尿剂使用、原发性醛固酮增多症（血压+血醛固酮/肾素比值）、库欣综合征"],"infusion":["⚠️ 以补生理盐水+补钾为核心，按对氯反应性选择！","方案1（对氯反应性碱中毒，首选0.9%氯化钠+氯化钾）：","用法：0.9%氯化钠 1000～2000ml 静滴（补充氯与容量，促进HCO₃⁻排泄）；10%氯化钾 15～20ml + 0.9%氯化钠 500ml 静滴（见尿补钾，速度≤1g/h，监测血钾与心电图）","方案2（合并严重低钾，需积极补钾）：","用法：10%氯化钾 20～30ml + 0.9%氯化钠 1000ml 静滴（持续缓慢，每小时不超过1g，监测血钾、尿量与心电图）","方案3（对氯抵抗性碱中毒/重度碱中毒pH>7.6）：","用法：乙酰唑胺 250～500mg 静推/口服 qd（促进HCO₃⁻排泄，注意低钾与低钠）；必要时 0.9%氯化钠 静滴 + 补钾；极重度者 稀盐酸静滴（罕见，ICU）","方案4（病因治疗）：","用法：持续胃肠减压者补充生理盐水与钾；停用/调整利尿剂（改用保钾利尿剂或乙酰唑胺）；原醛者用螺内酯 20～40mg bid（遵医嘱）+补钾；呕吐者止吐（甲氧氯普胺 10mg 静推）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","📌 纠正碱中毒需同时补氯与补钾（低钾使碱中毒难以纠正）；避免使用碳酸氢钠等碱性药物；伴低钙症状者需补钙。"],"oral_medication":["⚠️ 恢复期与慢性碱中毒用药：","药物1（补钾与补氯）：","用法：氯化钾缓释片 1g bid～tid（监测血钾与肾功能）；必要时口服盐水（补氯）","药物2（保钾利尿剂/醛固酮拮抗剂，原醛或利尿剂相关）：","用法：螺内酯 20～40mg qd～bid（监测血钾与血压）；或 阿米洛利 5mg qd〔调 ★ eGFR<30 禁用；高钾血症禁用〕","药物3（碳酸酐酶抑制剂，对氯抵抗性碱中毒）：","用法：乙酰唑胺 250mg qd～bid（口服，促进HCO₃⁻排泄，注意低钾与代谢性酸中毒）","药物4（病因治疗）：","用法：幽门梗阻（手术或内镜处理）；停用噻嗪类/袢利尿剂（改用其他降压药）；库欣综合征（内分泌科治疗）","📌 补钾不可骤停（需复查血钾至正常）；长期利尿剂使用者应定期监测血钾与血气。"],"treatment":["对氯反应性碱中毒：静脉补充0.9%氯化钠（补氯+扩容）+ 氯化钾（10～20mmol 静滴/h，浓度≤40mmol/L），通过促进HCO₃⁻排泄纠正","对氯抵抗性碱中毒：治疗病因（原醛用螺内酯 20～40mg 口服 qd～bid、库欣手术治疗）+ 补钾；必要时乙酰唑胺 250～500mg 口服/静推 qd","补钾为核心：碱中毒常伴严重低钾（尤其利尿剂与呕吐所致），需积极补钾（氯化钾 40～80mmol/d 分次口服或静滴）并监测心电图","停用/调整致病药物：停用噻嗪类/袢利尿剂、碳酸氢钠、过量甘草（甘草酸致假性醛固酮增多症）","持续胃肠减压/呕吐者：补充生理盐水与钾，止吐治疗（甲氧氯普胺 10mg 静推/肌注 q6～8h），必要时H2受体拮抗剂/PPI（奥美拉唑 40mg 静推 qd）减少胃酸丢失","重度碱中毒（pH>7.6）：乙酰唑胺 500mg 静推 或稀盐酸（ICU），并纠正低钾与低钙","监测：血气每2～4小时（急性期）、血钾（每2～6小时）、尿氯、心电图与尿量","并发症防治：低钾致心律失常、离子钙下降致抽搐、过度通气抑制（呼吸抑制）"],"management":["血气与电解质监测：每2～4小时复查血气（急性期）、血钾与尿氯，记录趋势","补钾护理：氯化钾静滴速度≤1g/h（外周静脉浓度≤0.3%并观察静脉炎），监测血钾与心电图（U波、QT延长）","容量与尿量：准确记录出入量与尿量（见尿补钾），观察脱水改善情况","神经肌肉观察：手足麻木、抽搐与腱反射（碱中毒致离子钙下降），出现抽搐时补钙并报告","呼吸观察：呼吸浅慢（代偿性）与呼吸抑制（重度碱中毒），监测血氧与意识","宣教：避免长期滥用利尿剂与含碳酸氢钠的胃药、呕吐与胃肠减压患者及时补液补钾、定期复查血气与电解质"],"notes":["代谢性碱中毒的分型关键是尿氯：尿氯<20mmol/L为对氯反应性（补生理盐水有效），>20mmol/L为对氯抵抗性（需治疗病因）","碱中毒常伴低钾，补钾是纠正的关键（低钾不纠正则碱中毒难以纠正）","碱中毒使离子钙下降，可出现手足搐搦（补钾同时注意补钙）","持续胃肠减压与反复呕吐是住院患者碱中毒的常见原因（补充生理盐水+钾+H2受体拮抗剂/PPI）","重度碱中毒（pH>7.6）可致心律失常、呼吸抑制与意识障碍，需乙酰唑胺或稀盐酸并转ICU"],"emergency":["pH>7.6伴意识障碍、抽搐或心律失常 → 乙酰唑胺/稀盐酸+积极补钾补钙，心电监护，转ICU","严重低钾（<2.5mmol/L）伴心律失常（室早、尖端扭转）→ 立即静脉补钾（速度≤1g/h，心电监护）+补镁","手足搐搦伴喉痉挛（离子钙下降）→ 静脉缓慢推注葡萄糖酸钙+吸氧","呼吸抑制（重度碱中毒致通气不足）→ 吸氧、必要时机械通气并纠正碱中毒"],"pinyin":"dxjxzdclfa","icd10":"E87.3","physical_exam":["生命体征：呼吸频率与深度（浅慢）、血压、心率、体温","神经肌肉兴奋性：手足麻木、手足搐搦、腱反射亢进、Chvostek征与Trousseau征（离子钙下降）","容量状态：血压、心率、皮肤弹性、黏膜干燥度（呕吐/利尿剂致脱水）","心血管：心律不齐、心音（低钾致心律失常）","腹部：腹胀、胃型与振水音（幽门梗阻）、手术瘢痕（持续胃肠减压）","病因相关：血压升高（原醛、库欣）、满月脸与水牛背（库欣）、水肿","意识与精神：淡漠、意识改变（重度碱中毒）"],"lab_tests":["动脉血气分析（pH、HCO₃⁻、PaCO₂、BE）：每2～4小时（急性期），评估代偿","电解质（K⁺、Cl⁻、Na⁺、Ca²⁺、Mg²⁺）+尿氯（关键分型指标）+尿钾","心电图：低钾改变（U波、QT延长、心律失常）与离子钙下降影响","肾功能+白蛋白：评估基础病与离子钙校正","血醛固酮+肾素活性+皮质醇（必要时）：原醛与库欣综合征筛查（对氯抵抗性碱中毒）","尿pH+尿钾+尿氯：评估肾性丢失（利尿剂、Bartter综合征）","胃液量与性状（胃肠减压者）：评估胃酸丢失量"],"nursing":["补钾护理：严格按医嘱速度静滴氯化钾（≤1g/h），外周静脉浓度不超过0.3%并观察静脉炎，监测血钾与心电图","出入量与尿量监测：准确记录24小时出入量与尿量，见尿补钾；观察脱水改善情况","神经肌肉观察：手足麻木、抽搐与腱反射（离子钙下降），异常立即报告并遵医嘱补钙","呼吸与意识观察：呼吸浅慢、呼吸抑制与意识改变（重度碱中毒）","病因护理：持续胃肠减压者记录引流量与性状并补充生理盐水与钾；呕吐者口腔护理与止吐处理","宣教：避免长期滥用利尿剂与含碳酸氢钠胃药、避免过量甘草制品、定期复查血气与电解质、出现手足麻木及时就诊"],"diet":["对氯反应性碱中毒：适量补盐（口服盐水或含盐食物，按医嘱）","补钾饮食：香蕉、橙子、土豆、菠菜、蘑菇、豆类（肾功能不全者按医嘱限制）","呕吐/胃肠减压者：禁食或少量流质（可视病情），注意补充水分与电解质","避免碱性食物与药物过量（大量牛奶、碳酸氢钠）、避免长期甘草制品（假性醛固酮增多症）","恢复期：均衡饮食、少量多餐；病因治疗（幽门梗阻者术后逐步恢复饮食）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1397},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5debc5e11285590baab65aa63d2ad86a145cee3ccaca8b2c36c1f8b0fd757679","pinyin":"daixiexingjianzhongduchuliyuanze","initials":"dxxjzdclyz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","神经肌肉兴奋性增高：手足麻木、肌肉抽搐、腱反射亢进（碱中毒致离子钙下降）\\n呼吸浅慢（代偿性通气不足），严重者呼吸抑制\\n心律失常（常伴低钾：房性/室性早搏、QT延长）\\n乏力、淡漠、意识改变（重度碱中毒）\\n原发病表现：反复呕吐（幽门梗阻）、利尿剂使用、腹胀与胃肠减压",60],["摘要","代谢性碱中毒是HCO₃⁻原发性升高（>26mmol/L）伴pH上升的酸碱失衡，常伴低氯与低钾。按对氯反应性分为：对氯反应性（呕吐、胃肠减压、利尿剂致低氯低钾性碱中毒——补生理盐水可纠正）与对氯抵抗性（原醛、库欣、Bartter综合征、严重低钾——需治疗病因与补钾）。",30],["疾病编码","E87.3",30],["原首字母","dxjxzdclfa",60]]},{"id":"orders-b801378f4a28e885c2e9","key":"v1-c9ccc21dfe2a3058|orders-b801378f4a28e885c2e9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"妊娠期患者夜班处理要点","category":"夜班特殊人群","raw":{"name":"妊娠期患者夜班处理要点","category":"夜班特殊人群","summary":"妊娠期患者夜班处理的特殊性在于：生理改变（血容量增加、心率增快、血压下降、胃排空延迟、高凝状态）使症状与检验值解读不同；用药需考虑胎儿安全（FDA分级）；急腹症、出血、高血压与感染需同时评估母胎安全，必要时产科急会诊。","symptoms":["需警惕的症状：阴道流血、腹痛（尤其持续或规律宫缩）、胎动减少、头痛视力模糊（子痫前期）、发热、呕吐不能进食","生理性改变易混淆：心率增快（10～20次/分）、血压偏低、下肢水肿、气短（膈肌上抬）、便秘与胃灼热","实验室生理性改变：白细胞轻度升高（可达15×10⁹/L）、血红蛋白偏低（血液稀释）、D-二聚体升高、ALP升高","急腹症表现偏上腹（子宫增大使阑尾上移、脏器位置改变）","夜班常见急症：先兆流产/早产、异位妊娠破裂、胎盘早剥、子痫前期/子痫、急性阑尾炎、尿路感染、肾绞痛"],"diagnosis":["生命体征与胎心：血压（子痫前期筛查）、心率、胎心率（110～160次/分）与胎动计数","产科评估：宫高、腹围、宫缩（有无规律）、阴道检查（慎用，疑前置胎盘禁查）、胎心监护（NST）","超声：胎儿情况、胎盘位置、羊水量；疑异位妊娠/急腹症时腹部超声（盆腔）","实验室：血常规、尿常规（尿蛋白定量，子痫前期关键）、肝肾功能、凝血功能、电解质；β-hCG（早孕）","感染评估：血常规+CRP+PCT、尿培养、阴道分泌物培养","心电图与心脏超声（心功能不全或严重贫血者）","多学科评估：产科、内科（合并症）、外科（急腹症）与麻醉科协作"],"infusion":["⚠️ 妊娠期用药须考虑胎儿安全（尽量选择FDA B类/C类，避免D/X类）！","","方案1（补液与容量管理）：","  用法：平衡盐溶液/0.9%氯化钠 静滴（妊娠期血容量增加、心负荷大，需控制输液速度防肺水肿）；子痫前期者限制液体并记录出入量","","方案2（子痫前期/子痫，降压与解痉）：","  用法：拉贝洛尔 20～40mg 静推（每10分钟可重复，总量≤300mg）或 尼卡地平 泵入；硫酸镁 4～5g（NS 100ml 或 5%GS 100ml）静滴（20分钟）后 1～2g/h 维持（防子痫抽搐，监测腱反射、呼吸、尿量与血镁）","","方案3（先兆早产，抑制宫缩）：","  用法：利托君 50～100μg/min 泵入（监测心率）或 阿托西班；同时促胎肺成熟：地塞米松 6mg 肌注 q12h×4次（24～34周）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案4（感染，选择孕期安全抗生素）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 头孢曲松 2g 静滴 qd（孕期相对安全）；青霉素过敏者 克林霉素 0.6g q8h〔调 CrCl<30 减量；青霉素过敏禁用〕","","📌 孕期禁用/慎用：ACEI/ARB、喹诺酮类、四环素类、氨基糖苷类、NSAIDs（妊娠晚期）、甲硝唑大剂量早期；所有用药须权衡母胎获益与风险并记录。"],"oral_medication":["⚠️ 孕期口服用药原则：单药、最小有效剂量、短疗程，避免D/X类药物！","药物1（降压，子痫前期/慢性高血压）：","用法：拉贝洛尔 100mg bid 或 硝苯地平缓释片 30mg qd（孕期相对安全）；禁用ACEI/ARB","药物2（抗感染，孕期相对安全）：","用法：头孢氨苄 0.5g qid 或 阿莫西林克拉维酸 0.625g tid；尿路感染按尿培养调整〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物3（补铁与叶酸）：","用法：琥珀酸亚铁 0.1g bid + 叶酸 0.4mg qd（孕早期起）；维生素B12（贫血者）〔调 ★ 铁负荷过多禁用；★ 与四环素/喹诺酮/左甲状腺素间隔2小时〕","药物4（对症，谨慎使用）：","用法：对乙酰氨基酚 0.5g 必要时（孕期镇痛退热首选）；避免NSAIDs（妊娠晚期致动脉导管早闭）；便秘用乳果糖 15ml bid〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 任何用药前核对孕期安全性；妊娠晚期避免NSAIDs与磺胺类；哺乳期用药亦需评估。"],"treatment":["急腹症处理：妊娠期阑尾炎、胆囊炎等一经确诊应积极处理（延误致流产/早产与母体风险），手术宜早（腹腔镜可行，注意气腹压力与体位）；术前产科会诊与胎心监护","产科急症：先兆流产（卧床、黄体酮 20～40mg 肌注 qd）、异位妊娠（手术或甲氨蝶呤 50mg/m² 肌注 单次）、胎盘早剥（急诊剖宫产）、前置胎盘出血（保守或剖宫产）、子痫（硫酸镁 4～6g 静推 继以 1～2g/h 静滴+降压+终止妊娠时机评估）","高血压疾病：子痫前期（降压，如拉贝洛尔 100～200mg 口服 bid～tid、硝苯地平 10mg 口服 q8h；硫酸镁防抽搐、监测尿蛋白与肝肾功能、评估终止妊娠时机）、HELLP综合征（血小板、肝酶、溶血）","感染：尿路感染（孕期安全抗生素，如头孢呋辛 0.25～0.5g 口服 bid、阿莫西林 0.5g 口服 tid）、绒毛膜羊膜炎（抗感染+评估分娩时机）、败血症（广谱抗感染+ICU）","用药原则：尽量选择妊娠安全药物、避免多药联用、记录用药理由；必要时咨询产科与临床药学","母胎监护：胎心监护、超声评估、胎动计数；危重患者转有产科ICU条件的医院","多学科协作：产科、麻醉科、重症医学科与相关专科共同管理（尤其是合并症与急症）","宣教：孕期规律产检、识别危险症状（出血、腹痛、头痛、胎动减少）立即就诊、避免自行用药"],"management":["胎心与胎动监测：入院后立即听胎心（每4～6小时或按病情），指导患者计数胎动（<10次/2小时需报告）","血压与尿蛋白监测：子痫前期者每4小时测血压、每日查尿蛋白（或尿蛋白/肌酐比）","用药安全核对：每次给药前核对孕期安全性（参考FDA分级/说明书），记录用药理由与产科意见","体位与护理：妊娠晚期取左侧卧位（改善子宫胎盘灌注、减少下腔静脉受压）；避免长时间平卧","监测与记录：胎心监护、宫缩情况、阴道流血与流液、出入量与体重","心理护理：妊娠期患者与家属焦虑明显，及时解释病情与治疗方案，减轻恐惧","急会诊与转诊：合并内外科急症时及时请产科与相关专科会诊，必要时转上级医院"],"notes":["妊娠期生理改变使症状与检验值解读不同（白细胞可轻度升高、D-二聚体升高、血红蛋白偏低）","妊娠期禁用ACEI/ARB、喹诺酮类、四环素类；妊娠晚期避免NSAIDs与磺胺类","妊娠期急腹症（阑尾炎、胆囊炎）应积极处理，延误易致流产/早产与母体并发症","子痫前期与子痫需硫酸镁防抽搐（监测腱反射、呼吸与尿量），并评估终止妊娠时机","任何用药均需权衡母胎获益与风险并记录；必要时咨询产科与临床药师"],"emergency":["阴道大量流血伴腹痛（胎盘早剥/前置胎盘）→ 立即建立静脉通路、胎心监护、产科急会诊，准备急诊剖宫产","抽搐（子痫）→ 立即硫酸镁 4～5g 静滴（20分钟）+降压+吸氧，防坠床与舌咬伤，产科急会诊","剧烈腹痛伴血压下降（异位妊娠破裂/子宫破裂）→ 立即抗休克+急诊手术","胎动消失或胎心<110次/分或>160次/分持续 → 立即产科评估与胎心监护","高热伴宫缩与阴道流液（绒毛膜羊膜炎）→ 抗感染+产科评估分娩时机"],"pinyin":"rsqhzybcl","icd10":"Z34.9","physical_exam":["生命体征：血压（子痫前期筛查，≥140/90mmHg需警惕）、心率、呼吸、体温、血氧","产科检查：宫高、腹围（与孕周对照）、宫缩（频率与强度）、胎心（多普勒，110～160次/分）、胎位","阴道检查（慎用）：有无流血、流液与宫颈情况（疑前置胎盘禁行阴道检查）","水肿与体重：下肢水肿、体重增长速度（子痫前期）、有无腹水","神经系统：头痛、视力模糊、腱反射（硫酸镁治疗时评估）、抽搐","腹部（急腹症）：压痛部位（子宫增大使阑尾上移）、反跳痛与肌紧张","其他：贫血貌、皮肤黏膜出血点（HELLP）、心肺听诊（容量负荷）"],"lab_tests":["血常规（注意孕期白细胞可轻度升高）+CRP+PCT：感染评估","尿常规+尿蛋白定量（24小时或尿蛋白/肌酐比）：子痫前期诊断与监测（每日或每2日）","肝肾功能+胆红素+LDH+凝血功能+血小板：HELLP综合征与子痫前期评估","电解质+血气分析：呕吐、脱水与酸碱失衡评估","β-hCG+孕酮（早孕）：异位妊娠与先兆流产评估","超声（胎儿+胎盘+羊水）+胎心监护（NST）：胎儿状况与胎盘位置评估","血型+交叉配血（出血者）：备血准备；尿培养（尿路感染）"],"nursing":["胎心与胎动监测：入院立即听胎心，按医嘱行胎心监护；指导并记录胎动（<10次/2小时报告）","血压与子痫前期护理：每4小时测血压，观察头痛、视力模糊与上腹痛（子痫前期预警）；硫酸镁治疗时监测腱反射、呼吸与尿量","用药护理：给药前核对孕期安全性（参考FDA分级），记录用药与产科意见；观察药物不良反应","体位护理：妊娠晚期取左侧卧位（改善胎盘灌注），避免长时间平卧（下腔静脉受压致低血压）","急症配合：出血、抽搐、剧烈腹痛时立即建立静脉通路、吸氧、胎心监护并通知产科急会诊","心理与宣教：安抚患者与家属情绪，解释病情与治疗，强调规律产检与危险症状（出血、腹痛、胎动减少）及时就诊"],"diet":["均衡营养：高蛋白、适量碳水、充足维生素与矿物质（孕期需求增加）","补铁与叶酸：富含铁食物（瘦肉、动物肝脏、深绿色蔬菜）+ 叶酸（孕早期起0.4mg/日）","子痫前期患者：限制钠盐（每日<5g，严重者<3g）、控制液体入量（按医嘱）","妊娠期糖尿病：按糖尿病饮食管理（控制碳水总量与升糖指数）、少量多餐","避免生冷、未煮熟食物与酒精（防感染与胎儿损害）；避免大量咖啡因；便秘者增加纤维与水分"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1398},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2926bca744cd6a20fed51e867914147aad8698d410d49ca282a64b0be515732c","pinyin":"renshenqihuanzheyebanchuliyaodian","initials":"rsqhzybclyd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","需警惕的症状：阴道流血、腹痛（尤其持续或规律宫缩）、胎动减少、头痛视力模糊（子痫前期）、发热、呕吐不能进食\\n生理性改变易混淆：心率增快（10～20次/分）、血压偏低、下肢水肿、气短（膈肌上抬）、便秘与胃灼热\\n实验室生理性改变：白细胞轻度升高（可达15×10⁹/L）、血红蛋白偏低（血液稀释）、D-二聚体升高、ALP升高\\n急腹症表现偏上腹（子宫增大使阑尾上移、脏器位置改变）\\n夜班常见急症：先兆流产/早产、异位妊娠破裂、胎盘早剥、子痫前期/子痫、急性阑尾炎、尿路感染、肾绞痛",60],["摘要","妊娠期患者夜班处理的特殊性在于：生理改变（血容量增加、心率增快、血压下降、胃排空延迟、高凝状态）使症状与检验值解读不同；用药需考虑胎儿安全（FDA分级）；急腹症、出血、高血压与感染需同时评估母胎安全，必要时产科急会诊。",30],["疾病编码","Z34.9",30],["原首字母","rsqhzybcl",60]]},{"id":"orders-0beb90cdc501c1604c05","key":"v1-c9ccc21dfe2a3058|orders-0beb90cdc501c1604c05","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"儿童患者夜班处理要点","category":"夜班特殊人群","raw":{"name":"儿童患者夜班处理要点","category":"夜班特殊人群","summary":"儿童夜班处理的特点：病情变化快、代偿能力强但失代偿迅速；用药需按体重/体表面积计算并注意儿童禁忌；补液需精确（易脱水与过量）；高热、惊厥、呼吸困难、腹痛、呕吐腹泻为常见就诊原因；须重视家长观察与沟通、警惕虐待与意外伤害。","symptoms":["需警惕的危险征象：精神萎靡或烦躁不安、呼吸急促/呻吟/三凹征、皮肤发花/发绀、毛细血管充盈>3秒、抽搐、前囟膨隆或凹陷、尿量减少（<1ml/kg/h）","常见夜班症状：发热（热性惊厥）、咳嗽与喘息（毛细支气管炎/哮喘）、呕吐腹泻（脱水）、腹痛（肠套叠、阑尾炎、肠系膜淋巴结炎）、头痛与呕吐（颅内感染）","婴幼儿表现不典型：拒奶、哭闹不安、嗜睡、体温不升（新生儿感染可无发热）","脱水评估：前囟与眼窝凹陷、皮肤弹性差、黏膜干燥、尿量减少、体重下降","家长信息关键：发病时间、进食与尿量、用药史、过敏史、预防接种史、外伤史"],"diagnosis":["生命体征与生长指标：体温、心率、呼吸、血压（儿童血压需按年龄判断）、血氧、体重、前囟","儿科评估三角（PAT）：外观、呼吸做功、循环灌注（快速判断危重）","脱水程度评估：轻/中/重度（体重下降百分比、尿量、皮肤弹性、眼窝与前囟、精神状态）","实验室：血常规+CRP+PCT（感染）、电解质+血糖+血气分析（脱水与代谢）、大便常规+培养（腹泻）","影像：腹部超声（肠套叠、阑尾炎、肠系膜淋巴结）、胸片（肺炎、异物）、头颅CT（外伤、颅压增高，慎用放射）","腰椎穿刺（疑颅内感染，注意颅压增高者先评估）：脑脊液常规、生化、涂片与培养","用药剂量核对：按体重（mg/kg）或体表面积计算并核对儿童最大剂量与禁忌"],"infusion":["⚠️ 儿童补液与用药必须按体重精确计算并核对！","","方案1（脱水补液，按脱水程度）：","  用法：轻度（体重下降<5%）：口服补液盐 50ml/kg（4小时内少量多次）；中度（5%～10%）：累积损失量 50～100ml/kg 用 0.45%～0.9%氯化钠+5%葡萄糖 静滴（先快后慢，8～12小时补足）；重度（>10%）或休克：0.9%氯化钠 20ml/kg 快速静推（10～20分钟，可重复至循环改善）","","方案2（维持量，Holliday-Segar法）：","  用法：第1个10kg：100ml/kg/日；第2个10kg：50ml/kg/日；超过20kg：20ml/kg/日（按体重计算，用1/4～1/5张液体，含钾20mmol/L，见尿补钾）","","方案3（抗感染，按体重计算）：","  用法：头孢曲松 50～75mg/kg（NS 100ml 或 5%GS 100ml）静滴 qd（最大2g）或 头孢呋辛 30～50mg/kg 静滴 q8h；肺炎/脓毒症按病情升级〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案4（热性惊厥/惊厥持续状态）：","  用法：地西泮 0.3～0.5mg/kg 缓慢静推（最大10mg，监测呼吸）；或 咪达唑仑 0.2mg/kg 肌注（无静脉通路时）；随后苯巴比妥 10～20mg/kg（NS 100ml 或 5%GS 100ml）静滴（负荷量）〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","","📌 儿童补液速度与量必须精确（易脱水与心衰/脑水肿）；补钾需见尿且浓度≤0.3%；用药剂量按体重计算并不要超过成人最大量。"],"oral_medication":["⚠️ 儿童用药按体重计算，避免成人剂型与禁忌药！","药物1（退热）：","用法：对乙酰氨基酚 10～15mg/kg q4～6h（最大每日4次，<75mg/kg/日）或 布洛芬 5～10mg/kg q6～8h（≥6月龄，避免脱水/肾病者）；禁用阿司匹林（Reye综合征）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（补液与电解质）：","用法：口服补液盐Ⅲ 按说明冲服（50～100ml/kg/4小时，少量多次）；补锌（腹泻患儿，<6月10mg/日，≥6月20mg/日×10～14天）","药物3（抗感染，按体重）：","用法：阿莫西林克拉维酸 25～45mg/kg/日 分2次（中耳炎/鼻窦炎）；阿奇霉素 10mg/kg qd×3天（支原体/百日咳）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物4（对症）：","用法：蒙脱石散（<1岁 1g tid，1～2岁 1～2g tid）；西替利嗪（≥6月龄，按体重）；益生菌（双歧杆菌 1粒 bid）〔调 ★ 肾功能不全必须减量；老年减量〕","📌 儿童禁用：阿司匹林（病毒感染）、喹诺酮类（<18岁）、四环素类（<8岁）、可待因（<12岁）、含麻黄碱复方感冒药（<2岁）；用药务必按体重核对剂量。"],"treatment":["危重识别与复苏：儿科评估三角异常者立即评估气道-呼吸-循环，建立静脉/骨内通路，按体重补液（20ml/kg 生理盐水）与吸氧","发热处理：物理降温+对乙酰氨基酚/布洛芬，寻找感染灶；<3月龄婴儿发热（≥38℃）需警惕严重细菌感染（血培养+经验性抗生素+住院观察）","热性惊厥：保持气道通畅、侧卧、地西泮止惊、退热，持续>5分钟按惊厥持续状态处理；首次发作需排除颅内感染与代谢病","脱水与腹泻：口服补液盐优先（轻中度），重度或不能口服者静脉补液；不常规使用止泻药与抗生素（按病因）","呼吸困难：吸氧、雾化（β2激动剂±糖皮质激素）、必要时无创/有创通气；警惕异物吸入（突发呛咳与单侧呼吸音减弱）","腹痛鉴别：肠套叠（阵发性哭闹+果酱样便+腹部包块，空气灌肠复位）、阑尾炎（转移性右下腹痛）、肠系膜淋巴结炎（多伴上感）","用药安全：按体重计算剂量（核对最大量）、注意儿童禁忌、观察药物不良反应","家长沟通与宣教：解释病情与治疗方案、家庭护理（补液、退热、观察危险征象）、随访与复诊指征"],"management":["生命体征与体重监测：按年龄评估心率、呼吸、血压与血氧；体重是补液与用药计算的基础（必须测量）","出入量与尿量：婴幼儿记录尿布重量/尿量（目标≥1ml/kg/h），评估脱水改善","用药核对：给药前双人核对体重、剂量（mg/kg）、浓度与最大剂量，记录用药时间与反应","饮食与喂养护理：能进食者少量多次喂养；呕吐者短暂禁食后从口服补液盐开始；母乳喂养可继续","静脉通路与补液：选择合适针径与部位（婴幼儿避免头皮静脉长时间使用），输液泵精确控制速度","家长参与与宣教：教会家长识别危险征象（精神萎靡、呼吸急促、尿少、抽搐）与家庭护理方法（退热、补液、喂养）","安全与人文关怀：避免强制约束（减少恐惧）、允许家长陪伴、注意保暖与舒适；警惕虐待与意外伤害（与病史不符的损伤）"],"notes":["儿童病情变化快：代偿期表现可正常，一旦失代偿迅速恶化（需动态评估儿科评估三角与生命体征）","补液与用药必须按体重精确计算（容易过量或不足）；补钾需见尿且浓度≤0.3%","<3月龄婴儿发热（≥38℃）需警惕严重细菌感染（血培养+经验性抗生素+住院观察）","儿童禁用阿司匹林（Reye综合征）、喹诺酮类（<18岁）、四环素类（<8岁）、可待因（<12岁）","家长提供的信息（尿量、进食、精神状态变化）对判断病情很重要，须认真询问并记录"],"emergency":["精神萎靡/意识改变、呼吸急促伴三凹征、皮肤发花（休克/呼吸衰竭）→ 立即复苏（气道-呼吸-循环）、补液与吸氧","惊厥持续>5分钟或反复发作（惊厥持续状态）→ 地西泮 0.3～0.5mg/kg 静推（监测呼吸）→ 苯巴比妥负荷量","重度脱水或休克（体重下降>10%、尿少、毛细血管充盈>3秒）→ 0.9%氯化钠 20ml/kg 快速补液（可重复），监测心率与尿量","突发呛咳、呼吸困难伴单侧呼吸音减弱（气道异物）→ 立即海姆立克法/婴幼儿拍背压胸，必要时喉镜/支气管镜取出","阵发性哭闹伴果酱样便与腹部包块（肠套叠）→ 急诊超声+空气灌肠复位，必要时手术"],"pinyin":"etHzybcl","icd10":"Z00.1","physical_exam":["生命体征：体温、心率、呼吸、血压（按年龄判断正常范围）、血氧、体重","儿科评估三角（PAT）：外观（神志/肌张力/互动）、呼吸做功（三凹征/呻吟/鼻翼扇动）、循环灌注（皮肤颜色/毛细血管充盈）","脱水评估：前囟与眼窝凹陷、皮肤弹性、黏膜干燥、尿量、体重下降百分比、精神状态","系统查体：咽部与扁桃体、颈部淋巴结、心肺听诊、腹部（压痛、包块、肠鸣音）、皮疹（发热出疹性疾病）","神经系统：意识、前囟张力、颈抵抗、病理反射、肌张力（婴幼儿）","其他：耳部（中耳炎）、鼻腔与呼吸（异物）、四肢与关节（外伤）、肛周（腹泻、肛裂）","生长与发育：身高体重与同龄比较（营养与慢性病评估）"],"lab_tests":["血常规+CRP+PCT：感染评估（注意儿童白细胞正常范围与年龄相关）","电解质+血糖+血气分析+肾功能：脱水、代谢紊乱与酸中毒评估（每4～6小时，重度脱水）","大便常规+隐血+培养+轮状病毒/诺如病毒抗原：腹泻病因","尿常规+尿培养：尿路感染（婴幼儿不明原因发热必查）","血培养（<3月龄发热或疑脓毒症）：抗生素前留取双份","腹部超声/胸片/头颅CT（按需）：肠套叠、肺炎、颅脑外伤与颅内感染评估","脑脊液检查（疑颅内感染，先评估颅压）：常规、生化、涂片与培养"],"nursing":["生命体征与体重监测：按年龄评估并记录心率、呼吸、血压、血氧与体温；入院必测体重（补液与用药依据）","出入量与尿量：记录每次进食、补液量与尿量（尿布称重），评估脱水改善（目标≥1ml/kg/h）","用药核对：双人核对体重与剂量（mg/kg）、最大剂量与儿童禁忌，观察药物反应","静脉输液护理：使用输液泵精确控制速度，选择合适针径，观察穿刺部位与输液反应；补钾时监测尿量与血钾","发热与惊厥护理：物理降温与退热药按时给予；惊厥时侧卧、保护气道与安全，记录发作时间与表现","家长参与与宣教：鼓励家长陪伴、教会识别危险征象与家庭护理（口服补液、退热、喂养），说明复诊指征"],"diet":["能进食者：少量多次喂养，选择易消化食物（米汤、面条、蒸蛋）；母乳喂养可继续","腹泻患儿：口服补液盐 50～100ml/kg（4小时内少量多次）；避免高糖饮料（加重腹泻）；继续喂养（不主张禁食）","呕吐患儿：短暂禁食1～2小时后从少量口服补液盐开始，逐渐恢复喂养","发热患儿：充足水分（少量多次），清淡饮食，避免油腻与刺激性食物","恢复期：高蛋白、高维生素饮食促进恢复；补充锌（腹泻患儿10～20mg/日×10～14天）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1399},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3ffa2c20b8d8c6b8dee2bca4251e42e4fd352d557b3885c0ad0cd914aa169a28","pinyin":"ertonghuanzheyebanchuliyaodian","initials":"ethzybclyd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","需警惕的危险征象：精神萎靡或烦躁不安、呼吸急促/呻吟/三凹征、皮肤发花/发绀、毛细血管充盈>3秒、抽搐、前囟膨隆或凹陷、尿量减少（<1ml/kg/h）\\n常见夜班症状：发热（热性惊厥）、咳嗽与喘息（毛细支气管炎/哮喘）、呕吐腹泻（脱水）、腹痛（肠套叠、阑尾炎、肠系膜淋巴结炎）、头痛与呕吐（颅内感染）\\n婴幼儿表现不典型：拒奶、哭闹不安、嗜睡、体温不升（新生儿感染可无发热）\\n脱水评估：前囟与眼窝凹陷、皮肤弹性差、黏膜干燥、尿量减少、体重下降\\n家长信息关键：发病时间、进食与尿量、用药史、过敏史、预防接种史、外伤史",60],["摘要","儿童夜班处理的特点：病情变化快、代偿能力强但失代偿迅速；用药需按体重/体表面积计算并注意儿童禁忌；补液需精确（易脱水与过量）；高热、惊厥、呼吸困难、腹痛、呕吐腹泻为常见就诊原因；须重视家长观察与沟通、警惕虐待与意外伤害。",30],["疾病编码","Z00.1",30],["原首字母","etHzybcl",60]]},{"id":"orders-6922104051fc8db46a92","key":"v1-c9ccc21dfe2a3058|orders-6922104051fc8db46a92","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"血液透析患者夜班处理要点","category":"夜班特殊人群","raw":{"name":"血液透析患者夜班处理要点","category":"夜班特殊人群","summary":"透析患者夜班处理需注意：肾功能衰竭（药物需按肾功能调整、禁用肾毒性药物）、容量与电解质波动（透析间期体重增长、高钾、酸中毒）、血管通路（内瘘保护与出血）、贫血与骨病，以及透析相关急症（失衡综合征、低血压、心律失常、高钾血症）。","symptoms":["高钾血症表现：乏力、肌无力、心律失常（可致心脏骤停，透析患者最常见急症）","容量负荷：呼吸困难、端坐呼吸、下肢与颜面水肿、血压升高（透析间期体重增长过多）","透析相关：透析中低血压（头晕、出汗、恶心）、失衡综合征（头痛、恶心、抽搐）、肌肉痉挛","尿毒症症状：恶心呕吐、食欲减退、皮肤瘙痒、贫血（乏力）、意识改变（尿毒症脑病）","血管通路问题：内瘘震颤减弱或消失（血栓）、穿刺部位出血、红肿热痛（感染）"],"diagnosis":["电解质（血钾、钠、钙、磷）+肾功能+BUN+血气分析：透析患者核心监测（血钾>6.0mmol/L危急）","心电图：高钾血症（T波高尖、QRS增宽、心律失常）与低钙/低钾改变（透析患者必查）","干体重评估：透析前后体重、血压、水肿与心肺听诊（容量状态）","血常规+铁代谢+白蛋白：贫血与营养状态","血管通路评估：震颤与杂音、超声（疑血栓或狭窄）、穿刺部位检查","透析参数：超滤量、血流量、透析液成分（电解质与温度）、透析充分性（Kt/V）","药物核对：按肾功能（肌酐清除率）调整剂量，评估药物与透析清除关系"],"infusion":["⚠️ 透析患者用药需按肾功能调整，禁用肾毒性药物！","","方案1（高钾血症紧急处理，血钾>6.0mmol/L伴心电图改变）：","  用法：10%葡萄糖酸钙 10ml 缓慢静推（心脏保护，>5分钟）；胰岛素 10U + 50%葡萄糖 50ml 静滴（10～20分钟）；5%碳酸氢钠 100ml 静滴（酸中毒者）；呋塞米 20～40mg 静推（有残余肾功能者）；紧急血液透析（最有效）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","","方案2（透析中低血压）：","  用法：立即停止超滤、减慢血流量；0.9%氯化钠 100～200ml 快速静滴；头低位；必要时去氧肾上腺素 0.1mg 静推或 白蛋白 10g 静滴","","方案3（失衡综合征，预防与处理）：","  用法：减慢血流量与超滤速度、提高透析液钠浓度与降低温度（35～36℃）；甘露醇 125ml 静滴（脑水肿者）；抽搐者地西泮 10mg 缓慢静推〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","方案4（抗感染，按肾功能调整剂量）：","  用法：头孢曲松 1～2g（NS 100ml 或 5%GS 100ml）静滴 qd（经肝肾双途径，透析患者相对安全）或 头孢唑林 1g 静滴（透析后给药）；避免氨基糖苷类、万古霉素需监测血药浓度〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","📌 透析患者用药须按肾功能调整剂量并注意透析清除（部分药物需透析后补充剂量）；禁用NSAIDs、氨基糖苷类、造影剂（必要时充分水化）。"],"oral_medication":["⚠️ 长期口服用药（按肾功能调整）：","药物1（降磷与钙剂，CKD-MBD）：","用法：碳酸钙 0.6g tid 随餐 或 司维拉姆 0.8g tid 随餐；骨化三醇 0.25μg qd（按血钙磷PTH调整）","药物2（降压）：","用法：氨氯地平 5mg qd 或 缬沙坦 80mg qd（透析患者通常不需调整）；避免透析日低血压（调整给药时间）〔调 肝功能不全减量；踝部水肿（剂量相关）〕","药物3（贫血治疗）：","用法：重组人促红素 10000IU 皮下注射 每周1～2次（透析后）；蔗糖铁 100mg 静滴（透析中，按铁代谢指标）；叶酸 5mg qd","药物4（降钾与通便）：","用法：聚苯乙烯磺酸钙散 15g tid（口服或灌肠，短期降钾）；乳果糖 15ml bid（便秘，注意避免含镁、含磷泻药）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 避免含镁/铝抗酸剂（镁铝蓄积）、避免NSAIDs（残余肾功能损害）、中成药需核对钾含量；所有用药须核对肾功能剂量。"],"treatment":["高钾血症：紧急处理（补钙+胰岛素葡萄糖+碳酸氢钠）+紧急透析（最有效措施），并排查原因（饮食、药物、酸中毒、出血）","容量管理：评估干体重、限制水钠摄入、调整超滤量；肺水肿者紧急超滤或单纯超滤","透析中并发症：低血压（停超滤+补液+调温）、失衡综合征（减慢速度+高钠透析+甘露醇）、肌肉痉挛（补液+高钠透析+奎宁）、心律失常（纠正电解质+吸氧）","药物剂量调整：按肌酐清除率调整所有经肾排泄药物；注意透析清除（必要时透析后补量）","血管通路保护：内瘘侧肢体禁止测血压、抽血、输液与受压；血栓（震颤消失）急诊评估溶栓或取栓","贫血与骨病管理：促红素+铁剂（目标Hb 100～120g/L）；磷结合剂+活性维生素D（控制钙磷PTH）","感染防治：透析导管相关感染（发热者血培养+抗生素，必要时拔管）、肺部感染（透析患者免疫力低）","多学科协作：肾内科、透析中心、ICU与相关专科协作；夜班需与透析中心联系安排急诊透析"],"management":["电解质与心电图监测：血钾>6.0mmol/L或心电图异常立即报告并准备急诊透析；透析前后复查电解质","体重与容量监测：记录透析前后体重、血压与超滤量，观察水肿与呼吸困难（容量负荷）","血管通路护理：每次接触评估内瘘震颤与杂音（消失立即报告）、穿刺部位有无出血与感染；内瘘侧肢体禁止操作","用药核对与调整：核对肾功能剂量、透析清除与给药时机（如透析后给药）","透析中监测：每30～60分钟测血压、心率与症状（低血压、抽搐、头痛）；观察体外循环管路与穿刺部位","饮食与宣教：限制水钠钾磷摄入、遵医嘱服磷结合剂与促红素、内瘘保护教育、识别高钾症状（乏力、心悸）及时就诊","心理与依从性：透析患者长期治疗负担重，提供心理支持并强调依从性（透析、用药、饮食）对预后的影响"],"notes":["透析患者最常见且最危险的急症是高钾血症（可致心脏骤停），血钾>6.0mmol/L伴心电图改变需紧急透析","透析患者用药必须按肾功能调整剂量，并注意透析清除（部分药物需透析后补充）","禁用NSAIDs（残余肾功能损害）与氨基糖苷类；含镁/铝抗酸剂避免使用（蓄积毒性）","内瘘是透析患者的生命线：内瘘侧肢体禁止测血压、抽血、输液与受压，震颤消失需急诊处理","透析患者血压与容量管理复杂（透析间期体重增长<干体重3%～5%），低血压与高血压均需处理"],"emergency":["血钾>6.5mmol/L或心电图出现QRS增宽、无脉性心律 → 立即补钙+胰岛素葡萄糖+碳酸氢钠，紧急透析","急性肺水肿（端坐呼吸、咳粉红色泡沫痰）→ 立即吸氧、紧急超滤/单纯超滤、必要时机械通气","内瘘震颤消失（急性血栓）→ 6小时内就诊溶栓或取栓（内瘘是生命线）","透析中抽搐、意识改变（失衡综合征/严重电解质紊乱）→ 停止或减慢透析、甘露醇、地西泮，复查电解质","透析导管出口红肿流脓伴寒战高热（导管相关血流感染）→ 双份血培养+经验性抗生素，评估拔管"],"pinyin":"xytxhzybcl","icd10":"Z99.2","physical_exam":["生命体征：血压（透析前后对比）、心率与心律（高钾致心律失常）、呼吸（肺水肿）、体温（感染）","容量状态：体重（透析前后）、水肿（下肢、颜面、骶部）、颈静脉充盈、肺部湿啰音、腹水","血管通路：内瘘震颤与杂音、穿刺部位出血与感染、导管出口情况（红肿渗液）","心肺：心界扩大、心音、心律不齐、呼吸音（肺水肿/胸腔积液）","皮肤与黏膜：贫血貌、皮肤瘙痒与抓痕、尿毒症霜、色素沉着、钙化（CKD-MBD）","神经系：意识状态（尿毒症脑病）、肌力与腱反射、抽搐","骨骼：骨痛、畸形、骨折（肾性骨病）"],"lab_tests":["电解质（钾、钠、钙、磷、镁）+肾功能（BUN、肌酐）+血气分析：透析患者核心监测（血钾>6.0mmol/L危急）","心电图：高钾血症（T波高尖、QRS增宽、心律失常）与低钙改变（必查，与血钾同步）","血常规+铁代谢（铁蛋白、转铁蛋白饱和度）+白蛋白：贫血与营养状态（每1～3个月）","甲状旁腺激素（PTH）+碱性磷酸酶：CKD-MBD监测（每3个月）","血管通路超声（疑血栓/狭窄时）：内瘘功能评估","血培养（发热者，尤其透析导管）+导管出口分泌物培养","凝血功能+D-二聚体：出血与血栓风险评估；心肌酶（胸痛者）"],"nursing":["高钾监测与护理：观察乏力、心悸与心电图改变，血钾>6.0mmol/L立即报告并准备急诊透析；限制高钾饮食宣教","透析中监测：每30～60分钟测血压、心率与症状（低血压、抽搐、头痛），观察体外循环与穿刺部位","血管通路护理：评估内瘘震颤与杂音、穿刺部位出血与感染；内瘘侧肢体禁止测血压、抽血、输液与受压","容量与体重管理：记录透析前后体重、超滤量与出入量，观察水肿与呼吸困难（容量负荷）","用药护理：核对肾功能剂量与给药时机（透析后给药），观察药物不良反应（促红素致高血压、磷结合剂致便秘）","饮食与宣教：限制水钠钾磷、遵医嘱服磷结合剂与促红素、内瘘保护、识别危险症状（乏力、心悸、气促）及时就诊"],"diet":["限水：透析间期体重增长控制在干体重的3%～5%（每日饮水约500～800ml+尿量）","限钠（<3～5g/日）：减少口渴与水分摄入，避免腌制品与加工食品","限钾：避免香蕉、橙子、土豆、蘑菇、低钠盐（含钾）等高钾食物；蔬菜可切块浸泡后焯水去钾","限磷：避免动物内脏、坚果、全谷物、碳酸饮料与加工肉；磷结合剂随餐服用（与餐同服效果最好）","优质蛋白：每日1.0～1.2g/kg（透析损失蛋白），以鱼、瘦肉、蛋、奶为主；保证足够热量（30～35kcal/kg）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1400},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7bc266d9a3533584f5c2c269567e350d4c30ca017d7417a5c6bcc59b9efd9d58","pinyin":"xueyetouxihuanzheyebanchuliyaodian","initials":"xytxhzybclyd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","高钾血症表现：乏力、肌无力、心律失常（可致心脏骤停，透析患者最常见急症）\\n容量负荷：呼吸困难、端坐呼吸、下肢与颜面水肿、血压升高（透析间期体重增长过多）\\n透析相关：透析中低血压（头晕、出汗、恶心）、失衡综合征（头痛、恶心、抽搐）、肌肉痉挛\\n尿毒症症状：恶心呕吐、食欲减退、皮肤瘙痒、贫血（乏力）、意识改变（尿毒症脑病）\\n血管通路问题：内瘘震颤减弱或消失（血栓）、穿刺部位出血、红肿热痛（感染）",60],["摘要","透析患者夜班处理需注意：肾功能衰竭（药物需按肾功能调整、禁用肾毒性药物）、容量与电解质波动（透析间期体重增长、高钾、酸中毒）、血管通路（内瘘保护与出血）、贫血与骨病，以及透析相关急症（失衡综合征、低血压、心律失常、高钾血症）。",30],["疾病编码","Z99.2",30],["原首字母","xytxhzybcl",60]]}]);